        [POST("EmpInfo")]
        [ActionName("EmpInfo")]
        [HttpPost]
        public IHttpActionResult UpdateEmpInfo(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;

            dynamic json = jsonContent;

            List<EMP_INFO> results = JsonConvert.DeserializeObject<List<EMP_INFO>>(json);
            //results = results.Where(t => t.EMP_CSP_ROLE != string.Empty).ToList<EMP_INFO>();
            foreach (EMP_INFO info in results)
            {
                EMP_INFO e = Cldb.EMP_INFO.GetById(info.EMP_ID);
                e.EMP_CSP_ROLE = info.EMP_CSP_ROLE;
                Cldb.EMP_INFO.Update(e);
                Cldb.Commit(CanCommit);
            }

            return Ok();
        }

