        [GET("EmpInfo")]
        [ActionName("EmpInfo")]
        [HttpGet]
        public IHttpActionResult GetEmpInfo(string search, string direction, int pageIndex, int pageSize)
        {
            List<EMP_INFO> empinfo;
            if (direction == "asc")
                empinfo = Cldb.EMP_INFO.GetAll().OrderBy(t => t.EMP_ID).ToList<EMP_INFO>();
            else if (direction == "desc")
                empinfo = Cldb.EMP_INFO.GetAll().OrderByDescending(t => t.EMP_ID).ToList<EMP_INFO>();
            else
                empinfo = Cldb.EMP_INFO.GetAll().ToList<EMP_INFO>();

            if (!string.IsNullOrEmpty(search))
                empinfo = empinfo.Where(t => t.FRST_NM.ToLower().Contains(search.ToLower().Trim())).ToList();
            //-------------------------------
            var total = empinfo.Select(p => p.EMP_ID).Count();

            var skip = pageSize * (pageIndex - 1);

            var result = empinfo.Select(p => p)
                         .Skip(skip)
                         .Take(pageSize)
                         .ToList();

            return Ok(new empresults() { count = total, empinfo = result });
        }

