        [POST("Logout")]
        [ActionName("Logout")]
        [HttpPost]
        public IHttpActionResult Logout(HttpRequestMessage request)
        {

            var tokenValue = request.Headers.GetValues("token").First();
            Token rec = this.Cldb.Token.GetAll().Where(t => t.AUTHKEY == tokenValue).FirstOrDefault();
            if (rec != null)
            {
                request.Headers.Add("EmailId", rec.EMAILID);
                Logger log = new Logger(request);
                rec.EXPIRESON = DateTime.Now;
                Cldb.Token.Update(rec);
                Cldb.Commit(CanCommit);
            }
            return Ok();
        }

