        [GET("GetSuccessGoalScoresForProject"), ActionName("GetSuccessGoalScoresForProject"), HttpGet]
        public IHttpActionResult GetSuccessGoalScoresForProject(string CustomerId)
        {
            int monthNumber = DateTime.Now.Month;
            int Year = DateTime.Now.Year;
            var selectedDate = new DateTime(Year, monthNumber, 01);
            DateRange range = new DateRange(selectedDate, enDateRange.Monthly);

            string startDate = range.StartDate.ToString();
            string endDate = range.EndDate.ToString();

            //string startDate = "1-Jul-2019";
            //string endDate = "31-jul-2019";
            List<SUCCESS_GOALS_SCORES> scores = GetSuccessGoalScoresForProject(CustomerId, startDate, endDate);
            return Ok(scores);
        }
        private List<SUCCESS_GOALS_SCORES> GetSuccessGoalScoresForProject(string CustomerId, string startDate, string endDate)
        {
            DateTime StartDate = Convert.ToDateTime(startDate);
            List<CUSTOMER_PROJECT_PORTFOLIO> overall = CSPdb.AppRepo.getCustomerProjectPorfolioList(StartDate, CustomerId).ToList();
            overall = overall.Where(t => t.CUST_ID == CustomerId).ToList();
            List<SUCCESS_GOALS_SCORES> scores = new List<SUCCESS_GOALS_SCORES>();
            List<CUSTOMER_PROJECT_PORTFOLIO> filteredList = overall.Where(x => x.CUST_ID == CustomerId).ToList();
            var projectstoSkipBySettings = helper.GetProjectConfigurationDataForSetting("SKIP_TO_SHOW_IN_DASHBOARD").Where(x => x.Bit_Value == true).ToList();
            foreach (var project in filteredList)
            {
                DASHBOARD_DETAILS details = CSPdb.DASHBOARD_DETAILS.GetAll().Where(t => t.PROJ_ID == project.PROJ_ID && t.TITLE == "SUCCESS_GOAL_SCORE").FirstOrDefault();
                if (projectstoSkipBySettings.Any(x => x.Proj_Id == project.PROJ_ID)) continue;
                string sScore = "-";
                decimal dScore = 0;
                if (details != null)
                {
                    if (details.CONTENT != "-")
                    {
                        dScore = Convert.ToDecimal(details.CONTENT.Replace("%", ""));
                        sScore = details.CONTENT;
                        sScore = sScore.Replace(".0%", "%");
                    }
                    else
                    {
                        dScore = -1;
                        sScore = "-";
                    }

                    SUCCESS_GOALS_SCORES score = new SUCCESS_GOALS_SCORES()
                    {
                        PROJ_NM = project.PROJ_NM,
                        CUSTOMER_NM = project.CUSTOMER_NM,
                        SCORE = sScore,
                        DSCORE = dScore,
                        COLOR = details.COLOR,
                        PROJ_ID = project.PROJ_ID,
                        CUST_ID = project.CUST_ID,
                        PORTFOLIO_ID = project.PORTFOLIO_ID
                    };
                    scores.Add(score);
                }
            }
            scores = scores.OrderByDescending(t => t.DSCORE).ToList();
            return scores;
        }

