        [GET("GetTaskCategoryListByTaskType"), ActionName("GetTaskCategoryListByTaskType"), HttpGet]
        public IHttpActionResult GetTaskCategoryListByTaskType(int TaskTypeId, bool filterAuditCategories)
        {
            var taskCategories = CSPdb.TASK_CATEGORY.GetAll().Where(t => t.ISACTIVE).OrderBy(x => x.TITLE).ToList();

            if (filterAuditCategories)
            {
                var auditCategoryList = CSPdb.PARAMETER_TABLE.GetAll().Where(t => t.ISACTIVE && t.NAME == "TASK_VIEW").Select(t => t.OPTIONS).ToList();
                taskCategories = taskCategories.Where(t => t.ISACTIVE && auditCategoryList.Contains(t.ID.ToString())).OrderBy(x => x.TITLE).ToList();
            }
            return Ok(taskCategories);
        }

        [GET("GetEventListByCategory"), ActionName("GetEventListByCategory"), HttpGet]
        public IHttpActionResult GetEventListByCategory(int categoryId)
        {
            string empId = Request.Headers.GetValues("empId").ToList()[0];
            //string intEmpId = "0";
            var auditTaskList = new List<int>();
            //if (int.TryParse(empId, out intEmpId))
            //{
            //    auditTaskList = CSPdb.AUDIT_SCHEDULE.GetAll().Where(x => x.ISACTIVE && x.TASK_ID.HasValue && x.AUDITOR_EMP_ID == intEmpId).Select(x=>x.TASK_ID.Value).ToList();
            //}

            List<TASK> results = CSPdb.TASK.GetAll().Where(t => t.ISACTIVE && t.TASK_CATEGORY_ID == categoryId
                        && (t.PARENT_TASK_ID == null || t.PARENT_TASK_ID == t.ID) && t.TASK_TYPE_ID == 1)
                  /// && (t.OWNER == empId || t.ASSIGNED_TO == empId || auditTaskList.Contains(t.ID))).Distinct()
                  .ToList();
            return this.Ok(results);
        }

        [GET("GetAuditScheduleByTaskId"), ActionName("GetAuditScheduleByTaskId"), HttpGet]
        public IHttpActionResult GetAuditScheduleByTaskId(int taskId)
        {
            var result = CSPdb.AUDIT_SCHEDULE.GetAll().FirstOrDefault(t => t.ISACTIVE && t.TASK_ID.HasValue && t.TASK_ID == taskId);
            if (result != null)
            {
                result.AUDITEE_EMP_ID = CSPdb.AUDIT_SCHEDULE_REF.GetAll().Where(x => x.KEY == "AUDITEE_EMP_ID" && x.AUDIT_SCHEDULE_ID == result.ID).ToList().Select(x => x.VALUE).ToList();
                result.SERVICE_AREA_ID = CSPdb.AUDIT_SCHEDULE_REF.GetAll().Where(x => x.KEY == "SERVICE_AREA_ID" && x.AUDIT_SCHEDULE_ID == result.ID).ToList().Select(x => GetIntvalue(x.VALUE)).ToList();
            }
            return this.Ok(result);
        }

        private int GetIntvalue(string val)
        {
            int res = 0;
            if (int.TryParse(val, out res)) return res;
            return res;
        }

