        [POST("GetAllPortfolioDetails"), ActionName("GetAllPortfolioDetails"), HttpPost]
        public IHttpActionResult GetAllPortfolioDetails(HttpRequestMessage request)
        {
            List<PORTFOLIO_VIEW_DETAILS> output = new List<PORTFOLIO_VIEW_DETAILS>();
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            PORTFOLIO_DASHBOARD_DETAILS results = JsonConvert.DeserializeObject<PORTFOLIO_DASHBOARD_DETAILS>(json);
            var portfolios = results.portfolios;
            var dashboarddetails = results.dashboarddetails;
            if (portfolios != null && dashboarddetails != null)
            {
                foreach (var portfolio in portfolios)
                {
                    PORTFOLIO_VIEW_DETAILS detail = new PORTFOLIO_VIEW_DETAILS();
                    detail.PORTFOLIO_NAME = portfolio.TITLE;
                    detail.PROJECTS_COUNT = GetProjectsCountByPortfolioId(portfolio.ID);
                    detail.SUCCESS_GOAL_PERCENTAGE = dashboarddetails.Where(x => x.TITLE == "CSS_SG" && x.PORTFOLIO_ID == portfolio.ID).Select(x => x.CONTENT).FirstOrDefault();
                    detail.PROCESS_COMPLIANCE_PERCENTAGE = dashboarddetails.Where(x => x.TITLE == "CSS_PC" && x.PORTFOLIO_ID == portfolio.ID).Select(x => x.CONTENT).FirstOrDefault();
                    detail.SUCCESS_SURVEY = dashboarddetails.Where(x => x.TITLE == "CSS_SS" && x.PORTFOLIO_ID == portfolio.ID).Select(x => x.CONTENT).FirstOrDefault();
                    detail.RISKS_HIGH = dashboarddetails.Where(x => x.TITLE == "RISK_H" && x.PORTFOLIO_ID == portfolio.ID).Select(x => x.CONTENT).FirstOrDefault();
                    detail.RISKS_MEDIUM = dashboarddetails.Where(x => x.TITLE == "RISK_M" && x.PORTFOLIO_ID == portfolio.ID).Select(x => x.CONTENT).FirstOrDefault();
                    detail.RISKS_LOW = dashboarddetails.Where(x => x.TITLE == "RISK_L" && x.PORTFOLIO_ID == portfolio.ID).Select(x => x.CONTENT).FirstOrDefault();
                    detail.AUTOMATIONS_COUNT = dashboarddetails.Where(x => x.TITLE == "CSS_AU" && x.PORTFOLIO_ID == portfolio.ID).Select(x => x.CONTENT).FirstOrDefault();
                    detail.IDEAS_COUNT = dashboarddetails.Where(x => x.TITLE == "CSS_ID" && x.PORTFOLIO_ID == portfolio.ID).Select(x => x.CONTENT).FirstOrDefault();
                    detail.IMPROVEMENTS_COUNT = dashboarddetails.Where(x => x.TITLE == "CSS_IM" && x.PORTFOLIO_ID == portfolio.ID).Select(x => x.CONTENT).FirstOrDefault();
                    var risksHigh = detail.RISKS_HIGH != "-" ? detail.RISKS_HIGH : "0"; ;
                    var risksMedium = detail.RISKS_MEDIUM != "-" ? detail.RISKS_MEDIUM : "0";
                    var risksLow = detail.RISKS_LOW != "-" ? detail.RISKS_LOW : "0";

                    if (risksHigh != null && risksMedium != null && risksLow != null)
                    {
                        detail.RISKS_TOTAL = int.Parse(risksHigh) + int.Parse(risksMedium) + int.Parse(risksLow);
                    }
                    if (detail.AUTOMATIONS_COUNT != null && detail.IDEAS_COUNT != null && detail.IMPROVEMENTS_COUNT != null)
                    {
                        detail.IDEAS_TOTAL_COUNT = int.Parse(detail.AUTOMATIONS_COUNT) + int.Parse(detail.IDEAS_COUNT) + int.Parse(detail.IMPROVEMENTS_COUNT);
                    }

                    output.Add(detail);
                }
            }

            return Ok(output);
        }

