        [POST("GetTaskDetails")]
        [ActionName("GetTaskDetails")]
        [HttpPost]
        public IHttpActionResult GetTaskDetails(HttpRequestMessage request)
        {
            string empId = Request.Headers.GetValues("empId").ToList()[0];
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;

            List<KeyValuePair<string, string>> results = JsonConvert.DeserializeObject<List<KeyValuePair<string, string>>>(json);
            DateTime startDate = new DateTime(DateTime.Now.Year, 4, 1);
            DateTime endDate = new DateTime(DateTime.Now.Year + 1, 3, 31);
            string range = "Y";
            string taskCategory = string.Empty;
            string customerId = string.Empty;
            string projectId = string.Empty;
            string viewBy = string.Empty;

            foreach (KeyValuePair<string, string> v in results)
            {
                if (v.Key == "StartDate")
                    startDate = Convert.ToDateTime(v.Value.ToString());
                else if (v.Key == "EndDate")
                    endDate = Convert.ToDateTime(v.Value.ToString());
                else if (v.Key == "Range")
                {
                    range = v.Value;
                }
                else if (v.Key == "TASK_CATEGORY_ID")
                {
                    taskCategory = v.Value;
                }
                else if (v.Key == "CUST_ID")
                {
                    customerId = v.Value;
                }
                else if (v.Key == "PROJ_ID")
                {
                    projectId = v.Value;
                }
                else if (v.Key == "VIEW_BY")
                {
                    viewBy = v.Value;
                }
            }

            switch (viewBy)
            {
                case "1":
                    List<TASK_DETAILS> taskList = CSPdb.AppRepo.getTaskDetailsByDateRange(startDate, endDate, empId, customerId, projectId, taskCategory, range).ToList();
                    foreach (KeyValuePair<string, string> v in results)
                    {
                        if (v.Key == "TASK_TYPE_ID")
                        {
                            taskList = taskList.Where(t => t.TASK_TYPE_ID == Convert.ToInt32(v.Value)).ToList();
                        }
                    }
                    TaskGroups TaskGroups = GetTaskGroups(taskList, empId, (string.IsNullOrEmpty(range) ? "Y" : range));
                    return Ok(TaskGroups);

                case "2":
                    var taskDetails = Cldb.AppRepo.getOverallTaskDetails(startDate, endDate, customerId, projectId, taskCategory);
                    return Ok(taskDetails);
                default:
                    return BadRequest("Invalid ViewBy value");
            }
        }

        public List<Grouping> GetList(List<TASK_DETAILS> coll)
        {
            var monthGroup = coll.GroupBy(t => t.PROJ_ID);

            List<Grouping> taskGroup = new List<Grouping>();
            foreach (var project in coll.GroupBy(x => x.PROJ_ID))
            {
                Grouping g = new Grouping() { projectName = project.Key };
                foreach (var month in project.GroupBy(x => x.MONTH_ID))
                {
                    Grouping h = new Grouping() { projectName = month.Key.ToString() };
                    h.tasks = month.ToList();
                    g.groups.Add(h);
                }
                taskGroup.Add(g);
            }
            return taskGroup;
        }
        public TaskGroups GetTaskGroups(List<TASK_DETAILS> results, string empId, string viewType = "Y")
        {
            TaskGroups taskGroups = new TaskGroups();
            List<string> projects = new List<string>();
            projects = results.Select(t => t.PROJ_NM).Distinct().ToList();
            projects.Sort();

            List<Tuple<int, int, string>> months = null;
            if (viewType == "Y")
                months = results.Select(t => new Tuple<int, int, string>(t.SCHEDULED_START_DATE.GetValueOrDefault(t.DUE_DATE).Year, t.MONTH_ID, "")).Distinct().ToList();
            else if (viewType == "Q")
                months = results.Select(t => new Tuple<int, int, string>(t.SCHEDULED_START_DATE.GetValueOrDefault(t.DUE_DATE).Year, t.WEEK_ID, "[" + Convert.ToDateTime(t.WEEK_START_DATE).ToString("dd MMM") + " - " + Convert.ToDateTime(t.WEEK_END_DATE).ToString("dd MMM") + "]")).Distinct().ToList();
            else if (viewType == "M")
                months = results.Select(t => new Tuple<int, int, string>(t.SCHEDULED_START_DATE.GetValueOrDefault(t.DUE_DATE).Year, t.DAY_ID, t.DATE_NAME)).Distinct().ToList();
            else if (viewType == "A")
                months = results.Select(t => new Tuple<int, int, string>(t.SCHEDULED_START_DATE.GetValueOrDefault(t.DUE_DATE).Year, t.WEEK_ID, "[" + Convert.ToDateTime(t.WEEK_START_DATE).ToString("dd MMM") + " - " + Convert.ToDateTime(t.WEEK_END_DATE).ToString("dd MMM") + "]")).Distinct().ToList();
            months = months.OrderBy(x => x.Item1).ThenBy(x => x.Item2).ToList();
            List<TASK_DETAILS> tasks = new List<TASK_DETAILS>();
            List<Grouping> ProjGroup = new List<Grouping>();
            if (viewType != "A")
            {
                foreach (string proj in projects)
                {
                    Grouping newProjGroup = new Grouping();
                    newProjGroup.projectName = proj;
                    newProjGroup.customerName = results.FirstOrDefault(t => t.PROJ_NM == proj).CUST_NM;
                    newProjGroup.projectId = results.FirstOrDefault(t => t.PROJ_NM == proj).PROJ_ID;
                    newProjGroup.customerId = results.FirstOrDefault(t => t.PROJ_NM == proj).CUST_ID;

                    foreach (var month in months)
                    {
                        if (viewType == "Y")
                            tasks = results.Where(t => t.PROJ_NM == proj && t.MONTH_ID == month.Item2).OrderBy(x => x.SCHEDULED_START_DATE.GetValueOrDefault(x.DUE_DATE)).ToList();
                        else if (viewType == "Q")
                            tasks = results.Where(t => t.PROJ_NM == proj && t.WEEK_ID == month.Item2).OrderBy(x => x.SCHEDULED_START_DATE.GetValueOrDefault(x.DUE_DATE)).ToList();
                        else if (viewType == "M")
                            tasks = results.Where(t => t.PROJ_NM == proj && t.DAY_ID == month.Item2).OrderBy(x => x.SCHEDULED_START_DATE.GetValueOrDefault(x.DUE_DATE)).ToList();
                        else if (viewType == "A")
                            tasks = results.Where(t => t.PROJ_NM == proj && t.WEEK_ID == month.Item2).OrderBy(x => x.SCHEDULED_START_DATE.GetValueOrDefault(x.DUE_DATE)).ToList();

                        Grouping newMonthGroup = new Grouping();

                        if (viewType == "Y")
                            newMonthGroup.projectName = GetMonthString(month.Item2).ToUpper();
                        else
                            newMonthGroup.projectName = month.Item2.ToString();
                        newMonthGroup.tasks = tasks;
                        newProjGroup.groups.Add(newMonthGroup);
                    }
                    ProjGroup.Add(newProjGroup);
                }
            }
            else
            {
                foreach (TASK_DETAILS proj in results)
                {
                    Grouping newProjGroup = new Grouping();
                    newProjGroup.projectName = proj.DESCRIPTION + "##" + proj.FREQUENCY;
                    newProjGroup.customerName = results.FirstOrDefault(t => t.PROJ_ID == proj.PROJ_ID).CUST_NM;
                    newProjGroup.projectId = proj.PROJ_ID;
                    newProjGroup.customerId = results.FirstOrDefault(t => t.PROJ_ID == proj.PROJ_ID).CUST_ID;

                    foreach (var month in months)
                    {
                        //if (viewType == "Y")
                        //    tasks = results.Where(t => t.PROJ_ID == proj.PROJ_ID && t.MONTH_ID == month.Item2).OrderBy(x => x.SCHEDULED_START_DATE.GetValueOrDefault(x.DUE_DATE)).ToList();
                        //else if (viewType == "Q")
                        //    tasks = results.Where(t => t.PROJ_ID == proj.PROJ_ID && t.WEEK_ID == month.Item2).OrderBy(x => x.SCHEDULED_START_DATE.GetValueOrDefault(x.DUE_DATE)).ToList();
                        //else if (viewType == "M")
                        //    tasks = results.Where(t => t.PROJ_ID == proj.PROJ_ID && t.DAY_ID == month.Item2).OrderBy(x => x.SCHEDULED_START_DATE.GetValueOrDefault(x.DUE_DATE)).ToList();
                        //else
                        if (viewType == "A")
                            tasks = results.Where(t => t.DESCRIPTION == proj.DESCRIPTION && t.PROJ_ID == proj.PROJ_ID && t.WEEK_ID == month.Item2).OrderBy(x => x.SCHEDULED_START_DATE.GetValueOrDefault(x.DUE_DATE)).ToList();

                        Grouping newMonthGroup = new Grouping();

                        if (viewType == "Y")
                            newMonthGroup.projectName = GetMonthString(month.Item2).ToUpper();
                        else
                            newMonthGroup.projectName = month.Item2.ToString();
                        newMonthGroup.tasks = tasks;
                        newProjGroup.groups.Add(newMonthGroup);
                    }
                    ProjGroup.Add(newProjGroup);
                }
            }
            taskGroups.Projects = ProjGroup;
            if (viewType == "Y")
                taskGroups.Dates = months.Select(t => GetMonthString(t.Item2).ToUpper()).ToList();
            else
                taskGroups.Dates = months.Select(t => t.Item2.ToString() + "#" + t.Item3).ToList(); //.Select(t => GetMonthString(t.Item2).ToUpper()).ToList(); 

            return taskGroups;
        }
        public class TaskGroups
        {
            public List<string> Dates { get; set; } = new List<string>();
            public List<Grouping> Projects = new List<Grouping>();
        }
        public class Grouping
        {
            public string customerName { get; set; }
            public string projectName { get; set; }
            public string customerId { get; set; }
            public string projectId { get; set; }
            public List<TASK_DETAILS> tasks { get; set; }
            public List<Grouping> groups { get; set; } = new List<Grouping>();

        }

