        [GET("GetRiskObjectivesMappingData"), ActionName("GetRiskObjectivesMappingData"), HttpGet]
        public IHttpActionResult GetRiskObjectivesMappingData()
        {
            List<RiskObjectiveMapping> list = new List<RiskObjectiveMapping>();
            List<PROCESS_MODEL_RISKS_NEW> list2 = (
                from x in base.CSPdb.PROCESS_MODEL_RISKS_NEW.GetAll()
                where x.ISACTIVE
                select x).ToList<PROCESS_MODEL_RISKS_NEW>();
            using (List<PROCESS_MODEL_RISKS_NEW>.Enumerator enumerator = list2.GetEnumerator())
            {
                while (enumerator.MoveNext())
                {
                    PROCESS_MODEL_RISKS_NEW o = enumerator.Current;
                    List<RISKS_OBJECTIVES_MAPPING> list3 = (
                        from x in base.CSPdb.RISKS_OBJECTIVES_MAPPING.GetAll()
                        where x.RISK_ID == o.ID && x.ISACTIVE
                        select x).ToList<RISKS_OBJECTIVES_MAPPING>();
                    List<PROCESS_MODEL_OBJECTIVES_NEW> list4 = new List<PROCESS_MODEL_OBJECTIVES_NEW>();
                    using (List<RISKS_OBJECTIVES_MAPPING>.Enumerator enumerator2 = list3.GetEnumerator())
                    {
                        while (enumerator2.MoveNext())
                        {
                            RISKS_OBJECTIVES_MAPPING obj = enumerator2.Current;
                            list4.Add((
                                from x in base.CSPdb.PROCESS_MODEL_OBJECTIVES_NEW.GetAll()
                                where x.ID == obj.OBJECTIVE_ID
                                select x).FirstOrDefault<PROCESS_MODEL_OBJECTIVES_NEW>());
                        }
                    }
                    list.Add(new AllSysController.RiskObjectiveMapping
                    {
                        PROCESS_MODEL_OBJECTIVES_NEW = list4,
                        PROCESS_MODEL_RISKS_NEW = o
                    });
                }
            }
            return this.Ok<List<AllSysController.RiskObjectiveMapping>>(list);
        }
