        [GET("GetControlRisksMappingData"), ActionName("GetControlRisksMappingData"), HttpGet]
        public IHttpActionResult GetControlRisksMappingData()
        {
            List<AllSysController.ControlRisksMapping> list = new List<AllSysController.ControlRisksMapping>();
            List<PROCESS_MODEL_CONTROL_NEW> list2 = (
                from x in base.CSPdb.PROCESS_MODEL_CONTROL_NEW.GetAll()
                where x.ISACTIVE
                select x).ToList<PROCESS_MODEL_CONTROL_NEW>();
            using (List<PROCESS_MODEL_CONTROL_NEW>.Enumerator enumerator = list2.GetEnumerator())
            {
                while (enumerator.MoveNext())
                {
                    PROCESS_MODEL_CONTROL_NEW o = enumerator.Current;
                    CONTROL_CATEGORY category = (
                        from x in base.CSPdb.CONTROL_CATEGORY.GetAll()
                        where x.ID == o.CATEGORY
                        select x).FirstOrDefault<CONTROL_CATEGORY>();
                    if (category == null) continue;
                    PROCESS_MODEL pROCESS_MODEL = (
                        from x in base.CSPdb.PROCESS_MODEL.GetAll()
                        where x.ID == category.PROCESS_MODEL_ID
                        select x).FirstOrDefault<PROCESS_MODEL>();

                    CONTROL_REFERENCE pROCESS_MODEL_CONTROL_REFERENCE = (
                        from x in base.CSPdb.CONTROL_REFERENCE.GetAll()
                        where x.CONTROL_CATEGORY_ID == category.ID
                        select x).FirstOrDefault<CONTROL_REFERENCE>();
                    AllSysController.PROCESS_MODELVIEW_FOR_CONTROL pROCESS_MODELVIEW_FOR_CONTROL = new AllSysController.PROCESS_MODELVIEW_FOR_CONTROL();
                    pROCESS_MODELVIEW_FOR_CONTROL.PROCESS_MODEL = pROCESS_MODEL;
                    pROCESS_MODELVIEW_FOR_CONTROL.PROCESS_MODEL_CATEGORY = category;
                    pROCESS_MODELVIEW_FOR_CONTROL.PROCESS_MODEL_CONTROL_REFERENCE = pROCESS_MODEL_CONTROL_REFERENCE;
                    //List<CONTROL_RISKS_MAPPING> list3 = (
                    //    from x in base.CSPdb.CONTROL_RISKS_MAPPING.GetAll()
                    //    where x.CONTROL_ID == o.ID 
                    //    select x).ToList<CONTROL_RISKS_MAPPING>();

                    List<CONTROL_RISKS_MAPPING> list3 = CSPdb.CONTROL_RISKS_MAPPING.GetAll().Where(x => x.CONTROL_ID == o.ID && x.ISACTIVE).ToList();
                    List<PROCESS_MODEL_RISKS_NEW> list4 = new List<PROCESS_MODEL_RISKS_NEW>();
                    using (List<CONTROL_RISKS_MAPPING>.Enumerator enumerator2 = list3.GetEnumerator())
                    {
                        while (enumerator2.MoveNext())
                        {
                            CONTROL_RISKS_MAPPING obj = enumerator2.Current;
                            list4.Add((
                                from x in base.CSPdb.PROCESS_MODEL_RISKS_NEW.GetAll()
                                where x.ID == obj.RISKS_ID
                                select x).FirstOrDefault<PROCESS_MODEL_RISKS_NEW>());
                        }
                    }
                    list.Add(new AllSysController.ControlRisksMapping
                    {
                        PROCESS_MODEL_CONTROL_NEW = o,
                        PROCESS_MODEL_RISKS_NEW = list4,
                        PROCESS_MODELVIEW_FOR_CONTROL = pROCESS_MODELVIEW_FOR_CONTROL
                    });
                }
            }
            return this.Ok<List<AllSysController.ControlRisksMapping>>(list);
        }
