            List<TestControlsMapping> list = new List<TestControlsMapping>();
            List<PROCESS_MODEL_TESTS_NEW> list2 = (
                from x in CSPdb.PROCESS_MODEL_TESTS_NEW.GetAll()
                where x.ISACTIVE
                select x).ToList<PROCESS_MODEL_TESTS_NEW>();
            using (List<PROCESS_MODEL_TESTS_NEW>.Enumerator enumerator = list2.GetEnumerator())
            {
                while (enumerator.MoveNext())
                {
                    PROCESS_MODEL_TESTS_NEW test = enumerator.Current;
                    List<TEST_CONTROL_MAPPING> list3 = (
                        from x in base.CSPdb.TEST_CONTROL_MAPPING.GetAll()
                        where x.TEST_ID == test.ID && x.ISACTIVE
                        select x).ToList<TEST_CONTROL_MAPPING>();
                    List<PROCESS_MODEL_CONTROL_NEW> list4 = new List<PROCESS_MODEL_CONTROL_NEW>();
                    using (List<TEST_CONTROL_MAPPING>.Enumerator enumerator2 = list3.GetEnumerator())
                    {
                        while (enumerator2.MoveNext())
                        {
                            TEST_CONTROL_MAPPING m = enumerator2.Current;
                            list4.Add((
                                from x in base.CSPdb.PROCESS_MODEL_CONTROL_NEW.GetAll()
                                where x.ID == m.CONTROL_ID
                                select x).FirstOrDefault<PROCESS_MODEL_CONTROL_NEW>());
