        [GET("GetProcessChecklistQuestionsMappingList")]
        [ActionName("GetProcessChecklistQuestionsMappingList")]
        [HttpGet]
        public IHttpActionResult GetProcessChecklistQuestionsMappingList(int ChecklistId, int ProcessId, int ProcessAreaId, int ServiceAreaId)
        {
            var checklistQuestions = CSPdb.PM_PROCESS_QUESTIONS_MAPPING.GetAll().Where(x => x.PROCESS_ID == ProcessId
                                        && x.CHECKLIST_ID == ChecklistId && x.SERVICE_AREA_ID == ServiceAreaId &&
                                        x.PROCESS_AREA_ID == ProcessAreaId && x.ISACTIVE).ToList();
            var output = new List<PM_CHECKLIST_QUESTIONS>();

            foreach (var question in checklistQuestions)
            {
                var rec = CSPdb.PM_CHECKLIST_QUESTIONS.GetAll().FirstOrDefault(x => x.ID == question.QUESTION_ID
                                        && x.ISACTIVE && x.CHECKLIST_ID == question.CHECKLIST_ID);
                if (rec != null)
                {
                    rec.DISPLAY_ORDER = question.DISPLAY_ORDER;
                    output.Add(rec);
                }
            }

            return Ok(output);
        }

