        [GET("GetProcessFile")]
        [ActionName("GetProcessFile")]
        [HttpGet]
        public HttpResponseMessage GetProcessFile(HttpRequestMessage request)
        {
            try
            {
                string project_id = request.Headers.GetValues("FILE_NAME_SERVER").ToList()[0];

                var content = request.Content;
                string jsonContent = content.ReadAsStringAsync().Result;

                PROJECT_PROCESS query = CSPdb.PROJECT_PROCESS.GetAll().Where(t => t.FILE_NAME_SERVER == project_id && t.ISACTIVE).FirstOrDefault<PROJECT_PROCESS>();

                if (!string.IsNullOrEmpty(query.FILE_NAME_SERVER))
                {
                    string uploadfolder = ConfigurationManager.AppSettings["uploadfolder"];
                    string filePath = HttpContext.Current.Server.MapPath(uploadfolder) + query.FILE_NAME_SERVER;

                    using (MemoryStream ms = new MemoryStream())
                    {
                        using (FileStream file = new FileStream(filePath, FileMode.Open, FileAccess.Read))
                        {
                            byte[] bytes = new byte[file.Length];
                            file.Read(bytes, 0, (int)file.Length);
                            ms.Write(bytes, 0, (int)file.Length);

                            HttpResponseMessage httpResponseMessage = new HttpResponseMessage();
                            httpResponseMessage.Content = new ByteArrayContent(bytes.ToArray());
                            httpResponseMessage.Content.Headers.Add("x-filename", query.FILE_NAME_SERVER);
                            httpResponseMessage.Content.Headers.ContentType = new MediaTypeHeaderValue("application/vnd.openxmlformats-officedocument.presentationml.presentation");
                            httpResponseMessage.Content.Headers.ContentDisposition = new ContentDispositionHeaderValue("attachment");
                            httpResponseMessage.Content.Headers.ContentDisposition.FileName = query.FILE_NAME_SERVER;
                            httpResponseMessage.StatusCode = HttpStatusCode.OK;
                            return httpResponseMessage;
                        }
                    }
                }
                return this.Request.CreateResponse(HttpStatusCode.NotFound, "File not found.");
            }
            catch (Exception ex)
            {
                return this.Request.CreateResponse(HttpStatusCode.InternalServerError, ex);
            }
        }
