        [GET("GetCustomerProjectList")]
        [ActionName("GetCustomerProjectList")]
        [HttpGet]
        public IHttpActionResult GetCustomerProjectList(string EmpId)
        {
            var stopwatch = Stopwatch.StartNew();


            var projects = GetProjectListForUser(EmpId);

            List<CustomerProjectsList> Customers = new List<CustomerProjectsList>();

            foreach (var p in projects)
            {
                CustomerProjectsList cust = Customers.Find(t => t.CUST_ID == p.CUST_ID);
                if (cust == null)
                    Customers.Add(new CustomerProjectsList()
                    {
                        CUST_ID = p.CUST_ID,
                        CUST_NM = p.CUST_NM,
                        Projects = new List<Projects>() { new Projects
                    {
                     PROJ_ID =  p.PROJ_ID,
                      CUST_ID = p.CUST_ID,
                      PROJ_NM = p.PROJ_NM,
                       PROJ_ALIAS_NM = p.PROJ_NM,
                        CUST_NM = p.CUST_NM,
                         IS_SLA_AVAILABLE = p.IS_SLA_AVAILABLE,
                          BILLING_PROJ_ID = p.PROJ_ID,
                           BILLING_PROJ_NM = p.PROJ_NM

                    }
                        }
                    });
                else
                    cust.Projects.Add(new Projects
                    {
                        PROJ_ID = p.PROJ_ID,
                        CUST_ID = p.CUST_ID,
                        PROJ_NM = p.PROJ_NM,
                        PROJ_ALIAS_NM = p.PROJ_NM,
                        CUST_NM = p.CUST_NM,
                        IS_SLA_AVAILABLE = p.IS_SLA_AVAILABLE,
                        BILLING_PROJ_ID = p.PROJ_ID,
                        BILLING_PROJ_NM = p.PROJ_NM

                    });
            }
            Customers = Customers.OrderBy(x => x.CUST_NM).ToList();
            //if (projects.Count > 0)
            //{
            //    Customers.Insert(0,new CustomerProjectsList() { CUST_ID = -1, CUST_NM = "All", Projects = projects.OrderBy(t => t.CUST_NM).ToList<Projects>() });
            //}
            if (Customers.Any())
                Customers.Insert(0, new CustomerProjectsList { CUST_ID = "0", CUST_NM = "ALL", Projects = new List<Projects>() });

            FillResponseTime(stopwatch);
            return Ok(Customers);
        }


        [GET("GetCustomerPortfolioProjectList")]
        [ActionName("GetCustomerPortfolioProjectList")]
        [HttpGet]
        public IHttpActionResult GetCustomerPortfolioProjectList(string EmpId, bool projFlag)
        {
            List<CUSTOMER_PROJECT_PORTFOLIO> projects = GetCustomerPortfolioProjectListForUser(EmpId, projFlag);

            var customerGroup = projects.GroupBy(t => t.CUST_ID);//.Select(x => new { CUST_ID = x.Key, PROJ_LIST = x.ToList() });
            List<CUSTOMER_GROUP> CUSTOMER_GROUP = new List<AllSysController.CUSTOMER_GROUP>();
            //List<CRISP_SCORES_PROJECT> crispScore = new List<CRISP_SCORES_PROJECT>();
            //List<SUCCESS_GOALS_SCORES> succesGoalScore = new List<SUCCESS_GOALS_SCORES>();
            foreach (var custGroup in customerGroup)
            {
                CUSTOMER_GROUP lstCust = new CUSTOMER_GROUP();
                lstCust.CUST_ID = custGroup.Key;
                lstCust.CUST_NM = projects.Where(t => t.CUST_ID == custGroup.Key).FirstOrDefault().CUST_NM;
                //portfolio
                var portfolioGroup = custGroup.Where(t => t.PORTFOLIO_ID != null).GroupBy(t => t.PORTFOLIO_ID);
                List<PORTFOLIO_GROUP> PORTFOLIO_GROUP = new List<PORTFOLIO_GROUP>();
                foreach (var portGroup in portfolioGroup)
                {
                    PORTFOLIO_GROUP lstPort = new PORTFOLIO_GROUP();
                    lstPort.PORTFOLIO_ID = portGroup.Key;
                    lstPort.PORTFOLIO_NM = projects.Where(t => t.PORTFOLIO_ID == portGroup.Key).FirstOrDefault().PORTFOLIO_NM;
                    //project
                    lstPort.PROJECT_INFO = portGroup.Select(x => new PROJECT_INFO() { PROJ_ID = x.PROJ_ID, PROJ_NM = x.PROJ_NM }).ToList();
                    PORTFOLIO_GROUP.Add(lstPort);
                }
                lstCust.PORTFOLIO_GROUP = PORTFOLIO_GROUP;
                lstCust.PROJECT_INFO = custGroup.ToList().Where(t => t.PORTFOLIO_ID == null).Select(x => new PROJECT_INFO() { PROJ_ID = x.PROJ_ID, PROJ_NM = x.PROJ_NM }).ToList();
                CUSTOMER_GROUP.Add(lstCust);
            }
            return Ok(CUSTOMER_GROUP);
        }

