        [GET("GetCustomerList")]
        [ActionName("GetCustomerList")]
        [HttpGet]
        public IHttpActionResult GetCustomerList(string EmpId)
        {
            var stopwatch = Stopwatch.StartNew();
            //var query = Cldb.AppRepo.CustomerProjectIds(EmpId);
            var projects = GetProjectListForUser(EmpId);
            List<string> cust = projects.Select(t => t.CUST_ID).Distinct().ToList<string>();
            List<CUSTOMER> Customers = new List<CUSTOMER>();
            Customers.AddRange(Cldb.CUSTOMER.GetAll().Where(t => cust.Contains(t.CUST_ID)).OrderBy(t => t.CUST_NM).ToList<CUSTOMER>());
            FillResponseTime(stopwatch);
            return Ok(Customers);
        }

        [GET("GetCustomerInfo")]
        [ActionName("GetCustomerInfo")]
        [HttpGet]
        public IHttpActionResult GetCustomerInfo(string managerid)
        {
            var projects = Cldb.AppRepo.GetProjectIdsForUser(managerid, "", "").ToList();
            List<string> proj = projects.Select(t => t.PROJ_ID).ToList<string>();
            List<CUSTOMER_PROJECTS> custProj = CSPdb.CUSTOMER_PROJECTS.GetAll().Where(t => proj.Contains(t.PROJ_ID)).ToList<CUSTOMER_PROJECTS>();
