        [GET("GetCSPDetails")]
        [ActionName("GetCSPDetails")]
        [HttpGet]
        public IHttpActionResult GetCSPDetails(string EmpId, DateTime CurrentDate, string customerId)
        {
            var stopwatch = Stopwatch.StartNew();
            var query = GetProjectListForUser(EmpId, customerId).ToList();
            if (!string.IsNullOrWhiteSpace(customerId))
                query = query.Where(x => x.CUST_ID == customerId).ToList();
            var projIds = query.Select(x => x.PROJ_ID).ToList();
            List<string> customers = new List<string>();
            CSPMODEL cspDetails = new CSPMODEL();
            var customerIds = query.Select(x => x.CUST_ID).Distinct().ToList();
            var overviewList = CSPdb.ENGAGEMENT_OVERVIEW.GetAll().Where(x => x.ISACTIVE && customerIds.Contains(x.CUSTOMER_ID)).ToList();
            var reportList = CSPdb.CUSTOMER_REPORTS.GetAll().Where(x => customerIds.Contains(x.CUSTOMER_ID)).ToList();
            foreach (var p in query.OrderBy(x => x.CUST_NM).ToList())
            {
                if (!customers.Contains(p.CUST_ID))
                {
                    customers.Add(p.CUST_ID);
                    cspDetails.clients.Add(GetNewClient(p, overviewList, reportList));
                }
            }
            //db
            List<PROJECT_RAGS> project_rags = CSPdb.PROJECT_RAGS.GetAll().Where(x => projIds.Contains(x.PROJECT_ID)).ToList<PROJECT_RAGS>();
            foreach (CSPMODEL.Client c in cspDetails.clients)
            {
                foreach (var p in query.Where(x => x.CUST_ID == c.Client_ID))
                {
                    if (p.CUST_ID == c.Client_ID)
                    {
                        c.projects.Add(new CSPMODEL.Client.Project()
                        {
                            PROJ_NM = p.PROJ_NM,
                            PROJ_ID = p.PROJ_ID,
                            PROJ_ALIAS_NM = p.PROJ_NM,
                            BILLING_PROJ_NM = p.PROJ_NM,
                            BILLING_PROJ_ID = p.PROJ_ID,
                            PROJ_RAG = GetProjectRAG(project_rags, p.PROJ_ID, ragCategory.project),
                            PUBLISHED_ON = GetProjectPublishedOn(project_rags, p.PROJ_ID),
                            Details = GetProjectDetails(p.PROJ_ID, CurrentDate),
                            LastUpdated = CSPdb.AppRepo.LastUpdatedDate(p.PROJ_ID)
                        });
                    }
                }
            }
            FillResponseTime(stopwatch);
            return Ok(cspDetails.clients);
        }

