        [GET("GetCCSPDetails")]
        [ActionName("GetCCSPDetails")]
        [HttpGet]
        public IHttpActionResult GetCCSPDetails(string CustomerEmailid, DateTime CurrentDate)
        {
            List<Projects> custProjects = Cldb.AppRepo.CustomerProjects(CustomerEmailid).ToList();
            var projIds = custProjects.Select(x => x.PROJ_ID).ToList();
            List<PROJECT_RAGS> project_rags = CSPdb.PROJECT_RAGS.GetAll().Where(x => projIds.Contains(x.PROJECT_ID)).ToList<PROJECT_RAGS>();
            List<string> customers = new List<string>();
            CSPMODEL cspDetails = new CSPMODEL();

            var customerIds = custProjects.Select(x => x.CUST_ID).Distinct().ToList();
            var overviewList = CSPdb.ENGAGEMENT_OVERVIEW.GetAll().Where(x => x.ISACTIVE && customerIds.Contains(x.CUSTOMER_ID)).ToList();
            var engageReport = CSPdb.CUSTOMER_REPORTS.GetAll().ToList();
            foreach (Projects p in custProjects)
            {
                if (!customers.Contains(p.CUST_ID.ToString()))
                {
                    customers.Add(p.CUST_ID.ToString());
                    cspDetails.clients.Add(GetNewClient(p, overviewList, engageReport));
                }
            }
            foreach (CSPMODEL.Client c in cspDetails.clients)
            {
                foreach (Projects p in custProjects)
                {
                    if (p.CUST_ID == c.Client_ID)
                    {
                        c.reports = GetEngageReport(p.CUST_ID, engageReport);
                        c.projects.Add(new CSPMODEL.Client.Project() { PROJ_NM = p.PROJ_NM, PROJ_ID = p.PROJ_ID, PROJ_ALIAS_NM = p.PROJ_ALIAS_NM, BILLING_PROJ_NM = p.BILLING_PROJ_NM, BILLING_PROJ_ID = p.BILLING_PROJ_ID, PROJ_RAG = GetProjectRAG(project_rags, p.PROJ_ID, ragCategory.project), Details = GetProjectDetails(p.PROJ_ID, CurrentDate), LastUpdated = CSPdb.AppRepo.LastUpdatedDate(p.PROJ_ID) });
                    }
                }
            }
            return Ok(cspDetails.clients);
        }
