        [GET("GetCustomerIds")]
        [ActionName("GetCustomerIds")]
        [HttpGet]
        public IHttpActionResult GetCustomerIds(string EmpId, bool istoFindSLA = false)
        {
            var stopwatch = Stopwatch.StartNew();
            var result = GetCustomerListForUser(EmpId);
            var customerIds = result.Select(x => x.CUST_ID).ToList();
            if (istoFindSLA)
            {
                var availableSLAs = CSPdb.KPI.GetAll().Where(x => customerIds.Contains(x.CUSTOMER_ID) && x.ISACTIVE && x.PRODUCT_ID.HasValue).ToList();
                foreach (var item in result)
                {
                    item.IS_SLA_AVAILABLE = availableSLAs.Any(x => x.CUSTOMER_ID == item.CUST_ID);
                }
            }

            FillResponseTime(stopwatch);
            return Ok(result);
        }

