        [GET("GetProjectIssueForEWS")]
        [ActionName("GetProjectIssueForEWS")]
        [HttpGet]
        public IHttpActionResult GetProjectIssueForEWS(DateTime Date)
        {
            List<string> PROJECT_IDs = new List<string>();
            if (Request.Headers.Contains("projectIds"))
                PROJECT_IDs = Request.Headers.GetValues("projectIds").ToList<string>()[0].ToString().Split(',').ToList<string>();
            List<PROJECT_PREFERENCE> ppr = new List<PROJECT_PREFERENCE>();
            List<PROJECT_PREFERENCE> projectlist = Cldb.PROJECT_PREFERENCE.GetAll().Where(t => t.PREFERENCE_TITLE == "EWS_DASHBOARD" && t.ALLOW == true).ToList<PROJECT_PREFERENCE>();
            foreach (PROJECT_PREFERENCE p in projectlist)
            {
                foreach (string pro in PROJECT_IDs)
                {
                    if (p.PROJ_ID == pro)
                        ppr.Add(p);
                }
            }
            //List<PROJECT_PREFERENCE> projectlistfalse = Cldb.PROJECT_PREFERENCE.GetAll().Where(t => t.PREFERENCE_TITLE == "EWS_DASHBOARD" && t.ALLOW == false).ToList<PROJECT_PREFERENCE>();
            List<PROJECT_ISSUE> issuelist = CSPdb.PROJECT_ISSUE.GetAll().Where(m => (m.REPORTED_BY == "reportedbyClient" || m.REPORTED_BY == "escalatedbyClient") && m.ISACTIVE == true).ToList<PROJECT_ISSUE>();
            List<string> ProjIds = issuelist.Select(t => t.PROJECT_ID).ToList<string>();
            ProjIds = ProjIds.Distinct().ToList<string>();
            List<ProjectIssues> project = new List<ProjectIssues>();
            List<PROJECT_ISSUE> finalissue = new List<PROJECT_ISSUE>();
            foreach (PROJECT_ISSUE p in issuelist)
            {
                foreach (PROJECT_PREFERENCE pp in ppr)
                {
                    if (pp.PROJ_ID == p.PROJECT_ID)
                        finalissue.Add(p);
                }
            }

            foreach (PROJECT_ISSUE p in finalissue)
            {
                //if (eligible(p))
                //{
                ProjectIssues issueproj = new ProjectIssues();
                issueproj.PRJ_NM = GetProjectName(p.PROJECT_ID, Date);
                issueproj.PROJ_ID = p.PROJECT_ID;
                issueproj.IsNeedFocus = GetNeedFocusFlag(p.PROJECT_ID);
                issueproj.RAG = GetIssueRag(finalissue, p.PROJECT_ID, p.LEVEL);
                issueproj.Severity = GetSeverity(finalissue, p.PROJECT_ID, p.LEVEL);
                issueproj.Level = p.LEVEL;
                issueproj.count = finalissue.Where(m => m.PROJECT_ID == p.PROJECT_ID && m.LEVEL == p.LEVEL).ToList<PROJECT_ISSUE>().Count;
                project.Add(issueproj);
                //}
            }
            //--------------------------------------

            List<ProjectIssues> filteredIssues = new List<ProjectIssues>();
            foreach (string p in ProjIds)
            {
                //sponser - red
                ProjectIssues issue = project.Where(t => t.PROJ_ID == p && t.Level == "sponser" && t.Severity.ToLower() == "red").FirstOrDefault<ProjectIssues>();
                if (issue != null) filteredIssues.Add(issue);
                //sponser - amber
                issue = project.Where(t => t.PROJ_ID == p && t.Level == "sponser" && t.Severity.ToLower() == "amber").FirstOrDefault<ProjectIssues>();
                if (issue != null) filteredIssues.Add(issue);
                //buhead - red
                issue = project.Where(t => t.PROJ_ID == p && t.Level == "buhead" && t.Severity.ToLower() == "red").FirstOrDefault<ProjectIssues>();
                if (issue != null) filteredIssues.Add(issue);
                //buhead - amber
                issue = project.Where(t => t.PROJ_ID == p && t.Level == "buhead" && t.Severity.ToLower() == "amber").FirstOrDefault<ProjectIssues>();
                if (issue != null) filteredIssues.Add(issue);
                //pm - red
                issue = project.Where(t => t.PROJ_ID == p && t.Level == "pm" && t.Severity.ToLower() == "red").FirstOrDefault<ProjectIssues>();
                if (issue != null) filteredIssues.Add(issue);
                //pm - amber
                issue = project.Where(t => t.PROJ_ID == p && t.Level == "pm" && t.Severity.ToLower() == "amber").FirstOrDefault<ProjectIssues>();
                if (issue != null) filteredIssues.Add(issue);
            }
            project = filteredIssues;
            //--------------------------------------
            string projId = "";
            foreach (PROJECT_PREFERENCE pr in ppr)
            {
                projId = finalissue.Where(t => t.PROJECT_ID == pr.PROJ_ID).Select(t => t.PROJECT_ID).FirstOrDefault();
                if (projId != pr.PROJ_ID || projId == null)
                {
                    ProjectIssues issueproj = new ProjectIssues();
                    issueproj.PRJ_NM = GetProjectName(pr.PROJ_ID, Date);
                    issueproj.IsNeedFocus = GetNeedFocusFlag(pr.PROJ_ID);
                    issueproj.PROJ_ID = pr.PROJ_ID;
                    issueproj.Level = "pm";
                    issueproj.RAG = "#237f00";
                    issueproj.Severity = "green";
                    project.Add(issueproj);
                }
            }
            if (project != null)
                project = project.OrderBy(t => t.PRJ_NM).ToList<ProjectIssues>();
            return Ok(project);
        }
        public string GetSeverity(List<PROJECT_ISSUE> finalissue, string projectId, string level)
        {
            List<PROJECT_ISSUE> severity = new List<PROJECT_ISSUE>();
            int highcount;
            int othercount;
            int mediumcount;
            foreach (PROJECT_ISSUE p in finalissue)
            {
                severity = finalissue.Where(m => m.PROJECT_ID == projectId).ToList<PROJECT_ISSUE>();
                highcount = severity.Where(t => t.SEVERITY.ToLower() == "high" && t.LEVEL == level).ToList<PROJECT_ISSUE>().Count;
                othercount = severity.Where(t => (t.SEVERITY.ToLower() == "low" || t.SEVERITY.ToLower() == "medium") && t.LEVEL == level).ToList<PROJECT_ISSUE>().Count;
                mediumcount = severity.Where(t => t.SEVERITY.ToLower() == "medium" && t.LEVEL == level).ToList<PROJECT_ISSUE>().Count;
                if (highcount >= 1)
                    return "red";
                else if (othercount <= 2 && othercount > 0)
                    return "amber";
                else if (othercount > 2)
                    return "red";
                else if (highcount == 0 || othercount == 0)
                    return "green";
            }
            return "";
        }
        public string GetProjectName(string projectid, DateTime Date)
        {
            string projName = "";
            List<PROJECT> projectlist = Cldb.PROJECT.GetAll().Where(t => t.END_DATE >= Date && t.CUST_ID.ToString() != null).ToList<PROJECT>();
            projName = projectlist.Where(t => t.PROJ_ID == projectid).Select(t => t.PROJ_NM).FirstOrDefault();
            return projName;
        }
        public string GetIssueRag(List<PROJECT_ISSUE> finalissue, string projectId, string level)
        {
            List<PROJECT_ISSUE> severity = new List<PROJECT_ISSUE>();
            int highcount;
            int othercount;
            int mediumcount;
            foreach (PROJECT_ISSUE p in finalissue)
            {
                severity = finalissue.Where(m => m.PROJECT_ID == projectId).ToList<PROJECT_ISSUE>();
                highcount = severity.Where(t => t.SEVERITY.ToLower() == "high" && t.LEVEL == level).ToList<PROJECT_ISSUE>().Count;
                othercount = severity.Where(t => (t.SEVERITY.ToLower() == "low" || t.SEVERITY.ToLower() == "medium") && t.LEVEL == level).ToList<PROJECT_ISSUE>().Count;
                mediumcount = severity.Where(t => t.SEVERITY.ToLower() == "medium" && t.LEVEL == level).ToList<PROJECT_ISSUE>().Count;
                if (highcount >= 1)
                    return "#f44336";
                else if (othercount > 2)
                    return "#f44336";
                else if (othercount <= 2 && mediumcount >= 1 && othercount > 0)
                    return "#FFC000";
                else if (othercount <= 2 && mediumcount < 1)
                    return "#FFFF00";
            }
            return "";
        }
        private bool GetNeedFocusFlag(string projectid)
        {
            bool focusflag;
            List<CRISP_SCORES_PROJECT> focus = CSPdb.CRISP_SCORES_PROJECT.GetAll().Where(t => t.PROJECT_ID == projectid).ToList<CRISP_SCORES_PROJECT>();
            if (focus.Count > 0)
            {
                //focusflag = focus.Where(t => t.PROJECT_ID == projectid).Select(t => t.NEED_FOCUS).FirstOrDefault();
                focusflag = focus.Where(t => t.PROJECT_ID == projectid).OrderByDescending(t => t.PUBLISH_DATE).Select(t => t.NEED_FOCUS).FirstOrDefault();
                return focusflag;
            }
            else
                return focusflag = false;
        }

