        [GET("GetCustomerProjectsName")]
        [ActionName("GetCustomerProjectsName")]
        [HttpGet]
        public IHttpActionResult GetCustomerProjectsName(string CustomerId)
        {
            List<PROJECT> projects = Cldb.PROJECT.GetAll().Where(t => t.PARENT_PROJ_ID == t.PROJ_ID && t.CUST_ID == CustomerId && t.PROJ_STATUS != "CLOSE").OrderBy(t => t.PROJ_NM).ToList();
            foreach (var item in projects)
            {
                if (!string.IsNullOrWhiteSpace(item.PROJ_ALIAS_NM))
                    item.PROJ_NM = item.PROJ_ALIAS_NM;
            }
            return Ok(projects.OrderBy(x => x.PROJ_NM).ToList());
        }

