        [GET("GetCountDataForNeedFocus")]
        [ActionName("GetCountDataForNeedFocus")]
        [HttpGet]
        public IHttpActionResult GetCountDataForNeedFocus(string projId)
        {
            NeedFocusData data = new NeedFocusData();
            data.PROJ_ID = projId;
            List<PROJECT_ISSUE> issuelist = CSPdb.PROJECT_ISSUE.GetAll().Where(m => m.ISACTIVE == true && m.PROJECT_ID == projId).ToList<PROJECT_ISSUE>();
            List<PROJECT_RISK> risklist = CSPdb.PROJECT_RISK.GetAll().Where(m => m.ISACTIVE == true && m.PROJECT_ID == projId).ToList<PROJECT_RISK>();
            List<PROJECT_ACTIONITEM> actionlist = CSPdb.PROJECT_ACTIONITEM.GetAll().Where(m => m.ISACTIVE == true && m.PROJECT_ID == projId).ToList<PROJECT_ACTIONITEM>();
            data.ISSUE_DUE = (issuelist.Where(t => t.TARGET_DATE < DateTime.Now && (t.SEVERITY.ToLower() == "high" || t.SEVERITY.ToLower() == "medium") && (t.STATUS == "Open" || t.STATUS == "In-Progress")).ToList<PROJECT_ISSUE>().Count);
            data.ISSUE_NO_DUE = (issuelist.Where(t => t.TARGET_DATE == null && (t.SEVERITY.ToLower() == "high" || t.SEVERITY.ToLower() == "medium") && (t.STATUS == "Open" || t.STATUS == "In-Progress")).ToList<PROJECT_ISSUE>().Count);
            data.RISK_DUE = (risklist.Where(t => (t.ACTION_TAKEN == null && t.TARGET_DATE < DateTime.Now) && t.STATUS != "Closed").ToList<PROJECT_RISK>().Count);
            data.RISK_TO_ISSUE = (risklist.Where(t => t.ACTION_TAKEN != null && t.TARGET_DATE < DateTime.Now && (t.STATUS != "Closed" || t.STATUS == "Occured")).ToList<PROJECT_RISK>().Count);
            data.RISK_NEXT = (issuelist.Where(t => t.IS_POTENTIAL_RISK == true && (t.SEVERITY.ToLower() == "high" || t.SEVERITY.ToLower() == "medium") && (t.STATUS == "Open" || t.STATUS == "In-Progress")).ToList<PROJECT_ISSUE>().Count);
            data.ACTION_ITEM_DUE = (actionlist.Where(t => (t.TARGET_DATE < DateTime.Now) && (t.PRIORITY == "High" || t.PRIORITY == "medium") && (t.STATUS == "Open")).ToList<PROJECT_ACTIONITEM>().Count);
            DateTime date = DateTime.Now;
            date = date.AddDays(7);
            data.ISSUE_NEXT = (issuelist.Where(t => t.TARGET_DATE > DateTime.Now && t.TARGET_DATE < date && (t.SEVERITY.ToLower() == "high" || t.SEVERITY.ToLower() == "medium") && (t.STATUS == "Open" || t.STATUS == "In-Progress")).ToList<PROJECT_ISSUE>().Count);
            data.ACTION_ITEM_NEXT = (actionlist.Where(t => t.TARGET_DATE > DateTime.Now && t.TARGET_DATE < date && (t.PRIORITY == "high" || t.PRIORITY == "medium") && t.STATUS == "Open").ToList<PROJECT_ACTIONITEM>().Count);
            return Ok(data);
        }



        [GET("GetDetailForNeedFocus")]
        [ActionName("GetDetailForNeedFocus")]
        [HttpGet]
        public IHttpActionResult GetDetailForNeedFocus(string projId, string Div)
        {
            List<PROJECT_RISK> risk = new List<PROJECT_RISK>();
            List<PROJECT_ISSUE> issue = new List<PROJECT_ISSUE>();
            List<PROJECT_ACTIONITEM> actionitem = new List<PROJECT_ACTIONITEM>();
            List<PROJECT_ISSUE> issuelist = CSPdb.PROJECT_ISSUE.GetAll().Where(m => m.ISACTIVE == true && m.PROJECT_ID == projId).ToList<PROJECT_ISSUE>();
            List<PROJECT_RISK> risklist = CSPdb.PROJECT_RISK.GetAll().Where(m => m.ISACTIVE == true && m.PROJECT_ID == projId).ToList<PROJECT_RISK>();
            List<PROJECT_ACTIONITEM> actionlist = CSPdb.PROJECT_ACTIONITEM.GetAll().Where(m => m.ISACTIVE == true && m.PROJECT_ID == projId).ToList<PROJECT_ACTIONITEM>();
            DateTime date = DateTime.Now;
            date = date.AddDays(7);
            if (Div == "div1")
            {
                risk = (risklist.Where(t => (t.ACTION_TAKEN == null && t.TARGET_DATE < DateTime.Now) && t.STATUS != "Closed").ToList<PROJECT_RISK>());
                return Ok(risk);
            }
            else if (Div == "div2")
            {
                issue = (issuelist.Where(t => t.IS_POTENTIAL_RISK == true && (t.SEVERITY.ToLower() == "high" || t.SEVERITY.ToLower() == "medium") && (t.STATUS == "Open" || t.STATUS == "In-Progress")).ToList<PROJECT_ISSUE>());
                return Ok(issue);
            }
            else if (Div == "div3")
            {
                issue = (issuelist.Where(t => t.TARGET_DATE < DateTime.Now && (t.SEVERITY.ToLower() == "high" || t.SEVERITY.ToLower() == "medium") && (t.STATUS == "Open" || t.STATUS == "In-Progress")).ToList<PROJECT_ISSUE>());
                return Ok(issue);
            }
            else if (Div == "div4")
            {
                issue = (issuelist.Where(t => t.TARGET_DATE == null && (t.SEVERITY.ToLower() == "high" || t.SEVERITY.ToLower() == "medium") && (t.STATUS == "Open" || t.STATUS == "In-Progress")).ToList<PROJECT_ISSUE>());
                return Ok(issue);
            }
            else if (Div == "div5")
            {
                issue = (issuelist.Where(t => t.TARGET_DATE > DateTime.Now && t.TARGET_DATE < date && (t.SEVERITY.ToLower() == "high" || t.SEVERITY.ToLower() == "medium") && (t.STATUS == "Open" || t.STATUS == "In-Progress")).ToList<PROJECT_ISSUE>());
                return Ok(issue);
            }
            else if (Div == "div6")
            {
                actionitem = (actionlist.Where(t => (t.TARGET_DATE < DateTime.Now) && (t.PRIORITY == "High" || t.PRIORITY == "medium") && (t.STATUS == "Open")).ToList<PROJECT_ACTIONITEM>());
                return Ok(actionitem);
            }
            else if (Div == "div7")
            {
                actionitem = (actionlist.Where(t => t.TARGET_DATE > DateTime.Now && t.TARGET_DATE < date && (t.PRIORITY == "high" || t.PRIORITY == "medium") && t.STATUS == "Open").ToList<PROJECT_ACTIONITEM>());
                return Ok(actionitem);

            }
            else if (Div == "div8")
            {
                risk = risklist.Where(t => t.ACTION_TAKEN != null && t.TARGET_DATE < DateTime.Now && (t.STATUS != "Closed" || t.STATUS == "Occured")).ToList<PROJECT_RISK>();
                return Ok(risk);
            }
            return Ok();
        }
        [GET("GetProjectComplainceInfoFail")]
        [ActionName("GetProjectComplainceInfoFail")]
        [HttpGet]

        public IHttpActionResult GetProjectComplainceInfoFail()
        {
            List<string> PROJECT_IDs = new List<string>();
            if (Request.Headers.Contains("projectIds"))
                PROJECT_IDs = Request.Headers.GetValues("projectIds").ToList<string>()[0].ToString().Split(',').ToList<string>();
            List<string> empInfoq = Cldb.PROJECT_RESOURCE.GetAll().Where(t => PROJECT_IDs.Contains(t.PROJ_ID) && t.BILL_FLG == true && t.END_DATE >= (DateTime.Now)).Select(t => t.EMP_ID).Distinct().ToList<string>();
            //List<int> eligibleemp = Cldb.EMP_INFO.GetAll().Where(t => empInfoq.Contains(t.EMP_ID) && t.CSM_TITLE_ID == 3).Select(t => t.EMP_ID).ToList<int>();
            List<string> empId = new List<string>();
            List<string> projs = new List<string>();
            List<PROJECT_COMPLIANCE_INFO> infolist = new List<PROJECT_COMPLIANCE_INFO>();
            List<COMPLIANCE_TRAINING_ASSESSMENT_RESULT> list = new List<COMPLIANCE_TRAINING_ASSESSMENT_RESULT>();
            List<string> passedEmpId = new List<string>();
            COMPLIANCE_TRAINING_ASSESSMENT_RESULT passCount = new COMPLIANCE_TRAINING_ASSESSMENT_RESULT();
            List<COMPLIANCE_TRAINING_ASSESSMENT_RESULT> traininglist = Cldb.COMPLIANCE_TRAINING_ASSESSMENT_RESULT.GetAll().Where(t => empInfoq.Contains(t.EMP_ID)).ToList<COMPLIANCE_TRAINING_ASSESSMENT_RESULT>();
            List<int> compId = new List<int>();
            Boolean trueFlag = true;
            foreach (string p in PROJECT_IDs.Distinct())
            {
                compId = Cldb.PROJECT_COURSE_MAPPING.GetAll().Where(t => t.PROJECT_ID == p && t.ISACTIVE == true).Select(t => t.COURSE_ID).ToList<int>();
                PROJECT_COMPLIANCE_INFO info = new PROJECT_COMPLIANCE_INFO();
                empId = Cldb.PROJECT_RESOURCE.GetAll().Where(t => t.PROJ_ID == p && t.BILL_FLG == true && t.END_DATE >= (DateTime.Now)).Select(t => t.EMP_ID).Distinct().ToList<string>();
                empId = Cldb.EMP_INFO.GetAll().Where(x => empId.Contains(x.EMP_ID) && x.DOR == null).Select(x => x.EMP_ID).ToList();
                if (empId.Count != 0)
                {
                    passedEmpId = new List<string>();
                    foreach (string i in empId)
                    {
                        trueFlag = true;
                        PROJECT_COMPLIANCE_DATA projectComplainceData = new PROJECT_COMPLIANCE_DATA();
                        PROJECT_COMPLIANCE_DATA projectComplainceDataPass = new PROJECT_COMPLIANCE_DATA();
                        COMPLIANCE_TRAINING_ASSESSMENT_RESULT result = new COMPLIANCE_TRAINING_ASSESSMENT_RESULT();
                        EMP_INFO empInfo = Cldb.EMP_INFO.GetAll().Where(t => t.EMP_ID == i).FirstOrDefault();
                        foreach (int c in compId)
                        {
                            result = new COMPLIANCE_TRAINING_ASSESSMENT_RESULT();
                            PROJECT_COMPLIANCE_RESULT pcresult = new PROJECT_COMPLIANCE_RESULT();
                            int count;

                            count = traininglist.Where(t => t.EMP_ID == i && t.TITLE_ID == c).Count();
                            if (count > 1)
                            {
                                list = traininglist.Where(t => t.EMP_ID == i && t.TITLE_ID == c).ToList<COMPLIANCE_TRAINING_ASSESSMENT_RESULT>();
                                result = list.OrderByDescending(s => s.IMPORT_DATE).FirstOrDefault();
                            }
                            else if (count == 1)
                            {
                                result = traininglist.Where(t => t.EMP_ID == i && t.TITLE_ID == c).FirstOrDefault();
                            }
                            else if (count == 0)
                            {
                                if (info.PROJ_ID == null)
                                {
                                    info.PROJ_ID = p;
                                    info.PROJ_NM = GetProjectName(p);
                                    projectComplainceData.EMP_NAME = empInfo.FRST_NM;
                                    pcresult.TITLE_NAME = GetTitleName(c);
                                    pcresult.IMPORT_DATE = DateTime.Now;
                                    projectComplainceData.RESULT.Add(pcresult);
                                }
                                else
                                {
                                    projectComplainceData.EMP_NAME = empInfo.FRST_NM;
                                    pcresult.TITLE_NAME = GetTitleName(c);
                                    pcresult.IMPORT_DATE = DateTime.Now;
                                    projectComplainceData.RESULT.Add(pcresult);
                                }
                            }
                            if (result != null && result.RESULT == "Failed")
                            {
                                if (info.PROJ_ID == null)
                                {
                                    info.PROJ_ID = p;
                                    info.PROJ_NM = GetProjectName(p);
                                    projectComplainceData.EMP_NAME = empInfo.FRST_NM;
                                    pcresult.TITLE_NAME = GetTitleName(c);
                                    pcresult.IMPORT_DATE = result.IMPORT_DATE;
                                    projectComplainceData.RESULT.Add(pcresult);
                                }
                                else
                                {
                                    projectComplainceData.EMP_NAME = empInfo.FRST_NM;
                                    pcresult.TITLE_NAME = GetTitleName(c);
                                    pcresult.IMPORT_DATE = result.IMPORT_DATE;
                                    projectComplainceData.RESULT.Add(pcresult);
                                }

                            }
                            passCount = Cldb.COMPLIANCE_TRAINING_ASSESSMENT_RESULT.GetAll().Where(t => t.EMP_ID == i && t.TITLE_ID == c).OrderByDescending(t => t.ID).FirstOrDefault();
                            if (passCount == null || passCount.RESULT == "Fail")
                                trueFlag = false;
                        }
                        if (projectComplainceData.EMP_NAME != null && projectComplainceData.RESULT.Count != 0)
                            info.PROJECT_COMPLIANCE.Add(projectComplainceData);

                        if (trueFlag == true)
                            passedEmpId.Add(i);
                    }
                    var empCount = Convert.ToDecimal(empId.Count);
                    var resultCount = Decimal.Divide(passedEmpId.Count, empCount);
                    info.COMPLIANCE_PERCENT = (resultCount * 100).ToString("0.00");
                    if (info.PROJ_ID != null)
                        infolist.Add(info);
                }

            }

            return Ok(infolist);
        }
