        public string GetTitleName(int TitleId)
        {
            string TITLE_NAME;
            TITLE_NAME = Cldb.COMPLIANCE_TRAINING_ASSESSMENT_HEADER.GetAll().Where(t => t.ID == TitleId).Select(t => t.COMPLIANCE_TRAINING_TITLE).FirstOrDefault();
            return TITLE_NAME;
        }
        public string GetProjectName(string ProjId, bool fullname = false)
        {
            PROJECT Project;
            Project = Cldb.PROJECT.GetAll().FirstOrDefault(t => t.PROJ_ID == ProjId);
            if (Project == null) return string.Empty;
            if (fullname)
                return Project.PROJ_NM;
            return Project.PROJ_ALIAS_NM ?? Project.PROJ_NM;
        }

