        [GET("GetCSATData")]
        [ActionName("GetCSATData")]
        [HttpGet]

        public IHttpActionResult GetCSATData(string month, int year)
        {

            List<string> PROJECT_IDs = new List<string>();
            if (Request.Headers.Contains("projectIds"))
                PROJECT_IDs = Request.Headers.GetValues("projectIds").ToList<string>()[0].ToString().Split(',').ToList<string>();
            string quarter = "";
            int yeardiv;
            yeardiv = year % 100;
            if (month == "Apr" || month == "May" || month == "Jun")
                quarter = "Q4" + " " + +(year - 1) + "-" + (yeardiv);
            if (month == "Jul" || month == "Aug" || month == "Sep")
                quarter = "Q1" + " " + +year + "-" + (yeardiv + 1);
            if (month == "Oct" || month == "Nov" || month == "Dec")
                quarter = "Q2" + " " + +year + "-" + (yeardiv + 1);
            if (month == "Jan" || month == "Feb" || month == "Mar")
                quarter = "Q3" + " " + +(year - 1) + "-" + (yeardiv);

            PROJECT_CSAT_COUNT count = new PROJECT_CSAT_COUNT();
            PROJECT_CSAT_DATA csatdata = new PROJECT_CSAT_DATA();
            List<PROJECT_CSAT_DATA> data = CSPdb.AppRepo.GetCSSTable(quarter).ToList();
            //List<PROJECT_CSAT_DATA> data = CSPdb.PROJECT_CSAT_DATA.GetAll().Where(t => t.YEAR_QUARTER == quarter).ToList<PROJECT_CSAT_DATA>();
            foreach (string p in PROJECT_IDs)
            {
                csatdata = data.Where(t => t.PROJECT_ID == p && (t.MIN_SCORE == 4 && t.NPS_SCORE >= 9)).FirstOrDefault();
                if (csatdata != null)
                {
                    PROJECT_CSAT_DATA csdata = new PROJECT_CSAT_DATA();
                    csdata = csatdata;
                    csatdata.CUSTOMER_ID = GetCustomerTitle(p);
                    csdata.PROJECT_ID = GetProjectName(p);
                    count.CSAT_4_DATA.Add(csdata);
                    count.NPS_HIGH_DATA.Add(csdata);

                }
                csatdata = data.Where(t => t.PROJECT_ID == p && (t.MIN_SCORE == 4 && t.NPS_SCORE < 9)).FirstOrDefault();
                if (csatdata != null)
                {
                    PROJECT_CSAT_DATA csdata = new PROJECT_CSAT_DATA();
                    csdata = csatdata;
                    csatdata.CUSTOMER_ID = GetCustomerTitle(p);
                    csdata.PROJECT_ID = GetProjectName(p);
                    count.CSAT_4_DATA.Add(csdata);
                    count.NPS_LOW_DATA.Add(csdata);

                }
                csatdata = data.Where(t => t.PROJECT_ID == p && (t.MIN_SCORE == 5 && t.NPS_SCORE >= 9)).FirstOrDefault();
                if (csatdata != null)
                {
                    PROJECT_CSAT_DATA csdata = new PROJECT_CSAT_DATA();
                    csdata = csatdata;
                    csatdata.CUSTOMER_ID = GetCustomerTitle(p);
                    csdata.PROJECT_ID = GetProjectName(p);
                    count.CSAT_5_DATA.Add(csdata);
                    count.NPS_HIGH_DATA.Add(csdata);
                }
                csatdata = data.Where(t => t.PROJECT_ID == p && (t.MIN_SCORE == 5 && t.NPS_SCORE < 9)).FirstOrDefault();
                if (csatdata != null)
                {
                    PROJECT_CSAT_DATA csdata = new PROJECT_CSAT_DATA();
                    csdata = csatdata;
                    csatdata.CUSTOMER_ID = GetCustomerTitle(p);
                    csdata.PROJECT_ID = GetProjectName(p);
                    count.CSAT_5_DATA.Add(csdata);
                    count.NPS_LOW_DATA.Add(csdata);
                }
                csatdata = data.Where(t => t.PROJECT_ID == p && (t.MIN_SCORE < 4 && t.NPS_SCORE >= 9)).FirstOrDefault();
                if (csatdata != null)
                {
                    PROJECT_CSAT_DATA csdata = new PROJECT_CSAT_DATA();
                    csdata = csatdata;
                    csatdata.CUSTOMER_ID = GetCustomerTitle(p);
                    csdata.PROJECT_ID = GetProjectName(p);
                    count.CSAT_3_DATA.Add(csdata);
                    count.NPS_HIGH_DATA.Add(csdata);
                }
                csatdata = data.Where(t => t.PROJECT_ID == p && (t.MIN_SCORE < 4 && t.NPS_SCORE < 9)).FirstOrDefault();
                if (csatdata != null)
                {
                    PROJECT_CSAT_DATA csdata = new PROJECT_CSAT_DATA();
                    csdata = csatdata;
                    csatdata.CUSTOMER_ID = GetCustomerTitle(p);
                    csdata.PROJECT_ID = GetProjectName(p);
                    count.CSAT_3_DATA.Add(csdata);
                    count.NPS_LOW_DATA.Add(csdata);
                }

                count.QUARTER = quarter;
            }
            return Ok(count);
        }
        public string GetCustomerTitle(string Proj_Id)
        {
            PROJECT p = Cldb.PROJECT.GetAll().Where(t => t.PROJ_ID == Proj_Id).FirstOrDefault();
            string cname = Cldb.CUSTOMER.GetAll().Where(t => t.CUST_ID == p.CUST_ID).Select(t => t.CUST_ID).FirstOrDefault();
            return cname;
        }

        [GET("CustomerProjects")]
        [ActionName("CustomerProjects")]
        [HttpGet]
        public IHttpActionResult GetCustomerProjects(string EmpId, string search, string direction, int pageIndex, int pageSize)
        {
            var projects = GetProjectListForUser(EmpId).ToList();
            List<string> arrProjects = projects.Select(t => t.PROJ_ID).ToList<string>();
            List<CUSTOMER_PROJECTS> cust_proj = CSPdb.CUSTOMER_PROJECTS.GetAll().Where(t => arrProjects.Contains(t.PROJ_ID)).ToList<CUSTOMER_PROJECTS>();
            List<int> arrCustomers = cust_proj.Select(t => t.CUSTOMER_USER_ID).ToList<int>();
            List<CustomerProjects> cust_user = CSPdb.AppRepo.CustomerProjects().Where(t => arrCustomers.Contains(t.ID)).OrderBy(t => t.EMAILID).ThenBy(t => t.CUST_NM).ToList<CustomerProjects>();

            //-------------------------------
            var total = cust_user.Select(p => p.CUST_ID).Count();

            var skip = pageSize * (pageIndex - 1);

            //var canPage = skip < total;

            //if (canPage) // do what you wish if you can page no further
            //    return;

            var result = cust_user.Select(p => p)
                         .Skip(skip)
                         .Take(pageSize)
                         .ToList();

            CustResult res = new CustResult();
            res.Total = total;
            res.Data = result;

            //List<object> r = new List<object>();
            //r.Add(total);
            //r.Add(result);
            return Ok(result);
        }
