        [GET("Delivery")]
        [ActionName("Delivery")]
        [HttpGet]
        public IHttpActionResult GetDelivery(string projId, string publishDate, string range)
        {
            string PROJECT_ID = projId;
            DateTime PUBLISH_DATE = DateTime.Parse(publishDate);
            enDateRange DATE_RANGE = (enDateRange)Enum.Parse(typeof(enDateRange), range);
            DateRange wdays = new DateRange(PUBLISH_DATE, DATE_RANGE);
            PROJECT_DELIVERY delivery = CSPdb.PROJECT_DELIVERY.GetAll().Where(t => t.PROJECT_ID == PROJECT_ID && t.PUBLISH_DATE >= wdays.StartDate && t.PUBLISH_DATE <= wdays.EndDate).FirstOrDefault<PROJECT_DELIVERY>();
            if (delivery == null)
                delivery = new PROJECT_DELIVERY();
            return Ok(new PROJECT_DELIVERY_DETAILS() { delivery = delivery, daterange = wdays });
        }

