        [GET("GetKPIDefinitions")]
        [ActionName("GetKPIDefinitions")]
        [HttpGet]
        public IHttpActionResult GetKPIDefinitions(string CustomerId, string ProjectId)
        {
            var goalIds = new List<int>();

            goalIds = CSPdb.KPI_GOALS.GetAll().Where(t => t.CUSTOMER_ID == CustomerId && t.PROJECT_ID == ProjectId && t.ISACTIVE).Select(t => t.ID).ToList();
            var kpis = CSPdb.KPI.GetAll().Where(t => goalIds.Contains(t.GOAL_ID) && t.ISACTIVE == true).ToList();
            List<KPIWithTargets> KPIWithTargets = new List<KPIWithTargets>();
            foreach (KPI kpi in kpis)
            {
                KPIWithTargets kpiWithTarget = new Model.CSP.KPIWithTargets();
                kpiWithTarget.ID = kpi.ID;
                kpiWithTarget.CUSTOMER_ID = kpi.CUSTOMER_ID;
                kpiWithTarget.PROJECT_ID = kpi.PROJECT_ID;
                kpiWithTarget.GOAL_ID = kpi.GOAL_ID;
                kpiWithTarget.SERVICE_AREA = kpi.SERVICE_AREA;
                kpiWithTarget.ABBREVIATION = kpi.ABBREVIATION;
                kpiWithTarget.KPI_NAME = kpi.KPI_NAME;
                kpiWithTarget.KPI_UNIQUEID = kpi.KPI_UNIQUEID;
                kpiWithTarget.SUPPORT_WINDOW = kpi.SUPPORT_WINDOW;
                kpiWithTarget.FREQUENCY = kpi.FREQUENCY;
                kpiWithTarget.PRIORITY = kpi.PRIORITY;
                kpiWithTarget.SLA_TARGET_UNIT_OF_MEASUREMENT = kpi.SLA_TARGET_UNIT_OF_MEASUREMENT;
                kpiWithTarget.DISPLAY_ORDER = kpi.DISPLAY_ORDER;
                kpiWithTarget.CHART_TYPE = kpi.CHART_TYPE;
                kpiWithTarget.SHOW_IN_CHART = kpi.SHOW_IN_CHART;
                kpiWithTarget.GLOBAL_KPI_CATEGORY_ID = kpi.GLOBAL_KPI_CATEGORY_ID;
                kpiWithTarget.IS_SOW_COMMITMENT = kpi.IS_SOW_COMMITMENT;
                kpiWithTarget.CREATED_BY = kpi.CREATED_BY;
                kpiWithTarget.CREATED_DATE = kpi.CREATED_DATE;
                kpiWithTarget.UPDATED_BY = kpi.UPDATED_BY;
                kpiWithTarget.UPDATED_DATE = kpi.UPDATED_DATE;
                kpiWithTarget.ISACTIVE = kpi.ISACTIVE;
                kpiWithTarget.KPI_TARGETS = CSPdb.KPI_TARGETS.GetAll().Where(t => t.KPI_ID == kpi.ID && t.ISACTIVE == true).OrderBy(t => t.START_DATE).ToList<KPI_TARGETS>();
                kpiWithTarget.KPI_MASTER_ID = kpi.KPI_MASTER_ID;

                foreach (KPI_TARGETS t in kpiWithTarget.KPI_TARGETS)
                {
                    t.START_DATE = t.START_DATE.ToUniversalTime();
                    t.END_DATE = t.END_DATE.ToUniversalTime();
                }

                kpiWithTarget.SERVICE_TOWER_ID = getServiceTowersMappedToKpi(kpi.ID);
                KPIWithTargets.Add(kpiWithTarget);

            }

            return Ok(KPIWithTargets);
        }


        [GET("GetGlobalKpiCategories")]
        [ActionName("GetGlobalKpiCategories")]
        [HttpGet]
        public IHttpActionResult GetGlobalKpiCategories()
        {
            List<PERSPECTIVE_LIST> kpis = CSPdb.AppRepo.GetGlobalCategory();
            List<GLOBAL_CAT_LIST> result = new List<GLOBAL_CAT_LIST>();
            var catkpis = kpis.GroupBy(t => t.PERSPECTIVE_NAME);
            foreach (var cat in catkpis)
            {
                GLOBAL_CAT_LIST list = new GLOBAL_CAT_LIST();
                list.PERSPECTIVE = cat.Key;
                list.CATEGORY = cat.ToList().ToList<PERSPECTIVE_LIST>();
                result.Add(list);
            }
            return Ok(result);
        }

