            List<int> kpiIds = CSPdb.KPI.GetAll().Where(t => t.CUSTOMER_ID == CustomerId && t.PROJECT_ID == ProjectId && t.ISACTIVE == true).ToList<KPI>().Select(u => u.ID).ToList<int>();
            List<KPI_DETAILS> kpis = CSPdb.KPI_DETAILS.GetAll().Where(t => kpiIds.Contains(t.KPI_ID) && t.ISACTIVE == true).ToList<KPI_DETAILS>();
            return Ok(kpis);
        }

