        [GET("GetHighlightsBydate")]
        [ActionName("GetHighlightsByDate")]
        [HttpGet]
        public IHttpActionResult GetHighlightsByDate(string CustomerId, string ProjectId, DateTime CurrentDate, string Period)
        {
            DateRange range = new DateRange(CurrentDate, enDateRange.Monthly);
            List<HIGHLIGHTS> highlights = CSPdb.HIGHLIGHTS.GetAll().Where(t => t.CUSTOMER_ID == CustomerId && t.PROJECT_ID == ProjectId && t.PUBLISH_DATE >= range.StartDate && t.PUBLISH_DATE <= range.EndDate && t.ISACTIVE == true).ToList<HIGHLIGHTS>();
            return Ok(highlights);
        }

        [GET("GetHighlights")]
        [ActionName("GetHighlights")]
        [HttpGet]
        public IHttpActionResult GetHighlights(string CustomerId, string ProjectId)
        {
            List<HIGHLIGHTS> highlights = CSPdb.HIGHLIGHTS.GetAll().Where(t => t.CUSTOMER_ID == CustomerId && t.PROJECT_ID == ProjectId && t.ISACTIVE == true).OrderByDescending(u => u.PUBLISH_DATE).ToList<HIGHLIGHTS>();
            return Ok(highlights);
        }

        [GET("GetNotesForCustomer")]
        [ActionName("GetNotesForCustomer")]
        [HttpGet]
        public IHttpActionResult GetNotesForCustomer(string CustomerId)
        {
            List<HIGHLIGHTS> result = new List<HIGHLIGHTS>();
            List<string> projids = Cldb.PROJECT.GetAll().Where(x => x.CUST_ID == CustomerId).Select(x => x.PARENT_PROJ_ID).Distinct().ToList();
            if (projids.Count == 1)
            {
                string id = projids[0];
                result = CSPdb.HIGHLIGHTS.GetAll().Where(x => x.CUSTOMER_ID == CustomerId && (x.PROJECT_ID == id || x.PROJECT_ID == null) && x.ISACTIVE).ToList();
            }
            else
            {
                result = CSPdb.HIGHLIGHTS.GetAll().Where(x => x.CUSTOMER_ID == CustomerId && x.PROJECT_ID == null && x.PORTFOLIO_ID == null && x.SERVICE_AREA == null && x.ISACTIVE).ToList();
            }

            return Ok(result);
        }



