        [ActionName("GetNotesForAPeriod")]
        [HttpGet]
        public IHttpActionResult GetNotesForAPeriod(string CustomerId, DateTime StartDate)
        {


            return Ok(GetNotesForPeriodPvt(CustomerId, StartDate));
