        private List<HIGHLIGHTS> GetNotesForPeriodPvt(string customerId, DateTime startDate)
        {
            var result = new List<HIGHLIGHTS>();
            DateRange range = new DateRange(startDate, enDateRange.Monthly);
            List<string> projids = Cldb.PROJECT.GetAll().Where(x => x.CUST_ID == customerId).Select(x => x.PARENT_PROJ_ID).Distinct().ToList();
            if (projids.Count == 1)
            {
                string id = projids[0];
                result = CSPdb.HIGHLIGHTS.GetAll().Where(x => x.CUSTOMER_ID == customerId && (x.PROJECT_ID == id || x.PROJECT_ID == null) && x.ISACTIVE && x.PUBLISH_DATE >= range.StartDate && x.PUBLISH_DATE <= range.EndDate).ToList();
            }
            else
            {
                result = CSPdb.HIGHLIGHTS.GetAll().Where(x => x.CUSTOMER_ID == customerId && x.PROJECT_ID == null && x.PORTFOLIO_ID == null && x.SERVICE_AREA == null && x.ISACTIVE && x.PUBLISH_DATE >= range.StartDate && x.PUBLISH_DATE <= range.EndDate).ToList();
            }
            return result;
        }

