        [POST("GetKpiDetailsForPerspective")]
        [ActionName("GetKpiDetailsForPerspective")]
        [HttpPost]
        public IHttpActionResult GetKpiDetailsForPerspective(HttpRequestMessage request)
        {
            string empId = GetHeaderDetails_String("empId");
            string custId = GetHeaderDetails_String("custId");
            List<string> projIds = GetHeaderDetails_Array("projId");
            DateTime StartDate = GetHeaderDetails_Date("startDate");
            DateTime EndDate = GetHeaderDetails_Date("endDate");
            EndDate = EndDate.AddMonths(1).AddMinutes(-1);
            string perspective = GetHeaderDetails_String("perspective");
            string color = GetHeaderDetails_String("color");
            color = GetDarkColor(color);

            var projects = GetProjectListForUser(empId);
            //var query = Cldb.AppRepo.Projects(Convert.ToInt32(empId), "");
            List<string> empProjects = projects.Select(t => t.PROJ_ID).ToList();

            List<KPI_DETAILS_EXTENDED> kpis = new List<KPI_DETAILS_EXTENDED>();
            kpis = CSPdb.AppRepo.GetKPIDetails(StartDate, EndDate);
            if (custId == "-1" || custId == string.Empty)
                //For All Customers
                kpis = kpis.Where(t => empProjects.Contains(t.PROJECT_ID) && t.KPI_ACTUAL != "" && t.SLA_TARGET_HIGH_VALUE != null).ToList();
            else
                //For specific customer and project(s)
                kpis = kpis.Where(t => empProjects.Contains(t.PROJECT_ID) && (projIds.Contains(t.PROJECT_ID) && t.CUSTOMER_ID == custId) && t.KPI_ACTUAL != "" && t.SLA_TARGET_HIGH_VALUE != null).ToList();

            FillDetails(ref kpis);
            kpis = kpis.Where(t => t.RAG == color).ToList();
            ////
            var tmpCustomer = kpis.GroupBy(t => t.CUSTOMER_ID);


            List<GLOBAL_PERSPECTIVE> perstectives = new List<GLOBAL_PERSPECTIVE>();
            if (!perspective.StartsWith("Overall"))
                perstectives = CSPdb.GLOBAL_PERSPECTIVE.GetAll().Where(t => t.GROUP_CODE == "KPI" && t.SHORT_DESC == perspective).ToList();
            else
                perstectives = CSPdb.GLOBAL_PERSPECTIVE.GetAll().Where(t => t.GROUP_CODE == "KPI").ToList();

            List<HealthReportCustomer> customers = new List<HealthReportCustomer>();
            foreach (var c in tmpCustomer)
            {
                HealthReportCustomer cust = new HealthReportCustomer(c.ToList(), perstectives);
                customers.Add(cust);
            }

            List<List<tableCell>> HelthReportTable = GetHelthReportTable(customers, perstectives);
            //>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

            List<List<tableCell>> newTable = new List<List<tableCell>>();

            //Remove projects which has no kpis
            foreach (HealthReportCustomer customer in customers)
            {
                List<HealthReportProject> ProjectsWithKpi = new List<HealthReportProject>();
                foreach (HealthReportProject proj in customer.PROJECTS)
                {
                    int kpiCount = 0;
                    foreach (KpiGlobalPerspective p in proj.KPI_GLOBAL_PERSPECTIVE)
                    {
                        kpiCount += p.KPIDetails.Count;
                    }
                    if (kpiCount > 0)
                        ProjectsWithKpi.Add(proj);
                }
                customer.PROJECTS = ProjectsWithKpi;
            }
            //------------------------------


            foreach (HealthReportCustomer customer in customers)
            {
                List<tableCell> row = new List<tableCell>();
                tableCell custcell = new tableCell();
                custcell.text = customer.CUSTOMER_NM;
                custcell.rowSpan = customer.PROJECTS.Sum(branch => branch.KPI_GLOBAL_PERSPECTIVE.Sum(subbranch => subbranch.KPIDetails.Count));
                row.Add(custcell);

                for (int iCnt = 0; iCnt < customer.PROJECTS.Count; iCnt++)
                {


                    if (iCnt > 0)
                        row = new List<tableCell>();
                    //Project Cell
                    tableCell projcell = new tableCell();
                    projcell.text = customer.PROJECTS[iCnt].PROJECT_NM;
                    projcell.rowSpan = customer.PROJECTS.Sum(branch => branch.KPI_GLOBAL_PERSPECTIVE.Sum(subbranch => subbranch.KPIDetails.Count));
                    projcell.rowSpan = customer.PROJECTS[iCnt].KPI_GLOBAL_PERSPECTIVE.Sum(subbranch => subbranch.KPIDetails.Count);
                    row.Add(projcell);

                    int jCnt = 0;
                    foreach (KpiGlobalPerspective perspect in customer.PROJECTS[iCnt].KPI_GLOBAL_PERSPECTIVE)
                    {
                        if (perspect.KPIDetails.Count > 0)
                        {
                            if (jCnt > 0)
                                row = new List<tableCell>();
                            //Project Cell
                            tableCell Perspectivecell = new tableCell();
                            Perspectivecell.text = perspect.GLOBAL_PERSPECTIVE_NM;
                            Perspectivecell.rowSpan = perspect.KPIDetails.Count;
                            row.Add(Perspectivecell);

                            for (int kCnt = 0; kCnt < perspect.KPIDetails.Count; kCnt++)
                            {
                                if (kCnt > 0)
                                    row = new List<tableCell>();

                                //GoalId
                                tableCell kpicell = new tableCell();
                                kpicell.text = perspect.KPIDetails[kCnt].GOAL_ID;
                                kpicell.rowSpan = 1;
                                row.Add(kpicell);
                                //KPI Area
                                kpicell = new tableCell();
                                kpicell.text = perspect.KPIDetails[kCnt].SERVICE_AREA;
                                kpicell.rowSpan = 1;
                                row.Add(kpicell);
                                //KPI Description
                                kpicell = new tableCell();
                                kpicell.text = perspect.KPIDetails[kCnt].KPI_NAME;
                                kpicell.rowSpan = 1;
                                row.Add(kpicell);
                                //KPI Priority
                                kpicell = new tableCell();
                                kpicell.text = perspect.KPIDetails[kCnt].PRIORITY;
                                kpicell.rowSpan = 1;
                                row.Add(kpicell);
                                //KPI Support Window
                                kpicell = new tableCell();
                                kpicell.text = perspect.KPIDetails[kCnt].SUPPORT_WINDOW;
                                kpicell.rowSpan = 1;
                                row.Add(kpicell);
                                //KPI Period Date
                                kpicell = new tableCell();
                                kpicell.text = perspect.KPIDetails[kCnt].PERIOD.ToString("dd-MMM-yy");
                                kpicell.rowSpan = 1;
                                kpicell.noWrap = true;
                                row.Add(kpicell);

                                //KPI Target Low
                                kpicell = new tableCell();
                                kpicell.text = perspect.KPIDetails[kCnt].SLA_TARGET_LOW_DESCRIPTION;
                                kpicell.rowSpan = 1;
                                row.Add(kpicell);
                                //KPI Target Medium
                                kpicell = new tableCell();
                                kpicell.text = perspect.KPIDetails[kCnt].SLA_TARGET_MEDIUM_DESCRIPTION;
                                kpicell.rowSpan = 1;
                                row.Add(kpicell);
                                //KPI Target High
                                kpicell = new tableCell();
                                kpicell.text = perspect.KPIDetails[kCnt].SLA_TARGET_HIGH_DESCRIPTION;
                                kpicell.rowSpan = 1;
                                row.Add(kpicell);
                                //KPI Target Very High
                                kpicell = new tableCell();
                                kpicell.text = perspect.KPIDetails[kCnt].SLA_TARGET_VERYHIGH_DESCRIPTION;
                                kpicell.rowSpan = 1;
                                row.Add(kpicell);






                                //KPI Actual
                                kpicell = new tableCell();
                                kpicell.text = perspect.KPIDetails[kCnt].KPI_ACTUAL;
                                kpicell.color = perspect.KPIDetails[kCnt].RAG;
                                kpicell.noWrap = true;
                                kpicell.rowSpan = 1;
                                row.Add(kpicell);

                                newTable.Add(row);
                            }
                            jCnt += 1;
                        }

                    }
                }
            }
            //>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
            return Ok(newTable);
        }

