        private int GetHeaderDetails_Int(string key)
        {
            string sValue = string.Empty;
            int iValue = -1;
            if (Request.Headers.Contains(key))
            {
                sValue = Request.Headers.GetValues(key).ToList()[0];
                var isNumeric = int.TryParse(sValue, out iValue);
                if (!isNumeric)
                    iValue = -1;
            }
            return iValue;
        }
        private DateTime GetHeaderDetails_Date(string key)
        {
            DateTime sValue = DateTime.Now;
            if (Request.Headers.Contains(key))
                sValue = Convert.ToDateTime(Request.Headers.GetValues(key).ToList()[0]);
            return sValue;
        }
        private List<string> GetHeaderDetails_Array(string key)
        {
            List<string> sValue = new List<string>();
            if (Request.Headers.Contains(key))
                sValue = Request.Headers.GetValues(key).ToList<string>()[0].ToString().Split(',').ToList<string>();
            return sValue;
        }


