        [GET("GetRiskDetailsByCustomerId")]
        [ActionName("GetRiskDetailsByCustomerId")]
        [HttpGet]
        public IHttpActionResult GetRiskDetailsByCustomerId(string customerId, bool allproj)
        {
            var empId = this.GetHeaderDetails_String("empId");
            var projectsForUser = GetProjectListForUser(empId);
            var projects = GetProjectListForUser(empId, customerId);
            string ProjIds = string.Join(",", projects.Select(t => t.PROJ_ID).ToArray());

            var projIdsForUserList = projectsForUser.Select(p => p.PROJ_ID).ToList();
            var projectIdsList = projects.Select(p => p.PROJ_ID).ToList();
            bool isEditAllowed = projIdsForUserList.Any(projId => projectIdsList.Contains(projId));

            List<PROJECT_RISK_EXT> riskDetails = CSPdb.AppRepo.GetRiskDetailsByCustomerId(ProjIds, allproj).ToList();
            foreach (PROJECT_RISK_EXT risk in riskDetails)
            {
                risk.IS_EDIT_ALLOWED = projectsForUser.Any(x => x.PROJ_ID == risk.PROJECT_ID);
            }

            var overallData = new
            {
                RiskDetails = riskDetails,
                EditAllowed = isEditAllowed
            };
            return Ok(overallData);
        }

