        private HighChartsCombination IssueChartHighChart(string CustomerId, List<string> Projects, DateRange range)
        {
            //Data
            List<PROJECT_ISSUE> issues = CSPdb.PROJECT_ISSUE.GetAll().Where(t => Projects.Contains(t.PROJECT_ID) && t.ISACTIVE == true).ToList<PROJECT_ISSUE>();


            //chart

            HighChartsCombination chart = new HighChartsCombination();

            chart.title.text = "";
            chart.yAxis = new yAxis_Combination();
            chart.yAxis.title.text = "In Numbers";
            chart.xAxis.categories = new List<string>() { "Open", "In-Progress", "Closed" };
            chart.labels = new labels() { items = new List<labelsItem>() { new labelsItem() { html = "Total Issues", style = new style() { left = "0x", top = "-10px", color = "grey" } } } };
            chart.series = new List<object>();
            chart.series.Add(new seriesItem()
            {
                type = "column",
                name = "High",
                data = new List<decimal>() {
                    issues.Where(t => t.STATUS == "Open" && t.SEVERITY.ToLower() == "high").ToList().Count,
                        issues.Where(t => t.STATUS == "In-Progress" && t.SEVERITY.ToLower() == "high").ToList().Count,
                            issues.Where(t => t.STATUS == "Closed" && t.SEVERITY.ToLower() == "high").ToList().Count,
                },
                color = "#ffc4c4"

            });
            chart.series.Add(new seriesItem()
            {
                type = "column",
                name = "Medium",
                data = new List<decimal>() {
                    issues.Where(t => t.STATUS == "Open" && t.SEVERITY.ToLower() == "medium").ToList().Count,
                        issues.Where(t => t.STATUS == "In-Progress" && t.SEVERITY.ToLower() == "medium").ToList().Count,
                            issues.Where(t => t.STATUS == "Closed" && t.SEVERITY.ToLower() == "medium").ToList().Count,
                },
                color = "#f7eb87"

            });
            chart.series.Add(new seriesItem()
            {
                type = "column",
                name = "Low",
                data = new List<decimal>() {
                    issues.Where(t => t.STATUS == "Open" && t.SEVERITY.ToLower() == "low").ToList().Count,
                        issues.Where(t => t.STATUS == "In-Progress" && t.SEVERITY.ToLower() == "low").ToList().Count,
                            issues.Where(t => t.STATUS == "Closed" && t.SEVERITY.ToLower() == "low").ToList().Count,
                },
                color = "#b6dcb6"

            });

            chart.series.Add(new seriesPie()
            {
                type = "pie",
                name = "Total Issues",
                data = new List<pieData>()
                {
                    new pieData() { name ="High", y =issues.Where(t => t.SEVERITY.ToLower() == "high").ToList().Count, color="#ffc4c4"  },
                    new pieData() {  name ="Medium", y =issues.Where(t => t.SEVERITY.ToLower() == "medium").ToList().Count, color="#f7eb87"  },
                    new pieData() {  name ="Low", y =issues.Where(t => t.SEVERITY.ToLower() == "low").ToList().Count, color="#b6dcb6"  }

                },
                center = new List<int>() { 20, 15 },
                size = 60,
                showInLegend = false,
                dataLabels = new credits() { enabled = false }
            });


            //issues.Select(t => t.STATUS == "Open" && t.SEVERITY.ToLower() == "High").ToList().Count
            return chart;
        }

