        [POST("GetKPITrendByMonthLine")]
        [ActionName("GetKPITrendByMonthLine")]
        [HttpPost]
        public IHttpActionResult GetKPITrendByMonthLine([FromBody] KPI_TRENDBY_MONTH dataModel)
        {
            var stopwatch = Stopwatch.StartNew();
            LogRequest(content: JsonConvert.SerializeObject(dataModel));

            List<KPI_DETAILS_EXTENDED> kpis = new List<KPI_DETAILS_EXTENDED>();
            List<KPI_DETAILS_EXTENDED> kpi_logged = new List<KPI_DETAILS_EXTENDED>();
            HighChartsLine result = new HighChartsLine();

            if (dataModel != null)
            {
                kpis = CSPdb.AppRepo.GetKPIDetails(dataModel.START_DATE, dataModel.END_DATE).ToList();
                kpi_logged = kpis.Where(x => x.CUSTOMER_ID == dataModel.CUST_ID && (dataModel.PROJ_IDS.IndexOf(x.PROJECT_ID) > -1) &&
                        !string.IsNullOrEmpty(x.KPI_ACTUAL) && x.SLA_TARGET_HIGH_VALUE.HasValue
                            && x.ISACTIVE).ToList();

                result = GetLineChartDataMonthlyNew(kpi_logged);
            }
            FillResponseTime(stopwatch);
            return Ok(result);
        }


        [POST("GetAchievementTrendByMonthLine")]
        [ActionName("GetAchievementTrendByMonthLine")]
        [HttpPost]
        public IHttpActionResult GetAchievementTrendByMonthLine([FromBody] KPI_AchievementBY_MONTH dataModel)
        {
            LogRequest(prefix: "GetAchievementTrendByMonthLine", content: JsonConvert.SerializeObject(dataModel));
            var stopwatch = Stopwatch.StartNew();
            var list = new List<KPI_DETAILS_EXTENDED>();
            var lineChart = new HighChartsLine();
            var result = new HighChartsLine();
            if (dataModel != null)
            {
                var months = int.Parse(helper.GetDBConfig("ACHIEVEMENT_TREND", dataModel.CUST_ID));
                var startDate = dataModel.END_DATE.AddMonths(-1 * months);
                list = CSPdb.AppRepo.GetKPIDetails(startDate, dataModel.END_DATE)
                             .Where(x => x.CUSTOMER_ID == dataModel.CUST_ID && (dataModel.PROJ_ID == x.PROJECT_ID) &&
                             !string.IsNullOrEmpty(x.KPI_ACTUAL) && x.SLA_TARGET_HIGH_VALUE.HasValue
                             && x.ISACTIVE).ToList();
                FillDetails(ref list);

                lineChart.title.text = "Achievement";
                lineChart.yAxis = new yAxis();
                lineChart.yAxis.max = 100;
                lineChart.yAxis.tickInterval = 20;
                lineChart.yAxis.title.text = "in %";
                lineChart.yAxis.gridLineWidth = 1;

                List<seriesItem> series = new List<seriesItem>();

                seriesItem seriesData = new seriesItem();
                seriesData.name = "Values"; string mm = string.Empty;
                var groupByMonthData = list.OrderBy(t => t.MONTH_YEAR).GroupBy(t => t.MONTH_YEAR);
                foreach (var gdata in groupByMonthData)
                {
                    lineChart.xAxis.categories.Add(gdata.Key.ToString("MMM-yyy"));

                    mm = gdata.Key.ToString("MMM-yyy");
                    decimal finalres = GetSuccessGoalScoreNewLogic(list.Where(t => t.MONTH_YEAR == Convert.ToDateTime(mm)).ToList<KPI_DETAILS_EXTENDED>());
                    seriesData.data.Add(Math.Round(finalres, 1));
                }
                series.Add(seriesData);
                lineChart.series = series;
            }
            FillResponseTime(stopwatch);
            return Ok(lineChart);
        }

