        private HighChartsLine GetLineChartDataMonthlyNew(List<KPI_DETAILS_EXTENDED> list)
        {
            FillDetails(ref list);

            HighChartsLine lineChart = new HighChartsLine();
            lineChart.title.text = "Health Index trend by Focus Area";
            lineChart.yAxis = new yAxis();
            lineChart.yAxis.max = 100;
            lineChart.yAxis.tickInterval = 20;
            lineChart.yAxis.title.text = "in %";
            lineChart.yAxis.gridLineWidth = 1;
            var groupByMonthData = list.OrderBy(t => t.MONTH_YEAR).GroupBy(t => t.MONTH_YEAR);
            var groupByPersepectivId = list.OrderBy(t => t.MONTH_YEAR).GroupBy(t => t.GLOBAL_KPI_PERSPECTIVE_ID);
            foreach (var gdata in groupByMonthData)
            {
                lineChart.xAxis.categories.Add(gdata.Key.ToString("MMM-yyy"));
            }
            List<seriesItem> series = new List<seriesItem>();
            foreach (var gdata in groupByPersepectivId)
            {
                seriesItem seriesData = new seriesItem();
                seriesData.name = GetPerspectiveName(gdata.Key);

                foreach (string mm in lineChart.xAxis.categories)
                {
                    List<KPI_DETAILS_EXTENDED> tes = gdata.ToList().Where(t => t.MONTH_YEAR == Convert.ToDateTime(mm)).ToList<KPI_DETAILS_EXTENDED>();
                    decimal result = 0;

                    if (tes.Count > 0)
                    {
                        foreach (KPI_DETAILS_EXTENDED ext in tes)
                        {
                            result += ext.PERCENT.HasValue ? ext.PERCENT.Value : 0;
                        }
                    }
                    else
                    {
                        result = result + 0;
                    }
                    decimal finalres;
                    if (tes.Count > 0 && result > 0)
                        finalres = result / tes.Count;
                    else
                        finalres = 0;

                    seriesData.data.Add(Math.Round(finalres, 1));
                }
                series.Add(seriesData);
            }
            lineChart.series = series;

            return lineChart;
        }

        public List<List<tableCell>> GetHelthReportTable(List<HealthReportCustomer> customers, List<GLOBAL_PERSPECTIVE> perstectives)
        {
            List<List<tableCell>> newTable = new List<List<tableCell>>();

            foreach (HealthReportCustomer customer in customers)
            {
                List<tableCell> row = new List<tableCell>();
                tableCell custcell = new tableCell();
                custcell.text = customer.CUSTOMER_NM;
                custcell.rowSpan = customer.PROJECTS.Count;
                row.Add(custcell);
                for (int iCnt = 0; iCnt < customer.PROJECTS.Count; iCnt++)
                {
                    if (iCnt > 0)
                        row = new List<tableCell>();
                    //Project Cell
                    tableCell projcell = new tableCell();
                    projcell.text = customer.PROJECTS[iCnt].PROJECT_NM;
                    //projcell.data = new RagCount() { projId = customer.PROJECTS[iCnt].PROJECT_ID, custId = customer.CUSTOMER_ID.ToString() };
                    projcell.rowSpan = 1;
                    row.Add(projcell);
                    //Overall Cell
                    tableCell overallcell = new tableCell();
                    overallcell.text = GetOverallScoreForProject(customer.PROJECTS[iCnt], -1);
                    overallcell.rowSpan = 1;
                    overallcell.data = new RagCount() { projId = customer.PROJECTS[iCnt].PROJECT_ID, custId = customer.CUSTOMER_ID.ToString() };
                    overallcell.color = GetHealthColor(customer.PROJECTS[iCnt]);
                    row.Add(overallcell);
                    //Compliance Cell
                    tableCell compliancecell = new tableCell();
                    compliancecell.text = GetOverallScoreForProject(customer.PROJECTS[iCnt], 4);
                    compliancecell.rowSpan = 1;
                    compliancecell.data = GetRagCount(customer.CUSTOMER_ID, customer.PROJECTS[iCnt], 4);
                    compliancecell.color = GetHealthColor(customer.PROJECTS[iCnt], 4);
                    row.Add(compliancecell);
                    //Value Cell
                    tableCell valuecell = new tableCell();
                    valuecell.text = GetOverallScoreForProject(customer.PROJECTS[iCnt], 3);
                    valuecell.rowSpan = 1;
                    valuecell.data = GetRagCount(customer.CUSTOMER_ID, customer.PROJECTS[iCnt], 3);
                    valuecell.color = GetHealthColor(customer.PROJECTS[iCnt], 3);
                    row.Add(valuecell);
                    //Performance Cell
                    tableCell performancecell = new tableCell();
                    performancecell.text = GetOverallScoreForProject(customer.PROJECTS[iCnt], 2);
                    performancecell.rowSpan = 1;
                    performancecell.data = GetRagCount(customer.CUSTOMER_ID, customer.PROJECTS[iCnt], 2);
                    performancecell.color = GetHealthColor(customer.PROJECTS[iCnt], 2);
                    row.Add(performancecell);
                    //Quality Cell
                    tableCell qualitycell = new tableCell();
                    qualitycell.text = GetOverallScoreForProject(customer.PROJECTS[iCnt], 1);
                    qualitycell.rowSpan = 1;
                    qualitycell.data = GetRagCount(customer.CUSTOMER_ID, customer.PROJECTS[iCnt], 1);
                    qualitycell.color = GetHealthColor(customer.PROJECTS[iCnt], 1);
                    row.Add(qualitycell);
                    //----------
                    newTable.Add(row);
                }
            }
            return newTable;
        }
        private Decimal GetDecimal(Decimal dec)
        {
            decimal d1 = Convert.ToDecimal(string.Format("{0:F1}", dec));
            decimal d2 = Convert.ToDecimal(string.Format("{0:F2}", dec));

            if (d1 >= 100)
            {
                string d = d2.ToString();
                String[] arr = d.Split('.');
                if (arr.Length > 1)
                {
                    if (arr[1].ToString().Length > 1)
                        dec = Convert.ToDecimal(arr[0] + "." + arr[1].ToString().Substring(0, 1));
                    else
                        dec = Convert.ToDecimal(arr[0] + "." + arr[1]);
                }
                else
                    dec = d2;
            }
            else
                dec = d1;
            return dec;
        }

