        private void FillDetails(ref List<KPI_DETAILS_EXTENDED> list)
        {
            list = list.Where(t => t.SLA_TARGET_HIGH_VALUE != null).ToList();
            decimal tmpPercent = 0.0M;
            foreach (KPI_DETAILS_EXTENDED kpi in list)
            {
                if (kpi.SLA_TARGET_LOW_VALUE.HasValue)
                {
                    if (!string.IsNullOrWhiteSpace(kpi.KPI_ACTUAL) && kpi.SLA_TARGET_HIGH_VALUE.HasValue)
                    {
                        decimal kpiActualValue = 0M;

                        decimal.TryParse(kpi.KPI_ACTUAL, out kpiActualValue);

                        if (kpi.SLA_TARGET_HIGH_OPERATOR == ">" && kpi.SLA_TARGET_HIGH_VALUE == kpiActualValue)
                            kpi.SLA_TARGET_HIGH_VALUE = kpi.SLA_TARGET_HIGH_VALUE + Convert.ToDecimal(.01);

                        decimal trend = kpi.SLA_TARGET_HIGH_VALUE.Value - kpi.SLA_TARGET_LOW_VALUE.Value;

                        if (trend > 0)
                            tmpPercent = kpiActualValue / kpi.SLA_TARGET_HIGH_VALUE.Value;
                        else if (trend < 0)
                        {
                            if (kpiActualValue > 0)
                                tmpPercent = kpi.SLA_TARGET_HIGH_VALUE.Value / kpiActualValue;
                            else
                                tmpPercent = 1;
                        }
                        else if (trend == 0)
                        {
                            if (kpi.SLA_TARGET_HIGH_OPERATOR == ">" || kpi.SLA_TARGET_HIGH_OPERATOR == ">=" || kpi.SLA_TARGET_LOW_OPERATOR == "<" || kpi.SLA_TARGET_LOW_OPERATOR == "<=")
                            {
                                if (kpi.SLA_TARGET_HIGH_VALUE.Value > 0)
                                    tmpPercent = kpiActualValue / kpi.SLA_TARGET_HIGH_VALUE.Value;
                                else
                                    tmpPercent = 1;
                            }
                            else if (kpi.SLA_TARGET_HIGH_OPERATOR == "<" || kpi.SLA_TARGET_HIGH_OPERATOR == "<=" || kpi.SLA_TARGET_LOW_OPERATOR == ">" || kpi.SLA_TARGET_LOW_OPERATOR == ">=")
                            {
                                if (kpiActualValue > 0)
                                    tmpPercent = kpi.SLA_TARGET_HIGH_VALUE.Value / kpiActualValue;
                                else
                                    tmpPercent = 1;
                            }
                        }

                        if (tmpPercent > 1)
                            kpi.PERCENT = 100;
                        else
                            kpi.PERCENT = tmpPercent * 100;
                    }
                }
                else if (kpi.KPI_ACTUAL != "" && kpi.KPI_ACTUAL != "0" && kpi.SLA_TARGET_HIGH_VALUE.Value != 0)
                {
                    if (kpi.SLA_TARGET_HIGH_OPERATOR == ">" && kpi.SLA_TARGET_HIGH_VALUE == Convert.ToDecimal(kpi.KPI_ACTUAL))
                        kpi.SLA_TARGET_HIGH_VALUE = kpi.SLA_TARGET_HIGH_VALUE + Convert.ToDecimal(.01);

                    tmpPercent = Convert.ToDecimal(kpi.KPI_ACTUAL) / kpi.SLA_TARGET_HIGH_VALUE.Value;


                    if (tmpPercent > 1)
                        kpi.PERCENT = 100;
                    else
                        kpi.PERCENT = tmpPercent * 100;
                }
                else if (kpi.KPI_ACTUAL == "0" && kpi.SLA_TARGET_HIGH_VALUE.Value == 0)
                    kpi.PERCENT = 100;
                else
                    kpi.PERCENT = 0;
            }

            foreach (KPI_DETAILS_EXTENDED kpi in list)
            {
                kpi.RAG = GetColorForKPIDetails(kpi, new KPI_TARGETS()
                {
                    SLA_TARGET_VERYHIGH_VALUE = kpi.SLA_TARGET_VERYHIGH_VALUE,
