        private decimal GetCompletedPercentage(DateTime month, List<KPI_DETAILS_EXTENDED> kpiMet, List<KPI> totalKpis)
        {
            decimal kpiPercentage = 0;
            if (totalKpis.Count > 0)
            {
                kpiPercentage = Decimal.Divide(kpiMet.Count, totalKpis.Count);
                if (kpiPercentage > 1)
                    kpiPercentage = 1;
                kpiPercentage = kpiPercentage * 100;
            }

            return Math.Round(kpiPercentage);
        }
        private HighChartsLine GetLineChart(Dictionary<DateTime, decimal> actuals, List<decimal> totalPercentage)
        {
            HighChartsLine chart = new HighChartsLine();
            actuals.OrderBy(t => t.Key);

            chart.title.text = "Overall Health Index";
            chart.title.style = new style() { color = "#333333", fontSize = "13px" };
            chart.xAxis.gridLineWidth = 0;

            chart.plotOptions.series.dataLabels.enabled = true;

            //Series Actual
            seriesItem item = new seriesItem();
            item.type = "line";
            item.name = "Health Index";
            item.color = "#000220";
            item.width = 1;
            // string yAxisTitle = "Period";

            seriesItem itemd = new seriesItem();
            itemd.type = "line";
            itemd.name = "KPI Actuals logged %";
            itemd.color = "#7CB5EC";

            foreach (var d in actuals.OrderBy(t => t.Key))
            {
                item.data.Add(d.Value);
                chart.xAxis.categories.Add(d.Key.ToString("MMM-yyy"));
            }

            itemd.data = totalPercentage;
            ////Target Actual
            //seriesItem actual = new seriesItem();
            //actual.name = "Target";
            //actual.color = "#63be7b";
            //actual.width = 1;
            //foreach (var d in actuals)
            //{
            //    actual.data.Add(d.Value);
            //}

            chart.series.Add(item);
            chart.series.Add(itemd);
            chart.yAxis = new yAxis();
            chart.yAxis.max = 100;
            chart.yAxis.tickInterval = 20;
            chart.yAxis.title.text = "in %";
            chart.yAxis.gridLineWidth = 0;

            return chart;
        }




