        public RagCount GetRagCount(string custId, HealthReportProject Project, int PerspectiveId)
        {
            RagCount RAG = new RagCount();
            KpiGlobalPerspective perspective = Project.KPI_GLOBAL_PERSPECTIVE.Where(t => t.GLOBAL_PERSPECTIVE_ID == PerspectiveId).FirstOrDefault();
            if (perspective != null)
            {
                RAG = perspective.RAGCOUNT;
            }
            RAG.projId = Project.PROJECT_ID;
            RAG.custId = custId.ToString();
            return RAG;
        }
        public string GetHealthColor(HealthReportProject Project, int PerspectiveId)
        {
            string color = COLOR_GREY_LIGHT;
            KpiGlobalPerspective perspective = Project.KPI_GLOBAL_PERSPECTIVE.Where(t => t.GLOBAL_PERSPECTIVE_ID == PerspectiveId).FirstOrDefault();
            if (perspective != null)
            {
                if (perspective.RAGCOUNT.RED > 0)
                    color = COLOR_RED_LIGHT;
                else if (perspective.RAGCOUNT.AMBER > 0)
                    color = COLOR_AMBER_LIGHT;
                else if (perspective.RAGCOUNT.GREEN > 0)
                    color = COLOR_GREEN_LIGHT;
                else if (perspective.RAGCOUNT.BLUE > 0)
                    color = COLOR_BLUE_LIGHT;
            }
            return color;
        }
        public string GetHealthColor(HealthReportProject Project)
        {
            string color = COLOR_GREY_LIGHT;

            if (Project.RAGCOUNT.RED > 0)
                color = COLOR_RED_LIGHT;
            else if (Project.RAGCOUNT.AMBER > 0)
                color = COLOR_AMBER_LIGHT;
            else if (Project.RAGCOUNT.GREEN > 0)
                color = COLOR_GREEN_LIGHT;
            else if (Project.RAGCOUNT.BLUE > 0)
                color = COLOR_BLUE_LIGHT;

            return color;
        }
        public string GetOverallScoreForProject(HealthReportProject Project, int PerspectiveId)
        {
            decimal score = 0;
            decimal totalPercent = 0;
            if (PerspectiveId == -1)
            {
                foreach (KpiGlobalPerspective perspective in Project.KPI_GLOBAL_PERSPECTIVE)
                {
                    totalPercent += perspective.PERCENT;
                }
                int count = Project.KPI_GLOBAL_PERSPECTIVE.Where(t => t.PERCENT > 0).ToList().Count;
                if (count > 0)
                {
                    score = totalPercent / count;
                    score = score * 100;
                }
                else
                    score = 0;

            }
            else
            {
                KpiGlobalPerspective perspective = Project.KPI_GLOBAL_PERSPECTIVE.Where(t => t.GLOBAL_PERSPECTIVE_ID == PerspectiveId).FirstOrDefault();
                if (perspective != null)
                {
                    score = perspective.PERCENT * 100;
                }
            }
            if (score == 0)
                return "";
            else
                return score.ToString("0") + "%";
        }
        public class HealthReportCustomer
        {
            public HealthReportCustomer(List<KPI_DETAILS_EXTENDED> list, List<GLOBAL_PERSPECTIVE> perstectives)
            {
                this.CUSTOMER_NM = list.FirstOrDefault().CUSTOMER_NM;
                this.CUSTOMER_ID = list.FirstOrDefault().CUSTOMER_ID;
                this.PROJECTS = new List<HealthReportProject>();
                var tmpProject = list.GroupBy(t => t.PROJECT_ID);
                List<HealthReportProject> projects = new List<HealthReportProject>();
                foreach (var c in tmpProject)
                {
                    this.PROJECTS.Add(new HealthReportProject(c.ToList(), perstectives));
                }
            }
            public string CUSTOMER_NM { get; set; }
            public string CUSTOMER_ID { get; set; }
            public List<HealthReportProject> PROJECTS { get; set; } = new List<HealthReportProject>();

        }

        public class HealthReportProject
        {
            public HealthReportProject(List<KPI_DETAILS_EXTENDED> list, List<GLOBAL_PERSPECTIVE> perstectives)
            {
                this.PROJECT_NM = list.FirstOrDefault().PROJECT_NM;
                this.PROJECT_ID = list.FirstOrDefault().PROJECT_ID;
                this.RAGCOUNT = GetRagCount(list);
                foreach (var c in perstectives.OrderBy(t => t.ID))
                {
                    List<KPI_DETAILS_EXTENDED> kpilist = list.Where(t => t.GLOBAL_KPI_PERSPECTIVE_ID == c.ID).ToList();
                    this.KPI_GLOBAL_PERSPECTIVE.Add(new KpiGlobalPerspective(kpilist, c));
                }

            }
            public string PROJECT_NM { get; set; }
            public string PROJECT_ID { get; set; }
            public List<KpiGlobalPerspective> KPI_GLOBAL_PERSPECTIVE { get; set; } = new List<KpiGlobalPerspective>();
            public RagCount RAGCOUNT { get; set; } = new RagCount();

        }
        public class KpiGlobalPerspective
        {
            public KpiGlobalPerspective(List<KPI_DETAILS_EXTENDED> list, GLOBAL_PERSPECTIVE Perspective)
            {
                GLOBAL_PERSPECTIVE_ID = Perspective.ID;
                GLOBAL_PERSPECTIVE_NM = Perspective.SHORT_DESC;
                RAGCOUNT = GetRagCount(list);
                KPIDetails = list;

                if (list.Count > 0)
                {
                    decimal totalPercent = 0;
                    foreach (KPI_DETAILS_EXTENDED kpi in list)
                    {
                        //if (kpi.KPI_ACTUAL != "")
                        if (kpi.KPI_ACTUAL != "" && kpi.KPI_ACTUAL != "0" && kpi.SLA_TARGET_HIGH_VALUE.Value != 0)
                        {
                            decimal tmpPercent = Convert.ToDecimal(kpi.KPI_ACTUAL) / kpi.SLA_TARGET_HIGH_VALUE.Value;
                            if (tmpPercent > 1)
                                totalPercent += 1;
                            else
                                totalPercent += tmpPercent;
                        }
                        else if (kpi.KPI_ACTUAL == "0" && kpi.SLA_TARGET_HIGH_VALUE.Value == 0)
                            totalPercent += 1;
                    }
                    this.PERCENT = totalPercent / list.Count;
                }
            }
            public decimal PERCENT { get; set; }
            public int GLOBAL_PERSPECTIVE_ID { get; set; }
            public string GLOBAL_PERSPECTIVE_NM { get; set; }
            public RagCount RAGCOUNT { get; set; } = new RagCount();
            public List<KPI_DETAILS_EXTENDED> KPIDetails = new List<KPI_DETAILS_EXTENDED>();

        }
        public static RagCount GetRagCount(List<KPI_DETAILS_EXTENDED> list)
        {
            string color_Blue = "#00bfff";
            string color_Green = "#237f00";
            string color_Amber = "#f9a400";
            string color_Red = "#f60000";
            //   string color_grey = "#a6a6a6";
            RagCount ragCount = new RagCount();
            var tmpRAG = list.GroupBy(t => t.RAG);
            foreach (var c in tmpRAG)
            {
                if (c.Key == color_Blue)
                    ragCount.BLUE = c.ToList().Count;
                if (c.Key == color_Green)
                    ragCount.GREEN = c.ToList().Count;
                if (c.Key == color_Amber)
                    ragCount.AMBER = c.ToList().Count;
                if (c.Key == color_Red)
                    ragCount.RED = c.ToList().Count;
            }
            return ragCount;
        }
        public class KpiGlobalCategory
        {
            public KpiGlobalCategory(List<KPI_DETAILS_EXTENDED> list)
            {
                decimal totalPercent = 0;
                foreach (KPI_DETAILS_EXTENDED kpi in list)
                {
                    decimal tmpPercent = Convert.ToDecimal(kpi.KPI_ACTUAL) / kpi.SLA_TARGET_HIGH_VALUE.Value;
                    if (tmpPercent > 1)
                        totalPercent += 1;
                    else
                        totalPercent += tmpPercent;
                }
                this.PERCENT = totalPercent / list.Count;

                this.GLOBAL_KPI_CATEGORY_NM = list.FirstOrDefault().GLOBAL_KPI_CATEGORY_NM;
                this.GLOBAL_KPI_CATEGORY_ID = list.FirstOrDefault().GLOBAL_KPI_CATEGORY_ID;
                var tmpRAG = list.GroupBy(t => t.RAG);
                foreach (var c in tmpRAG)
                {
                    if (c.Key == color_Green)
                        green = c.ToList().Count;
                    if (c.Key == color_Amber)
                        amber = c.ToList().Count;
                    if (c.Key == color_Red)
                        red = c.ToList().Count;
                    if (c.Key == color_Blue)
                        blue = c.ToList().Count;
                }
            }
            public string GLOBAL_KPI_CATEGORY_NM { get; set; }
            public int GLOBAL_KPI_CATEGORY_ID { get; set; }
            public decimal PERCENT { get; set; }
            public int blue { get; set; }
            public int green { get; set; }
            public int amber { get; set; }
            public int red { get; set; }
            readonly string color_Blue = "#00bfff";
            readonly string color_Green = "#237f00";
            readonly string color_Amber = "#f9a400";
            readonly string color_Red = "#f60000";

        }



        private string GetLightColor(string color)
        {
            if (color == "#00bfff")//blue
                return "#00bfff";
            else if (color == "#f60000") //red
                return "#ffc4c4";
            else if (color == "#f9a400") //amber
                return "#f7eb87";
            else if (color == "#237f00") //green
                return "#b6dcb6";
            else
                return "grey";
        }
        private string GetDarkColor(string color)
        {
            if (color == "#00bfff")//blue
                return "#00bfff";
            else if (color == "#ffc4c4") //red
                return "#f60000";
            else if (color == "#f7eb87") //amber
                return "#f9a400";
            else if (color == "#b6dcb6") //green
                return "#237f00";
            else
                return "grey";
        }
        private string GetName(string color)
        {
            string color_Green = "#237f00";
            string color_Amber = "#f9a400";
            string color_Red = "#f60000";
            string color_Blue = "#00bfff";
            //  string color_Grey = "grey";
            if (color == color_Green)
                return "Acheived Goal";
            else if (color == color_Amber)
                return "Partially achieved";
            else if (color == color_Red)
                return "Not Met";
            else if (color == color_Blue)
                return "Exceeded Goal";
            else
                return "Not Applicable";
        }
        private string GetPerspectiveName(int? PersID)
        {
            if (!PersID.HasValue)
                return string.Empty;
            string persName = CSPdb.GLOBAL_PERSPECTIVE.GetAll().Where(t => t.ID == PersID).Select(t => t.SHORT_DESC).FirstOrDefault();
            return persName;
        }



        private decimal GetAverageofMonthData(KPI_DETAILS_EXTENDED m)
        {
            decimal ma;
            if (m.SLA_TARGET_HIGH_VALUE == 0 && m.KPI_ACTUAL == "0")
                return ma = 1;
            else if (m.KPI_ACTUAL != "" && m.KPI_ACTUAL != "0" && m.SLA_TARGET_HIGH_VALUE != 0)
            {
                ma = Convert.ToDecimal(m.KPI_ACTUAL) / Convert.ToDecimal(m.SLA_TARGET_HIGH_VALUE);
                if (ma > 1)
                    return ma = 1;
                else
                    return ma;
            }
            else
                return 0;
        }

