        private string GetColorForKPIDetails(KPI_DETAILS d, KPI_TARGETS k)
        {
            string color = "";
            if (d == null || d.KPI_ACTUAL == string.Empty || d.KPI_ACTUAL == null || k == null)
                return color;
            if (d.ISFLAG)
                return "#696969";

            color = GetColorForKpiActual(d.KPI_ACTUAL, k);
            return color;
        }

        private string GetColorForKpiActual(string kpiActual, KPI_TARGETS k)
        {
            string color = "";

            if (k == null || kpiActual == string.Empty || kpiActual == null)
                return color;

            decimal kpiActualDecimal = 0M;

            if (!decimal.TryParse(kpiActual, out kpiActualDecimal))
                return color;

            if (
                (k.SLA_TARGET_VERYHIGH_DESCRIPTION == string.Empty || k.SLA_TARGET_VERYHIGH_DESCRIPTION == null) &&
                (k.SLA_TARGET_HIGH_DESCRIPTION != string.Empty || k.SLA_TARGET_HIGH_DESCRIPTION != null) &&
                (k.SLA_TARGET_LOW_DESCRIPTION == string.Empty || k.SLA_TARGET_LOW_DESCRIPTION == null) &&
                (k.SLA_TARGET_MEDIUM_DESCRIPTION == string.Empty || k.SLA_TARGET_MEDIUM_DESCRIPTION == null)
                )
            {
                if (IsKPIActualMeetingTarget(kpiActualDecimal, Convert.ToDecimal(k.SLA_TARGET_HIGH_VALUE), k.SLA_TARGET_HIGH_OPERATOR))
                    return COLOR_GREEN;
                else
                    return COLOR_AMBER;
            }

            if (k.SLA_TARGET_VERYHIGH_DESCRIPTION != string.Empty && IsKPIActualMeetingTarget(kpiActualDecimal, Convert.ToDecimal(k.SLA_TARGET_VERYHIGH_VALUE), k.SLA_TARGET_VERYHIGH_OPERATOR))
                return COLOR_BLUE;
            if (IsKPIActualMeetingTarget(kpiActualDecimal, Convert.ToDecimal(k.SLA_TARGET_HIGH_VALUE), k.SLA_TARGET_HIGH_OPERATOR))
                return COLOR_GREEN;
            else if (k.SLA_TARGET_MEDIUM_DESCRIPTION != string.Empty)
            {
                if (k.SLA_TARGET_VERYHIGH_DESCRIPTION != string.Empty && IsKPIActualMeetingTarget(kpiActualDecimal, Convert.ToDecimal(k.SLA_TARGET_VERYHIGH_VALUE), k.SLA_TARGET_VERYHIGH_OPERATOR))
                    return COLOR_BLUE;

                if (IsKPIActualMeetingTarget(kpiActualDecimal, Convert.ToDecimal(k.SLA_TARGET_HIGH_VALUE), k.SLA_TARGET_HIGH_OPERATOR))
                    return COLOR_GREEN;
                else if (k.SLA_TARGET_MEDIUM_DESCRIPTION != string.Empty)
                {
                    if (k.SLA_TARGET_LOW_DESCRIPTION == string.Empty && IsKPIActualMeetingTarget(kpiActualDecimal, Convert.ToDecimal(k.SLA_TARGET_MEDIUM_VALUE), k.SLA_TARGET_MEDIUM_OPERATOR))
                        return COLOR_AMBER;
                    else if (k.SLA_TARGET_LOW_DESCRIPTION != string.Empty)
                    {
                        if (IsKPIActualMeetingTarget(kpiActualDecimal, Convert.ToDecimal(k.SLA_TARGET_LOW_VALUE), k.SLA_TARGET_LOW_OPERATOR))
                            return COLOR_RED;
                        else
                            return COLOR_AMBER;
                    }
                    else
                        return COLOR_RED;
                }
                else
                    return COLOR_RED;
            }
            else if (k.SLA_TARGET_MEDIUM_DESCRIPTION == string.Empty && k.SLA_TARGET_LOW_DESCRIPTION != string.Empty)
            {
                if (IsKPIActualMeetingTarget(kpiActualDecimal, Convert.ToDecimal(k.SLA_TARGET_LOW_VALUE), k.SLA_TARGET_LOW_OPERATOR))
                    return COLOR_RED;
            }
            return color;
        }

        private bool IsKPIActualMeetingTarget(decimal Actual, decimal Target, string Operator)
        {
            if (Operator == "<" && Actual < Target)
                return true;
            else if (Operator == "<=" && Actual <= Target)
                return true;
            else if (Operator == "=" && Actual == Target)
                return true;
            if (Operator == ">" && Actual > Target)
                return true;
            else if (Operator == ">=" && Actual >= Target)
                return true;

            return false;
        }

        private List<LineChart> GetTrendCharts(string CustomerId, DateRange range)
        {
            //Data
            List<KPI> KPIs = CSPdb.KPI.GetAll().Where(t => t.CUSTOMER_ID == CustomerId).ToList<KPI>();
            List<int> kpiIds = KPIs.Select(s => s.ID).ToList<int>();
            List<KPI_DETAILS> allDetails = CSPdb.KPI_DETAILS.GetAll().Where(t => kpiIds.Contains(t.KPI_ID)).ToList<KPI_DETAILS>();
            //Chart
            List<LineChart> TrendCharts = new List<LineChart>();
            foreach (int i in kpiIds)
            {
                List<KPI_DETAILS> details = allDetails.Where(t => t.KPI_ID == i).ToList<KPI_DETAILS>();
                if (details != null)
                {
                    KPI tmpKPI = KPIs.Where(t => t.ID == i).FirstOrDefault<KPI>();
                    LineChart chart = new LineChart();
                    chart.options.title = tmpKPI.SERVICE_AREA + " - " + tmpKPI.KPI_NAME;
                    chart.dataTable.Add(new List<object>() { "Month", tmpKPI.SUPPORT_WINDOW });
                    foreach (KPI_DETAILS d in details)
                    {
                        chart.dataTable.Add(new List<object>() { d.PERIOD.ToString("MMM-yyy"), d.KPI_ACTUAL });
                    }
                    TrendCharts.Add(chart);
                }
            }

            return TrendCharts;
        }
        private decimal GetKPITarget(List<KPI_TARGETS> kpiTargets, DateTime PERIOD)
        {
            decimal target = 0;
            KPI_TARGETS kpiTarget = kpiTargets.Where(t => PERIOD >= t.START_DATE && PERIOD <= t.END_DATE).FirstOrDefault();
            if (kpiTarget != null)
                target = Convert.ToDecimal(kpiTarget.SLA_TARGET_HIGH_VALUE);

            return target;
        }
        private KPI_TARGETS GetKPITargets(List<KPI_TARGETS> kpiTargets, DateTime startDate, DateTime endDate)
        {
            KPI_TARGETS kpiTarget = kpiTargets.Where(t => startDate >= GetStartDateTime(t.START_DATE) && endDate <= GetEndDateTime(t.END_DATE)).OrderByDescending(x => x.ID).FirstOrDefault();
            if (kpiTarget != null)
                return kpiTarget;
            else
                return new KPI_TARGETS();
        }
        private List<HighChartsLineGroup> GetTrendHighChartsNew(string CustomerId, string ProjectId, DateRange range)
        {
            //Data
            List<KPI_GOALS> goals = CSPdb.KPI_GOALS.GetAll().Where(t => t.CUSTOMER_ID == CustomerId && t.PROJECT_ID == ProjectId && t.ISACTIVE == true).OrderBy(u => u.DISPLAY_ORDER).ToList<KPI_GOALS>();
            List<int> goalIds = goals.Select(s => s.ID).ToList<int>();

            List<KPI> KPIs = CSPdb.KPI.GetAll().Where(t => goalIds.Contains(t.GOAL_ID) && t.ISACTIVE == true).ToList<KPI>();
            List<KPI> SortedKPIs = new List<KPI>();
            foreach (KPI_GOALS g in goals)
            {
                SortedKPIs.AddRange(KPIs.Where(t => t.GOAL_ID == g.ID).OrderBy(u => u.DISPLAY_ORDER).ToList<KPI>());
            }

            List<int> kpiIds = SortedKPIs.Select(s => s.ID).ToList<int>();
            List<KPI_DETAILS> allDetails = CSPdb.KPI_DETAILS.GetAll().Where(t => kpiIds.Contains(t.KPI_ID) && t.ISACTIVE == true && t.KPI_ACTUAL != "").ToList<KPI_DETAILS>();
            List<KPI_DETAILS> SortedallDetails = new List<KPI_DETAILS>();
            foreach (KPI k in SortedKPIs)
            {
                SortedallDetails.AddRange(allDetails.Where(t => t.KPI_ID == k.ID).ToList<KPI_DETAILS>());
            }
            //Chart

            List<HighChartsLineGroup> TrendChartsGroup = new List<HighChartsLineGroup>();

            foreach (int i in kpiIds)
            {
                List<KPI_DETAILS> details = allDetails.Where(t => t.KPI_ID == i).OrderBy(u => u.PERIOD).ToList<KPI_DETAILS>();
                if (details != null && details.Count > 0)
                {
                    KPI tmpKPI = KPIs.Where(t => t.ID == i).FirstOrDefault<KPI>();
                    HighChartsLine chart = new HighChartsLine();
                    chart.title.text = tmpKPI.KPI_NAME + " - " + tmpKPI.SERVICE_AREA;
                    chart.title.style = new style() { color = "#333333", fontSize = "13px" };
                    chart.subtitle.text = tmpKPI.SUPPORT_WINDOW;
                    chart.xAxis.gridLineWidth = 1;


                    //Series Actual
                    seriesItem item = new seriesItem();
                    item.name = "Actual";
                    item.width = 1;
                    string yAxisTitle = string.Empty;
                    List<decimal> Targets = new List<decimal>();
                    List<KPI_TARGETS> kpiTargets = CSPdb.KPI_TARGETS.GetAll().Where(t => t.KPI_ID == tmpKPI.ID && t.ISACTIVE == true).ToList<KPI_TARGETS>();
                    foreach (KPI_DETAILS d in details)
                    {
                        Targets.Add(GetKPITarget(kpiTargets, d.PERIOD));
                        if (d.KPI_ACTUAL != "")
                            item.data.Add(Convert.ToDecimal(d.KPI_ACTUAL));
                        if (tmpKPI.FREQUENCY == "Monthly")
                            chart.xAxis.categories.Add(d.PERIOD.ToString("MMM-yyy"));
                        else
                            chart.xAxis.categories.Add(d.PERIOD.ToString("dd-MMM-yyy"));
                        yAxisTitle = "In " + tmpKPI.SLA_TARGET_UNIT_OF_MEASUREMENT;
                    }

                    //Target Actual
                    seriesItem target = new seriesItem();
                    target.name = "Target";
                    target.color = "#63be7b";
                    target.width = 1;
                    foreach (decimal d in Targets)
                    {
                        target.data.Add(d);
                    }

                    chart.series.Add(target);
                    chart.series.Add(item);




                    chart.yAxis = new yAxis();
                    chart.yAxis.tickInterval = 20;
                    chart.yAxis.title.text = yAxisTitle;
                    chart.yAxis.gridLineWidth = 1;

                    string sGoal = goals.Where(t => t.ID == tmpKPI.GOAL_ID).FirstOrDefault<KPI_GOALS>().DESCRIPTION;

                    HighChartsLineGroup h = TrendChartsGroup.Where(t => t.GoalName == sGoal).FirstOrDefault<HighChartsLineGroup>();
                    if (h != null)
                    {
                        h.TrendHighChart.Add(new HighChartsLineWithArea() { KPIId = tmpKPI.ID, AreaName = tmpKPI.SERVICE_AREA, TrendHighChart = chart });
                    }
                    else
                    {
                        TrendChartsGroup.Add(new HighChartsLineGroup() { GoalName = sGoal, TrendHighChart = new List<HighChartsLineWithArea>() { new HighChartsLineWithArea() { KPIId = tmpKPI.ID, AreaName = tmpKPI.SERVICE_AREA, TrendHighChart = chart } } });
                    }
                }
            }
            return TrendChartsGroup;
        }

        private RiskChart GetRiskChart(string CustomerId, List<string> Projects, DateRange range)
        {
            //Data
            List<PROJECT_RISK> risks = CSPdb.PROJECT_RISK.GetAll().Where(t => Projects.Contains(t.PROJECT_ID) && t.STATUS.ToLower() != "closed" && t.ISACTIVE == true).ToList<PROJECT_RISK>();

            //Chart
            RiskChart riskChart = new RiskChart();
            foreach (PROJECT_RISK r in risks)
                riskChart.Data[r.PROBABILITY_SCALE - 1][r.IMPACT_SCALE - 1] = riskChart.Data[r.PROBABILITY_SCALE - 1][r.IMPACT_SCALE - 1] + 1;

            return riskChart;
        }


        private PieChart GetIssueChart(string CustomerId, List<string> Projects, DateRange range)
        {
            //Data
            List<PROJECT_ISSUE> issues = CSPdb.PROJECT_ISSUE.GetAll().Where(t => Projects.Contains(t.PROJECT_ID) && t.STATUS.ToLower() != "closed").ToList<PROJECT_ISSUE>();
            List<PROJECT_ISSUE> high = issues.Where(t => t.SEVERITY.ToLower() == "high").ToList<PROJECT_ISSUE>();
            List<PROJECT_ISSUE> medium = issues.Where(t => t.SEVERITY.ToLower() == "medium").ToList<PROJECT_ISSUE>();
