        [GET("GetNewResource")]
        [ActionName("GetNewResource")]
        [HttpGet]
        public IHttpActionResult GetNewResource(string projectId)
        {
            var resource = Cldb.AppRepo.ResourceCount(projectId);

            List<Model.CSP.ResourceDetails> lstResource = new List<Model.CSP.ResourceDetails>();

            List<CSM_TITLES> titles = Cldb.CSM_TITLES.GetAll().ToList<CSM_TITLES>();
            foreach (CSM_TITLES t in titles)
            {

                List<Resource> res = resource.Where(r => r.TITLE == t.TITLE).ToList<Resource>();
                if (res.Count > 0)
                {
                    Model.CSP.ResourceDetails resourceDetails = new Model.CSP.ResourceDetails();
                    resourceDetails.TITLE = t.TITLE;
                    resourceDetails.RESOURCE = res;
                    lstResource.Add(resourceDetails);
                }

            }
            return Ok(lstResource);
        }
        [GET("GetRisk")]
        [ActionName("GetRisk")]
        [HttpGet]
        public IHttpActionResult GetRisk(string CustomerId, int Probability, int Impact)
        {
            List<PROJECT> lstProjects = Cldb.PROJECT.GetAll().Where(t => t.CUST_ID == CustomerId).ToList<PROJECT>();
            List<string> projects = lstProjects.Where(t => t.CUST_ID == CustomerId).Select(t => t.PROJ_ID).ToList<string>();

            List<PROJECT_RISK> risks = CSPdb.PROJECT_RISK.GetAll().Where(t => projects.Contains(t.PROJECT_ID) && t.IMPACT_SCALE == Impact && t.PROBABILITY_SCALE == Probability && t.ISACTIVE == true && t.STATUS != "Closed").ToList<PROJECT_RISK>();
            foreach (PROJECT_RISK r in risks)
            {
                r.RAG = lstProjects.Where(t => t.PROJ_ID == r.PROJECT_ID).Select(l => l.PROJ_NM).FirstOrDefault();
            }
            if (risks == null)
                risks = new List<PROJECT_RISK>();
            return Ok(risks);
        }

