        [GET("GetIdeasDetails")]
        [ActionName("GetIdeasDetails")]
        [HttpGet]
        public IHttpActionResult GetIdeasDetails(string CustomerId, bool Projflag)
        {
            var result = new GenericList<PROJECT_INNOVATIONEXT>();
            string EmpId = this.GetHeaderDetails_String("empId");
            var projects = GetProjectListForUser(EmpId, CustomerId);
            string ProjIds = string.Join(",", projects.Select(t => t.PROJ_ID).ToArray());
            result.projects = projects;

            List<GAVSSERVICE> gavsServicelist = new List<GAVSSERVICE>();
            GAVSSERVICE gavsService = new GAVSSERVICE();
            List<GAVS_SERVICE> service = CSPdb.GAVS_SERVICE.GetAll().ToList();
            INNOVATION_SERVICE_MAPPING serviceloop = new INNOVATION_SERVICE_MAPPING();

            List<PROJECT_INNOVATIONEXT> output = CSPdb.AppRepo.GetAllIdeasDetails(ProjIds).ToList();
            List<int> innovationIds = output.Select(t => t.ID).ToList<int>();
            List<INNOVATION_SERVICE_MAPPING> servicemapping = CSPdb.INNOVATION_SERVICE_MAPPING.GetAll().Where(t => innovationIds.Contains(t.INNOVATION_ID)).ToList();
            PROJECT_INNOVATION innovation = new PROJECT_INNOVATION();

            foreach (var row in output)
            {
                gavsServicelist = new List<GAVSSERVICE>();
                foreach (GAVS_SERVICE ser in service)
                {
                    serviceloop = servicemapping.Where(t => t.SERVICE_ID == ser.ID && t.INNOVATION_ID == row.ID).FirstOrDefault();
                    if (serviceloop == null)
                    {
                        gavsService = new GAVSSERVICE();
                        gavsService.SERVICE_ID = ser.ID;
                        gavsService.IS_CHECKED = false;
                    }
                    else
                    {
                        gavsService = new GAVSSERVICE();
                        gavsService.SERVICE_ID = ser.ID;
                        gavsService.IS_CHECKED = true;
                    }
                    gavsServicelist.Add(gavsService);
                }
                row.GAVS_SERVICE = gavsServicelist;
            }

            result.output = output;
            return Ok(result);
        }

