        [GET("GetActionItemsDetails")]
        [ActionName("GetActionItemsDetails")]
        [HttpGet]
        public IHttpActionResult GetActionItemsDetails(string customerId, bool Projflag, int viewBy)
        {
            string empId = this.GetHeaderDetails_String("empId");
            var projects = GetProjectListForUser(empId, customerId);
            string ProjIds = string.Join(",", projects.Select(t => t.PROJ_ID).ToArray());
            var allActionItems = CSPdb.AppRepo.GetActionItemsViewDetails(ProjIds).ToList();

            switch (viewBy)
            {
                case 1:
                    return Ok(allActionItems);
                case 2:
                    var actionItemData = allActionItems.Where(x => x.BATCH_CUSTOMER_ID != null && x.BATCH_CUSTOMER_MONTHLY_ID != null)
                                        .GroupBy(x => new { x.BATCH_CUSTOMER_ID, x.BATCH_CUSTOMER_MONTHLY_ID })
                                        .Select(group => new
                                        {
                                            BATCH_CUSTOMER_ID = group.Key.BATCH_CUSTOMER_ID,
                                            BATCH_CUSTOMER_MONTHLY_ID = group.Key.BATCH_CUSTOMER_MONTHLY_ID,
                                            PROJ_NM = group.First().PROJ_NM,
                                            PROJ_ID = group.First().PROJ_ID,
                                            SOURCE = group.First().SOURCE_DESCRIPTION,
                                            Items = group.ToList()
                                        }).OrderByDescending(x => x.BATCH_CUSTOMER_ID).ToList();

                    return Ok(actionItemData);
                default:
                    return BadRequest("Invalid ViewBy value");
            }
        }

