        [POST("GetRiskChartData")]
        [ActionName("GetRiskChartData")]
        [HttpPost]
        public IHttpActionResult GetRiskChartData([FromBody] RiskDashboardInputHolder riskDashboardInput)
        {
            CheckAccessForFeature(99);
            var overallRisk = Cldb.AppRepo.GetOverallRisksForRiskDashboard(riskDashboardInput.START_DATE, riskDashboardInput.END_DATE, riskDashboardInput.CUSTOMER_IDS,
                riskDashboardInput.RISK_STATUS, riskDashboardInput.PROJECT_IDS, riskDashboardInput.BUSINESS_UNITS).ToList();

            RiskChart riskChart = new RiskChart();
            var requestDomain = helper.GetAbsoulteUri();
            var path = "layout/risk";

            int lowCount = 0;
            int moderateCount = 0;
            int highCount = 0;
            int catastrophicCount = 0;

            foreach (var risk in overallRisk)
            {
                riskChart.Data[risk.PROBABILITY_SCALE - 1][risk.IMPACT_SCALE - 1] = riskChart.Data[risk.PROBABILITY_SCALE - 1][risk.IMPACT_SCALE - 1] + 1;
                risk.LINK = $"{requestDomain}/{path}/{risk.CUST_ID}/{risk.PROJ_ID}/{risk.ID}";

                switch (risk.RISK_LEVEL)
                {
                    case "Catastrophic":
                        catastrophicCount++;
                        break;
                    case "High":
                        highCount++;
                        break;
                    case "Moderate":
                        moderateCount++;
                        break;
                    case "Low":
                        lowCount++;
                        break;
                    default:
                        break;
                }
            }

            var overallData = new
            {
                RiskChart = riskChart,
                OverallRisk = overallRisk,
                LowCount = lowCount,
                ModerateCount = moderateCount,
                HighCount = highCount,
                CatastrophicCount = catastrophicCount
            };
            return Ok(overallData);
        }

