        [GET("MailToCSM_CRISP")]
        [ActionName("MailToCSM_CRISP")]
        [HttpGet]
        public IHttpActionResult MailToCSM_CRISP()
        {
            List<CRISPScores> crispScores = GetCrispScores();
            string Subject = "Service Delivery Performance Report";

            var csm = crispScores.GroupBy(t => t.EMAIL_ID);
            foreach (var scores in csm)
            {
                if (scores.Key == string.Empty || scores.Key == null)
                {
                    SendCRISPScoresMail(Constants.QUALITY_MAIL, "Quality", "Service Delivery Performance Report - Project(s) with no CSM", scores.ToList());
                }
                else
                {
                    SendCRISPScoresMail(scores.Key, scores.ToList()[0].CSM, Subject, scores.ToList());
                }
            }

            return Ok(crispScores);
        }

        [GET("MailToMGT_CRISP")]
        [ActionName("MailToMGT_CRISP")]
        [HttpGet]
        public IHttpActionResult MailToMGT_CRISP()
        {
            List<CRISPScores> crispScores = GetCrispScores();
            string Subject = "Service Delivery Performance Report";
            string tomail = helper.GetDBConfig("CRISP_LEADERSHIP_MAIL", "-1");

            if (crispScores != null && crispScores.Count > 0)
            {
                //SendCRISPScoresMail("Quality@gavstech.com", Subject, crispScores);
                SendCRISPScoresMail(tomail, "Leaders", Subject, crispScores);
            }

            return Ok(crispScores);
        }
        private void SendCRISPScoresMail(string ToEmailId, string To, string Subject, List<CRISPScores> scores, string period = null, string path = null)
        {
            string SenderEmaiId = string.Empty;

            string filePath = HttpContext.Current.Server.MapPath("~/UploadFile/Mails/") + path ?? "CRISPScores.htm";
            if (period == null) period = GetMonthString(CrispScoreMailDate().StartDate.Month) + "-" + CrispScoreMailDate().StartDate.Year.ToString();
            using (System.IO.StreamReader sr = new StreamReader(filePath))
            {
                string emailContent = sr.ReadToEnd();
                emailContent = emailContent.Replace("{{TABLE}}", GetCrispScoresTable(scores, period));
                emailContent = emailContent.Replace("{{TO_NAME}}", To);
                var ep = new EmailProvider(Cldb, CSPdb);
                ep.SendEmail
                    (
                    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                    new EmailContent { from = _email, to = ToEmailId, cc = SenderEmaiId, content = emailContent, subject = Subject, hasAttachments = false, attachmentFilePath = "" }, Request
                    );
            }
        }

        private string GetCrispScoresTable(List<CRISPScores> scores, string period)
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("<table width='100%'>\n");
            sb.Append("<tr>");
            sb.Append("<th rowspan=2>Customer</th>");
            sb.Append("<th rowspan=2>Project</th>");
            sb.Append("<th colspan=3>Status</th>");
            sb.Append("<th colspan=6>CRISP Scores for " + period + "</th>");
            sb.Append("</tr>\n");


            sb.Append("<tr>");
            //sb.Append("<th>CSM</th>");

            //sb.Append("<th>Published Date</th>");
            sb.Append("<th>Status</th>");
            sb.Append("<th class='comments'>QA Remarks</th>");
            sb.Append("<th class='comments'>HR Remarks</th>");
            sb.Append("<th>C</th>");
            sb.Append("<th>R</th>");
            sb.Append("<th>I</th>");
            sb.Append("<th>S</th>");
            sb.Append("<th>P</th>");
            sb.Append("<th>TOTAL</th>");
            sb.Append("</tr>\n");

            foreach (CRISPScores item in scores)
            {
                sb.Append("<TR>");
                //sb.Append("<td>"); sb.Append(item.CSM); sb.Append("</td>");
                sb.Append("<td>"); sb.Append(item.CUST_NM); sb.Append("</td>");
                sb.Append("<td>"); sb.Append(item.PROJ_NM); sb.Append("</td>");
                //sb.Append("<td>"); sb.Append(item.PUBLISH_DATE); sb.Append("</td>");

                if (item.NEED_FOCUS == true || item.HR_NEED_FOCUS == true || item.NEED_FOCUS == null || item.HR_NEED_FOCUS == null)
                {
                    sb.Append("<td class='statusRed'>"); sb.Append("Need Focus"); sb.Append("</td>");
                }
                else
                {
                    sb.Append("<td class='statusGreen'>"); sb.Append("Under Control"); sb.Append("</td>");
                }
                sb.Append("<td class='comments'>"); sb.Append(item.COMMENTS); sb.Append("</td>");
                sb.Append("<td class='comments'>"); sb.Append(item.HR_NEED_FOCUS_COMMENTS); sb.Append("</td>");
                sb.Append("<td class='crisp'>"); sb.Append(item.C); sb.Append("</td>");
                sb.Append("<td class='crisp'>"); sb.Append(item.R); sb.Append("</td>");
                sb.Append("<td class='crisp'>"); sb.Append(item.I); sb.Append("</td>");
                sb.Append("<td class='crisp'>"); sb.Append(item.S); sb.Append("</td>");
                sb.Append("<td class='crisp'>"); sb.Append(item.P); sb.Append("</td>");
                sb.Append("<td class='crisp'>"); sb.Append(item.TOTAL); sb.Append("</td>");
                sb.Append("</TR>\n");
            }
            sb.Append("</table>");
            return sb.ToString();
        }
        private List<CRISPScores> GetCrispScores()
        {
            List<CRISPScores> crispScores = CSPdb.AppRepo.GetCrispScores(CrispScoreMailDate().StartDate, CrispScoreMailDate().EndDate);
            return crispScores;
        }
        private DateRange CrispScoreMailDate()
        {
            DateRange range = new DateRange(DateTime.Now.AddMonths(-1), enDateRange.Monthly);
            return range;
        }

        [GET("GetCrispProjects")]
        [ActionName("GetCrispProjects")]
        [HttpGet]
        public IHttpActionResult GetCrispProjects(string empid, string month, int year)
        {
            LogRequest();

            DateTime pubdate = Convert.ToDateTime($"1-{month}-{year.ToString()}");
            var projects = Cldb.PROJECT.GetAll().Where(x => x.QUALITY_SPOC != "" && x.QUALITY_SPOC == empid && x.END_DATE > pubdate && x.PROJ_STATUS.ToUpper() != "CLOSE").ToList();// Cldb.AppRepo.Projects(empid, "").ToList<Projects>();
            List<string> existingCrispPorjects = CSPdb.CRISP_PROJECT_CATEGORY.GetAll().Select(t => t.PROJECT_ID).Distinct().ToList<string>();
            List<string> PROJECT_IDs = projects.Select(t => t.PROJ_ID.Trim()).Distinct().ToList<string>();
            foreach (var p in PROJECT_IDs)
            {
                if (!existingCrispPorjects.Any(x => x == p))
                {
                    CSPdb.AppRepo.AddCRISPDetails(p, empid.ToString());
                }
            }
            CRISP_DATA crispData = new Controllers.AllSysController.CRISP_DATA
            {
                CRISP_CATEGORY = new List<CRISP_CATEGORY>(),
                CRISP_PROJECT = new List<CRISP_PROJECT>(),
                PROJECTS = new List<Projects>(),
                CRISP_CRITERIA = new List<CRISP_CRITERIA>(),
                CRISP_VALIDATIONS = new List<CRISP_VALIDATIONS>()
            };
            if (!projects.Any()) return Ok(crispData);

            crispData.PROJECTS = projects.Select(x => new Projects
            {
                CUST_ID = x.CUST_ID,
                BILLING_PROJ_ID = x.PROJ_ID,
                PROJ_ALIAS_NM = x.PROJ_NM,
                PROJ_NM = x.PROJ_NM,
                BILLING_PROJ_NM = x.PROJ_NM,
                PROJ_ID = x.PROJ_ID,
                QUALITY_SPOC = x.QUALITY_SPOC,
                UPDATED_DATE = x.UPDATED_DATE.ToString("mm/DD/yyyy")
            }).ToList();
            crispData.CRISP_CATEGORY = CSPdb.CRISP_CATEGORY.GetAll().Where(t => t.ISACTIVE).ToList<CRISP_CATEGORY>();
            crispData.CRISP_CRITERIA = CSPdb.CRISP_CRITERIA.GetAll().Where(t => t.ISACTIVE).ToList<CRISP_CRITERIA>();
            crispData.CRISP_VALIDATIONS = CSPdb.CRISP_VALIDATIONS.GetAll().Where(t => t.ISACTIVE).ToList<CRISP_VALIDATIONS>();

            //Project
            List<CRISP_PROJECT_CATEGORY> project_category = CSPdb.CRISP_PROJECT_CATEGORY.GetAll().Where(t => PROJECT_IDs.Contains(t.PROJECT_ID)).ToList<CRISP_PROJECT_CATEGORY>();
            List<CRISP_PROJECT_CRITERIA> project_criteria = CSPdb.CRISP_PROJECT_CRITERIA.GetAll().Where(t => PROJECT_IDs.Contains(t.PROJECT_ID)).ToList<CRISP_PROJECT_CRITERIA>();
            List<CRISP_PROJECT_VALIDATIONS> project_validations = CSPdb.CRISP_PROJECT_VALIDATIONS.GetAll().Where(t => PROJECT_IDs.Contains(t.PROJECT_ID)).ToList<CRISP_PROJECT_VALIDATIONS>();
            //Scores
            List<CRISP_SCORES_PROJECT> scores_projects = CSPdb.CRISP_SCORES_PROJECT.GetAll().Where(t => PROJECT_IDs.Contains(t.PROJECT_ID) && t.PUBLISH_DATE == pubdate).ToList<CRISP_SCORES_PROJECT>();
            List<int> scores_projectIds = scores_projects.Select(t => t.ID).ToList<int>();
            //Add scores details for the first 
            foreach (var p in PROJECT_IDs)
            {
                CRISP_SCORES_PROJECT proj = scores_projects.Where(t => t.PROJECT_ID == p && t.PUBLISH_DATE == pubdate).FirstOrDefault();
                if (proj == null)
                {
                    AddProjectScores(empid, crispData.PROJECTS.First(x => x.PROJ_ID == p), pubdate);
                }
            }
            scores_projects = CSPdb.CRISP_SCORES_PROJECT.GetAll().Where(t => PROJECT_IDs.Contains(t.PROJECT_ID) && t.PUBLISH_DATE == pubdate).ToList<CRISP_SCORES_PROJECT>();
            scores_projectIds = scores_projects.Select(t => t.ID).ToList<int>();
            List<CRISP_SCORES_CATEGORY> scores_category = CSPdb.CRISP_SCORES_CATEGORY.GetAll().Where(t => scores_projectIds.Contains(t.CRISP_SCORES_PROJECT_ID)).ToList<CRISP_SCORES_CATEGORY>();
            List<CRISP_SCORES_CRITERIA> scores_criteria = CSPdb.CRISP_SCORES_CRITERIA.GetAll().Where(t => scores_projectIds.Contains(t.CRISP_SCORES_PROJECT_ID)).ToList<CRISP_SCORES_CRITERIA>();
            if (scores_criteria != null)
                scores_criteria = scores_criteria.OrderBy(t => t.CRISP_SCORES_PROJECT_ID).ThenBy(t => t.CRITERIA_ID).ToList();
            List<CRISP_SCORES_VALIDATIONS> scores_validations = CSPdb.CRISP_SCORES_VALIDATIONS.GetAll().Where(t => scores_projectIds.Contains(t.CRISP_SCORES_PROJECT_ID)).ToList<CRISP_SCORES_VALIDATIONS>();

            //Filling required data
            List<string> customers = new List<string>();
            List<CRISP_PROJECT> crispProjects = new List<CRISP_PROJECT>();
            foreach (var p in projects.ToList())
            {
                CRISP_PROJECT crispProject = new CRISP_PROJECT();

                CRISP_SCORES_PROJECT proj = scores_projects.Where(t => t.PROJECT_ID == p.PROJ_ID && t.PUBLISH_DATE == pubdate).FirstOrDefault();

                crispProject.CRISP_SCORES_PROJECT = proj;
                crispProject.CRISP_SCORES_CATEGORY = scores_category.Where(t => t.CRISP_SCORES_PROJECT_ID == proj.ID).ToList<CRISP_SCORES_CATEGORY>();
                crispProject.CRISP_SCORES_CRITERIA = scores_criteria.Where(t => t.CRISP_SCORES_PROJECT_ID == proj.ID).ToList<CRISP_SCORES_CRITERIA>();
                crispProject.CRISP_SCORES_VALIDATIONS = scores_validations.Where(t => t.CRISP_SCORES_PROJECT_ID == proj.ID).ToList<CRISP_SCORES_VALIDATIONS>();

                crispProject.CRISP_PROJECT_CATEGORY = project_category.Where(t => t.PROJECT_ID == proj.PROJECT_ID && t.ISACTIVE == true).ToList<CRISP_PROJECT_CATEGORY>();
                crispProject.CRISP_PROJECT_CRITERIA = project_criteria.Where(t => t.PROJECT_ID == proj.PROJECT_ID && t.ISACTIVE == true).ToList<CRISP_PROJECT_CRITERIA>();
                crispProject.CRISP_PROJECT_VALIDATIONS = project_validations.Where(t => t.PROJECT_ID == proj.PROJECT_ID && t.ISACTIVE == true).ToList<CRISP_PROJECT_VALIDATIONS>();

                //var results = from val in crispData.CRISP_VALIDATIONS
                //              group val.ID by val.CRITERIA_ID into g
                //              select new { CRITERIA_ID = g.Key, Validations = g.ToList() };

                crispProjects.Add(crispProject);
            }

            crispData.CRISP_PROJECT = crispProjects;
            //List<CRISP_VALIDATIONS> criterias = CSPdb.CRISP_VALIDATIONS.GetAll().Where(t => t.CRITERIA_ID == CriteriaId && t.ISACTIVE == true).ToList<CRISP_VALIDATIONS>();
            return Ok(crispData);
        }


        [GET("GetCrispProjectStatus")]
        [ActionName("GetCrispProjectStatus")]
        [HttpGet]
        public IHttpActionResult GetCrispProjectStatus(string empid, string month, int year)
        {
            List<string> PROJECT_IDs = new List<string>();
            if (Request.Headers.Contains("projectIds"))
                PROJECT_IDs = Request.Headers.GetValues("projectIds").ToList<string>()[0].ToString().Split(',').ToList<string>();
            DateTime pubdate = Convert.ToDateTime("1-" + month + "-" + year.ToString());
            List<CRISP_SCORES_PROJECT> projects = CSPdb.CRISP_SCORES_PROJECT.GetAll().Where(t => PROJECT_IDs.Contains(t.PROJECT_ID) && t.STATUS == "Published" && t.PUBLISH_DATE == pubdate).ToList<CRISP_SCORES_PROJECT>();
            List<CRISP_SCORES_CATEGORY> cate = new List<CRISP_SCORES_CATEGORY>();
            int crit = 0;
            ProjectStatusRAGCount rag = new ProjectStatusRAGCount();
            foreach (CRISP_SCORES_PROJECT p in projects)
            {
                int count = 0;
                cate = CSPdb.CRISP_SCORES_CATEGORY.GetAll().Where(t => t.CRISP_SCORES_PROJECT_ID == p.ID).ToList<CRISP_SCORES_CATEGORY>();
                foreach (CRISP_SCORES_CATEGORY csc in cate)
                {
                    if (csc.CATEGORY_ID != 3)
                    {
                        crit = CSPdb.CRISP_CRITERIA.GetAll().Where(t => t.CATEGORY_ID == csc.CATEGORY_ID).Sum(t => t.SCORE);
                        if (crit == csc.SCORE)
                            count++;
                    }
                }
                if (count == 4)
                {
                    if (p.SCORE == 98)
                        rag.Green += 1;
                    else if (p.SCORE >= 90)
                        rag.Amber += 1;
                    else
                        rag.Red += 1;
                }
                else
                {
                    if (p.SCORE == 100)
                        rag.Green += 1;
                    else if (p.SCORE >= 90)
                        rag.Amber += 1;
                    else
                        rag.Red += 1;
                }

            }

            return Ok(rag);
        }

        public class ProjectStatusRAGCount
        {
            public int Red { get; set; } = 0;
            public int Amber { get; set; } = 0;
            public int Green { get; set; } = 0;
        }
        [GET("GetCSATForQuarter")]
        [ActionName("GetCSATForQuarter")]
        [HttpGet]
        public IHttpActionResult GetCSATForQuarter(string Quarter, int year)
        {
            string quart;
            ProjectCSATCount csatCount = new ProjectCSATCount();
            int y = (year + 1) % 100;
            quart = Quarter + " " + year + "-" + y;
            //List<PROJECT_CSAT_DATA> csatlist = CSPdb.PROJECT_CSAT_DATA.GetAll().Where(t => t.YEAR_QUARTER == quart).ToList<PROJECT_CSAT_DATA>();
            List<PROJECT_CSAT_DATA> csatlist = CSPdb.AppRepo.GetCSSTable(quart).ToList();
            foreach (PROJECT_CSAT_DATA csat in csatlist)
            {
                if (csat.MIN_SCORE <= 2)
                    csatCount.LessThan2++;
                else if (csat.MIN_SCORE == 3)
                    csatCount.EqualTo3++;
                else if (csat.MIN_SCORE == 4)
                    csatCount.Equalto4++;
                else if (csat.MIN_SCORE == 5)
                    csatCount.Equalto5++;
            }
            return Ok(csatCount);
        }

        public class ProjectCSATCount
        {
            public int LessThan2 { get; set; } = 0;
            public int EqualTo3 { get; set; } = 0;
            public int Equalto4 { get; set; } = 0;
            public int Equalto5 { get; set; } = 0;
        }
