                        GetNPSScoreData(csatdata.Where(t => t.NPS_SCORE >= 9  && t.YEAR_QUARTER == quart2).ToList().Count ,csatdata.Where(t => t.NPS_SCORE <= 6 && t.YEAR_QUARTER == quart2).ToList().Count ,csatdata.Where(t =>t.YEAR_QUARTER == quart2).ToList().Count)
                },
                    color = "#737373"

                });
            }
            if (Slider == 0)
            {
                charts.series.Add(new seriesItem()
                {
                    name = "Detractors",
                    type = "column",
                    data = new List<decimal>() {
                    csatdata.Where(t => t.NPS_SCORE <= 6 && t.YEAR_QUARTER == quart1).ToList().Count
                },
                    color = "#FB8F73"

                });
                charts.series.Add(new seriesItem()
                {
                    name = "Passives",
                    type = "column",
                    data = new List<decimal>() {
                    csatdata.Where(t => (t.NPS_SCORE == 7 || t.NPS_SCORE == 8) && t.YEAR_QUARTER == quart1).ToList().Count
                },
                    color = "#FFFF9D"

                });
                charts.series.Add(new seriesItem()
                {
                    name = "Promoters",
                    type = "column",
                    data = new List<decimal>() {
                    csatdata.Where(t => t.NPS_SCORE >= 9  && t.YEAR_QUARTER == quart1).ToList().Count
                },
                    color = "#CAEE97"

                });
                charts.series.Add(new seriesItem()
                {
                    name = "NPScore",
                    type = "line",
                    data = new List<decimal>() {
                   GetNPSScoreData(csatdata.Where(t => t.NPS_SCORE >= 9  && t.YEAR_QUARTER == quart1).ToList().Count ,csatdata.Where(t => t.NPS_SCORE <= 6 && t.YEAR_QUARTER == quart1).ToList().Count ,csatdata.Where(t =>t.YEAR_QUARTER == quart1).ToList().Count)
                },
                    color = "#737373"

                });

            }

            return Ok(charts);

        }
        private decimal GetNPSScoreData(int promoters, int detractors, int total)
        {
            if (total != 0)
            {
                decimal para1 = Decimal.Divide(promoters, total);
                decimal para2 = Decimal.Divide(detractors, total);
                decimal result = (para1 * 100) - (para2 * 100);
                return Math.Round(result);
            }
            else
                return 0;


        }
