        [HttpGet]
        public IHttpActionResult GetCSATProjWise(int year)
        {
            int y = ((year + 1) % 100);

            string quart1 = "Q1" + " " + year + "-" + y;
            string quart2 = "Q2" + " " + year + "-" + y;
            string quart3 = "Q3" + " " + year + "-" + y;
            string quart4 = "Q4" + " " + year + "-" + y;

            List<string> Quarters = new List<string>() { quart1, quart2, quart3, quart4 };

            List<CSAT_NPS_DATA> resultlist = new List<CSAT_NPS_DATA>();
            List<PROJECT_CSAT_DATA> csatdata = CSPdb.AppRepo.GetCSSTable("").ToList();
            csatdata = csatdata.Where(t => Quarters.Contains(t.YEAR_QUARTER)).ToList();
            //List<PROJECT_CSAT_DATA> csatdata = CSPdb.PROJECT_CSAT_DATA.GetAll().Where(t => Quarters.Contains(t.YEAR_QUARTER)).ToList<PROJECT_CSAT_DATA>();
            List<string> projIds = csatdata.Select(t => t.PROJECT_ID).Distinct().ToList<string>();

            foreach (string p in projIds)
            {
