                chartsCSAT.xAxis.categories.Add(quart1);
                chartsCSAT.xAxis.categories.Add(quart2);
                chartsCSAT.xAxis.categories.Add(quart3);
                chartsCSAT.xAxis.categories.Add(quart4);
                chartsCSAT.xAxis.visible = false;
                chartsCSAT.yAxis.visible = false;
                chartsCSAT.plotOptions.series.marker.radius = 3;
                chartsCSAT.plotOptions.series.dataLabels.enabled = true;
                chartsCSAT.plotOptions.series.dataLabels.style.fontSize = "9";
                chartsCSAT.plotOptions.series.dataLabels.style.fontWeight = "normal";
                chartsCSAT.legend.enabled = false;
                chartsCSAT.exporting.enabled = false;
                chartsCSAT.series.Add(new seriesItemCSAT()
                {
                    data = new List<lineData>() {
                        new lineData() { y= GetCSATProjData(quart1, p, csatdata) , color =GetCSATColor(quart1, p, csatdata) },
                        new lineData() { y= GetCSATProjData(quart2, p, csatdata) , color =GetCSATColor(quart2, p, csatdata) },
                        new lineData() { y= GetCSATProjData(quart3, p, csatdata) , color =GetCSATColor(quart3, p, csatdata) },
                        new lineData() { y= GetCSATProjData(quart4, p, csatdata) , color =GetCSATColor(quart4, p, csatdata) }
                },
                    color = "#A9A9A9"
                });
                HighChartsLineForCSAT chartsNPS = new HighChartsLineForCSAT();
                chartsNPS.chart.type = enChartType.line;
                chartsNPS.chart.height = "50";
                chartsNPS.yAxis = new yAxis();
                chartsNPS.yAxis.tickInterval = 5;
                chartsNPS.yAxis.lineColor = "transparent";
                chartsNPS.yAxis.gridLineWidth = 0;
                chartsNPS.xAxis.categories.Add(quart1);
                chartsNPS.xAxis.categories.Add(quart2);
                chartsNPS.xAxis.categories.Add(quart3);
                chartsNPS.xAxis.categories.Add(quart4);
                chartsNPS.xAxis.visible = false;
                chartsNPS.yAxis.visible = false;
                chartsNPS.plotOptions.series.marker.radius = 3;
                chartsNPS.plotOptions.series.dataLabels.enabled = true;
                chartsNPS.plotOptions.series.dataLabels.style.fontSize = "9";
                chartsNPS.plotOptions.series.dataLabels.style.fontWeight = "normal";
                chartsNPS.legend.enabled = false;
                chartsNPS.exporting.enabled = false;
                chartsNPS.series.Add(new seriesItemCSAT()
                {
                    data = new List<lineData>() {
                        new lineData() { y= GetNPSProjData(quart1, p, csatdata) , color =GetNPSColor(quart1, p, csatdata) },
                        new lineData() { y= GetNPSProjData(quart2, p, csatdata) , color =GetNPSColor(quart2, p, csatdata) },
                        new lineData() { y= GetNPSProjData(quart3, p, csatdata) , color =GetNPSColor(quart3, p, csatdata) },
                        new lineData() { y= GetNPSProjData(quart4, p, csatdata) , color =GetNPSColor(quart4, p, csatdata) }
                },
                    color = "#A9A9A9"
                });
                result.PROJ_ID = p;
                result.PROJ_NM = GetProjectName(p);
                result.chartListCSAT = chartsCSAT;
