        private decimal GetCSATProjData(string quarter, string projId, List<PROJECT_CSAT_DATA> csatdata)
        {
            int score = Convert.ToInt32((csatdata.Where(t => t.YEAR_QUARTER == quarter && t.PROJECT_ID == projId).Select(t => t.MIN_SCORE).FirstOrDefault()));
            decimal s = Convert.ToDecimal(score);
            return s;
        }
        private decimal GetNPSProjData(string quarter, string projId, List<PROJECT_CSAT_DATA> csatdata)
        {
            int score = Convert.ToInt32((csatdata.Where(t => t.YEAR_QUARTER == quarter && t.PROJECT_ID == projId).Select(t => t.NPS_SCORE).FirstOrDefault()));
            decimal s = Convert.ToDecimal(score);
            return s;
        }
        private string GetCSATColor(string quarter, string projId, List<PROJECT_CSAT_DATA> csatdata)
        {
            decimal s;
            int? score = csatdata.Where(t => t.YEAR_QUARTER == quarter && t.PROJECT_ID == projId).Select(t => t.MIN_SCORE).FirstOrDefault();
            if (score != null)
            {
                s = Convert.ToDecimal(score);
                if (s <= 2)
                    return "#f44336";
                else if (s == 3)
                    return "#ffc000";
                else if (s == 4)
                    return "#237f00";
                else if (s == 5)
                    return "#337ab7";
                return "";
            }
            else
                return "#A9A9A9";

        }
        private string GetNPSColor(string quarter, string projId, List<PROJECT_CSAT_DATA> csatdata)
        {
            decimal s;
            int? score = csatdata.Where(t => t.YEAR_QUARTER == quarter && t.PROJECT_ID == projId).Select(t => t.NPS_SCORE).FirstOrDefault();
            if (score != null)
            {
                s = Convert.ToDecimal(score);
                if (s < 7)
                    return "#f44336";
                else if (s == 7 && s == 8)
                    return "#ffc000";
                else if (s >= 9)
                    return "#237f00";
                return "";
            }
            else
                return "#A9A9A9";
        }

        public List<decimal> GetCSATCount(List<string> months, int year, List<CSAT_SURVEY_DATA> csatList, string status = "")
        {
            List<decimal> counts = new List<decimal>();
            foreach (string month in months)
            {
                if (status == string.Empty)
                {
                    counts.Add(csatList.Where(t => t.CSAT_MONTH == month && t.CSAT_YEAR == year).ToList().Count);
                }
                else
                {
                    counts.Add(csatList.Where(t => t.CSAT_MONTH == month && t.STATUS == status && t.CSAT_YEAR == year).ToList().Count);
                }
            }
            return counts;
        }
        public List<decimal> GetCSATPercent(List<string> months, int year, List<CSAT_SURVEY_DATA> csatList)
        {
            List<decimal> counts = new List<decimal>();
            foreach (string month in months)
            {
                counts.Add(GetSurveyPercentage(csatList.Where(t => t.CSAT_MONTH == month && t.STATUS == "COMPLETED" && t.CSAT_YEAR == year).ToList().Count, csatList.Where(t => t.CSAT_MONTH == month && t.CSAT_YEAR == year).ToList().Count));
            }
            return counts;
        }

