        private decimal GetSurveyPercentage(int x, int y)
        {
            decimal m;
            // decimal n;
            if (y != 0)
            {
                m = decimal.Divide(x, y);
                return Math.Round(m * 100);
            }
            else
                return m = 0;

        }

