        private string GetHeatColor(int x, int y)
        {
            if ((x == 0) && (y == 0 || y == 1))
                return "#FF0000";
            else if (x == 1 && y == 0)
                return "#FF0000";
            else if ((x == 3) && (y == 1 || y == 2))
                return "#63be7b";
            else if ((x == 2) && (y == 2))
                return "#63be7b";
            else return "#feeb84";

        }
        private int GetHeatMapCount(int x, int y, List<PROJECT_CSAT_DATA> csat)
        {
            int count = 0;
            if (x == 0 && y == 0)
                count = csat.Where(t => t.MIN_SCORE <= 2 && t.NPS_SCORE < 7).ToList<PROJECT_CSAT_DATA>().Count;
            else if (x == 0 && y == 1)
                count = csat.Where(t => t.MIN_SCORE <= 2 && t.NPS_SCORE == 7).ToList<PROJECT_CSAT_DATA>().Count;
            else if (x == 0 && y == 2)
                count = csat.Where(t => t.MIN_SCORE <= 2 && t.NPS_SCORE >= 8).ToList<PROJECT_CSAT_DATA>().Count;
            else if (x == 1 && y == 0)
                count = csat.Where(t => t.MIN_SCORE == 3 && t.NPS_SCORE < 7).ToList<PROJECT_CSAT_DATA>().Count;
            else if (x == 1 && y == 1)
                count = csat.Where(t => t.MIN_SCORE == 3 && t.NPS_SCORE == 7).ToList<PROJECT_CSAT_DATA>().Count;
            else if (x == 1 && y == 2)
                count = csat.Where(t => t.MIN_SCORE == 3 && t.NPS_SCORE >= 8).ToList<PROJECT_CSAT_DATA>().Count;
            else if (x == 2 && y == 0)
                count = csat.Where(t => t.MIN_SCORE == 3 && t.NPS_SCORE < 7).ToList<PROJECT_CSAT_DATA>().Count;
            else if (x == 2 && y == 1)
                count = csat.Where(t => t.MIN_SCORE == 3 && t.NPS_SCORE == 7).ToList<PROJECT_CSAT_DATA>().Count;
            else if (x == 2 && y == 2)
                count = csat.Where(t => t.MIN_SCORE == 3 && t.NPS_SCORE >= 8).ToList<PROJECT_CSAT_DATA>().Count;
            else if (x == 3 && y == 0)
                count = csat.Where(t => t.MIN_SCORE == 3 && t.NPS_SCORE < 7).ToList<PROJECT_CSAT_DATA>().Count;
            else if (x == 3 && y == 1)
                count = csat.Where(t => t.MIN_SCORE == 3 && t.NPS_SCORE == 7).ToList<PROJECT_CSAT_DATA>().Count;
            else if (x == 3 && y == 2)
                count = csat.Where(t => t.MIN_SCORE == 3 && t.NPS_SCORE >= 8).ToList<PROJECT_CSAT_DATA>().Count;
            return count;
        }

        private int GetCSATVal(int? minScore)
        {
            if (minScore != null)
            {
                if (minScore <= 2)
                    return 0;
                else if (minScore == 3)
                    return 1;
                else if (minScore == 4)
                    return 2;
                else if (minScore == 5)
                    return 3;
            }
            return 0;
        }
        private int GetNPSVal(int? npsScore)
        {
            if (npsScore != null)
            {
                if (npsScore < 7)
                    return 0;
                else if (npsScore == 7)
                    return 1;
                else if (npsScore >= 8)
                    return 2;
            }
            return 0;
        }

