        private void AddProjectScores(string empid, Projects proj, DateTime dt)
        {
            var existing = CSPdb.CRISP_SCORES_PROJECT.GetAll().FirstOrDefault(x => x.PROJECT_ID == proj.PROJ_ID && x.PUBLISH_DATE == dt);
            if (existing != null) return;
            CRISP_SCORES_PROJECT projectScores = new CRISP_SCORES_PROJECT();
            projectScores.CUSTOMER_ID = proj.CUST_ID;
            projectScores.PROJECT_ID = proj.PROJ_ID;
            projectScores.PUBLISH_DATE = dt;
            projectScores.STATUS = "New";
            projectScores.CREATED_BY = empid.ToString();
            projectScores.CREATED_DATE = DateTime.Now;
            projectScores.UPDATED_BY = empid.ToString();
            projectScores.UPDATED_DATE = DateTime.Now;
            CSPdb.CRISP_SCORES_PROJECT.Add(projectScores);
            CSPdb.Commit(CanCommit);

            List<CRISP_PROJECT_CATEGORY> projectCategories = CSPdb.CRISP_PROJECT_CATEGORY.GetAll().Where(t => t.PROJECT_ID == proj.PROJ_ID && t.ISACTIVE == true).ToList<CRISP_PROJECT_CATEGORY>();
            foreach (CRISP_PROJECT_CATEGORY pc in projectCategories)
            {
                CRISP_SCORES_CATEGORY categoryScores = new CRISP_SCORES_CATEGORY();
                categoryScores.CRISP_SCORES_PROJECT_ID = projectScores.ID;
                categoryScores.CATEGORY_ID = pc.CATEGORY_ID;
                categoryScores.CREATED_BY = empid.ToString();
                categoryScores.CREATED_DATE = DateTime.Now;
                categoryScores.UPDATED_BY = empid.ToString();
                categoryScores.UPDATED_DATE = DateTime.Now;
                categoryScores.ISACTIVE = true;
                CSPdb.CRISP_SCORES_CATEGORY.Add(categoryScores);
            }
            //CSPdb.Commit(CanCommit);

            List<CRISP_PROJECT_CRITERIA> projectCriteria = CSPdb.CRISP_PROJECT_CRITERIA.GetAll().Where(t => t.PROJECT_ID == proj.PROJ_ID && t.ISACTIVE == true).ToList<CRISP_PROJECT_CRITERIA>();
            foreach (CRISP_PROJECT_CRITERIA pcr in projectCriteria)
            {
                CRISP_SCORES_CRITERIA criteriaScores = new CRISP_SCORES_CRITERIA();
                criteriaScores.CRISP_SCORES_PROJECT_ID = projectScores.ID;
                criteriaScores.CRITERIA_ID = pcr.CRITERIA_ID;
                criteriaScores.CREATED_BY = empid.ToString();
                criteriaScores.CREATED_DATE = DateTime.Now;
                criteriaScores.UPDATED_BY = empid.ToString();
                criteriaScores.UPDATED_DATE = DateTime.Now;
                criteriaScores.ISACTIVE = true;
                CSPdb.CRISP_SCORES_CRITERIA.Add(criteriaScores);
            }
            //CSPdb.Commit(CanCommit);

            List<CRISP_PROJECT_VALIDATIONS> projectValidations = CSPdb.CRISP_PROJECT_VALIDATIONS.GetAll().Where(t => t.PROJECT_ID == proj.PROJ_ID && t.ISACTIVE == true).ToList<CRISP_PROJECT_VALIDATIONS>();
            foreach (CRISP_PROJECT_VALIDATIONS pcr in projectValidations)
            {
                CRISP_SCORES_VALIDATIONS validationsScores = new CRISP_SCORES_VALIDATIONS();
                validationsScores.CRISP_SCORES_PROJECT_ID = projectScores.ID;
                validationsScores.VALIDATION_ID = pcr.VALIDATION_ID;
                validationsScores.CREATED_BY = empid.ToString();
                validationsScores.CREATED_DATE = DateTime.Now;
                validationsScores.UPDATED_BY = empid.ToString();
                validationsScores.UPDATED_DATE = DateTime.Now;
                validationsScores.ISACTIVE = true;
                CSPdb.CRISP_SCORES_VALIDATIONS.Add(validationsScores);
            }
            CSPdb.Commit(CanCommit);

        }

