        [GET("GetProjectForeCast")]
        [ActionName("GetProjectForeCast")]
        [HttpGet]

        public IHttpActionResult GetProjectForeCast(string EmpId)
        {
            List<string> projId = GetProjectsForUser(EmpId);
            //List<string> projId = Cldb.PROJECT_RESOURCE.GetAll().Where(t => t.EMP_ID == empId).Select(t => t.PROJ_ID).ToList<string>();
            PROJECT project = new PROJECT();
            List<PROJECT_RESOURCE> people = new List<PROJECT_RESOURCE>();
            EMP_INFO empinfo = new EMP_INFO();
            List<PROJECT> pro = Cldb.PROJECT.GetAll().ToList<PROJECT>();
            PROJECT_FORECAST proj = new PROJECT_FORECAST();
            DateTime date = DateTime.Now.AddMonths(3);
            foreach (string p in projId)
            {
                project = pro.Where(t => t.PROJ_ID == p && (t.END_DATE > DateTime.Now && t.END_DATE < date)).FirstOrDefault();
                if (project != null && !proj.projectstart.Contains(project))
                {
                    proj.projectend.Add(project);
                }
                project = pro.Where(t => t.PROJ_ID == p && (t.START_DATE > DateTime.Now && t.START_DATE < date)).FirstOrDefault();
                if (project != null && !proj.projectstart.Contains(project))
                {
                    proj.projectstart.Add(project);
                }
            }
            foreach (PROJECT p in proj.projectend)
            {
                people = Cldb.PROJECT_RESOURCE.GetAll().Where(t => t.PROJ_ID == p.PROJ_ID && t.BILL_FLG == true && t.END_DATE > (DateTime.Now)).ToList<PROJECT_RESOURCE>();
                foreach (PROJECT_RESOURCE pr in people)
                {
                    empinfo = Cldb.EMP_INFO.GetAll().Where(t => t.EMP_ID == pr.EMP_ID).FirstOrDefault();
                    if (!proj.projresrc.Contains(empinfo))
                        proj.projresrc.Add(empinfo);
                }

            }
            return Ok(proj);
        }

        [GET("GetProjectForeCastForCustomer")]
        [ActionName("GetProjectForeCastForCustomer")]
        [HttpGet]

        public IHttpActionResult GetProjectForeCastForCustomer(string CustomerId)
        {
            PROJECT project = new PROJECT();
            List<PROJECT_RESOURCE> people = new List<PROJECT_RESOURCE>();
            EMP_INFO empinfo = new EMP_INFO();
            List<PROJECT> pro = Cldb.PROJECT.GetAll().Where(x => x.CUST_ID == CustomerId).ToList<PROJECT>();
            PROJECT_FORECAST_FOR_CUSTOMER proj = new PROJECT_FORECAST_FOR_CUSTOMER();
            DateTime date = DateTime.Now.AddMonths(3);
            foreach (var p in pro)
            {
                project = pro.Where(t => t.PROJ_ID == p.PROJ_ID && (t.START_DATE >= DateTime.Now && t.START_DATE <= date)).FirstOrDefault();
                if (project != null && !proj.projectstart.Contains(project))
                {
                    proj.projectstart.Add(project);
                }
                project = pro.Where(t => t.PROJ_ID == p.PROJ_ID && (t.END_DATE >= DateTime.Now && t.END_DATE <= date)).FirstOrDefault();
                if (project != null && !proj.projectend.Contains(project) && !proj.projectstart.Contains(project))
                {
                    proj.projectend.Add(project);
                }

            }
            foreach (PROJECT p in proj.projectend)
            {
                people = Cldb.PROJECT_RESOURCE.GetAll().Where(t => t.PROJ_ID == p.PROJ_ID && t.BILL_FLG == true && t.END_DATE > (DateTime.Now)).ToList<PROJECT_RESOURCE>();
                foreach (PROJECT_RESOURCE pr in people)
                {
                    var emp = new EmployeeDetails();
                    string projectName = Cldb.PROJECT.GetAll().Where(x => x.PROJ_ID == pr.PROJ_ID).Select(x => x.PROJ_NM).FirstOrDefault();
                    empinfo = Cldb.EMP_INFO.GetAll().Where(t => t.EMP_ID == pr.EMP_ID).FirstOrDefault();

                    emp.EMP_ID = empinfo.EMP_ID;
                    emp.EMP_NAME = empinfo.FRST_NM;
                    emp.PROJ_NM = projectName;
                    emp.PROJ_ID = pr.PROJ_ID;

                    if (!proj.projresrc.Contains(emp))
                        proj.projresrc.Add(emp);
                }
            }
            return Ok(proj);
        }

