        private KPIWithTargets GetKPIWithTargets(KPI kp, DateRange range)
        {
            KPIWithTargets kpiWithTargets = new KPIWithTargets()
            {
                ID = kp.ID,
                CUSTOMER_ID = kp.CUSTOMER_ID,
                PROJECT_ID = kp.PROJECT_ID,
                GOAL_ID = kp.GOAL_ID,
                SERVICE_AREA = kp.SERVICE_AREA,
                ABBREVIATION = kp.ABBREVIATION,
                KPI_NAME = kp.KPI_NAME,
                SUPPORT_WINDOW = kp.SUPPORT_WINDOW,
                FREQUENCY = kp.FREQUENCY,
                PRIORITY = kp.PRIORITY,
                SLA_TARGET_UNIT_OF_MEASUREMENT = kp.SLA_TARGET_UNIT_OF_MEASUREMENT,
                DISPLAY_ORDER = kp.DISPLAY_ORDER,
                CHART_TYPE = kp.CHART_TYPE,
                SHOW_IN_CHART = kp.SHOW_IN_CHART,
                GLOBAL_KPI_CATEGORY_ID = kp.GLOBAL_KPI_CATEGORY_ID,
                IS_SOW_COMMITMENT = kp.IS_SOW_COMMITMENT,
                CREATED_BY = kp.CREATED_BY,
                CREATED_DATE = kp.CREATED_DATE,
                UPDATED_BY = kp.UPDATED_BY,
                UPDATED_DATE = kp.UPDATED_DATE,
                ISACTIVE = kp.ISACTIVE
            };
            var kpiDetails = CSPdb.KPI_DETAILS.GetAll().FirstOrDefault(x => x.ISACTIVE && x.KPI_ID == kp.ID);
            var targets = CSPdb.KPI_TARGETS.GetAll().Where(t => t.KPI_ID == kp.ID && t.ISACTIVE == true).OrderBy(t => t.START_DATE).ToList();
            ExtendStartAndEndDate(targets);
            kpiWithTargets.KPI_TARGETS = targets.Where(x => range.StartDate >= x.START_DATE && range.EndDate <= x.END_DATE).ToList();
            return kpiWithTargets;
        }

        private DateTime GetStartDateTime(DateTime dt)
        {
            //dt = dt.ToLocalTime();
            dt = new DateTime(dt.Year, dt.Month, dt.Day, 0, 0, 0);
            //dt = Convert.ToDateTime(dt.ToString("dd-MMM-yyy") + " 00:00");
            return dt;
        }
        private DateTime GetEndDateTime(DateTime dt)
        {
            //dt = dt.ToLocalTime();
            dt = new DateTime(dt.Year, dt.Month, dt.Day, 23, 59, 0);
            //dt = Convert.ToDateTime(dt.ToString("dd-MMM-yyy") + " 23:59");
            return dt;
        }

        private void ExtendStartAndEndDate(List<KPI_TARGETS> kpitargets)
        {
            if (kpitargets == null)
                return;

            foreach (var target in kpitargets)
            {
                var startDateRange = new DateRange(target.START_DATE, enDateRange.Monthly);
                target.START_DATE = startDateRange.StartDate;

                var endDateRange = new DateRange(target.END_DATE, enDateRange.Monthly);
                target.END_DATE = endDateRange.EndDate;
            }
        }

        [GET("GetKPIDetailsMonthlyAndWeekly")]
        [ActionName("GetKPIDetailsMonthlyAndWeekly")]
        [HttpGet]
        public IHttpActionResult GetKPIDetailsMonthlyAndWeekly(string CustomerId, string ProjectId, DateTime date)
        {
            date = new DateTime(date.Year, date.Month, date.Day);
            DateRange range = new DateRange(date, enDateRange.Monthly);
            DateTime stDate = range.StartDate;
            DateTime enDate = range.EndDate;
            var inputYear = stDate.Year;
            var inputMonth = stDate.Month;

            var allGoals = CSPdb.KPI_GOALS.GetAll().Where(t => t.ISACTIVE && t.CUSTOMER_ID == CustomerId && t.PROJECT_ID == ProjectId).ToList();
            var goals = new List<KPI_GOALS>();

            foreach (var goal in allGoals)
            {
                if (inputYear > goal.START_DATE.Year && inputYear < goal.END_DATE.Year)
                    goals.Add(goal);

                else if (inputYear == goal.START_DATE.Year && inputYear == goal.END_DATE.Year)
                {
                    if (inputMonth >= goal.START_DATE.Month && inputMonth <= goal.END_DATE.Month)
                        goals.Add(goal);
                }
                else if (inputYear == goal.END_DATE.Year && inputMonth <= goal.END_DATE.Month)
                    goals.Add(goal);
                else if (inputYear == goal.START_DATE.Year && inputMonth >= goal.START_DATE.Month)
                    goals.Add(goal);
            }

            goals = goals.OrderBy(x => x.DISPLAY_ORDER).ToList();

            List<KPI_GOALS> goalswithkpi = new List<KPI_GOALS>();
            List<KPI_TARGETS> targets = new List<KPI_TARGETS>();
            List<KPI_DetailMonthandWeekly> alldetail = new List<KPI_DetailMonthandWeekly>();
            KPI_DETAILS kpidet = new KPI_DETAILS();
            List<KPI_DETAILS> kpilistdet = new List<KPI_DETAILS>();
            string[] weeks = new string[] { "Week1", "Week2", "Week3", "Week4", "Week5" };
            List<string> kpiser = new List<string>();

            foreach (KPI_GOALS gid in goals)
            {
                KPI_DetailMonthandWeekly detail = new KPI_DetailMonthandWeekly();
                var StartDate = DateTime.Now;
                var EndDate = DateTime.Now;

                var allkpis = CSPdb.KPI.GetAll().Where(t => t.GOAL_ID == gid.ID && t.ISACTIVE).ToList();
                var allKpiIds = allkpis.Select(x => x.ID);
                var allKpiTargets = CSPdb.KPI_TARGETS.GetAll().Where(x => x.ISACTIVE && allKpiIds.Contains(x.KPI_ID)).ToList();

                // extend KPI target date to its month start and end date

                ExtendStartAndEndDate(allKpiTargets);
                var kpis = new List<KPI>();

                foreach (var kpi in allkpis)
                {
                    var targetRow = allKpiTargets.FirstOrDefault(x => x.KPI_ID == kpi.ID && (range.StartDate >= x.START_DATE && range.EndDate <= x.END_DATE));

                    if (targetRow != null)
                        kpis.Add(kpi);
                }

                if (kpis.Count > 0)
                {
                    foreach (KPI kp in kpis)
                    {
                        detail.GOAL_ID = kp.GOAL_ID;
                        detail.GOAL_NAME = GetGoalName(kp.GOAL_ID);
