            List<KPIEntry> weekly = new List<Controllers.AllSysController.KPIEntry>();

            foreach (KPI_DetailMonthandWeekly l in alldetail)
            {
                foreach (KPI_Month_List m in l.KPI_Month)
                {
                    if (m.Monthly.Count > 0)
                    {
                        for (int i = 0; i < m.Monthly.Count; i++)
                        {
                            monthly.Add(new KPIEntry()
                            {
                                GOAL_NAME = l.GOAL_NAME,
                                KPI_AREA = m.SERVICE_AREA,
                                KPI_DESCRIPTION = m.kpilist[i].KPI_NAME,
                                PRIORITY = m.kpilist[i].PRIORITY,
                                SUPPORT_WINDOW = m.kpilist[i].SUPPORT_WINDOW,
                                TARGET_RED = m.KPIWithTargets[i].KPI_TARGETS.Count > 0 ? m.KPIWithTargets[i].KPI_TARGETS[0].SLA_TARGET_LOW_DESCRIPTION : "",
                                TARGET_AMBER = m.KPIWithTargets[i].KPI_TARGETS.Count > 0 ? m.KPIWithTargets[i].KPI_TARGETS[0].SLA_TARGET_MEDIUM_DESCRIPTION : "",
                                TARGET_GREEN = m.KPIWithTargets[i].KPI_TARGETS.Count > 0 ? m.KPIWithTargets[i].KPI_TARGETS[0].SLA_TARGET_HIGH_DESCRIPTION : "",
                                TARGET_BLUE = m.KPIWithTargets[i].KPI_TARGETS.Count > 0 ? m.KPIWithTargets[i].KPI_TARGETS[0].SLA_TARGET_VERYHIGH_DESCRIPTION : "",
                                UOM = m.kpilist[i].SLA_TARGET_UNIT_OF_MEASUREMENT,
                                details = m.Monthly[i]
                            });
                        }
                    }
                }
            }

            string table = "<table border=1>";
            if (monthly.Count > 0)
            {

                var tmpGoals = monthly.GroupBy(t => t.GOAL_NAME);
                foreach (var goal in tmpGoals)
                {
                    table += "<tr><td rowspan='" + goal.ToList().Count + "'>" + goal.Key + "</td>";
                    var tmpAreas = goal.ToList().GroupBy(t => t.KPI_AREA);
                    int i = 0;
                    foreach (var details in tmpAreas)
                    {
                        if (i > 0)
                            table += "<tr>";
                        table += "<td rowspan='" + details.ToList().Count + "'>" + details.Key + "</td>";
                        int j = 0;
                        foreach (var item in details.ToList())
                        {
                            if (j > 0)
                                table += "<tr>";
                            table += "<td>" + item.KPI_DESCRIPTION + "</td>";
                            table += "<td>" + item.PRIORITY + "</td>";
                            table += "<td>" + item.SUPPORT_WINDOW + "</td>";
                            table += "<td>" + item.TARGET_RED + "</td>";
                            table += "<td>" + item.TARGET_AMBER + "</td>";
                            table += "<td>" + item.TARGET_GREEN + "</td>";
                            table += "<td>" + item.TARGET_BLUE + "</td>";
                            table += "<td>" + item.TARGET_BLUE + "</td>";
                            table += "<td>" + item.UOM + "</td>";
                            table += "<td>" + item.details.KPI_ACTUAL + "</td></tr>";
                            j += 1;
                        }

                        i += 1;
                    }
                }
            }
            table += "</table>";
            return Ok(alldetail);
        }

        private object GetStartAndEnddateofQuarterlyKPI(DateTime startDate, DateTime endDate, DateTime selectedDate)
        {
            var StartDate = GetStartDateTime(startDate);
            var EndDate = GetEndDateTime(endDate);
            var periodstDate = StartDate;
            var periodedDate = EndDate;
            int QuarterMonthCount = 1;

            while (StartDate <= EndDate)
            {
                if (QuarterMonthCount == 4)
                {
                    periodstDate = StartDate;
                    QuarterMonthCount = 1;
                }

                if (selectedDate.Month == StartDate.Month && selectedDate.Year == StartDate.Year)
                {
                    periodedDate = periodstDate.AddMonths(3).AddSeconds(-1);
                    break;
                }

                StartDate = StartDate.AddMonths(1);
                QuarterMonthCount++;
            }

            return new
            {
                startdate = periodstDate,
                enddate = periodedDate
            };
        }

