        [POST("GetKpiAdditionalData")]
        [ActionName("GetKpiAdditionalData")]
        [HttpPost]
        public IHttpActionResult GetKpiAdditionalData([FromBody] List<KPI_DetailMonthandWeekly> kpiDetails)
        {
            LogRequest(prefix: "GetKpiMetricsAdditionalData", content: JsonConvert.SerializeObject(kpiDetails));
            var watch = Stopwatch.StartNew();
            var allKpiDetails = new List<KPI_DETAILS>();
            foreach (KPI_DetailMonthandWeekly l in kpiDetails)
            {
                foreach (KPI_Month_List m in l.KPI_Month)
                {
                    foreach (KPI_DETAILS k in m.Monthly)
                    {
                        allKpiDetails.Add(k);
                    }
                }
                foreach (KPI_Quarterly_List m in l.KPI_Quaterly)
                {
                    foreach (KPI_DETAILS k in m.Quarterly)
                    {
                        allKpiDetails.Add(k);
                    }
                }
                foreach (KPI_Week_List m in l.KPI_week)
                {
                    foreach (KPI_DETAILS k in m.Week1.Concat(m.Week2).Concat(m.Week3).Concat(m.Week4).Concat(m.Week5))
                    {
                        allKpiDetails.Add(k);
                    }
                }
            }

            var capaDataCollection = new CAPADataHolder();
            var baseMeasureDataCollection = GetBaseMeasureDataCollection(allKpiDetails.Select(x => new Tuple<int, int>(x.KPI_ID, x.ID)).ToList());
            capaDataCollection = GetCAPAAndRCADataCollection(allKpiDetails.Select(x => x.ID).ToList());
            var kpiDetailsIdList = allKpiDetails.Select(x => x.ID).ToList();
            var kpiDetailsEty = CSPdb.KPI_DETAILS.GetAll().Where(x => x.ISACTIVE && kpiDetailsIdList.Contains(x.ID)).ToList();

            foreach (var item in allKpiDetails)
            {
                var kpiDetail = kpiDetailsEty.FirstOrDefault(x => x.ID == item.ID);
                if (baseMeasureDataCollection.BaseMeasureData.Count > 0)
                {
                    item.BaseMeasureDataList = baseMeasureDataCollection.BaseMeasureData[item.KPI_ID];
                }

                if (kpiDetail != null)
                    item.CapaStage = GetCAPAStagesForKPIInternal(item.ID, capaDataCollection);
                else item.CapaStage = new FINDING_STAGE_DATA
                {
                    AUDIT_REPORTING_FINDING = new AUDIT_REPORTING_FINDING { FINDINGS = new AUDIT_CHECKLIST_PROJECT_FINDINGS { } },
                    CAPA_REVIEW = new CAPA_REVIEW { CAPA = new List<AUDIT_FINDINGS_CAPA_REVIEW_EXTENDED>() },
                    CAP_IMPLEMENTATION = new AUDIT_CAPA_IMPLEMENTATION { CAPA = new List<AUDIT_FINDING_CAPA_IMPLEMENTATION>() },
                    CAP_VERIFICATION = new AUDIT_REPORTING_VERIFICATION { CAPA = new List<AUDIT_FINDING_CAPA_VERIFICATION>() },
                    CAPA_SUBMISSION = new CAPA_SUBMISSION { CAPA = new List<AUDIT_FINDING_CAPPA_EXT>() },
                    CAPA_CUSTOMER_APPROVAL = new CAPA_CUSTOMER_APPROVAL { CAPA = new List<CUSTOMER_CAPA_APPROVAL>() },

                };
            }

            FillResponseTime(watch);
            return Ok(allKpiDetails);
        }


        [GET("GetMoMsWithDate")]
        [ActionName("GetMoMsWithDate")]
        [HttpGet]
        public IHttpActionResult GetMoMsWithDate(DateTime Date, string CustId)
        {
            var first = new DateTime(Date.Year, Date.Month, 1);
            var last = first.AddMonths(1).AddDays(-1).AddHours(23).AddMinutes(59).AddSeconds(59);
            DateRange dtRange = new DateRange(Date, enDateRange.Weekly);
            CUSTOMER_MOM_DETAILS cmo = new CUSTOMER_MOM_DETAILS();
            List<CUSTOMER_MOM_DETAILS> cmod = new List<CUSTOMER_MOM_DETAILS>();
            List<string> key = new List<string>();
            //var momdet = CSPdb.CUSTOMER_MOM_DETAILS.GetAll().Where(t => t.MOM_DATE >= first && t.MOM_DATE <= last && t.ISACTIVE == true && t.PROJECT_ID.Contains(ProjId)).GroupBy(c => c.MOM_ID);

            var momdet = CSPdb.CUSTOMER_MOM_DETAILS.GetAll().Where(t => t.MOM_DATE >= first && t.MOM_DATE <= last && t.ISACTIVE == true && t.CUSTOMER_ID == CustId).GroupBy(c => c.MOM_ID);

            foreach (var item in momdet)
            {
                key.Add(item.Key);
            }
            foreach (string p in key)
            {
                cmod.Add(CSPdb.CUSTOMER_MOM_DETAILS.GetAll().Where(t => t.MOM_ID == p && t.ISACTIVE == true).FirstOrDefault());
            }
            return Ok(cmod);
        }

        [GET("GetProjectCharts")]
        [ActionName("GetProjectCharts")]
        [HttpGet]
        public IHttpActionResult GetProjectCharts(string ProjectId)
        {
            List<SQA_PROJECT_CHART_PARAMS> charts = new List<SQA_PROJECT_CHART_PARAMS>();
            List<SQA_PROJECT_CHART_PARAMS_WITH_FILTER> chartsWithFilter = new List<SQA_PROJECT_CHART_PARAMS_WITH_FILTER>();
            charts = CSPdb.SQA_PROJECT_CHART_PARAMS.GetAll().Where(t => (t.PROJECT_ID == ProjectId || t.CHART_USER == "SYSTEM") && t.ISACTIVE == true).OrderBy(t => t.CATEGORY).ThenBy(t => t.SUBCATEGORY).ThenBy(t => t.TITLE).ToList();

            foreach (SQA_PROJECT_CHART_PARAMS c in charts)
            {
                string s = JsonConvert.SerializeObject(c);
                SQA_PROJECT_CHART_PARAMS_WITH_FILTER cf = JsonConvert.DeserializeObject<SQA_PROJECT_CHART_PARAMS_WITH_FILTER>(s);
                cf.FILTERS = CSPdb.SQA_CHART_FILTER.GetAll().Where(t => t.CHART_ID == c.ID && t.ISACTIVE == true).ToList();
                chartsWithFilter.Add(cf);
            }
            return Ok(chartsWithFilter);
        }

        [GET("GetMOMDetailsbyMOMId")]
        [ActionName("GetMOMDetailsbyMOMId")]
        [HttpGet]
        public IHttpActionResult GetMOMDetailsbyMOMId(string MOMId, string ProjId, bool IsGAVS)
        {
            string empId = "";
            if (Request.Headers.Contains("empId"))
                empId = Request.Headers.GetValues("empId").ToList()[0];
            List<CUSTOMER_MOM_DETAILS> cmod = new List<CUSTOMER_MOM_DETAILS>();
            List<MOM.MOM_DETAIL> nn = new List<MOM.MOM_DETAIL>();
            string createdBy = CSPdb.CUSTOMER_MOM_DETAILS.GetAll().Where(t => t.MOM_ID == MOMId && t.ISACTIVE == true).Select(t => t.CREATED_BY).FirstOrDefault();
            cmod = CSPdb.CUSTOMER_MOM_DETAILS.GetAll().Where(t => t.MOM_ID == MOMId && t.ISACTIVE == true).ToList<CUSTOMER_MOM_DETAILS>();
            if (IsGAVS == true)
            {
                if (createdBy == empId)
                {
                    cmod = CSPdb.CUSTOMER_MOM_DETAILS.GetAll().Where(t => t.MOM_ID == MOMId && t.ISACTIVE == true).ToList<CUSTOMER_MOM_DETAILS>();
                }
                else
                {
                    cmod = CSPdb.CUSTOMER_MOM_DETAILS.GetAll().Where(t => t.MOM_ID == MOMId && t.ISACTIVE == true && t.PROJECT_ID.Contains(ProjId)).ToList<CUSTOMER_MOM_DETAILS>();
                }
            }
            else
            {
                cmod = CSPdb.CUSTOMER_MOM_DETAILS.GetAll().Where(t => t.MOM_ID == MOMId && t.ISACTIVE == true && t.PROJECT_ID.Contains(ProjId)).ToList<CUSTOMER_MOM_DETAILS>();
            }
            MOM mm = new MOM();
            mm.MEETING_DESCRIPTION = cmod[0].DESCRIPTION;
            mm.MEETING_DATE = cmod[0].MOM_DATE;
            mm.MEETING_TIME = cmod[0].MOM_TIME;
            mm.MEETING_VENUE = cmod[0].MOM_VENUE;
            mm.CHAIRPERSON = cmod[0].MOM_CHAIRPERSON;
            mm.MEETING_AGENDA = cmod[0].MOM_AGENDA;
            mm.MEETING_PARTICIPANTS = cmod[0].MOM_PARTICIPANTS;
            mm.CREATED_BY = cmod[0].CREATED_BY;
            mm.STATUS = cmod[0].MOM_STATUS;
            foreach (CUSTOMER_MOM_DETAILS cd in cmod)
            {
                MOM.MOM_DETAIL mdet = new MOM.MOM_DETAIL();
                string[] cust = cd.CUSTOMER_ID.Split(',');
                string[] proj = cd.PROJECT_ID.Split(',');
                foreach (string c in cust)
                    mdet.CUSTOMER_ID.Add(c);
                foreach (string p in proj)
                    mdet.PROJECT_ID.Add(p);
                mdet.ID = cd.ID;
                mdet.DISCUSSION_POINTS = cd.DISCUSSION_POINTS;
                mdet.ACTION_ITEM = cd.ACTION_ITEM_DESCRIPTION;
                mdet.PRIORITY = cd.ACTION_ITEM_PRIORITY;
                //mdet.RESPONSIBILITY = GetEmpDet(cd.ACTION_ITEM_RESPONSIBILITY);
                mdet.RESPONSIBILITY = cd.ACTION_ITEM_RESPONSIBILITY;
                if (cd.ACTION_ITEM_TARGET_DATE != null)
                    mdet.TARGET_DATE = Convert.ToDateTime(cd.ACTION_ITEM_TARGET_DATE);
                else
                    mdet.TARGET_DATE = null;
                nn.Add(mdet);
            }
            mm.MOM_ITEMS = nn;
            return Ok(mm);
        }
