        [POST("GetTestsStatus")]
        [ActionName("GetTestsStatus")]
        [HttpPost]
        public IHttpActionResult GetTestsStatus(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;

            ExecutionTestsResults results = JsonConvert.DeserializeObject<ExecutionTestsResults>(json);
            List<AUDIT_EXECUTION_MODEL> resultList = new List<AUDIT_EXECUTION_MODEL>();
            foreach (var test in results.TESTSARRAY)
            {
                AUDIT_EXECUTION_MODEL result = CSPdb.AUDIT_EXECUTION_MODEL.GetAll().Where(x => x.CUSTOMER_ID == results.CUSTOMER_ID &&
                                                         x.PROJECT_ID == results.PROJECT_ID &&
                                                         x.TEST_ID == test.ID).FirstOrDefault();
                if (result != null)
                    resultList.Add(result);
            }
            return Ok(resultList);
        }

