        private string GetEmployeeNamebyId(string EmpId)
        {
            //int id = 0;
            string result = EmpId;
            //if (int.TryParse(EmpId, out id))
            result = Cldb.EMP_INFO.GetAll().FirstOrDefault(t => t.EMP_ID == EmpId)?.FRST_NM;
            if (string.IsNullOrWhiteSpace(result))
            {
                result = Cldb.EMP_INFO.GetAll().FirstOrDefault(t => t.EMAIL_ID == EmpId)?.FRST_NM;
            }
            if (string.IsNullOrWhiteSpace(result))
            {
                result = CSPdb.CONTACTS.GetAll().FirstOrDefault(x => x.CONTACT_EMAILID == EmpId)?.CONTACT_NAME;
            }
            return result ?? EmpId;
        }


        [GET("GetProcessNew")]
        [ActionName("GetProcessNew")]
        [HttpGet]
        public IHttpActionResult GetProcessNew(string ProjId)
        {
            PROJECT_PROCESS_DATA ProcessData = new PROJECT_PROCESS_DATA();

            List<PROJECT_PROCESS> ppr = CSPdb.PROJECT_PROCESS.GetAll().Where(t => t.PROJECT_ID == ProjId && t.ISACTIVE == true).OrderByDescending(t => t.PUBLISH_DATE).ToList<PROJECT_PROCESS>();
            List<string> reportType = ppr.Select(t => t.REPORT_TYPE).Distinct().ToList<string>();

            foreach (string rp in reportType)
            {
                PROJECT_PROCESS_TYPE processType = new PROJECT_PROCESS_TYPE();
                processType.REPORT_TYPE = rp;

                List<string> category = new List<string>();
                category = ppr.Where(t => t.REPORT_TYPE == rp && t.CATEGORY != null).Select(t => t.CATEGORY).Distinct().ToList<string>();

                //Files without category
                processType.PROJECT_PROCESS = ppr.Where(t => t.CATEGORY == null && t.REPORT_TYPE == rp).ToList<PROJECT_PROCESS>();
                //Files with category
                if (category.Count > 0)
                {
                    foreach (string c in category)
                    {
                        PROCESS_CATEGORY processCategory = new PROCESS_CATEGORY();
                        processCategory.REPORT_CATEGORY = c;
                        processCategory.PROJECT_PROCESS = ppr.Where(t => t.REPORT_TYPE == rp && t.CATEGORY == c).ToList<PROJECT_PROCESS>();
                        if (processCategory.PROJECT_PROCESS != null)
                            processType.PROCESS_CATEGORY.Add(processCategory);
                    }
                }


                if (processType != null)
                    ProcessData.PROJECT_PROCESS_TYPE.Add(processType);

                //Filling Type and category names

            }

            foreach (PROJECT_PROCESS_TYPE PType in ProcessData.PROJECT_PROCESS_TYPE)
            {
                DDData ddData = new DDData();
                ddData.REPORT_TYPE = PType.REPORT_TYPE;
                ddData.REPORT_CATEGORY = PType.PROCESS_CATEGORY.Select(t => t.REPORT_CATEGORY).ToList<string>();
                ProcessData.DDData.Add(ddData);
            }

            //Add WSR

            if (ProcessData.DDData.Where(t => t.REPORT_TYPE == "WSR").ToList().Count == 0)
            {
                ProcessData.DDData.Add(new DDData() { REPORT_TYPE = "WSR" });
            }
            if (ProcessData.DDData.Where(t => t.REPORT_TYPE == "Audit Reports").ToList().Count == 0)
            {
                ProcessData.DDData.Add(new DDData() { REPORT_TYPE = "Audit Reports" });
            }

            //if (ProcessData)
            //{
            //    ProcessData.DDData.Add(new DDData() { REPORT_TYPE = "WSR" });
            //    ProcessData.DDData.Add(new DDData() { REPORT_TYPE = "WSR" });
            //}
            ProcessData.PROJECT_PROCESS_TYPE = ProcessData.PROJECT_PROCESS_TYPE.OrderBy(s => s.REPORT_TYPE).ToList<PROJECT_PROCESS_TYPE>();
            return Ok(ProcessData);
        }



        public List<CalendarDateRange> GetCalendarDateRangeList(DateTime Date, enDateRange Range)
        {
            List<CalendarDateRange> calendarDateRange = new List<Controllers.AllSysController.CalendarDateRange>();
            DateRange range = new DateRange(Date, Range);

            if (Range == enDateRange.Weekly)
            {
                //Before current date
                DateTime tmpdt = Convert.ToDateTime(Date.ToString());
                tmpdt = range.StartDate.AddDays(-1);
                for (int iCnt = 1; iCnt <= 4; iCnt++)
                {
                    DateRange tmprange = new DateRange(tmpdt, Range);
                    calendarDateRange.Add(new CalendarDateRange() { StartDate = tmprange.StartDate, EndDate = tmprange.EndDate, DisplayName = tmprange.StartDate.ToString("dd-MMM-yyyy") + " - " + tmprange.EndDate.ToString("dd-MMM-yyyy") });
                    tmpdt = tmprange.StartDate.AddDays(-1);
                }
                calendarDateRange.Add(new CalendarDateRange() { StartDate = range.StartDate, EndDate = range.EndDate, DisplayName = range.StartDate.ToString("dd-MMM-yyyy") + " - " + range.EndDate.ToString("dd-MMM-yyyy"), Current = true });


                //After current date
                tmpdt = Convert.ToDateTime(Date.ToString());
                tmpdt = range.EndDate.AddDays(1);

                for (int iCnt = 1; iCnt <= 4; iCnt++)
                {
                    DateRange tmprange = new DateRange(tmpdt, Range);
                    calendarDateRange.Add(new CalendarDateRange() { StartDate = tmprange.StartDate, EndDate = tmprange.EndDate, DisplayName = tmprange.StartDate.ToString("dd-MMM-yyyy") + " - " + tmprange.EndDate.ToString("dd-MMM-yyyy") });
                    tmpdt = tmprange.EndDate.AddDays(1);
                }

            }
            else if (Range == enDateRange.Monthly)
            {
                calendarDateRange.Add(new CalendarDateRange() { StartDate = range.StartDate, EndDate = range.EndDate, DisplayName = range.StartDate.ToString("dd-MMM-yyyy") + " - " + range.EndDate.ToString("dd-MMM-yyyy"), Current = true });

            }
            calendarDateRange = calendarDateRange.OrderBy(t => t.StartDate).ToList();

            return calendarDateRange;
        }

        public class TimesheetType
        {
            public TimesheetType()
            {
                DateRange range = new Model.CSP.DateRange(DateTime.Now, enDateRange.Monthly);

                for (DateTime date = range.StartDate; date <= range.EndDate; date = date.AddDays(1))
                    this.SelectedDates.Add(date.Day.ToString());

                //int days = DateTime.DaysInMonth(DateTime.Now.Year, DateTime.Now.Month);
                //this.SelectedDates = Enumerable.Range(0, days).ToList<int>();
            }
            public enDateRange Period { get; set; } = enDateRange.Monthly;
            public List<CalendarDateRange> DateRange { get; set; } = new List<CalendarDateRange>();
            public CalendarDateRange SelectedDateRange { get; set; } = new CalendarDateRange();
            public List<string> SelectedDates { get; set; } = new List<string>();
            //
            public int DayLimit { get; set; }
            //
        }
        public class CalendarDateRange
        {
            public CalendarDateRange()
            {
                DateTime dt = DateTime.Now;
                this.StartDate = new DateTime(dt.Year, dt.Month, 1);
                this.EndDate = this.StartDate.AddMonths(1).AddMinutes(-1);
            }
            public DateTime StartDate { get; set; }
            public DateTime EndDate { get; set; }
            public string DisplayName { get; set; }
            public bool Current { get; set; }
        }


        [GET("GetTimesheetDetailsByEmpId")]
        [ActionName("GetTimesheetDetailsByEmpId")]
        [HttpGet]
        public IHttpActionResult GetTimesheetDetailsByEmpId()
        {
            string CustId = this.GetHeaderDetails_String("custId");
            string EmpId = this.GetHeaderDetails_String("empid");
            DateTime StartDate = this.GetHeaderDetails_Date("startDate");
            DateTime EndDate = this.GetHeaderDetails_Date("endDate");

            List<ProjectTimesheetDetails> projects = new List<ProjectTimesheetDetails>();
            var query = Cldb.AppRepo.ProjectsWithBillingProj(EmpId, "");
            List<Projects> pr = query.Where(t => t.CUST_ID == CustId).ToList();

            foreach (Projects proj in pr)
            {
                PROJECT_RESOURCE psrc = Cldb.PROJECT_RESOURCE.GetAll().Where(t => t.PROJ_ID == proj.BILLING_PROJ_ID && t.EMP_ID == EmpId).FirstOrDefault(); //test                
                                                                                                                                                            //PROJECT_RESOURCE psrc = Cldb.PROJECT_RESOURCE.GetAll().Where(t => t.PROJ_ID == proj.BILLING_PROJ_ID && t.EMP_ID == EmpId && t.END_DATE >= EndDate).FirstOrDefault(); //test                
