                //List<TimesheetDetailsMonthly> timesheets = Cldb.AppRepo.TimesheetDetailsMonthly(EmpId, proj.PROJ_ID, proj.BILLING_PROJ_ID, GetMonthId(Month), Year).ToList<TimesheetDetailsMonthly>();
                decimal sum = timesheets.Select(t => t.CLOCKED_MINS ?? 0).Sum();
                string ProjName = proj.PROJ_NM;
                if (proj.PROJ_ID != proj.BILLING_PROJ_ID)
                    ProjName += " (Onsite)";

                List<PROJECT_RESOURCE> lstObj = Cldb.AppRepo.TimeSheetTaggedProject(StartDate, EndDate, EmpId).ToList<PROJECT_RESOURCE>();
                foreach (var s in lstObj)
                {
                    string getprojid = s.PROJ_ID;
                    if (getprojid == proj.BILLING_PROJ_ID && !projects.Any(x => x.PROJ_ID == getprojid))
                    {
                        projects.Add(new ProjectTimesheetDetails() { PROJ_ID = proj.PROJ_ID, PROJ_NM = ProjName, BILLING_PROJ_ID = proj.BILLING_PROJ_ID, TIMESHEET = timesheets, TOTAL = sum, STATUS = GetTimesheetStatus(timesheets), COMMENTS = GetTimesheetComments(timesheets), STARTDATE = psrc.START_DATE, ENDDATE = psrc.END_DATE }); //test //bak
                    }
                }

                // projects.Add(new ProjectTimesheetDetails() { PROJ_ID = proj.PROJ_ID, PROJ_NM = ProjName, BILLING_PROJ_ID = proj.BILLING_PROJ_ID, TIMESHEET = timesheets, TOTAL = sum, STATUS = GetTimesheetStatus(timesheets), COMMENTS = GetTimesheetComments(timesheets), STARTDATE = psrc.START_DATE, ENDDATE = psrc.END_DATE }); //test //bak                                                           
                //projects.Add(new ProjectTimesheetDetails() { PROJ_ID = proj.PROJ_ID, PROJ_NM = proj.PROJ_NM, BILLING_PROJ_ID = proj.BILLING_PROJ_ID, TIMESHEET = timesheets, TOTAL = sum, STATUS = GetTimesheetStatus(timesheets), COMMENTS = GetTimesheetComments(timesheets) });                
            }
            return Ok(projects);
        }

        [GET("GetTimesheetType")]
        [ActionName("GetTimesheetType")]
        [HttpGet]
        public IHttpActionResult GetTimesheetType(string CustId)
        {
            TimesheetType timesheetType = new TimesheetType();
            TIMESHEET_SETTINGS timesheetSettings = Cldb.TIMESHEET_SETTINGS.GetAll().FirstOrDefault(t => t.CUST_ID == CustId);

            if (timesheetSettings != null)
            {
                timesheetType.Period = (enDateRange)Enum.Parse(typeof(enDateRange), timesheetSettings.TIME_ENTRY_PERIOD, true);
                if (timesheetType.Period == enDateRange.Weekly)
                {
                    timesheetType.DateRange = GetCalendarDateRangeList(DateTime.Now, timesheetType.Period);
                    timesheetType.SelectedDateRange = timesheetType.DateRange.FirstOrDefault(t => t.Current == true);
                    timesheetType.SelectedDates = new List<string>();

                    timesheetType.DayLimit = timesheetSettings.DAY_LIMIT.Value;

                    for (DateTime date = timesheetType.SelectedDateRange.StartDate; date <= timesheetType.SelectedDateRange.EndDate; date = date.AddDays(1))
                        timesheetType.SelectedDates.Add(date.ToString("dd-MMM"));
                }
                else if (timesheetType.Period == enDateRange.Monthly)
                {
                    DateRange range = new DateRange(timesheetType.SelectedDateRange.StartDate, timesheetType.Period);
                    timesheetType.DateRange = GetCalendarDateRangeList(range.StartDate, timesheetType.Period);
                    timesheetType.SelectedDateRange = new CalendarDateRange() { Current = true, StartDate = range.StartDate, EndDate = range.EndDate };
                    timesheetType.SelectedDates = new List<string>();

                    timesheetType.DayLimit = timesheetSettings.DAY_LIMIT.Value; //

                    for (DateTime date = timesheetType.SelectedDateRange.StartDate; date <= timesheetType.SelectedDateRange.EndDate; date = date.AddDays(1))
                        timesheetType.SelectedDates.Add(date.Day.ToString());
                }
            }
            return Ok(timesheetType);
        }


        [POST("GetCalendarDateRange")]
        [ActionName("GetCalendarDateRange")]
        [HttpPost]
        public IHttpActionResult GetCalendarDateRange(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            TimesheetType timesheetType = JsonConvert.DeserializeObject<TimesheetType>(json);

            if (timesheetType.Period == enDateRange.Weekly)
            {
                timesheetType.DateRange = GetCalendarDateRangeList(timesheetType.SelectedDateRange.StartDate, timesheetType.Period);
                timesheetType.SelectedDateRange = timesheetType.DateRange.FirstOrDefault(t => t.Current == true);
                timesheetType.SelectedDates = new List<string>();
                for (DateTime date = timesheetType.SelectedDateRange.StartDate; date <= timesheetType.SelectedDateRange.EndDate; date = date.AddDays(1))
                    timesheetType.SelectedDates.Add(date.ToString("dd-MMM"));
            }
            else if (timesheetType.Period == enDateRange.Monthly)
            {
                DateRange range = new DateRange(timesheetType.SelectedDateRange.StartDate, timesheetType.Period);
                timesheetType.DateRange = GetCalendarDateRangeList(range.StartDate, timesheetType.Period);
                timesheetType.SelectedDateRange = new CalendarDateRange() { Current = true, StartDate = range.StartDate, EndDate = range.EndDate };
                timesheetType.SelectedDates = new List<string>();
                for (DateTime date = timesheetType.SelectedDateRange.StartDate; date <= timesheetType.SelectedDateRange.EndDate; date = date.AddDays(1))
                    timesheetType.SelectedDates.Add(date.Day.ToString());
            }
            else if (timesheetType.Period == enDateRange.Custom)
            {
                timesheetType.SelectedDates = new List<string>();
                for (DateTime date = timesheetType.SelectedDateRange.StartDate.AddDays(1); date <= timesheetType.SelectedDateRange.EndDate.AddDays(1); date = date.AddDays(1))
                    timesheetType.SelectedDates.Add(date.ToString("MMM") + date.Day.ToString());
            }
            return Ok(timesheetType);
        }


        private bool CheckProjResourceDateRange(PROJECT_RESOURCE t, DateTime startDate, DateTime endDate)
        {
            return (startDate >= t.START_DATE && startDate <= t.END_DATE) || (endDate >= t.START_DATE && endDate <= t.END_DATE);
        }

        [GET("GetTimesheetDetailsByProjectId")]
