                        //if (!string.IsNullOrEmpty(empStatus))
                        //{
                        //    employee.STATUS = empStatus;
                        //}

                        projects.employees.Add(employee);
                    }


                }
            }
            projects.employees = projects.employees.OrderBy(t => t.FRST_NM).ToList<EmployeeTimesheetDetails>();
            FillResponseTime(watch);
            return Ok(projects);
        }


        private List<EmployeeTimesheetDetails> CreateMultipleTimesheetRecords(EmployeeTimesheetDetails employee)
        {
            List<EmployeeTimesheetDetails> result = new List<EmployeeTimesheetDetails>();
            var statuses = employee.TIMESHEET.Where(x => !string.IsNullOrWhiteSpace(x.TIME_ENTRY_STATUS)).Select(x => x.TIME_ENTRY_STATUS).Distinct().ToList();
            foreach (var item in statuses)
            {

                var newEmp = new EmployeeTimesheetDetails
                {
                    startdate = employee.startdate,
                    enddate = employee.enddate,
                    EMP_ID = employee.EMP_ID,
                    BILLING_PROJ_ID = employee.BILLING_PROJ_ID,
                    FRST_NM = employee.FRST_NM,
                    PROJ_ID = employee.PROJ_ID,
                    PROJ_NM = employee.PROJ_NM,
                    TIMESHEET = new List<TimesheetDetailsMonthly>()
                };
                foreach (var n in employee.TIMESHEET.GroupBy(x => x.DATE_ID))
                {
                    var dayTimesheet = n.FirstOrDefault(x => x.TIME_ENTRY_STATUS == item);
                    if (dayTimesheet != null)
                    {
                        newEmp.TIMESHEET.Add(new TimesheetDetailsMonthly
                        {
                            APPRL_DATE = dayTimesheet.APPRL_DATE,
                            BILLING_PROJ_ID = dayTimesheet.BILLING_PROJ_ID,
                            CLNDR_DATE = dayTimesheet.CLNDR_DATE,
                            CLNDR_DATE_DAY = dayTimesheet.CLNDR_DATE_DAY,
                            CLNDR_DAY_NAME = dayTimesheet.CLNDR_DAY_NAME,
                            DATE_ID = n.Key,
                            EMP_ID = dayTimesheet.EMP_ID,
                            CREATED_BY = dayTimesheet.CREATED_BY,
                            CREATED_DATE = dayTimesheet.CREATED_DATE,
                            OTHER_DETAILS = dayTimesheet.OTHER_DETAILS,
                            PROJ_ID = dayTimesheet.PROJ_ID,
                            PROJ_RESRC_TIME_ENTRY_ID = dayTimesheet.PROJ_RESRC_TIME_ENTRY_ID,
                            PROJ_TASK_ID = dayTimesheet.PROJ_TASK_ID,
                            REJECT_DATE = dayTimesheet.REJECT_DATE,
                            TASK_DESC = dayTimesheet.TASK_DESC,
                            REJECT_DESC = dayTimesheet.REJECT_DESC,
                            UPDATED_BY = dayTimesheet.UPDATED_BY,
                            UPDATED_DATE = dayTimesheet.UPDATED_DATE,
                            CLOCKED_MINS = dayTimesheet.CLOCKED_MINS,
                            TIME_ENTRY_STATUS = dayTimesheet.TIME_ENTRY_STATUS


                        });
                    }
                    else
                    {
                        newEmp.TIMESHEET.Add(new TimesheetDetailsMonthly
                        {
                            CLNDR_DATE = n.First().CLNDR_DATE,
                            PROJ_TASK_ID = n.First().PROJ_TASK_ID,
                            CLNDR_DATE_DAY = n.First().CLNDR_DATE_DAY,
                            CLNDR_DAY_NAME = n.First().CLNDR_DAY_NAME,
                            DATE_ID = n.Key,
                        });
                    }

                }

                newEmp.TOTAL = newEmp.TIMESHEET.Sum(c => c.CLOCKED_MINS ?? 0);
                newEmp.STATUS = GetTimesheetStatus(newEmp.TIMESHEET);
                newEmp.COMMENTS = GetTimesheetComments(newEmp.TIMESHEET);
                newEmp.REJECT_DESC = GetTimesheetRejectDescription(newEmp.TIMESHEET);
                result.Add(newEmp);



            }
            return result;
        }

        [POST("GetTimesheetDetailsByProjectIds")]
        [ActionName("GetTimesheetDetailsByProjectIds")]
        [HttpPost]
        public IHttpActionResult GetTimesheetDetailsByProjectIds(HttpRequestMessage request)
        {
            var watch = Stopwatch.StartNew();
            string PeriodType = GetHeaderDetails_String("periodType");
            DateTime StartDate = GetHeaderDetails_Date("startDate");
            DateTime EndDate = GetHeaderDetails_Date("endDate");

            if (PeriodType != string.Empty)
            {
                enDateRange enPeriod = (enDateRange)Enum.Parse(typeof(enDateRange), PeriodType, true);
                if (enPeriod == enDateRange.Monthly)
                {
                    DateRange dtRange = new DateRange(StartDate, enPeriod);
                    EndDate = dtRange.EndDate;
                }
            }


            string Status = string.Empty;
            List<string> lstStatus = new List<string>();
            if (Request.Headers.Contains("status"))
            {
                Status = Request.Headers.GetValues("status").ToList()[0];
                lstStatus = Status.Split(',').ToList<string>();
            }

            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            List<string> projIds = JsonConvert.DeserializeObject<List<string>>(json);
            List<PROJECT> projDetails = GetProjectList(projIds);
            List<string> ProjIdsWithBillingProjId = projDetails.Select(t => t.PROJ_ID).ToList();

            List<PROJECT_RESOURCE> employees = Cldb.PROJECT_RESOURCE.GetAll().Where(t => (projIds.Contains(t.PROJ_ID) || ProjIdsWithBillingProjId.Contains(t.PROJ_ID)) && t.BILL_FLG == true
            && ((StartDate >= t.START_DATE && StartDate <= t.END_DATE) || (EndDate >= t.START_DATE && EndDate <= t.END_DATE))).Distinct().ToList();

            List<PROJECT_RESOURCE_EXT> employeesWithBillingProjId = new List<PROJECT_RESOURCE_EXT>();
            foreach (PROJECT_RESOURCE PR in employees)
            {
                string s = JsonConvert.SerializeObject(PR);
                PROJECT_RESOURCE_EXT tmp = JsonConvert.DeserializeObject<PROJECT_RESOURCE_EXT>(s);
                tmp.PARENT_PROJ_ID = Cldb.PROJECT.GetAll().FirstOrDefault(t => t.PROJ_ID == PR.PROJ_ID).PARENT_PROJ_ID;
                employeesWithBillingProjId.Add(tmp);
            }

            var projectGroup = employeesWithBillingProjId.GroupBy(t => t.PARENT_PROJ_ID);

            List<ProjectTimesheetDetailsEmp> projectTimesheet = new List<ProjectTimesheetDetailsEmp>();
            foreach (var p in projectGroup)
            {
                ProjectTimesheetDetailsEmp timesheets = new ProjectTimesheetDetailsEmp();
                timesheets.PROJ_ID = p.Key;
                timesheets.PROJ_NM = projDetails.Where(t => t.PROJ_ID == p.Key).FirstOrDefault().PROJ_NM;
                timesheets.PROJ_ALIAS_NM = projDetails.Where(t => t.PROJ_ID == p.Key).FirstOrDefault().PROJ_ALIAS_NM;
                timesheets.employees = new List<EmployeeTimesheetDetails>();
                timesheets.REPORTING_MANAGER = CSPdb.CUSTOMER_PROJECTS.GetAll().Any(x => x.REPORTING && x.PROJ_ID == p.Key);
                var list = p.ToList();
                foreach (PROJECT_RESOURCE_EXT emp in list)
                {
                    EmployeeTimesheetDetails employee = new EmployeeTimesheetDetails();
                    employee.EMP_ID = emp.EMP_ID;
                    employee.PROJ_ID = timesheets.PROJ_ID;
                    employee.BILLING_PROJ_ID = emp.PROJ_ID;
                    List<EMP_INFO_FOR_CUSTOMER> DISPLAYNAME = Cldb.EMP_INFO_FOR_CUSTOMER.GetAll().Where(t => t.EMP_ID == employee.EMP_ID).ToList();

                    if (DISPLAYNAME.Count == 0)
                    {
                        employee.FRST_NM = Cldb.EMP_INFO.GetById(emp.EMP_ID).FRST_NM;
                    }

                    foreach (var DNAME in DISPLAYNAME)
                    {
                        if (emp.EMP_ID == DNAME.EMP_ID)
                        {
                            employee.FRST_NM = Cldb.EMP_INFO_FOR_CUSTOMER.GetById(emp.EMP_ID).DISPLAY_NAME;
                        }
                    }

                    // employee.FRST_NM = Cldb.EMP_INFO.GetById(emp.EMP_ID).FRST_NM;
                    employee.startdate = emp.START_DATE; //
                    employee.enddate = emp.END_DATE; //                    

                    //employee.TIMESHEET = Cldb.AppRepo.TimesheetDetailsMonthly(emp.EMP_ID, emp.PARENT_PROJ_ID, emp.PROJ_ID, GetMonthId(Month), Year).ToList<TimesheetDetailsMonthly>();
                    employee.TIMESHEET = Cldb.AppRepo.TimesheetDetailsMonthly(emp.EMP_ID, emp.PARENT_PROJ_ID, emp.PROJ_ID, StartDate, EndDate).ToList<TimesheetDetailsMonthly>();

                    var statuses = employee.TIMESHEET.Where(x => !string.IsNullOrWhiteSpace(x.TIME_ENTRY_STATUS)).Select(x => x.TIME_ENTRY_STATUS).Distinct().ToList();

                    if (statuses.Count > 1)
                    {
                        timesheets.employees.AddRange(CreateMultipleTimesheetRecords(employee));
                        continue;
                    }

                    employee.TOTAL = employee.TIMESHEET.Select(t => t.CLOCKED_MINS ?? 0).Sum();
                    employee.STATUS = GetTimesheetStatus(employee.TIMESHEET);
                    employee.COMMENTS = GetTimesheetComments(employee.TIMESHEET);
                    employee.REJECT_DESC = GetTimesheetRejectDescription(employee.TIMESHEET);

                    if (Status == string.Empty)
                        timesheets.employees.Add(employee);
                    else if (employee.TIMESHEET.Count > 0 && employee.TOTAL > 0 && lstStatus.Contains(GetTimesheetStatus(employee.TIMESHEET)))
                        timesheets.employees.Add(employee);


                    //test
                    //string empStatus = string.Empty;
                    else if (employee.TOTAL > 0 && employee.STATUS.Contains(","))
                    {
                        //foreach (TimesheetDetailsMonthly objtsdmonth2 in employee.TIMESHEET)
                        //{
                        //    if (!objtsdmonth2.TIME_ENTRY_STATUS.Contains(","))
                        //    {
                        //        empStatus = objtsdmonth2.TIME_ENTRY_STATUS;
                        //    }
                        //}
                        //if (!string.IsNullOrEmpty(empStatus))
                        //{
                        //    employee.STATUS = empStatus;
                        //}
                        timesheets.employees.Add(employee);
                    }
                    //test            
                }
                timesheets.employees = timesheets.employees.OrderBy(t => t.EMP_ID).ToList<EmployeeTimesheetDetails>();
                projectTimesheet.Add(timesheets);
            }
            projectTimesheet = projectTimesheet.OrderBy(t => t.PROJ_NM).ToList();
            FillResponseTime(watch);
            return Ok(projectTimesheet);
        }


        [GET("GetTimesheetDetailsByCustomerId")]
        [ActionName("GetTimesheetDetailsByCustomerId")]
        [HttpGet]
        public IHttpActionResult GetTimesheetDetailsByCustomerId(HttpRequestMessage request)
        {
            var watch = Stopwatch.StartNew();
            string cutomerId = GetHeaderDetails_String("CustId");

            TimesheetType timesheetType = new TimesheetType();
            TIMESHEET_SETTINGS timesheetSettings = Cldb.TIMESHEET_SETTINGS.GetAll().FirstOrDefault(t => t.CUST_ID == cutomerId);
            timesheetType.Period = (enDateRange)Enum.Parse(typeof(enDateRange), timesheetSettings.TIME_ENTRY_PERIOD, true);

            DateTime dtoldesttimesheetdateforapproval;
            dtoldesttimesheetdateforapproval = Cldb.AppRepo.GetOldestTimesheetdateAvailableforApproval(cutomerId.ToString());

            List<ProjectTimesheetDetailsEmpByDateRange> lstProjectTimesheetDetailsEmpByDateRange = new List<ProjectTimesheetDetailsEmpByDateRange>();

            if (timesheetType.Period == enDateRange.Monthly)
            {


            }
            else if (timesheetType.Period == enDateRange.Weekly)
            {
                ProjectTimesheetDetailsEmpByDateRange objprojTimesheet;

                DateRangeModel dtrange = new DateRangeModel(dtoldesttimesheetdateforapproval, enDateRange.Weekly);
                objprojTimesheet = new ProjectTimesheetDetailsEmpByDateRange();
                objprojTimesheet.dtrange = dtrange;

                for (DateTime date = dtrange.startDate; date <= dtrange.endDate; date = date.AddDays(1))
                    objprojTimesheet.tmpSelectedDates.Add(date.ToString("MMM") + "-" + date.ToString("dd"));

                lstProjectTimesheetDetailsEmpByDateRange.Add(objprojTimesheet);

                while (!(DateTime.Today >= dtrange.startDate && DateTime.Today <= dtrange.endDate))
                {
                    dtrange = new DateRangeModel(dtrange.endDate.AddDays(1), enDateRange.Weekly);
                    objprojTimesheet = new ProjectTimesheetDetailsEmpByDateRange();
                    objprojTimesheet.dtrange = dtrange;

                    for (DateTime date = dtrange.startDate; date <= dtrange.endDate; date = date.AddDays(1))
                        objprojTimesheet.tmpSelectedDates.Add(date.ToString("MMM") + "-" + date.ToString("dd"));

                    lstProjectTimesheetDetailsEmpByDateRange.Add(objprojTimesheet);
                }

            }

            List<PROJECT> projDetails = Cldb.PROJECT.GetAll().Where(proj => proj.CUST_ID == cutomerId).ToList<PROJECT>();

            List<string> ProjIdsWithBillingProjId = projDetails.Select(t => t.PROJ_ID).ToList();

            List<PROJECT_RESOURCE> employees = Cldb.PROJECT_RESOURCE.GetAll().Where(t => (ProjIdsWithBillingProjId.Contains(t.PROJ_ID)) && t.BILL_FLG == true && t.END_DATE > DateTime.Now).Distinct().ToList();

            List<PROJECT_RESOURCE_EXT> employeesWithBillingProjId = new List<PROJECT_RESOURCE_EXT>();
            foreach (PROJECT_RESOURCE PR in employees)
            {
                string s = JsonConvert.SerializeObject(PR);
                PROJECT_RESOURCE_EXT tmp = JsonConvert.DeserializeObject<PROJECT_RESOURCE_EXT>(s);
                tmp.PARENT_PROJ_ID = Cldb.PROJECT.GetAll().Where(t => t.PROJ_ID == PR.PROJ_ID).FirstOrDefault().PARENT_PROJ_ID;
                employeesWithBillingProjId.Add(tmp);
            }

            var projectGroup = employeesWithBillingProjId.GroupBy(t => t.PARENT_PROJ_ID);


            foreach (ProjectTimesheetDetailsEmpByDateRange objtimesheetbydaterange in lstProjectTimesheetDetailsEmpByDateRange)
            {
                List<ProjectTimesheetDetailsEmp> projectTimesheet = new List<ProjectTimesheetDetailsEmp>();

                foreach (var p in projectGroup)
                {
                    ProjectTimesheetDetailsEmp timesheets = new ProjectTimesheetDetailsEmp();
                    timesheets.PROJ_ID = p.Key;
                    timesheets.PROJ_NM = projDetails.Where(t => t.PROJ_ID == p.Key).FirstOrDefault().PROJ_NM;
                    timesheets.PROJ_ALIAS_NM = projDetails.Where(t => t.PROJ_ID == p.Key).FirstOrDefault().PROJ_ALIAS_NM;
                    timesheets.employees = new List<EmployeeTimesheetDetails>();
                    foreach (PROJECT_RESOURCE_EXT emp in p.ToList())
                    {
                        EmployeeTimesheetDetails employee = new EmployeeTimesheetDetails();
                        employee.EMP_ID = emp.EMP_ID;
                        employee.PROJ_ID = timesheets.PROJ_ID;
                        employee.BILLING_PROJ_ID = emp.PROJ_ID;
                        employee.FRST_NM = Cldb.EMP_INFO.GetById(emp.EMP_ID).FRST_NM;
                        employee.TIMESHEET = Cldb.AppRepo.TimesheetDetailsMonthly(emp.EMP_ID, emp.PARENT_PROJ_ID, emp.PROJ_ID, objtimesheetbydaterange.dtrange.startDate, objtimesheetbydaterange.dtrange.endDate).Where(s => s.TIME_ENTRY_STATUS == "FOR APPROVAL" || object.Equals(s.TIME_ENTRY_STATUS, null)).ToList<TimesheetDetailsMonthly>();
                        var statuses = employee.TIMESHEET.Where(x => !string.IsNullOrWhiteSpace(x.TIME_ENTRY_STATUS)).Select(x => x.TIME_ENTRY_STATUS).Distinct().ToList();
                        if (statuses.Count > 1)
                        {
                            timesheets.employees.AddRange(CreateMultipleTimesheetRecords(employee));
                            continue;
                        }
                        employee.TOTAL = employee.TIMESHEET.Select(t => t.CLOCKED_MINS ?? 0).Sum();
                        employee.STATUS = GetTimesheetStatus(employee.TIMESHEET);
                        employee.COMMENTS = GetTimesheetComments(employee.TIMESHEET);
                        employee.REJECT_DESC = GetTimesheetRejectDescription(employee.TIMESHEET);
                        //if (Status == string.Empty)
                        //    timesheets.employees.Add(employee);
                        //else if (employee.TIMESHEET.Count > 0 && lstStatus.Contains(GetTimesheetStatus(employee.TIMESHEET)))

                        if (employee.TOTAL > 0)
                            timesheets.employees.Add(employee);
                    }
                    timesheets.employees = timesheets.employees.OrderBy(t => t.EMP_ID).ToList<EmployeeTimesheetDetails>();

                    if (timesheets.employees.Count > 0)
                        projectTimesheet.Add(timesheets);
                }
                projectTimesheet = projectTimesheet.OrderBy(t => t.PROJ_NM).ToList();

                objtimesheetbydaterange.multipleProjectTimesheets = projectTimesheet;
            }
            var result = lstProjectTimesheetDetailsEmpByDateRange.Where(temp => temp.multipleProjectTimesheets.Where(x => x.employees.Count() > 0).Count() > 0).OrderByDescending(sel => sel.dtrange.startDate);

            FillResponseTime(watch);
            return Ok(result);
        }

