        [GET("GetBestPracticeMatrix")]
        [ActionName("GetBestPracticeMatrix")]
        [HttpGet]
        public IHttpActionResult GetBestPracticeMatrix(string Status, string ServiceArea, string ProcessArea, int DeptId, string StartDate, string EndDate)
        {
            //List<PROJECT_BEST_PRACTICES> bestPracList = new List<PROJECT_BEST_PRACTICES>();
            List<BEST_PRACTICE_MATRIX_LIST> finalmatrixlist = new List<BEST_PRACTICE_MATRIX_LIST>();
            List<BESTPRACTICE_MATRIX> matrixlist = new List<BESTPRACTICE_MATRIX>();


            //Full List
            List<string> AllProjects = Cldb.PROJECT.GetAll().Where(t => t.PROJ_ID == t.PARENT_PROJ_ID && t.END_DATE > (DateTime.Now)).Select(t => t.PROJ_ID).ToList<string>();
            List<PROJECT_BEST_PRACTICES> bpFullList = new List<PROJECT_BEST_PRACTICES>();
            List<int> bpFullListIds = new List<int>();
            if (StartDate != null && EndDate != null)
            {
                DateTime start = Convert.ToDateTime(StartDate);
                DateTime end = Convert.ToDateTime(EndDate);
                bpFullList = CSPdb.PROJECT_BEST_PRACTICES.GetAll().Where(t => t.REFERENCE_BEST_PRACTICE_ID == 0 && t.STATUS == "Completed" && AllProjects.Contains(t.PROJECT_ID) && t.CREATED_DATE >= start && t.CREATED_DATE <= end).ToList();
                bpFullListIds = bpFullList.Select(t => t.ID).ToList();
            }
            //--------------------
            //Filter BP
            List<string> NotImpProjs = new List<string>();
            List<PROJECT_BEST_PRACTICES> FilteredBP = new List<PROJECT_BEST_PRACTICES>();
            FilteredBP = CSPdb.PROJECT_BEST_PRACTICES.GetAll().Where(t => bpFullListIds.Contains(t.REFERENCE_BEST_PRACTICE_ID) || bpFullListIds.Contains(t.ID)).ToList();
            if (Status != "All")
                FilteredBP = FilteredBP.Where(t => t.STATUS == Status).ToList();
            if (ServiceArea != "All")
                FilteredBP = FilteredBP.Where(t => t.STATUS == ServiceArea).ToList();
            if (ProcessArea != "All")
                FilteredBP = FilteredBP.Where(t => t.STATUS == ProcessArea).ToList();

            List<string> FilteredProjects = new List<string>();
            FilteredProjects = FilteredBP.Select(t => t.PROJECT_ID).Distinct().ToList();

            if (Status == "Not Implemented")
            {
                foreach (string proj in AllProjects)
                {
                    foreach (int bp in bpFullListIds)
                    {
                        if (FilteredBP.Where(t => t.PROJECT_ID == proj && (t.REFERENCE_BEST_PRACTICE_ID == bp || t.ID == bp)).ToList().Count == 0)
                        {
                            NotImpProjs.Add(proj);
                        }
                    }
                }
                FilteredProjects = NotImpProjs.Distinct().ToList();
            }

            foreach (PROJECT_BEST_PRACTICES i in bpFullList)
            {
                PROJECT_BEST_PRACTICES bestprac = CSPdb.PROJECT_BEST_PRACTICES.GetAll().Where(t => t.ID == i.ID).FirstOrDefault();
                BESTPRACTICE_MATRIX bpm = new BESTPRACTICE_MATRIX();
                BEST_PRACTICE_MATRIX_LIST matrix = new BEST_PRACTICE_MATRIX_LIST();
                bpm.PROJ_ID = bestprac.PROJECT_ID;
                bpm.STATUS = bestprac.STATUS;
                //matrixlist.Add(bpm);
                matrixlist = CSPdb.AppRepo.GetFilteredBestPractices(i.ID, DeptId).Where(t => FilteredProjects.Contains(t.PROJ_ID)).OrderBy(t => t.PROJ_NM).ToList();
                matrix.bestPractice = i.DESCRIPTION;
                matrix.processArea = i.PROCESS_AREA;
                matrix.referenceId = i.ID;
                matrix.matrix = matrixlist;
                finalmatrixlist.Add(matrix);
            }
            return Ok(finalmatrixlist);
        }

