        [POST("GetParametersByTypes")]
        [ActionName("GetParametersByTypes")]
        [HttpPost]
        public IHttpActionResult GetParametersByTypes(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            List<string> types = JsonConvert.DeserializeObject<List<string>>(json);
            types = types.ConvertAll(d => d.ToLower());

            List<PARAMETER_TABLE> parameters = CSPdb.PARAMETER_TABLE.GetAll().Where(t => types.Contains(t.NAME.ToLower()) && t.ISACTIVE == true).ToList();
            return Ok(parameters);
        }

