        [GET("GetAllIdeasInnovations")]
        [ActionName("GetAllIdeasInnovations")]
        [HttpGet]
        public IHttpActionResult GetAllIdeasInnovations(string ProcessArea, int DeptId, string StartDate, string EndDate, string IdeaType)
        {
            List<PROJECT_INNOVATION> innovationList = new List<PROJECT_INNOVATION>();
            List<INNOVATIONS_MATRIX> matrixlist = new List<INNOVATIONS_MATRIX>();
            if (StartDate != null && EndDate != null)
            {
                DateTime start = Convert.ToDateTime(StartDate);
                DateTime end = Convert.ToDateTime(EndDate).AddDays(1);
                List<string> project = Cldb.PROJECT.GetAll().Where(t => t.DEPT_ID == DeptId && t.END_DATE > (DateTime.Now)).Select(t => t.PROJ_ID).ToList<string>();
                if (ProcessArea == "All")
                {
                    if (IdeaType == "Ideas")
                    {
                        innovationList = CSPdb.PROJECT_INNOVATION.GetAll().Where(t => t.REFERENCE_IDEA_ID == 0 && t.STATUS == "Completed" && t.AUTOMATE == false && t.ISINNOVATION == false && t.ISPROCESSIMPROVEMENT == false && project.Contains(t.PROJECT_ID) && t.CREATED_DATE >= start && t.CREATED_DATE < end).ToList<PROJECT_INNOVATION>();
                    }
                    else if (IdeaType == "Innovation")
                    {
                        innovationList = CSPdb.PROJECT_INNOVATION.GetAll().Where(t => t.REFERENCE_IDEA_ID == 0 && t.STATUS == "Completed" && t.ISINNOVATION == true && project.Contains(t.PROJECT_ID) && t.CREATED_DATE >= start && t.CREATED_DATE <= end).ToList<PROJECT_INNOVATION>();
                    }
                    else if (IdeaType == "Process Improvement")
                    {
                        innovationList = CSPdb.PROJECT_INNOVATION.GetAll().Where(t => t.REFERENCE_IDEA_ID == 0 && t.STATUS == "Completed" && t.ISPROCESSIMPROVEMENT == true && project.Contains(t.PROJECT_ID) && t.CREATED_DATE >= start && t.CREATED_DATE <= end).ToList<PROJECT_INNOVATION>();
                    }
                    else if (IdeaType == "Automate")
                    {
                        innovationList = CSPdb.PROJECT_INNOVATION.GetAll().Where(t => t.REFERENCE_IDEA_ID == 0 && t.STATUS == "Completed" && t.AUTOMATE == true && project.Contains(t.PROJECT_ID) && t.CREATED_DATE >= start && t.CREATED_DATE <= end).ToList<PROJECT_INNOVATION>();
                    }

                }
                else if (IdeaType == "Ideas")
                {
                    innovationList = CSPdb.PROJECT_INNOVATION.GetAll().Where(t => t.AREA == ProcessArea && t.REFERENCE_IDEA_ID == 0 && t.STATUS == "Completed" && t.AUTOMATE == false && t.ISINNOVATION == false && t.ISPROCESSIMPROVEMENT == false && project.Contains(t.PROJECT_ID) && t.CREATED_DATE >= start && t.CREATED_DATE <= end).ToList<PROJECT_INNOVATION>();
                }
                else if (IdeaType == "Innovation")
                {
                    innovationList = CSPdb.PROJECT_INNOVATION.GetAll().Where(t => t.AREA == ProcessArea && t.REFERENCE_IDEA_ID == 0 && t.STATUS == "Completed" && t.ISINNOVATION == true && project.Contains(t.PROJECT_ID) && t.CREATED_DATE >= start && t.CREATED_DATE <= end).ToList<PROJECT_INNOVATION>();
                }
                else if (IdeaType == "Process Improvement")
                {
                    innovationList = CSPdb.PROJECT_INNOVATION.GetAll().Where(t => t.AREA == ProcessArea && t.REFERENCE_IDEA_ID == 0 && t.STATUS == "Completed" && t.ISPROCESSIMPROVEMENT == true && project.Contains(t.PROJECT_ID) && t.CREATED_DATE >= start && t.CREATED_DATE <= end).ToList<PROJECT_INNOVATION>();
                }
                else if (IdeaType == "Automate")
                {
                    innovationList = CSPdb.PROJECT_INNOVATION.GetAll().Where(t => t.AREA == ProcessArea && t.REFERENCE_IDEA_ID == 0 && t.STATUS == "Completed" && t.AUTOMATE == true && project.Contains(t.PROJECT_ID) && t.CREATED_DATE >= start && t.CREATED_DATE <= end).ToList<PROJECT_INNOVATION>();
                }
            }
            List<INNOVATIONS_MATRIX_LIST> finalmatrixlist = new List<INNOVATIONS_MATRIX_LIST>();
            //    if (StartDate != null && EndDate != null)
            //     {
            //    DateTime start = Convert.ToDateTime(StartDate);
            //    DateTime end = Convert.ToDateTime(EndDate);
            //    if (ProcessArea == "All")
            //        innovationList = CSPdb.PROJECT_INNOVATION.GetAll().Where(t => t.REFERENCE_IDEA_ID == 0 && t.STATUS == "Completed" && project.Contains(t.PROJECT_ID) && t.CREATED_DATE >= start && t.CREATED_DATE <= end).ToList<PROJECT_INNOVATION>();
            //    else
            //        innovationList = CSPdb.PROJECT_INNOVATION.GetAll().Where(t => t.AREA == ProcessArea && t.REFERENCE_IDEA_ID == 0 && t.STATUS == "Completed" && project.Contains(t.PROJECT_ID) && t.CREATED_DATE >= start && t.CREATED_DATE <= end).ToList<PROJECT_INNOVATION>();
            //}
            foreach (PROJECT_INNOVATION i in innovationList)
            {
                PROJECT_INNOVATION bestprac = CSPdb.PROJECT_INNOVATION.GetAll().Where(t => t.ID == i.ID).FirstOrDefault();
                INNOVATIONS_MATRIX bpm = new INNOVATIONS_MATRIX();
                INNOVATIONS_MATRIX_LIST matrix = new INNOVATIONS_MATRIX_LIST();
                bpm.PROJ_ID = bestprac.PROJECT_ID;
                bpm.STATUS = bestprac.STATUS;
                matrixlist.Add(bpm);
                matrixlist = CSPdb.AppRepo.GetFilteredIdeas(i.ID, DeptId);
                matrix.innovation = i.DESCRIPTION;
                matrix.processArea = i.AREA;
                matrix.referenceId = i.ID;
                matrix.matrix = matrixlist;
                finalmatrixlist.Add(matrix);
            }
            return Ok(finalmatrixlist);

        }
