        [GET("GetAnalyzedScoreForProject")]
        [ActionName("GetAnalyzedScoreForProject")]
        [HttpGet]
        public IHttpActionResult GetAnalyzedScoreForProject(string ProjId, string Month, string Year)
        {
            List<string> kpiScore = new List<string>();
            string risk_score = "";
            string issue_score;
            string csat_score;
            string training_score;
            string ideas_score;
            string improvements_score;
            string concerns_score;
            DateTime StartDateForComp;
            DateTime EndDateForComp;
            string date = "1-" + Month + "-" + Year;
            DateTime dt = Convert.ToDateTime(date);
            DateTime StartDate = dt;
            DateTime EndDate = dt.AddMonths(1).AddSeconds(-1);
            List<CRISP_AUTOMATION> crispList = new List<CRISP_AUTOMATION>();
            CRISP_AUTOMATION crispKPI = new CRISP_AUTOMATION();
            CRISP_AUTOMATION crispRisk = new CRISP_AUTOMATION();
            CRISP_AUTOMATION crispIssues = new CRISP_AUTOMATION();
            CRISP_AUTOMATION crispIdeas = new CRISP_AUTOMATION();
            CRISP_AUTOMATION crispImprovements = new CRISP_AUTOMATION();
            CRISP_AUTOMATION crispConcerns = new CRISP_AUTOMATION();
            CRISP_AUTOMATION crispCSAT = new CRISP_AUTOMATION();
            CRISP_AUTOMATION crisp_mandatory_training = new CRISP_AUTOMATION();

            List<CRISP_VALIDATIONS> validations = CSPdb.CRISP_VALIDATIONS.GetAll().ToList<CRISP_VALIDATIONS>();
            kpiScore = CSPdb.AppRepo.GetKPIForCRISP(ProjId, dt).ToList<string>();
            risk_score = CSPdb.AppRepo.GetRiskForCRISP(ProjId, StartDate, EndDate).ToString();
            issue_score = CSPdb.AppRepo.GetIssueForCRISP(ProjId, StartDate, EndDate).ToString();
            csat_score = CSPdb.AppRepo.GetCSATForCRISP(ProjId, StartDate.Month, StartDate.Year).ToString();
            ideas_score = CSPdb.AppRepo.GetIdeasForCRISP(ProjId, StartDate, EndDate).ToString();
            improvements_score = CSPdb.AppRepo.GetImprovementsForCRISP(ProjId, StartDate, EndDate).ToString();
            concerns_score = CSPdb.AppRepo.GetConcernsForCRISP(ProjId, StartDate, EndDate).ToString();

            if (dt.Month < 3)
            {
                StartDateForComp = new DateTime(dt.Year - 1, 04, 01);
                EndDateForComp = new DateTime(dt.Year, 03, 31);
            }
            else
            {
                StartDateForComp = new DateTime(dt.Year, 04, 01);
                EndDateForComp = new DateTime(dt.Year + 1, 03, 31);
            }
            training_score = CSPdb.AppRepo.GetMandatoryTrainingForCRISP(ProjId, StartDateForComp, EndDateForComp).ToString();

            List<CRISP_PROJECT_VALIDATIONS> crispProValidations = CSPdb.CRISP_PROJECT_VALIDATIONS.GetAll().Where(t => t.PROJECT_ID == ProjId).ToList<CRISP_PROJECT_VALIDATIONS>();
            CRISP_SCORES_VALIDATIONS crispValidations = new CRISP_SCORES_VALIDATIONS();
            List<CRISP_SCORES_CRITERIA> listcsv = new List<CRISP_SCORES_CRITERIA>();
            CRISP_SCORES_CRITERIA csv = new CRISP_SCORES_CRITERIA();
            crispKPI = GetKPICRISPSOW(kpiScore, validations);
            crispList.Add(crispKPI);

            crispKPI = GetKPICRISPGoal(kpiScore, true, validations);
            crispList.Add(crispKPI);

            crispRisk = GetRiskCRISP(risk_score, validations);
            crispList.Add(crispRisk);

            crispIssues = GetIssuesCRISP(issue_score, validations);
            crispList.Add(crispIssues);

            crispIdeas = GetIdeasCRISP(ideas_score, validations);
            crispList.Add(crispIdeas);

            crispImprovements = GetImprovementsCRISP(improvements_score, validations);
            crispList.Add(crispImprovements);

            crispConcerns = GetConcernsCRISP(concerns_score, IsActionitemsPending(ProjId, EndDate, "CSS"), validations);
            crispList.Add(crispConcerns);

            crispCSAT = GetCSATCRISP(csat_score, validations);
            crispList.Add(crispCSAT);

            crisp_mandatory_training = GetPCFindingsforCRISP(training_score, validations);
            crispList.Add(crisp_mandatory_training);

            return Ok(crispList);
        }
        private void FillCommentsAndValidationId(List<CRISP_VALIDATIONS> validations, CRISP_SCORES_VALIDATIONS crispValidations, int criteriaId, int scorePercent)
        {
            var v = validations.FirstOrDefault(t => t.CRITERIA_ID == criteriaId && t.SCORE_PERCENTAGE == scorePercent);
            if (v == null)
                v = validations.Where(t => t.CRITERIA_ID == criteriaId && t.SCORE_PERCENTAGE >= scorePercent).OrderBy(x => x.SCORE_PERCENTAGE).FirstOrDefault();
            if (v == null) return;

            crispValidations.VALIDATION_ID = v.ID;
            if (scorePercent == 100)
            {
                crispValidations.ACHIEVED = true;
            }
            else
            {
                crispValidations.COMMENTS = v.DEFAULT_COMMENTS;
            }
        }

        private CRISP_AUTOMATION GetKPICRISPSOW(List<string> kpiScore, List<CRISP_VALIDATIONS> validations)
        {
            CRISP_AUTOMATION crisp = new CRISP_AUTOMATION();
            CRISP_SCORES_CRITERIA csv = new CRISP_SCORES_CRITERIA { CRITERIA_ID = 1 };
            CRISP_SCORES_VALIDATIONS crispValidations = new CRISP_SCORES_VALIDATIONS();

            if (kpiScore.Any())
            {
                if (kpiScore.Contains("RED") || kpiScore.Contains("AMBER") || kpiScore.Contains(""))
                {
                    csv.SCORE_PERCENTAGE = "0";
                    FillCommentsAndValidationId(validations, crispValidations, 1, 0);
                    crisp.Comments = "1";
                    crisp.CreateActionItem = true;
                }
                else
                {
                    csv.SCORE_PERCENTAGE = "100";
                    FillCommentsAndValidationId(validations, crispValidations, 1, 100);
                }
            }
            else
            {
                csv.SCORE_PERCENTAGE = "0";
                FillCommentsAndValidationId(validations, crispValidations, 1, 0);
                crisp.Comments = "1";
            }
            crisp.crisp_score_criteria = csv;
            crisp.crisp_score_validations = crispValidations;
            return crisp;
        }



        private CRISP_AUTOMATION GetKPICRISPGoal(List<string> kpiScore, bool kpiSOWAvailable, List<CRISP_VALIDATIONS> validations)
        {
            CRISP_AUTOMATION crisp = new CRISP_AUTOMATION();
            CRISP_SCORES_CRITERIA csv = new CRISP_SCORES_CRITERIA();
            CRISP_SCORES_VALIDATIONS crispValidations = new CRISP_SCORES_VALIDATIONS();
            csv.CRITERIA_ID = 2;
            if (kpiScore.Count > 0)
            {
                var score = kpiScore.Count(x => x.Contains("GREEN"));
                var percent = Convert.ToInt32(score * 100 / kpiScore.Count);
                csv.SCORE_PERCENTAGE = percent.ToString();
                FillCommentsAndValidationId(validations, crispValidations, 2, percent);

            }
            else
            {
                if (kpiSOWAvailable)
                {
                    csv.SCORE_PERCENTAGE = "100";
                    FillCommentsAndValidationId(validations, crispValidations, 2, 100);
                }
                else
                {
                    csv.SCORE_PERCENTAGE = "0";
                    FillCommentsAndValidationId(validations, crispValidations, 2, 0);
                    crisp.Comments = "2";
                }

            }
            crisp.crisp_score_criteria = csv;
            crisp.crisp_score_validations = crispValidations;
            return crisp;
        }
