        private CRISP_AUTOMATION GetAuditReportFindingsforCRISP(string score, bool isActionItemPending, List<CRISP_VALIDATIONS> validations)
        {
            CRISP_AUTOMATION crisp = new CRISP_AUTOMATION();
            CRISP_SCORES_CRITERIA csv = new CRISP_SCORES_CRITERIA();
            CRISP_SCORES_VALIDATIONS crispValidations = new CRISP_SCORES_VALIDATIONS();
            csv.CRITERIA_ID = 9;
            if (isActionItemPending || score == "RED")
            {
                csv.SCORE_PERCENTAGE = "0";

                //crispValidations.COMMENTS = validations.Where(t => t.CRITERIA_ID == 11 && t.SCORE_PERCENTAGE == 0).Select(t => t.DEFAULT_COMMENTS).FirstOrDefault();
                //crispValidations.VALIDATION_ID = validations.Where(t => t.CRITERIA_ID == 11 && t.SCORE_PERCENTAGE == 0).Select(t => t.ID).FirstOrDefault();
                FillCommentsAndValidationId(validations, crispValidations, csv.CRITERIA_ID, 0);
                crisp.Comments = csv.CRITERIA_ID.ToString();
            }
            else if (score == "GREEN")
            {

                csv.SCORE_PERCENTAGE = "100";
                //csv.CRITERIA_ID = 10;
                //crispValidations.VALIDATION_ID = validations.Where(t => t.CRITERIA_ID == 11 && t.SCORE_PERCENTAGE == 0).Select(t => t.ID).FirstOrDefault();
                FillCommentsAndValidationId(validations, crispValidations, csv.CRITERIA_ID, 100);
