                //crispValidations.VALIDATION_ID = validations.Where(t => t.CRITERIA_ID == 11 && t.SCORE_PERCENTAGE == 0).Select(t => t.ID).FirstOrDefault();
                FillCommentsAndValidationId(validations, crispValidations, csv.CRITERIA_ID, 50);
            }
            crisp.crisp_score_criteria = csv;
            crisp.crisp_score_validations = crispValidations;
            return crisp;
        }
