        [GET("GetTimelineChart")]
        [ActionName("GetTimelineChart")]
        [HttpGet]
        public IHttpActionResult GetTimelineChart(string CustId, string ProjId, string StartDate, string EndDate)
        {
            List<string> Colors = new List<string>() { "#EFFFFF", "#FFFFEF", "#FFEFFF", "#dcffd4" };
            int iColor = 0;
            DateTime dtStartDate = Convert.ToDateTime(StartDate);
            DateTime dtEndDate = Convert.ToDateTime(EndDate);
            HighChartsAdvancedTimeline timeline = new HighChartsAdvancedTimeline();
            timeline.xAxis.type = "datetime";
            //timeline.xAxis.minTickInterval = 365 * 24 * 365;
            timeline.xAxis.labels.align = "left";
            DateTime tmpStartDate = dtStartDate;
            do
            {
                int iQuarter = 1;
                if (tmpStartDate.Month == 4)
                    iQuarter = 2;
                else if (tmpStartDate.Month == 7)
                    iQuarter = 3;
                else if (tmpStartDate.Month == 10)
                    iQuarter = 4;

                DateTime tmpEndDate = tmpStartDate.AddMonths(3).AddDays(-1);
                timeline.xAxis.plotBands.Add(new PlotBands()
                {
                    from = GetDateInMilliseconds(tmpStartDate),
                    to = GetDateInMilliseconds(tmpEndDate),
                    color = Colors[iColor],
                    label = new label_AdvancedTimeLine()
                    {
                        text = "<em>" + dtStartDate.Year.ToString() + "</em><br> Quarter " + iQuarter,
                        style = new style() { color = "#999999" },
                        y = 180
                    },
                });
                tmpStartDate = tmpStartDate.AddMonths(3);
                iColor += 1;
            } while (!(tmpStartDate > dtEndDate));


            timeline.title.text = "Journey Map";
            timeline.tooltip.style.width = "250px";
            //timeline.yAxis.Add(new yAxis_AdvancedTimeline()
            //{
            //    max = 200,
            //    labels = new labels_AdvancedTimeline() { enabled = false },
            //    title = new title() { text = "" },
            //    gridLineColor = "rgba(0, 0, 0, 0.07)"
            //});
            //timeline.yAxis.Add(new yAxis_AdvancedTimeline()
            //{
            //    allowDecimals = false,
            //    //max = 15,
            //    labels = new labels_AdvancedTimeline() { enabled = false, style = new style() { color = "rgba(144, 237, 125, 0.5)" } },
            //    title = new title() { text = "Employees", style = new style() { color = "rgba(144, 237, 125, 0.5)" } },
            //    oppsite = true,
            //    gridLineWidth = 0
            //});

            timeline.plotOptions.series.marker.enable = false;
            timeline.plotOptions.series.marker.symbol = "circle";
            timeline.plotOptions.series.marker.radius = 2;
            timeline.plotOptions.series.fillOpacity = 0.5;
            timeline.plotOptions.flags.tooltip.xDateFormat = "%B %e, %Y";

            List<series_AdvancedTimeline> kpiSeries = GetTimelineKPISeries(CustId, ProjId, dtStartDate, dtEndDate);
            foreach (series_AdvancedTimeline series in kpiSeries)
            {
                timeline.series.Add(series);
            }

            List<series_AdvancedTimeline> milestoneSeries = GetTimelineMilestoneSeries(CustId, ProjId, dtStartDate, dtEndDate);
            foreach (series_AdvancedTimeline series in milestoneSeries)
            {
                timeline.series.Add(series);
            }
            return Ok(timeline);
        }
        public double GetDateInMilliseconds(DateTime dt)
        {
            DateTime baseDate = new DateTime(1970, 1, 1);
            TimeSpan diff = dt - baseDate;
            return diff.TotalMilliseconds;
        }
        public double GetDateInMilliseconds(string dt)
        {
            DateTime baseDate = new DateTime(1970, 1, 1);
            TimeSpan diff = Convert.ToDateTime(dt) - baseDate;
            return diff.TotalMilliseconds;
        }
        private List<series_AdvancedTimeline> GetTimelineMilestoneSeries(string CustomerId, string ProjectId, DateTime dtStartDate, DateTime dtEndDate)
        {
            List<series_AdvancedTimeline> series = new List<series_AdvancedTimeline>();
            List<SUBPROJECT_TASK> tasks = CSPdb.SUBPROJECT_TASK.GetAll().Where(t => t.PROJECT_ID == ProjectId && t.STATUS.ToLower() == "completed" && t.SHOW_IN_CHART == true && t.ISACTIVE == true).ToList();
            tasks = tasks.Where(t => t.ACTUAL_END_DATE >= dtStartDate && t.ACTUAL_END_DATE < dtEndDate.AddDays(1)).ToList();
            series.Add(getMilestoneSeries(tasks));

            return series;
        }
        private series_AdvancedTimeline getMilestoneSeries(List<SUBPROJECT_TASK> details)
        {
            series_AdvancedTimeline_withTooltip series = new series_AdvancedTimeline_withTooltip();

            series.type = "flags";
            series.name = "Milestones";
            series.color = "#333333";
            series.shape = "circlepin";
            series.fillColor = "rgba(255,255,255,0.8)";
            series.y = -30;

            foreach (SUBPROJECT_TASK metric in details)
            {
                series.data.Add(new data_AdvancedTimeline()
                {
                    x = GetDateInMilliseconds(metric.ACTUAL_END_DATE.ToString()),
                    text = metric.DESCRIPTION,
                    title = getSubstring(metric.DESCRIPTION, 15)
                });
                series.tooltip = new tooltip()
                {
                    headerFormat = "<span style='font-size: 11px;color:#666'>{point.x:%B %e, %Y}</span><br/><span style='font-size: 11px;font-weight:bold'>" + metric.DESCRIPTION + "</span><br>",
                    pointFormat = "",
                    valueSuffix = "",
                };
            }

            return series;
        }
        private string getSubstring(string s, int len)
        {
            if (s.Length > len)
                return s.Substring(0, 10).Trim();
            else
                return s.Trim();
        }
        private List<series_AdvancedTimeline> GetTimelineKPISeries(string CustomerId, string ProjectId, DateTime dtStartDate, DateTime dtEndDate)
        {
            List<series_AdvancedTimeline> series = new List<series_AdvancedTimeline>();
            List<KPI_GOALS> goals = CSPdb.KPI_GOALS.GetAll().Where(t => t.CUSTOMER_ID == CustomerId && t.PROJECT_ID == ProjectId && t.ISACTIVE == true).OrderBy(u => u.DISPLAY_ORDER).ToList<KPI_GOALS>();
            List<int> goalIds = goals.Select(s => s.ID).ToList<int>();

            List<KPI> KPIs = CSPdb.KPI.GetAll().Where(t => goalIds.Contains(t.GOAL_ID) && t.ISACTIVE == true && t.SHOW_IN_CHART == true).ToList<KPI>();
            List<KPI> SortedKPIs = new List<KPI>();
            foreach (KPI_GOALS g in goals)
            {
                SortedKPIs.AddRange(KPIs.Where(t => t.GOAL_ID == g.ID).OrderBy(u => u.DISPLAY_ORDER).ToList<KPI>());
            }

            List<int> kpiIds = SortedKPIs.Select(s => s.ID).ToList<int>();
            List<KPI_DETAILS> allDetails = CSPdb.KPI_DETAILS.GetAll().Where(t => kpiIds.Contains(t.KPI_ID) && t.ISACTIVE == true && t.KPI_ACTUAL != "").ToList<KPI_DETAILS>();
            List<KPI_DETAILS> SortedallDetails = new List<KPI_DETAILS>();
            foreach (KPI k in SortedKPIs)
            {
                SortedallDetails.AddRange(allDetails.Where(t => t.KPI_ID == k.ID).ToList<KPI_DETAILS>());
            }
            //Chart

            List<HighChartsLineGroup> TrendChartsGroup = new List<HighChartsLineGroup>();

            foreach (int i in kpiIds)
            {
                List<KPI_DETAILS> details = allDetails.Where(t => t.KPI_ID == i && t.PERIOD >= dtStartDate && t.PERIOD < dtEndDate.AddDays(1)).OrderBy(u => u.PERIOD).ToList<KPI_DETAILS>();
                series.Add(getKPISeries(KPIs, details));
            }
            return series;
        }
        private series_AdvancedTimeline getKPISeries(List<KPI> KPIs, List<KPI_DETAILS> details)
        {

            String kpiName = string.Empty;
            if (details.Count > 0)
            {
                KPI kpi = KPIs.Where(t => t.ID == details[0].KPI_ID).FirstOrDefault();
                if (kpi != null)
                    kpiName = kpi.KPI_NAME;
            }
            series_AdvancedTimeline_withTooltip series = new series_AdvancedTimeline_withTooltip();

            //series.yAxis = 1;
            series.name = kpiName;

            //series.id = "employees";
            series.type = "area";
            //series.step = "left";
            series.tooltip = new tooltip()
            {
                headerFormat = "<span style='font-size: 11px;color:#666'>{point.x:%B %e, %Y}</span><br>",
                pointFormat = "{point.name}<br><b>{point.y}</b>",
                valueSuffix = " ",
            };
            series.showInLegend = true;

            foreach (KPI_DETAILS metric in details)
                series.data.Add(new data_AdvancedTimeline() { x = GetDateInMilliseconds(metric.PERIOD), y = Convert.ToDouble(metric.KPI_ACTUAL), name = metric.HIGHLIGHTS });

            return series;
        }





