        [POST("AddControlCategory")]
        [ActionName("AddControlCategory")]
        [HttpPost]
        public IHttpActionResult AddControlCategory(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            CONTROL_CATEGORY results = JsonConvert.DeserializeObject<CONTROL_CATEGORY>(json);
            if (results != null)
            {
                if (!CSPdb.CONTROL_CATEGORY.GetAll().Any(x => x.DESCRIPTION == results.DESCRIPTION && x.PROCESS_MODEL_ID == results.PROCESS_MODEL_ID))
                {
                    CSPdb.CONTROL_CATEGORY.Add(results);
                    CSPdb.Commit(CanCommit);
                }
            }
            return Ok(CSPdb.CONTROL_CATEGORY.GetAll().ToList());
        }

