        [POST("UpdateRiskAndRiskObjMapping"), ActionName("UpdateRiskAndRiskObjMapping"), HttpPost]
        public IHttpActionResult UpdateRiskAndRiskObjMapping(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            RiskObjectiveMapping results = JsonConvert.DeserializeObject<RiskObjectiveMapping>(json);

            string empid = request.Headers.GetValues("empId").FirstOrDefault();

            //DELETE existing records

            List<RISKS_OBJECTIVES_MAPPING> delrec = CSPdb.RISKS_OBJECTIVES_MAPPING.GetAll().Where(t => t.RISK_ID == results.PROCESS_MODEL_RISKS_NEW.ID && t.ISACTIVE
                                                                                                       ).ToList();
            delrec.ToList().ForEach(c => c.ISACTIVE = false);
            CSPdb.RISKS_OBJECTIVES_MAPPING.Update(delrec);
            CSPdb.Commit(CanCommit);
            //----------------

            // Add data to Risks and RiskObjectiveMapping Table

            if (results != null)
            {
                PROCESS_MODEL_RISKS_NEW risk = results.PROCESS_MODEL_RISKS_NEW;
                List<PROCESS_MODEL_OBJECTIVES_NEW> objectives = results.PROCESS_MODEL_OBJECTIVES_NEW;
                if (risk != null)
                {
                    PROCESS_MODEL_RISKS_NEW newobj = new PROCESS_MODEL_RISKS_NEW();
                    newobj.TITLE = risk.TITLE;
                    newobj.DESCRIPTION = risk.DESCRIPTION;
                    newobj.RISK_CATEGORY_LEVEL1 = risk.RISK_CATEGORY_LEVEL1;
                    newobj.RISK_CATEGORY_LEVEL2 = risk.RISK_CATEGORY_LEVEL2;
                    newobj.RISK_CATEGORY_LEVEL3 = risk.RISK_CATEGORY_LEVEL3;
                    newobj.RISK_OWNER = risk.RISK_OWNER;
                    newobj.CREATED_BY = empid;
                    newobj.CREATED_DATE = DateTime.Now;
                    newobj.UPDATED_DATE = DateTime.Now;
                    newobj.UPDATED_BY = empid;
                    CSPdb.PROCESS_MODEL_RISKS_NEW.Add(newobj);
                    CSPdb.Commit(CanCommit);
                }
                if (objectives != null && risk != null)
                {
                    foreach (var obj in objectives)
                    {
                        RISKS_OBJECTIVES_MAPPING map = new RISKS_OBJECTIVES_MAPPING();
                        map.RISK_ID = results.PROCESS_MODEL_RISKS_NEW.ID;
                        map.OBJECTIVE_ID = obj.ID;
                        map.ISACTIVE = true;
                        map.CREATED_BY = empid;
                        map.CREATED_DATE = DateTime.Now;
                        map.UPDATED_DATE = DateTime.Now;
                        map.UPDATED_BY = empid;
                        CSPdb.RISKS_OBJECTIVES_MAPPING.Add(map);
                        CSPdb.Commit(CanCommit);
                    }
                }
            }

            return Ok(results);
        }

        [POST("AddSQARisk"), ActionName("AddSQARisk"), HttpPost]
        public IHttpActionResult AddSQARisk([FromBody] PROCESS_MODEL_RISKS_NEW RiskModel)
        {
            string empid = Request.Headers.GetValues("empId").FirstOrDefault();

            PROCESS_MODEL_RISKS_NEW newobj = new PROCESS_MODEL_RISKS_NEW();
            if (RiskModel != null)
            {
                newobj.TITLE = RiskModel.TITLE;
                newobj.DESCRIPTION = RiskModel.DESCRIPTION;
                newobj.RISK_CATEGORY_LEVEL1 = RiskModel.RISK_CATEGORY_LEVEL1;
                newobj.RISK_CATEGORY_LEVEL2 = RiskModel.RISK_CATEGORY_LEVEL2;
                newobj.RISK_CATEGORY_LEVEL3 = RiskModel.RISK_CATEGORY_LEVEL3;
                newobj.RISK_OWNER = RiskModel.RISK_OWNER;
                newobj.CREATED_BY = empid;
                newobj.CREATED_DATE = DateTime.Now;
                newobj.UPDATED_DATE = DateTime.Now;
