        [POST("AddServiceAreaProjectMapping"), ActionName("AddServiceAreaProjectMapping"), HttpPost]
        public IHttpActionResult AddServiceAreaProjectMapping(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            PROCESS_SERVICE_AREA_PROJECT_MAPPING results = JsonConvert.DeserializeObject<PROCESS_SERVICE_AREA_PROJECT_MAPPING>(json);
            if (results != null)
            {
                var existing = CSPdb.PROCESS_SERVICE_AREA_PROJECT_MAPPING.GetAll().Any(x => x.SERVICE_AREA_ID == results.SERVICE_AREA_ID && x.PROJ_ID == results.PROJ_ID && x.ISACTIVE);
                if (existing)
                {
                    return Content(HttpStatusCode.Conflict, "SERVICE TOWER PROJECT MAPPING exists already.");
                }
                CSPdb.PROCESS_SERVICE_AREA_PROJECT_MAPPING.Add(results);
                CSPdb.Commit(CanCommit);

                var inscopeDetails = Cldb.PROJECT_INSCOPE_DETAILS.GetAll().Where(x => x.PROJECT_ID == results.PROJ_ID && x.ISACTIVE).ToList();
                if (!inscopeDetails.Any(x => x.SERVICE_AREA_ID == results.SERVICE_AREA_ID))
                {
                    var newItem = new PROJECT_INSCOPE_DETAILS
                    {
                        PROJECT_ID = results.PROJ_ID,
                        SERVICE_AREA_ID = results.SERVICE_AREA_ID,

                    };
                    UpdateAuditFields(newItem);
                    Cldb.PROJECT_INSCOPE_DETAILS.Add(newItem);
                    Cldb.Commit(CanCommit);
                }
            }

            return Ok(results);
        }


        [POST("AddControlAndRisksMapping"), ActionName("AddControlAndRisksMapping"), HttpPost]
        public IHttpActionResult AddControlAndRisksMapping(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;

            string empId = request.Headers.GetValues("empId").FirstOrDefault();

            ControlRisksMapping results = JsonConvert.DeserializeObject<ControlRisksMapping>(json);

            if (results != null)
            {
                PROCESS_MODEL_CONTROL_NEW control = results.PROCESS_MODEL_CONTROL_NEW;
                List<PROCESS_MODEL_RISKS_NEW> risks = results.PROCESS_MODEL_RISKS_NEW;

                if (control != null)
                {
                    PROCESS_MODEL_CONTROL_NEW newcontrol = new PROCESS_MODEL_CONTROL_NEW();

                    newcontrol = control;
                    newcontrol.CREATED_BY = empId;
                    newcontrol.CREATED_DATE = DateTime.Now;
                    newcontrol.UPDATED_BY = empId;
                    newcontrol.UPDATED_DATE = DateTime.Now;
                    CSPdb.PROCESS_MODEL_CONTROL_NEW.Add(newcontrol);
                    CSPdb.Commit(CanCommit);
                }

                if (risks != null && control != null)
                {
                    foreach (var obj in risks)
                    {
                        CONTROL_RISKS_MAPPING map = new CONTROL_RISKS_MAPPING();
                        map.CONTROL_ID = control.ID;
                        map.RISKS_ID = obj.ID;
                        map.ISACTIVE = true;
                        CSPdb.CONTROL_RISKS_MAPPING.Add(map);
                        CSPdb.Commit(CanCommit);
                    }
                }
            }

            return Ok(results);

        }

