        [POST("UpdateControlAndRisksMapping"), ActionName("UpdateControlAndRisksMapping"), HttpPost]
        public IHttpActionResult UpdateControlAndRisksMapping([FromBody] ControlRisksMapping results)
        {
            string empid = Request.Headers.GetValues("empId").FirstOrDefault();
            if (results != null)
            {
                PROCESS_MODEL_CONTROL_NEW control = results.PROCESS_MODEL_CONTROL_NEW;
                List<PROCESS_MODEL_RISKS_NEW> risks = results.PROCESS_MODEL_RISKS_NEW;

                var updatecontrol = CSPdb.PROCESS_MODEL_CONTROL_NEW.GetById(control.ID);
                if (updatecontrol != null)
                {
                    updatecontrol.DESCRIPTION = control.DESCRIPTION;
                    updatecontrol.REFERENCE_DOCUMENT = control.REFERENCE_DOCUMENT;
                    updatecontrol.REQUIREMENT_REFERENCE = control.REQUIREMENT_REFERENCE;
                    updatecontrol.UPDATED_BY = empid;
                    updatecontrol.UPDATED_DATE = DateTime.Now;
                    updatecontrol.CATEGORY = control.CATEGORY;
                    updatecontrol.CLASSIFICATION = control.CLASSIFICATION;
                    updatecontrol.CONTROL_OWNER = control.CONTROL_OWNER;
                    updatecontrol.AUTOMATION = control.AUTOMATION;
                    updatecontrol.ASSERTION = control.ASSERTION;
                    updatecontrol.CONTROL_TYPE = control.CONTROL_TYPE;
                    updatecontrol.FILE_NAME_SERVER = control.FILE_NAME_SERVER;
                    updatecontrol.FRAMEWORK = control.FRAMEWORK;
                    updatecontrol.FUNCTIONS = control.FUNCTIONS;
                    CSPdb.PROCESS_MODEL_CONTROL_NEW.Update(updatecontrol);
                    CSPdb.Commit(CanCommit);
                }


                if (control != null && risks != null)
                {
                    // delete already existing mapping

                    List<CONTROL_RISKS_MAPPING> mappings = CSPdb.CONTROL_RISKS_MAPPING.GetAll().Where(x => x.CONTROL_ID == control.ID).ToList();
                    mappings.ForEach(x => x.ISACTIVE = false);
                    CSPdb.CONTROL_RISKS_MAPPING.Update(mappings);
                    CSPdb.Commit(CanCommit);

                    // create new mapping

                    foreach (var obj in risks)
                    {
                        CONTROL_RISKS_MAPPING map = new CONTROL_RISKS_MAPPING();
                        map.CONTROL_ID = control.ID;
                        map.RISKS_ID = obj.ID;
                        map.ISACTIVE = true;
                        CSPdb.CONTROL_RISKS_MAPPING.Add(map);
                        CSPdb.Commit(CanCommit);
                    }

                }
            }
            return Ok();
        }

