        [POST("UpdateProjectServiceAreaProcessMapping")]
        [ActionName("UpdateProjectServiceAreaProcessMapping")]
        [HttpPost]
        public IHttpActionResult UpdateProjectServiceAreaProcessMapping([FromBody] List<PM_PROJECT_SERVICE_AREA_PROCESS_MAPPING> results)
        {
            if (results == null || results.Count == 0)
                return BadRequest("Request data is empty");

            PM_PROJECT_SERVICE_AREA_PROCESS_MAPPING mapping = results[0];

            string empId = GetHeaderDetails_String("empId");


            List<PM_PROJECT_SERVICE_AREA_PROCESS_MAPPING> existingList = CSPdb.PM_PROJECT_SERVICE_AREA_PROCESS_MAPPING.GetAll().Where(t => t.PROJ_ID == mapping.PROJ_ID && t.SERVICE_AREA_ID == mapping.SERVICE_AREA_ID).ToList();

            existingList.ForEach(x => x.ISACTIVE = false);

            foreach (var item in results.Where(x => x.ID == 0))
            {

                CSPdb.PM_PROJECT_SERVICE_AREA_PROCESS_MAPPING.Add(item);

            }
            CSPdb.Commit(CanCommit);
            foreach (var item in results.Where(x => x.ID > 0)) // Active
            {
                var existing = existingList.FirstOrDefault(x => x.ID == item.ID);
                if (existing == null) continue;
                existing.ISACTIVE = true;
                existing.PROCESS_MODEL_ID = item.PROCESS_MODEL_ID;
                existing.PROCESS_ID = item.PROCESS_ID;
                existing.UPDATED_BY = empId.ToString();
                existing.UPDATED_DATE = DateTime.Now;
                //CSPdb.PM_PROJECT_SERVICE_AREA_PROCESS_MAPPING.Update(item);
                CSPdb.PM_PROJECT_SERVICE_AREA_PROCESS_MAPPING.Update(existing);
                existingList.Remove(existing);

            }

            if (existingList.Count > 0)
            {
                CSPdb.PM_PROJECT_SERVICE_AREA_PROCESS_MAPPING.Update(existingList);
            }

            CSPdb.Commit(CanCommit);

            return Ok(results);
        }

