        [POST("GetProcessByServiceArea")]
        [ActionName("GetProcessByServiceArea")]
        [HttpPost]
        public IHttpActionResult GetProcessByServiceArea(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            int ServiceAreaId = JsonConvert.DeserializeObject<int>(json);
            List<ProcessDetails> processDetails = CSPdb.AppRepo.GetProcessByServiceArea(ServiceAreaId);

            List<GroupByProcessModel> output = new List<GroupByProcessModel>();

            foreach (var processmodel in processDetails)
            {
                if (!output.Any(x => x.PROCESS_MODEL_ID == processmodel.PROCESS_MODEL_ID))
                    output.Add(new GroupByProcessModel(processmodel.PROCESS_MODEL_ID, processmodel.PROCESS_MODEL_TITLE));

                var processModelRec = output.Find(x => x.PROCESS_MODEL_ID == processmodel.PROCESS_MODEL_ID);

                if (!processModelRec.GroupByProcessArea.Any(x => x.PROCESS_AREA_ID == processmodel.PROCESS_AREA_ID))
                    processModelRec.GroupByProcessArea.Add(new GroupByProcessArea(processmodel.PROCESS_AREA_ID, processmodel.PROCESS_AREA_TITLE));

                var processAreaRec = processModelRec.GroupByProcessArea.Find(x => x.PROCESS_AREA_ID == processmodel.PROCESS_AREA_ID);

                processAreaRec.Processess.Add(processmodel);
            }

            return Ok(output);
        }


