        [POST("GetProcessDescription")]
        [ActionName("GetProcessDescription")]
        [HttpPost]
        public IHttpActionResult GetProcessDescription(HttpRequestMessage request)
        {
            var content = request.Content;
            string customerId = "";
            string projectId = "";
            //string custId;
            string jsonContent = content.ReadAsStringAsync().Result;
            if (Request.Headers.Contains("customerid"))
                customerId = Request.Headers.GetValues("customerid").ToList()[0];
            if (Request.Headers.Contains("projectId"))
                projectId = Request.Headers.GetValues("projectId").ToList()[0];
            dynamic json = jsonContent;
            //custId = Convert.ToInt32(customerId);
            List<int> rows = JsonConvert.DeserializeObject<List<int>>(json);
            string row = string.Join(",", rows.ToArray());
            List<PROCESS_MODEL_DESCRIPTION> processModelDescription = new List<AllSysController.PROCESS_MODEL_DESCRIPTION>();
            var desc = CSPdb.AppRepo.GetProcessDescription(customerId, projectId, row).ToList<PROCESS_DESCRIPTION>().GroupBy(t => t.MODEL_ID);
            foreach (var d in desc)
            {
                List<SERVICE_AREA> serviceAreaList = new List<SERVICE_AREA>();
                PROCESS_MODEL_DESCRIPTION pmd = new PROCESS_MODEL_DESCRIPTION();
                pmd.MODEL_ID = d.Key;
                pmd.MODEL_NAME = d.ToList()[0].PROCESS_MODEL_DESCRIPTION;
                pmd.GAVS_SERVICE_AREA = d.ToList().Select(t => t.GAVS_SERVICE_AREA).Distinct().ToList();
                var area = d.ToList().GroupBy(t => t.AREA_ID);
                foreach (var a in area)
                {
                    SERVICE_AREA ar = new SERVICE_AREA();
                    ar.AREA_ID = a.Key;
                    ar.AREA_NAME = a.ToList()[0].PROCESS_AREA_DESCRIPTION;
                    ar.PROCESS_NAME = a.ToList().ToList<PROCESS_DESCRIPTION>();
                    serviceAreaList.Add(ar);
                }
                pmd.SERVICE_AREA = serviceAreaList;
                processModelDescription.Add(pmd);
            }
            return Ok(processModelDescription);
        }

