        [GET("GetAuditExecutionModelandCatalogDD")]
        [ActionName("GetAuditExecutionModelandCatalogDD")]
        [HttpGet]
        public IHttpActionResult GetAuditExecutionModelandCatalogDD(string CustomerId, string ProjectId)
        {
            List<int> modelIds = new List<int>();
            List<int> areaIds = new List<int>();
            AUDIT_PROCESS_DD_LIST audit = new AUDIT_PROCESS_DD_LIST();
            List<PROCESS_MODEL_PROJECT_CONFIG> desc = CSPdb.PROCESS_MODEL_PROJECT_CONFIG.GetAll().Where(t => t.PROJECT_ID == ProjectId && t.CUSTOMER_ID == CustomerId && t.APPLICABLE == true).ToList<PROCESS_MODEL_PROJECT_CONFIG>();
            modelIds = desc.Select(t => t.PROCESS_MODEL_ID).Distinct().ToList<int>();
            areaIds = desc.Select(t => t.SERVICE_AREA_ID).Distinct().ToList<int>();
            audit.GAVS_SERVICE_AREA = CSPdb.PROCESS_SERVICE_AREA.GetAll().Where(t => areaIds.Contains(t.ID)).Select(t => t.GAVS_SERVICE_AREA).Distinct().ToList(); ;
            audit.PROJECT_MODEL = CSPdb.PROCESS_MODEL.GetAll().Where(t => modelIds.Contains(t.ID)).Select(t => t.TITLE).ToList<string>();
            audit.PROJECT_SERVICE_AREA = CSPdb.PROCESS_SERVICE_AREA.GetAll().Where(t => areaIds.Contains(t.ID)).Select(t => t.PROCESS_AREA_DESCRIPTION).ToList<string>();

            return Ok(audit);
        }
