            auditTestsList = CSPdb.PARAMETER_TABLE.GetAll().ToList<PARAMETER_TABLE>();
            DropDownAudit ddData = new DropDownAudit();
            ddData.TEST_RESULTS = auditTestsList.Where(t => t.NAME == "TEST_RESULTS").Select(t => t.OPTIONS).ToList<string>();
            ddData.IMPACTING_ATTRIBUTES = auditTestsList.Where(t => t.NAME == "IMPACTING_ATTRIBUTES").Select(t => t.OPTIONS).ToList<string>();
            ddData.RISK_SEVERITY = auditTestsList.Where(t => t.NAME == "RISK_SEVERITY").Select(t => t.OPTIONS).ToList<string>();
            ddData.STATUS_CONTROLS = auditTestsList.Where(t => t.NAME == "STATUS_CONTROLS").Select(t => t.OPTIONS).ToList<string>();
            //ddData.AUDITOR_LIST = Cldb.AppRepo.GetAuditorDetails().ToList<EMP_INFO>();
            IHttpActionResult actionResult = GetAuditorList();
            var result = actionResult as OkNegotiatedContentResult<List<EMP_INFO>>;
            ddData.AUDITOR_LIST = result.Content;
            ddData.SERVICE_AREA = CSPdb.GAVS_SERVICE_AREA.GetAll().ToList();
            ddData.PROCESS_SERVICE_AREA_NEW = CSPdb.PROCESS_SERVICE_AREA_NEW.GetAll().ToList();
            return Ok(ddData);
        }

        [GET("GetAuditProcessTests")]
        [ActionName("GetAuditProcessTests")]
        [HttpGet]
        public IHttpActionResult GetAuditProcessTests(string CustomerId, string ProjectId)
        {
            List<AUDIT_PROCESS_TESTS> auditTestsList = new List<AUDIT_PROCESS_TESTS>();
            List<int> data = CSPdb.PROCESS_MODEL_PROJECT_CONFIG.GetAll().Where(t => t.CUSTOMER_ID == CustomerId && t.PROJECT_ID == ProjectId).Select(t => t.PROCESS_MODEL_ID).Distinct().ToList().ToList<int>();
            foreach (int id in data)
            {
                List<AUDIT_PROCESS_TESTS> list = CSPdb.AppRepo.GetAuditProcessTests(id).ToList<AUDIT_PROCESS_TESTS>();
                auditTestsList.AddRange(list);
            }
            return Ok(auditTestsList);
        }

