        [GET("GetSavedAudits")]
        [ActionName("GetSavedAudits")]
        [HttpGet]
        public IHttpActionResult GetSavedAudits(string CustomerId, string ProjectId)
        {

            List<AUDIT_EXECUTION_MODEL> model = new List<AUDIT_EXECUTION_MODEL>();
            List<AUDIT_EXECUTION_LIST> auditExecList = new List<AUDIT_EXECUTION_LIST>();
            List<string> mapping = new List<string>();
            List<string> auditee = new List<string>();
            model = CSPdb.AUDIT_EXECUTION_MODEL.GetAll().Where(t => t.CUSTOMER_ID == CustomerId && t.PROJECT_ID == ProjectId).ToList<AUDIT_EXECUTION_MODEL>();
            foreach (AUDIT_EXECUTION_MODEL l in model)
            {
                mapping = CSPdb.EXECUTION_IMPACT_MAPPING.GetAll().Where(t => t.TEST_ID == l.TEST_ID && t.AUDIT_ID == l.AUDIT_EXECUTION_ID).Select(t => t.IMPACTING_ATTRIBUTES).Distinct().ToList<string>();
                auditee = CSPdb.AUDIT_EXECUTION_AUDITEE_DETAILS.GetAll().Where(t => t.AUDIT_EXECUTION_ID == l.AUDIT_EXECUTION_ID).Select(t => t.AUDITEE_EMP_ID).Distinct().ToList<string>();
                l.IMPACTING_ATTRIBUTES = mapping;
                l.AUDITEE_NAME = auditee;
            }
            var execList = model.GroupBy(t => t.AUDIT_EXECUTION_ID).ToList();
            foreach (var m in execList)
            {
                AUDIT_EXECUTION_LIST auditExec = new AUDIT_EXECUTION_LIST();
                auditExec.EXEC_ID = m.Key;
                auditExec.AUDIT_TITLE = m.ToList()[0].AUDIT_TITLE;
                auditExec.EXEC_LIST = m.ToList().ToList<AUDIT_EXECUTION_MODEL>();
                auditExecList.Add(auditExec);
            }
            return Ok(auditExecList);
        }

        [GET("GetPlannedAudits")]
        [ActionName("GetPlannedAudits")]
        [HttpGet]
        public IHttpActionResult GetPlannedAudits(string CustomerId, string ProjectId)
        {
            var stopwatch = Stopwatch.StartNew();
            CheckUserHasAccess(GetHeaderDetails_String("empID"), CustomerId, ProjectId);
            List<PlannedAudits> audits = CSPdb.AppRepo.GetPlannedAudits(CustomerId, ProjectId).ToList();
            List<PlannedAuditsConsolidated> auditresultset = new List<PlannedAuditsConsolidated>();
            //DateTime StartDate = new DateTime(DateTime.Now.Year, DateTime.Now.Month, 01);
            //DateTime EndDate = StartDate.AddMonths(1).AddSeconds(-1);
            //audits = audits.Where(x => x.SCHEDULED_START_DATE >= StartDate && x.SCHEDULED_START_DATE <= EndDate).ToList();
            var groupbyId = audits.GroupBy(x => x.ID).OrderByDescending(x => x.Key);
            foreach (var key in groupbyId)
            {
                var auditrec = new PlannedAuditsConsolidated();
                var firstItem = key.FirstOrDefault();
                if (firstItem == null) continue;

                auditrec.ID = key.Key;
                auditrec.DESCRIPTION = firstItem.DESCRIPTION;
                auditrec.STATUS = firstItem.STATUS.ToLower() == "in progress" && firstItem.ISSUBMITTED.GetValueOrDefault() ? "Findings Submitted" : firstItem.STATUS;
                auditrec.PRIORITY = firstItem.PRIORITY;
                auditrec.CUST_ID = firstItem.CUST_ID;
                auditrec.PROJ_ID = firstItem.PROJ_ID;
                auditrec.SCHEDULED_START_DATE = firstItem.SCHEDULED_START_DATE;
                auditrec.ACTUAL_START_DATE = firstItem.ACTUAL_START_DATE;
                auditrec.DUE_DATE = firstItem.DUE_DATE;
                auditrec.SCHEDULED_DURATION = firstItem.SCHEDULED_DURATION;
                auditrec.PROCESS_COMPLIANCE_AS_ON_AUDIT_DATE = firstItem.PROCESS_COMPLIANCE_AS_ON_AUDIT_DATE;
                auditrec.CURRENT_PROCESS_COMPLIANCE = firstItem.CURRENT_PROCESS_COMPLIANCE;
                auditrec.ACTUAL_DURATION = firstItem.ACTUAL_DURATION.GetValueOrDefault();
                auditrec.AUDITESS_ID = key.Where(x => x.KEY == "AUDITEE_EMP_ID").Select(y => y.VALUE).ToList();
                auditrec.AUDITOR_ID = firstItem.AUDITOR_EMP_ID != null ? firstItem.AUDITOR_EMP_ID.ToString() : "";
                auditrec.SERVICE_AREA_ID = key.Where(x => x.KEY == "SERVICE_AREA_ID").Select(y => y.VALUE).ToList();
                auditrec.ACTUAL_AUDIT_START_DATE = firstItem.ACTUAL_AUDIT_START_DATE;
                auditrec.ACTUAL_AUDIT_END_DATE = firstItem.ACTUAL_AUDIT_END_DATE;
                auditresultset.Add(auditrec);
            }
            FillResponseTime(stopwatch);
            return Ok(auditresultset);
        }

        [POST("GetAuditDetails")]
        [ActionName("GetAuditDetails")]
        [HttpPost]
        public IHttpActionResult GetAuditDetails([FromBody] AuditData auditdata)
        {
            var output = new TestAuditData();
            TEST_DATA newrec = new TEST_DATA();
            newrec.CUSTID = auditdata.CUSTID;
            newrec.PROJID = auditdata.PROJID;
            newrec.SERVICEAREA = auditdata.SERVICEAREAS;
            newrec.AUDIT_TITLE = auditdata.AUDITTITLE;
            IHttpActionResult actionResult = GetTestsData(newrec);
            var result = actionResult as OkNegotiatedContentResult<List<TESTS_VIEW_MODEL>>;
            output.TESTS_VIEW_MODELS = result.Content;

            List<AUDIT_EXECUTION_MODEL> auditList = new List<AUDIT_EXECUTION_MODEL>();

            foreach (var rec in result.Content)
            {
                var auditrow = new AUDIT_EXECUTION_MODEL();
                var testrow = CSPdb.AUDIT_EXECUTION_MODEL.GetAll().Where(x => x.TEST_ID == rec.ID && x.CUSTOMER_ID == auditdata.CUSTID && x.PROJECT_ID == auditdata.PROJID && x.ISACTIVE
                     && x.AUDIT_TITLE == auditdata.AUDITTITLE && x.AUDIT_START_DATE.Year == auditdata.STARTDATE.Year && x.AUDIT_START_DATE.Month == auditdata.STARTDATE.Month
                       && x.AUDIT_START_DATE.Day == auditdata.STARTDATE.Day).FirstOrDefault();
                if (testrow != null)
                {
                    testrow.IMPACTING_ATTRIBUTES = CSPdb.EXECUTION_IMPACT_MAPPING.GetAll().Where(x => x.TEST_ID == rec.ID && x.AUDIT_ID == testrow.AUDIT_EXECUTION_ID).Select(x => x.IMPACTING_ATTRIBUTES).ToList();
                    testrow.AUDITEE_NAME = auditdata.AUDITESSNAME.Select(x => x).ToList();
                    auditList.Add(testrow);
                }

                else
                {
                    auditrow.TEST_ID = rec.ID;
                    auditrow.CUSTOMER_ID = auditdata.CUSTID;
                    auditrow.PROJECT_ID = auditdata.PROJID;
                    auditrow.AUDITOR_NAME = int.TryParse(auditdata.AUDITORNAME, out int auditorName) ? auditorName : 0;
                    auditrow.AUDITEE_NAME = auditdata.AUDITESSNAME.Select(x => x).ToList();
                    auditrow.AUDIT_START_DATE = auditdata.STARTDATE;
                    auditrow.AUDIT_END_DATE = auditdata.ENDDATE;
                    auditrow.AUDIT_TITLE = auditdata.AUDITTITLE;
                    auditList.Add(auditrow);
                }

            }
            //if(auditdata != null)
            //{
            //    int.TryParse(auditdata.AUDITORNAME, out int auditorname);
            //    var auditrecords = CSPdb.AUDIT_EXECUTION_MODEL.GetAll().Where(x => x.AUDIT_TITLE == auditdata.AUDITTITLE && x.AUDIT_START_DATE >= auditdata.STARTDATE
            //             && x.AUDIT_END_DATE <= auditdata.ENDDATE && x.CUSTOMER_ID == auditdata.CUSTID
            //             && x.PROJECT_ID == auditdata.PROJID && x.AUDITOR_NAME == auditorname).ToList();

            //    return Ok(auditrecords);
            //}
            output.AUDIT_DATA = auditList;
            return Ok(output);
        }

