        [GET("LoadSavedCheckListAudits")]
        [ActionName("LoadSavedCheckListAudits")]
        [HttpGet]
        public IHttpActionResult LoadSavedCheckListAudits(int AuditId)
        {
            List<AUDIT_CHECKLIST_PROJECT_EXECUTION> model = new List<AUDIT_CHECKLIST_PROJECT_EXECUTION>();
            List<AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED> modList = new List<AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED>();
            List<AUDIT_CHECKLIST_EXECUTION> auditExecList = new List<AUDIT_CHECKLIST_EXECUTION>();
            List<string> mapping = new List<string>();
            List<AUDIT_CHECKLIST_EXECUTION> executionList = new List<AUDIT_CHECKLIST_EXECUTION>();
            List<int> auditee = new List<int>();
            model = CSPdb.AUDIT_CHECKLIST_PROJECT_EXECUTION.GetAll().Where(t => t.AUDIT_ID == AuditId).ToList<AUDIT_CHECKLIST_PROJECT_EXECUTION>();
            foreach (AUDIT_CHECKLIST_PROJECT_EXECUTION l in model)
            {
                AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED mod = new AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED();
                mod.AUDIT_ID = l.AUDIT_ID;
                mod.CUSTOMER_ID = l.CUSTOMER_ID;
                mod.PROJECT_ID = l.PROJECT_ID;
                mod.AUDIT_TITLE = l.AUDIT_TITLE;
                mod.ACTUAL_AUDIT_START_DATE = l.ACTUAL_AUDIT_START_DATE;
                mod.ACTUAL_AUDIT_END_DATE = l.ACTUAL_AUDIT_END_DATE;
                mod.APPLICABLE_QUESTIONS = l.APPLICABLE_QUESTIONS;
                mod.AUDITEE_NAME = GetAuditeeNames(l.AUDIT_ID);
                mod.AUDITOR_NAME = l.AUDITOR_NAME;
                mod.AUDIT_SCOPE = l.AUDIT_SCOPE;
                mod.AUDIT_ACTUAL_HOURS = l.AUDIT_ACTUAL_HOURS;
                mod.AUDIT_PLANNED_HOURS = l.AUDIT_PLANNED_HOURS;
                mod.CHECKLIST_SAMPLE_AUDITED = GetSamplesAudited(l);
                mod.CREATED_BY = l.CREATED_BY;
                mod.CREATED_DATE = l.CREATED_DATE;
                mod.UPDATED_BY = l.UPDATED_BY;
                mod.UPDATED_DATE = l.UPDATED_DATE;
                mod.ISSUBMITTED = l.ISSUBMITTED;
                mod.FINDINGS = GetChecklistFindings(l, new List<FINDINGSTYPE_VALUES>() { });
                mod.STATUS = l.STATUS;
                GetWeightageScale(l, mod);
                mod.ID = l.ID;
                mod.ISACTIVE = l.ISACTIVE;
                mod.NOTES = l.NOTES;
                mod.LOOK_FOR = GetCheckListQuestion(l);
                GetProcessModeldetails(l, mod);
                modList.Add(mod);
            }

            var result = modList.GroupBy(t => t.PROCESS_MODEL_DESCRIPTION).ToList();
            foreach (var mod in result)
            {
                AUDIT_CHECKLIST_EXECUTION execution = new AUDIT_CHECKLIST_EXECUTION();
                execution.PROCESS_MODEL_DESCRIPTION = mod.Key;
                var area = mod.ToList().GroupBy(t => t.PROCESS_AREA_DESCRIPTION).ToList();
                List<AUDIT_CHECKLIST_SERVICE_AREA> areaList = new List<AUDIT_CHECKLIST_SERVICE_AREA>();
                foreach (var ar in area)
                {
                    AUDIT_CHECKLIST_SERVICE_AREA a = new AUDIT_CHECKLIST_SERVICE_AREA();
                    a.PROCESS_AREA_DESCRIPTION = ar.Key;
                    a.SERVICE_AREA_NAME = ar.ToList()[0].SERVICE_AREA_NAME;
                    var process = ar.ToList().GroupBy(t => t.PROCESS_DESCRIPTION).ToList();
                    List<PROCESS_DESC> descList = new List<PROCESS_DESC>();
                    foreach (var p in process)
                    {
                        PROCESS_DESC desc = new PROCESS_DESC();
                        desc.PROCESS_DESCRIPTION = p.Key;
                        desc.CHECKPOINTS = p.ToList();
                        descList.Add(desc);
                    }
                    a.PROCESS = descList;
                    areaList.Add(a);
                }
                execution.PROCESS_AREA_DATA = areaList;
                executionList.Add(execution);
            }


            return Ok(executionList);
        }

