        private List<CHECKLIST_SAMPLE_AUDITED> GetSamplesAudited(AUDIT_CHECKLIST_PROJECT_EXECUTION Audit)
        {
            List<CHECKLIST_SAMPLE_AUDITED> result = new List<CHECKLIST_SAMPLE_AUDITED>();
            List<AUDIT_CHECKLIST_PROJECT_SAMPLES_AUDITED> mat = CSPdb.AUDIT_CHECKLIST_PROJECT_SAMPLES_AUDITED.GetAll().Where(t => t.AUDIT_ID == Audit.AUDIT_ID && t.APPLICABLE_QUESTIONS == Audit.APPLICABLE_QUESTIONS
                                       && t.PROCESS_ID == Audit.PROCESS_ID && t.SERVICE_AREA_ID == Audit.SERVICE_AREA_ID
                                       && t.PROCESS_AREA_ID == Audit.PROCESS_AREA_ID).ToList();

            foreach (AUDIT_CHECKLIST_PROJECT_SAMPLES_AUDITED aud in mat)
            {
                CHECKLIST_SAMPLE_AUDITED n = new CHECKLIST_SAMPLE_AUDITED();
                n.EMP_ID = aud.EMP_ID;
                n.TOTAL_SAMPLES_AUDITED = aud.TOTAL_SAMPLES_AUDITED;
                n.SAMPLES_COMPLIED = aud.SAMPLES_COMPLIED;
                n.SAMPLES_NOTCOMPLIED = aud.SAMPLES_NOTCOMPLIED;
                n.PERCENTAGE = aud.PERCENTAGE;
                n.COMMENTS = aud.COMMENTS;
                result.Add(n);
            }
            return result;
        }
        private List<AUDIT_CHECKLIST_PROJECT_FINDINGS> GetChecklistFindings(AUDIT_CHECKLIST_PROJECT_EXECUTION Audit, List<FINDINGSTYPE_VALUES> FindingtypeValues)
        {

            var findings = CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.GetAll().Where(x => x.AUDIT_ID == Audit.AUDIT_ID && x.APPLICABLE_QUESTIONS == Audit.APPLICABLE_QUESTIONS
                                                                                        && x.PROCESS_ID == Audit.PROCESS_ID && x.SERVICE_AREA_ID == Audit.SERVICE_AREA_ID
                                                                                        && x.PROCESS_AREA_ID == Audit.PROCESS_AREA_ID
                                                                                        && x.PROCESS_MODEL_ID == Audit.PROCESS_MODEL_ID && x.ISACTIVE).ToList();

            foreach (var row in FindingtypeValues)
            {
                var record = findings.Find(x => x.FINDING_TYPE == row.FINDINGTYPE_VALUE);
                if (record != null)
                {
                    record.FINDING_CATEGORY = row.FINDINGTYPE_CATEGORY;
                    record.GO_CATEGORY = row.GO_CATEGORY;
                }
                else
                {
                    var finding = new AUDIT_CHECKLIST_PROJECT_FINDINGS();
                    finding.FINDING_TYPE = row.FINDINGTYPE_VALUE;
                    finding.FINDING_DESCRIPTION = string.Empty;
                    finding.FINDING_CATEGORY = row.FINDINGTYPE_CATEGORY;
                    finding.ISSUBMITTED = false;
                    finding.GO_CATEGORY = row.GO_CATEGORY;
                    findings.Add(finding);
                }
            }

            return findings;
        }
