        [POST("SendAuditExecutionMail")]
        [ActionName("SendAuditExecutionMail")]
        [HttpPost]
        public IHttpActionResult SendAuditExecutionMail(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            AUDIT_EXECUTION_MODEL report = JsonConvert.DeserializeObject<AUDIT_EXECUTION_MODEL>(json);

            IHttpActionResult processmodelsummary = GetProcessModelSummary(report.PROJECT_ID, report.AUDIT_START_DATE, report.AUDIT_TITLE, report.CUSTOMER_ID);
            var contentResult1 = processmodelsummary as OkNegotiatedContentResult<List<List<tableCell>>>;

            IHttpActionResult testdetails = GetTestsReport(report.CUSTOMER_ID, report.PROJECT_ID, report.AUDIT_TITLE);
            var contentResult2 = testdetails as OkNegotiatedContentResult<List<TEST_REPORT_SUMMARY>>;

            IHttpActionResult summ = GetAuditControlandTestCountReport(report.PROJECT_ID, report.AUDIT_START_DATE, report.CUSTOMER_ID, report.AUDIT_TITLE);
            var contentResult3 = summ as OkNegotiatedContentResult<List<List<tableCell>>>;

            List<List<tableCell>> processmodel = contentResult1.Content;
            List<TEST_REPORT_SUMMARY> tests = contentResult2.Content;
            List<List<tableCell>> summary = contentResult3.Content;

            // ProcessModel Summary
            string processmodelcount = FillProcessModelSummaryDetails(processmodel);

            // Tests information
            string testinfo = FillTestInformation(tests);

            // Detailed Report

            string detailedreport = FillSummaryDetails(summary);

            SendMailToAuditee(processmodelcount, testinfo, detailedreport, report);
            return Ok();
        }

        public string FillProcessModelSummaryDetails(List<List<tableCell>> processmodel)
        {
            string result = string.Empty;
            processmodel.RemoveAt(0);
            string content = GetLoopAuditData(processmodel);
            if (!string.IsNullOrEmpty(content))
                result = "<table><tr><th>Process Model</th><th> No of Controls </th><th> Total tests </th><th> No of tests passed </th><th> No of tests failed </th><th> Pass % </th></tr> " + content + " </table>";

            return result;
        }

        public string FillTestInformation(List<TEST_REPORT_SUMMARY> tests)
        {
            string result = string.Empty;
            string content = GetLoopTestsData(tests);
            if (!string.IsNullOrEmpty(content))
                result = "<table style=" + "width:550px" + "><tr><th colSpan=" + 1 + " rowSpan =" + 1 + "> Test Title</th><th colSpan=" + 1 + " rowSpan =" + 1 + "> Test Description </th><th colSpan=" + 1 + " rowSpan =" + 1 + "> Test Result </th><th colSpan=" + 1 + " rowSpan =" + 1 + "> Control </th><th colSpan=" + 1 + " rowSpan =" + 1 + "> Risk </th><th colSpan=" + 1 + " rowSpan =" + 1 + "> Objective </th></tr> " + content + " </table>";

            return result;
        }

        public string FillSummaryDetails(List<List<tableCell>> summary)
        {
            string result;
            result = "<table> " + GetLoopAuditData(summary) + " </table>";

            return result;
        }

        private string GetLoopAuditData(List<List<tableCell>> execution)
        {
            string loopD = "";
            string finLoop = "";
            foreach (List<tableCell> m in execution)
            {
                loopD = "";
                foreach (tableCell k in m)
                {
                    loopD += "<td rowspan = " + k.rowSpan + " colspan = " + k.colSpan + ">" + k.text + "</td>";
                }
                finLoop += "<tr>" + loopD + "</tr>";
            }

            return finLoop;
        }

        private string GetLoopTestsData(List<TEST_REPORT_SUMMARY> tests)
        {
            // string loopD = "";
            string finLoop = "";
            foreach (TEST_REPORT_SUMMARY m in tests)
            {
                finLoop += "<tr><td colSpan=" + 1 + " rowSpan =" + 1 + ">" + m.TITLE + "</td> <td colSpan=" + 1 + " rowSpan =" + 1 + ">" + m.DESCRIPTION + "</td> <td colSpan=" + 1 + " rowSpan =" + 1 + ">" + m.TEST_RESULT + "</td> <td colSpan=" + 1 + " rowSpan =" + 1 + ">" + m.CONTROL_TITLE + "</td> <td colSpan=" + 1 + " rowSpan =" + 1 + ">" + m.RISK_TITLE + "</td> <td colSpan=" + 1 + " rowSpan =" + 1 + ">" + m.OBJECTIVE_TITLE + "</td></tr>";
            }

            return finLoop;
        }

        private void SendMailToAuditee(string processmodelcount, string testinfo, string detailedreport, AUDIT_EXECUTION_MODEL audit)
        {


            string filePath = HttpContext.Current.Server.MapPath("~/UploadFile/Mails/") + "AuditReport1.htm";
            string empName = "";
            string auditorId = audit.AUDITOR_NAME.ToString();
            string ccmail = "";
            List<EMP_INFO> ccToCSM = helper.GetEmpInfoFromProject(audit.PROJECT_ID, 1);

            foreach (var emp in ccToCSM)
            {
                ccmail += emp.EMAIL_ID + ',';
            }

            if (ccmail == "")
                ccmail = "";
            else
                ccmail.Remove(ccmail.LastIndexOf(','), 1);
            //ccmail.Remove()

            List<EMP_INFO> ccToFuncManager = helper.GetEmpInfoFromProject(audit.PROJECT_ID, 9);

            foreach (var emp in ccToFuncManager)
            {
                ccmail += emp.EMAIL_ID + ',';
            }

            if (ccmail == "")
                ccmail = "";
            else
                ccmail.Remove(ccmail.LastIndexOf(','), 1);

            foreach (string n in audit.AUDITEE_NAME)
            {
                empName += GetEmployeeNamebyId(n.ToString()) + ",";
            }
            string projNm = GetProjectName(audit.PROJECT_ID);
            var customer = audit.CUSTOMER_ID;
            string custNm = Cldb.CUSTOMER.GetAll().Where(t => t.CUST_ID == customer).Select(t => t.CUST_NM).FirstOrDefault();
            string dateofAudit = audit.AUDIT_START_DATE.ToLongDateString();


            using (System.IO.StreamReader sr = new StreamReader(filePath))
            {
                string emailContent = sr.ReadToEnd();
                emailContent = emailContent.Replace("{{DETAILEDREPORT}}", detailedreport);
                emailContent = emailContent.Replace("{{AUDITEE_NM}}", empName);
                emailContent = emailContent.Replace("{{AUDITOR_NAME}}", GetEmployeeNamebyId(auditorId));
                emailContent = emailContent.Replace("{{CUSTOMER}}", custNm);
                emailContent = emailContent.Replace("{{PROJECT}}", projNm);
                emailContent = emailContent.Replace("{{AUDITDATE}}", dateofAudit);
                if (string.IsNullOrEmpty(processmodelcount))
                    emailContent = emailContent.Replace("{{processmodelclass}}", "hidden");
                else
                    emailContent = emailContent.Replace("{{PROCESSMODELCOUNT}}", processmodelcount);

                if (string.IsNullOrEmpty(testinfo))
                    emailContent = emailContent.Replace("{{testDetailClass}}", "hidden");
                else
                    emailContent = emailContent.Replace("{{TESTINFO}}", testinfo);

                var ep = new EmailProvider(Cldb, CSPdb);
                ep.SendEmail
                    (
                    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                    new EmailContent { from = _email, to = Constants.QUALITY_MAIL, cc = "", content = emailContent, subject = "Internal Audit – " + custNm + " – Date of Audit : " + dateofAudit + "", hasAttachments = false, attachmentFilePath = "", ProjId = audit.PROJECT_ID },
                    Request
                    );
            }
            //EmailProvider ep = new WebApi.EmailProvider();
            //ep.SendEmail
            //    (
            //    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = email, smtpHost = "smtp.office365.com", smtpPassword = password, smtpPortValue = "587" },
            //    new EmailContent { from = email, to = "balakumar.munuswamy@gavstech.com", cc = "", content = body, subject = "Audit Execution Summary and Report", hasAttachments = false, attachmentFilePath = "" }
            //    );
        }

