                    PMName = PMName.Remove(PMName.Length - 1, 1);
                List<EMP_INFO> Quality = helper.GetEmpInfoFromProject(report.BEST_PRACTICE.PROJECT_ID, 7);
                foreach (var x in Quality)
                {
                    tomail += x.EMAIL_ID + ',';
                }

                if (CSM.Count > 0 || ProjManager.Count > 0 || FuncManager.Count > 0)
                    tomail = tomail.Remove(tomail.Length - 1, 1);

                if (serviceArea != null && nMailTriggerOption == 2)
                {

                    List<string> projIds = new List<string>();
                    projIds = CSPdb.PROCESS_SERVICE_AREA_PROJECT_MAPPING.GetAll().Where(t => t.SERVICE_AREA_ID == serviceArea.ID && t.ISACTIVE == true).Select(t => t.PROJ_ID).Distinct().ToList();

                    List<string> empids = new List<string>();
                    empids = Cldb.PROJECT_RESOURCE.GetAll().Where(t => projIds.Contains(t.PROJ_ID) && t.CURR_INDC == "Y").Select(t => t.EMP_ID).ToList<string>();
                    List<EMP_INFO> empData = Cldb.EMP_INFO.GetAll().Where(t => empids.Contains(t.EMP_ID) && (t.CSM_TITLE_ID == 1 || t.CSM_TITLE_ID == 2)).ToList<EMP_INFO>();

                    foreach (var x in empData)
                    {
                        tomail += x.EMAIL_ID + ',';
                    }
                    tomail = tomail.TrimEnd(',');
                }

                string filePath = HttpContext.Current.Server.MapPath("~/UploadFile/Mails/");

                if (nMailTriggerOption == 2)
                {
                    filePath += "BestPracticesNotifyMailOnApproval.htm";
                }
                else
                {
                    filePath += "BestPracticesMailRequestForApproval.htm";
                }
                using (System.IO.StreamReader sr = new StreamReader(filePath))
                {
                    string emailContent = sr.ReadToEnd();
                    emailContent = emailContent.Replace("{{SERVICE AREA}}", report.BEST_PRACTICE.SERVICE_AREA ?? string.Empty);
                    emailContent = emailContent.Replace("{{PROCESS AREA}}", report.BEST_PRACTICE.PROCESS_AREA ?? string.Empty);
                    emailContent = emailContent.Replace("{{PROCESS}}", report.BEST_PRACTICE.PROCESS ?? string.Empty);
                    emailContent = emailContent.Replace("{{BEST PRACTICE}}", report.BEST_PRACTICE.DESCRIPTION ?? string.Empty);
                    emailContent = emailContent.Replace("{{PROJECT NAME}}", project.PROJ_NM);
                    emailContent = emailContent.Replace("{{CSM NAME}}", CSMName);
                    emailContent = emailContent.Replace("{{PM NAME}}", PMName);
                    emailContent = emailContent.Replace("{{CUSTOMER NAME}}", CustomerName);
                    var ep = new EmailProvider(Cldb, CSPdb);
                    ep.SendEmail
                        (
                        new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                        new EmailContent { from = _email, to = tomail, content = emailContent, subject = "Best Practices for the Project ( " + ProjectName + " ) of Customer ( " + CustomerName + " )", hasAttachments = false, attachmentFilePath = "" }
                        , Request);
                }
            }
            catch (Exception ex)
            {

                Logger l = new Logger(Request, ex);
            }

        }

