        private void SendChecklistAuditMail(List<AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED> audit)
        {

            string filePath = HttpContext.Current.Server.MapPath("~/UploadFile/Mails/") + "CheckListAuditReport.htm";
            string empName = "";
            string auditorId = audit[0].AUDITOR_NAME.ToString();
            string dateofAudit = "";
            foreach (string n in audit[0].AUDITEE_NAME)
            {
                empName += GetEmployeeNamebyId(n.ToString()) + ",";
            }
            var projectId = audit[0].PROJECT_ID;
            string projNm = GetProjectName(projectId);
            string cust = audit[0].CUSTOMER_ID;
            string custNm = Cldb.CUSTOMER.GetAll().Where(t => t.CUST_ID == cust).Select(t => t.CUST_NM).FirstOrDefault();
            if (audit[0].ACTUAL_AUDIT_START_DATE != null)
                dateofAudit = audit[0].ACTUAL_AUDIT_START_DATE.Value.ToLongDateString();
            using (System.IO.StreamReader sr = new StreamReader(filePath))
            {
                string emailContent = sr.ReadToEnd();
                emailContent = emailContent.Replace("{{AUDITEE_NM}}", empName);
                emailContent = emailContent.Replace("{{AUDITOR_NAME}}", GetEmployeeNamebyId(auditorId));
                var ep = new EmailProvider(Cldb, CSPdb);
                ep.SendEmail
                    (
                    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                    new EmailContent { from = _email, to = Constants.QUALITY_MAIL, cc = "", content = emailContent, subject = "Internal Audit – " + custNm + "," + projNm + " – " + dateofAudit + "", hasAttachments = false, attachmentFilePath = "", ProjId = projectId },
                    Request
                    );
            }
            //EmailProvider ep = new WebApi.EmailProvider();
            //ep.SendEmail
            //    (
            //    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = email, smtpHost = "smtp.office365.com", smtpPassword = password, smtpPortValue = "587" },
            //    new EmailContent { from = email, to = "balakumar.munuswamy@gavstech.com", cc = "", content = body, subject = "Audit Execution Summary and Report", hasAttachments = false, attachmentFilePath = "" }
            //    );
        }


