        [POST("CheckIsEvaluated")]
        [ActionName("CheckIsEvaluated")]
        [HttpPost]
        public IHttpActionResult CheckIsEvaluated(HttpRequestMessage request)
        {
            bool result = false;

            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            AUDIT_EXECUTION_MODEL AuditData = JsonConvert.DeserializeObject<AUDIT_EXECUTION_MODEL>(json);

            AUDIT_EXECUTION_MODEL rec = new AUDIT_EXECUTION_MODEL();
            if (AuditData != null)
            {
                rec = CSPdb.AUDIT_EXECUTION_MODEL.GetAll().Where(x => x.TEST_ID == AuditData.TEST_ID && x.CUSTOMER_ID == AuditData.CUSTOMER_ID
                                                                            && x.PROJECT_ID == AuditData.PROJECT_ID).FirstOrDefault();
            }

            if (rec != null)
                result = true;
            else
                result = false;

            return Ok(result);
        }

        [GET("GetProcessModelSummary")]
        [ActionName("GetProcessModelSummary")]
        [HttpGet]
        [ResponseType(typeof(List<List<tableCell>>))]
        public IHttpActionResult GetProcessModelSummary(string ProjectId, DateTime StartDate, string AuditTitle, string CustomerId)
        {
            //  DateTime StartDate1 = 
            List<PROCESS_MODEL_SUMMARY> result = CSPdb.AppRepo.GetProcessModelSummaryReport(ProjectId, StartDate, AuditTitle, CustomerId);
            List<List<tableCell>> rowList = new List<List<tableCell>>();
            List<tableCell> rowHeader = new List<tableCell>();
            tableCell header = new tableCell();
            header.text = "Process Model";
            header.rowSpan = 1;
            rowHeader.Add(header);

            header = new tableCell();
            header.text = "No of Controls";
            header.rowSpan = 1;
            rowHeader.Add(header);

            header = new tableCell();
            header.text = "Total Tests";
            header.rowSpan = 1;
            rowHeader.Add(header);

            header = new tableCell();
            header.text = "No of Tests Passed";
            header.rowSpan = 1;
            rowHeader.Add(header);

            header = new tableCell();
            header.text = "No of Tests Failed";
            header.rowSpan = 1;
            rowHeader.Add(header);

            header = new tableCell();
            header.text = "Pass %";
            header.rowSpan = 1;
            rowHeader.Add(header);
            rowList.Add(rowHeader);

            var grp = result.GroupBy(t => t.PROCESS_MODEL_TITLE);

            foreach (var g in grp)
            {
                List<tableCell> row = new List<tableCell>();
                tableCell cell = new tableCell();
                cell.text = g.Key;
                cell.rowSpan = 1;
                cell.colSpan = 1;
                row.Add(cell);

                cell = new tableCell();
                cell.text = g.Select(x => x.CONTROL_TITLE).Distinct().ToList().Count;
                //   int totalControl = int.Parse(cell.text.ToString());
                // decimal deno = totalControl;
                cell.rowSpan = 1;
                cell.colSpan = 1;
                row.Add(cell);

                cell = new tableCell();
                cell.text = g.Select(x => x.TEST_ID).Distinct().ToList().Count;
                int totalTests = int.Parse(cell.text.ToString());
                decimal deno = totalTests;
                cell.rowSpan = 1;
                cell.colSpan = 1;
                row.Add(cell);

                cell = new tableCell();
                cell.text = g.Select(x => x.TEST_RESULT == "Passed").Distinct().ToList().Count;
                int passedCount = int.Parse(cell.text.ToString());
                decimal num = passedCount;
                cell.rowSpan = 1;
                cell.colSpan = 1;
                row.Add(cell);

                cell = new tableCell();
                cell.text = g.Select(x => x.TEST_RESULT == "Failed").Distinct().ToList().Count;
                cell.rowSpan = 1;
                cell.colSpan = 1;
                row.Add(cell);

                cell = new tableCell();
                decimal percentage;
                if (deno != 0)
                {
                    percentage = (num / deno) * 100;
                    percentage = Math.Round(percentage, 0);
                }

                else
                    percentage = 0;
                cell.text = percentage.ToString() + "%";
                cell.rowSpan = 1;
                cell.colSpan = 1;
                row.Add(cell);

                rowList.Add(row);
            }
            return Ok(rowList);
        }

