        [GET("GetAuditExecutionReport")]
        [ActionName("GetAuditExecutionReport")]
        [HttpGet]
        public IHttpActionResult GetAuditExecutionReport(string ProjectId, DateTime StartDate)
        {
            List<AUDIT_EXECUTION_REPORT> result = CSPdb.AppRepo.GetAuditExecutionReport(ProjectId, StartDate);
            List<List<tableCell>> rowList = new List<List<tableCell>>();
            var processMod = result.ToList().GroupBy(t => t.MODEL_DESC);
            List<tableCell> row = new List<tableCell>();
            for (int i = 0; i < processMod.ToList().Count; i++)
            {
                if (i > 0)
                    row = new List<tableCell>();

                tableCell cell = new tableCell();
                cell.text = processMod.ToList()[i].Key;
                cell.rowSpan = result.Where(t => t.MODEL_DESC == processMod.ToList()[i].Key).ToList().Count;
                row.Add(cell);

                var objModel = processMod.ToList()[i].ToList().GroupBy(t => t.OBJECTIVE_DESC);

                for (int j = 0; j < objModel.ToList().Count; j++)
                {
                    if (j > 0)
                        row = new List<tableCell>();

                    cell = new tableCell();
                    cell.text = objModel.ToList()[j].Key;
                    cell.rowSpan = result.Where(t => t.MODEL_DESC == processMod.ToList()[i].Key && t.OBJECTIVE_DESC == objModel.ToList()[j].Key).ToList().Count;
                    row.Add(cell);

                    var riskModel = objModel.ToList()[j].ToList().GroupBy(t => t.RISK_DESC);
                    for (int k = 0; k < riskModel.ToList().Count; k++)
                    {
                        if (k > 0)
                            row = new List<tableCell>();

                        cell = new tableCell();
                        cell.text = riskModel.ToList()[k].Key;
                        cell.rowSpan = result.Where(t => t.MODEL_DESC == processMod.ToList()[i].Key && t.OBJECTIVE_DESC == objModel.ToList()[j].Key && t.RISK_DESC == riskModel.ToList()[k].Key).ToList().Count;
                        row.Add(cell);

                        var contModel = riskModel.ToList()[k].ToList().GroupBy(t => t.CONT_DESC);

                        for (int l = 0; l < contModel.ToList().Count; l++)
                        {
                            if (l > 0)
                                row = new List<tableCell>();

                            cell = new tableCell();
                            cell.text = contModel.ToList()[l].Key;
                            cell.rowSpan = result.Where(t => t.MODEL_DESC == processMod.ToList()[i].Key && t.OBJECTIVE_DESC == objModel.ToList()[j].Key && t.RISK_DESC == riskModel.ToList()[k].Key && t.CONT_DESC == contModel.ToList()[l].Key).ToList().Count;
                            row.Add(cell);

                            var testModel = contModel.ToList()[l].ToList().GroupBy(t => t.TEST_DESC);

                            for (int m = 0; m < testModel.ToList().Count; m++)
                            {
                                if (m > 0)
                                    row = new List<tableCell>();

                                cell = new tableCell();
                                cell.text = testModel.ToList()[m].Key;
                                cell.rowSpan = result.Where(t => t.MODEL_DESC == processMod.ToList()[i].Key && t.OBJECTIVE_DESC == objModel.ToList()[j].Key && t.RISK_DESC == riskModel.ToList()[k].Key && t.CONT_DESC == contModel.ToList()[l].Key && t.TEST_DESC == testModel.ToList()[m].Key).ToList().Count;
                                row.Add(cell);

                                cell = new tableCell();
                                cell.text = result.Where(t => t.MODEL_DESC == processMod.ToList()[i].Key && t.OBJECTIVE_DESC == objModel.ToList()[j].Key && t.RISK_DESC == riskModel.ToList()[k].Key && t.CONT_DESC == contModel.ToList()[l].Key && t.TEST_DESC == testModel.ToList()[m].Key).Select(t => t.RESULT).FirstOrDefault();
                                cell.rowSpan = result.Where(t => t.MODEL_DESC == processMod.ToList()[i].Key && t.OBJECTIVE_DESC == objModel.ToList()[j].Key && t.RISK_DESC == riskModel.ToList()[k].Key && t.CONT_DESC == contModel.ToList()[l].Key && t.TEST_DESC == testModel.ToList()[m].Key).ToList().Count;
                                row.Add(cell);

                                cell = new tableCell();
                                cell.text = result.Where(t => t.MODEL_DESC == processMod.ToList()[i].Key && t.OBJECTIVE_DESC == objModel.ToList()[j].Key && t.RISK_DESC == riskModel.ToList()[k].Key && t.CONT_DESC == contModel.ToList()[l].Key && t.TEST_DESC == testModel.ToList()[m].Key).Select(t => t.RESULT_DESC).FirstOrDefault();
                                cell.rowSpan = result.Where(t => t.MODEL_DESC == processMod.ToList()[i].Key && t.OBJECTIVE_DESC == objModel.ToList()[j].Key && t.RISK_DESC == riskModel.ToList()[k].Key && t.CONT_DESC == contModel.ToList()[l].Key && t.TEST_DESC == testModel.ToList()[m].Key).ToList().Count;
                                row.Add(cell);

                                rowList.Add(row);
                            }

                        }

                    }


                }

            }

            return Ok(rowList);
        }
        public string GetProcessModel(int testId)
        {
            List<PROCESS_MODEL> modelList = CSPdb.PROCESS_MODEL.GetAll().ToList();
            List<PROCESS_MODEL_OBJECTIVES> objectives = CSPdb.PROCESS_MODEL_OBJECTIVES.GetAll().ToList();
            List<PROCESS_MODEL_RISKS> risks = CSPdb.PROCESS_MODEL_RISKS.GetAll().ToList();
            List<PROCESS_MODEL_CONTROL> controls = CSPdb.PROCESS_MODEL_CONTROL.GetAll().ToList();
            List<PROCESS_MODEL_TESTS> tests = CSPdb.PROCESS_MODEL_TESTS.GetAll().ToList();
            var modelId = from tes in tests
                          join cont in controls on tes.CONTROL_ID equals cont.ID
                          join model in modelList on cont.PROCESS_ID equals model.ID
                          where tes.ID == testId
                          select model.TITLE;

            return modelId.ToList()[0];
        }
