        [GET("GetCheckListAuditforProject")]
        [ActionName("GetCheckListAuditforProject")]
        [HttpGet]
        public IHttpActionResult GetCheckListAuditforProject(string CustomerId, string ProjectId)
        {
            List<AUDIT_CHECKLIST_EXECUTION> executionList = new List<AUDIT_CHECKLIST_EXECUTION>();
            List<AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED> res = CSPdb.AppRepo.GetChecklistAudit(CustomerId, ProjectId).ToList();
            var result = res.GroupBy(t => t.PROCESS_MODEL_DESCRIPTION).ToList();
            foreach (var mod in result)
            {
                AUDIT_CHECKLIST_EXECUTION execution = new AUDIT_CHECKLIST_EXECUTION();
                execution.PROCESS_MODEL_DESCRIPTION = mod.Key;
                var area = mod.ToList().GroupBy(t => t.PROCESS_AREA_DESCRIPTION).ToList();
                List<AUDIT_CHECKLIST_SERVICE_AREA> areaList = new List<AUDIT_CHECKLIST_SERVICE_AREA>();
                foreach (var ar in area)
                {
                    AUDIT_CHECKLIST_SERVICE_AREA a = new AUDIT_CHECKLIST_SERVICE_AREA();
                    a.PROCESS_AREA_DESCRIPTION = ar.Key;
                    a.SERVICE_AREA_NAME = ar.ToList()[0].SERVICE_AREA_NAME;
                    var process = ar.ToList().GroupBy(t => t.PROCESS_DESCRIPTION).ToList();
                    List<PROCESS_DESC> descList = new List<PROCESS_DESC>();
                    foreach (var p in process)
                    {
                        PROCESS_DESC desc = new PROCESS_DESC();
                        desc.PROCESS_DESCRIPTION = p.Key;
                        desc.CHECKPOINTS = p.ToList();
                        descList.Add(desc);
                    }
                    a.PROCESS = descList;
                    areaList.Add(a);
                }
                execution.PROCESS_AREA_DATA = areaList;
                executionList.Add(execution);
            }

            return Ok(executionList);
        }

