        [Obsolete("Verify logic and confirm")]
        private string GetCurrentPeriodString(string Frequency, int Sequence, int Year)
        {
            string CurrentPeriod = string.Empty;
            if (Frequency.ToLower() == "quarterly")
            {
                if (Sequence == 1) { CurrentPeriod = "Jul-" + Year.ToString(); }
                else if (Sequence == 2) { CurrentPeriod = "Oct-" + Year.ToString(); }
                else if (Sequence == 3) { CurrentPeriod = "Jan-" + (Year + 1).ToString(); }
                else if (Sequence == 4) { CurrentPeriod = "Apr-" + (Year + 1).ToString(); }
            }
            else if (Frequency.ToLower() == "halfyearly" || Frequency.ToLower() == "half-yearly")
            {
                if (Sequence == 1) { CurrentPeriod = "Jan-Jun " + (Year).ToString(); }
                else if (Sequence == 2) { CurrentPeriod = "Apr-Sep " + Year.ToString(); }
                else if (Sequence == 3) { CurrentPeriod = "Jul-Dec " + Year.ToString(); }


            }
            return CurrentPeriod;
        }
        private string GetCurrentPeriodStringNew(string Frequency, int Sequence, int Year)
        {
            string CurrentPeriod = string.Empty;
            if (Frequency.ToLower() == "quarterly")
            {
                if (Sequence == 1) { CurrentPeriod = "Apr-Jun " + (Year).ToString(); }
                else if (Sequence == 2) { CurrentPeriod = "Jul-Sep " + Year.ToString(); }
                else if (Sequence == 3) { CurrentPeriod = "Oct-Dec " + Year.ToString(); }
                else if (Sequence == 4 || Sequence == 0) { CurrentPeriod = "Jan-Mar " + (Year).ToString(); }

            }
            else if (Frequency.ToLower() == "halfyearly" || Frequency.ToLower() == "half-yearly")
            {
                if (Sequence == 1) { CurrentPeriod = "Jan-Jun " + (Year).ToString(); }
                else if (Sequence == 2) { CurrentPeriod = "Apr-Sep " + Year.ToString(); }
                else if (Sequence == 3) { CurrentPeriod = "Jul-Dec " + Year.ToString(); }
               

            }
            return CurrentPeriod;
        }

        private string GetCurrentMonthString(int month, int year)
        {

            var newDate = new DateTime(year, month, 1);

            return newDate.ToString("MMMM yyyy");
        }

        private string GetPrevMonthString(int month, int year)
        {

            var newDate = new DateTime(year, month, 1).AddMonths(-1);

            return newDate.ToString("MMMM yyyy");
        }

        private string GetCurrentPeriod(string Frequency)
        {
            string CurrentPeriod = string.Empty;
            if (Frequency.ToLower() == "quarterly")
            {
                CurrentPeriod = DateTime.Now.ToString("MMM") + "-" + DateTime.Now.ToString("yy");
            }
            return CurrentPeriod;
        }
        private string GetPreviousPeriod(string Frequency)
        {
            string CurrentYear = DateTime.Now.ToString("yy");
            string PreviousYear = DateTime.Now.AddYears(-1).ToString("yy");
            string PreviousPeriod = string.Empty;
            if (Frequency.ToLower() == "quarterly")
            {
                if (DateTime.Now.Month == 4 || DateTime.Now.Month == 5 || DateTime.Now.Month == 6)
                {
                    PreviousPeriod = "Jan-" + CurrentYear + " to Mar-" + CurrentYear;
                }
                if (DateTime.Now.Month == 7 || DateTime.Now.Month == 8 || DateTime.Now.Month == 9)
                {
                    PreviousPeriod = "Apr-" + CurrentYear + " to Jun-" + CurrentYear;
                }
                if (DateTime.Now.Month == 10 || DateTime.Now.Month == 11 || DateTime.Now.Month == 12)
                {
                    PreviousPeriod = "Jul-" + CurrentYear + " to Sep-" + CurrentYear;
                }
                else if (DateTime.Now.Month == 1 || DateTime.Now.Month == 2 || DateTime.Now.Month == 3)
                {
                    PreviousPeriod = "Oct-" + PreviousYear + " to Dec-" + PreviousYear;
                }
            }
            return PreviousPeriod;
        }
        private string GetSurveyPeriodString(string Frequency, int Sequence, int Year)
        {
            string Period = Frequency;
            if (Frequency.ToLower() == "quarterly")
            {
                if (Sequence == 1)
                {
                    Period = "Apr-" + Year.ToString() + " to Jun-" + Year.ToString();
                }
                else if (Sequence == 2) { Period = "Jul-" + Year.ToString() + " to Sep-" + Year.ToString(); }
                else if (Sequence == 3) { Period = "Oct-" + Year.ToString() + " to Dec-" + Year.ToString(); }
                else if (Sequence == 4) { Period = "Jan-" + (Year + 1).ToString() + " to Mar-" + (Year + 1).ToString(); }
                else Period = string.Empty;
            }
            if (Frequency.ToLower() == "halfyearly" || Frequency.ToLower() == "half-yearly")
            {
                if (Sequence == 1)
                {
                    Period = "Jan-" + Year.ToString() + " to Jun-" + Year.ToString();
                }
                else if (Sequence == 2)
                {
                    Period = "Apr-" + Year.ToString() + " to Sep-" + Year.ToString();

                }
                else if (Sequence == 3)
                {
                    Period = "Jul-" + Year.ToString() + " to Dec-" + Year.ToString();

                }
                else Period = string.Empty;

            }
            return Period;
        }





