        [POST("GetCSMListByCustomerIds")]
        [ActionName("GetCSMListByCustomerIds")]
        [HttpPost]
        public IHttpActionResult GetCSMListByCustomerIds(HttpRequestMessage request)
        {
            var content = request.Content;
            var header = request.Headers;
            string jsonContent = content.ReadAsStringAsync().Result;
            var custIds = jsonContent.ToString();
            var custIdlist = custIds.Split(',');
            if (custIds.Contains("-1"))
            {
                var list = Cldb.AppRepo.GetCSMList().Select(p => new { p.CSM_ID, p.CSM }).Distinct().OrderBy(x => x.CSM).ToList();
                return Ok(list);
            }
            else
            {
                var list = Cldb.AppRepo.GetCSMList().Where(x => custIdlist.Contains(x.CUST_ID.ToString())).Select(p => new { p.CSM_ID, p.CSM }).Distinct().OrderBy(x => x.CSM).ToList();
                return Ok(list);
            }
        }

