        [HttpGet]
        public IHttpActionResult GetGavsServiceArea()
        {
            List<string> serviceArea = new List<string>();
            List<int> gavsServiceArea = new List<int>();
            if (Request.Headers.Contains("serviceArea"))
                serviceArea = Request.Headers.GetValues("serviceArea").ToList<string>()[0].ToString().Split(',').ToList<string>();

            foreach (string s in serviceArea)
            {
                int? sa = CSPdb.PROCESS_SERVICE_AREA.GetAll().Where(t => t.ID == Convert.ToInt32(s)).Select(t => t.GAVS_SERVICE_AREA).FirstOrDefault();
