                    if (!gavsServiceArea.Contains(sa.Value))
                        gavsServiceArea.Add(sa.Value);

            }
            return Ok(gavsServiceArea);
        }




        private HighChartsPiePortfolio ConfigurePieChart(string chartTitle)
        {
            HighChartsPiePortfolio pieDataOverAll = new HighChartsPiePortfolio();
            pieDataOverAll.chart.type = "pie";
            pieDataOverAll.exporting.enabled = false;
            pieDataOverAll.credits.enabled = false;
            pieDataOverAll.title.text = chartTitle;
            pieDataOverAll.title.style.color = "#333333";
            pieDataOverAll.title.style.fontSize = "12px";
            pieDataOverAll.tooltip.pointFormat = "{point.name}: <b> {point.y} </b>";
            pieDataOverAll.plotOptions.pie.allowPointSelect = true;
            pieDataOverAll.plotOptions.pie.cursor = "pointer";
            pieDataOverAll.plotOptions.pie.dataLabels.enabled = true;
            pieDataOverAll.plotOptions.pie.dataLabels.format = "<b>{point.name}</b>: {point.y} ";
            pieDataOverAll.plotOptions.pie.dataLabels.distance = 5;
            pieDataOverAll.plotOptions.pie.size = 80;

            return pieDataOverAll;

        }
        private List<HighChartsPiePortfolio> PopulateStaffingPieChartDetails(List<StaffingSummary> staffingList, bool isBilledReport = false)
        {
            var pieDataList = new List<HighChartsPiePortfolio>();
            var dataoverAll = new List<pieData>();

            if (isBilledReport)
            {
                var pieDataOverAll = ConfigurePieChart("Billing Summary");
                pieDataOverAll.tooltip.pointFormat = "{point.name}";
                pieDataOverAll.plotOptions.pie.dataLabels.format = "<b>{point.name}</b>";
                pieDataOverAll.credits.format = "<b>{point.name}</b>";
                pieDataOverAll.plotOptions.pie.size = 80;

                var offshoreBilledCnt = staffingList.SingleOrDefault(sb => sb.NAME == "OFFSHORE")?.BILLED;
                var onshoreBilledCnt = staffingList.SingleOrDefault(sb => sb.NAME == "ONSITE")?.BILLED;

                var offshoreUnBilledCnt = staffingList.SingleOrDefault(sb => sb.NAME == "OFFSHORE")?.UNBILLED;
                var onshoreUnBilledCnt = staffingList.SingleOrDefault(sb => sb.NAME == "ONSITE")?.UNBILLED;

                var billedData = new pieData
                {
                    color = COLOR_BLUE_LIGHT,
                    y = staffingList.Sum(a => a.BILLED),
                    name = $"Billed Resources <br /> <br /> OFFSHORE COUNT: { offshoreBilledCnt } <br /> ONSITE COUNT: { onshoreBilledCnt } ", // GetName(det.Key);
                }; dataoverAll.Add(billedData);

                var UnBilledData = new pieData
                {
                    color = COLOR_GREEN_LIGHT,
                    y = staffingList.Sum(a => a.UNBILLED),
                    name = $"Non-Billable Resources <br /> <br /> OFFSHORE COUNT: { offshoreUnBilledCnt } <br /> ONSITE COUNT: { onshoreUnBilledCnt } ", // GetName(det.Key);
                }; dataoverAll.Add(UnBilledData);

                pieDataOverAll.series.Add(new seriesPiePortFolio() { name = "Chart", data = dataoverAll });
                pieDataList.Add(pieDataOverAll);
            }
            else
            {
                var pieDataOverAll = ConfigurePieChart("Resources Summary");

                foreach (var item in staffingList)
                {
                    var data1 = new pieData();
                    data1.color = item.NAME.Equals("OFFSHORE") ? COLOR_BLUE_LIGHT : COLOR_GREEN_LIGHT;  //det.Key;
                    data1.y = item.TOTAL;
                    data1.name = item.NAME; // GetName(det.Key);
                    dataoverAll.Add(data1);
                }
                pieDataOverAll.series.Add(new seriesPiePortFolio() { name = "Chart", data = dataoverAll });
                pieDataList.Add(pieDataOverAll);
            }

            return pieDataList;
        }


        [POST("GetFindingStatusDetails")]
        [ActionName("GetFindingStatusDetails")]
        [HttpPost]
        public IHttpActionResult GetFindingStatusDetails([FromBody] AUDIT_CHECKLIST_PROJECT_FINDINGS batch)
        {
            List<AUDIT_FINDING_STAGES_MAPPING> map = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().Where(t => t.FINDING_ID == batch.ID).ToList();
            List<AUDIT_FINDING_CAPPA_EXT> capaList = new List<AUDIT_FINDING_CAPPA_EXT>();
            List<AUDIT_FINDING_CAPPA_EXT> caparevList = new List<AUDIT_FINDING_CAPPA_EXT>();
            List<AUDIT_FINDINGS_CAPA> capa = new List<AUDIT_FINDINGS_CAPA>();
            FINDING_STAGE_DATA resultData = new FINDING_STAGE_DATA();
            List<AUDIT_FINDINGS_CAPA_REVIEW_EXTENDED> extList = new List<AUDIT_FINDINGS_CAPA_REVIEW_EXTENDED>();


            resultData.AUDITEE_ACCEPTANCE_STATUS.STATUS = map.FirstOrDefault(t => t.STAGE_ID == 1);
            if (resultData.AUDITEE_ACCEPTANCE_STATUS.STATUS == null)
                resultData.AUDITEE_ACCEPTANCE_STATUS.STATUS = new AUDIT_FINDING_STAGES_MAPPING();
            resultData.AUDITEE_ACCEPTANCE_STATUS.AUDITEE_ACCEPTANCE = CSPdb.AUDITEE_ACCEPTANCE.GetAll().FirstOrDefault(x => x.FINDING_ID == batch.ID && x.ISACTIVE);
            if (resultData.AUDITEE_ACCEPTANCE_STATUS.AUDITEE_ACCEPTANCE == null)
                resultData.AUDITEE_ACCEPTANCE_STATUS.AUDITEE_ACCEPTANCE = new AUDITEE_ACCEPTANCE();

            resultData.CAPA_SUBMISSION.STATUS = map.FirstOrDefault(t => t.STAGE_ID == 1);

            AUDIT_FINDINGS_CAPA latest = CSPdb.AUDIT_FINDINGS_CAPA.GetAll().Where(t => t.FINDING_ID == batch.ID && t.ISACTIVE == true).OrderByDescending(x => x.CREATED_DATE).FirstOrDefault();
            if (latest != null)
                capa = CSPdb.AUDIT_FINDINGS_CAPA.GetAll().Where(t => t.FINDING_ID == batch.ID && t.ISSAVED == false && t.UNIQUE_ID == latest.UNIQUE_ID && t.ISACTIVE == true).ToList();

            if (!capa.Any())
                return Ok(resultData);

            // Stage 1 - CAP Submission

            foreach (AUDIT_FINDINGS_CAPA c in capa)
            {
                AUDIT_MANAGEMENT_ROOTCAUSES rootcause = CSPdb.AUDIT_MANAGEMENT_ROOTCAUSES.GetById(c.ROOT_CAUSE_ID.Value);
                AUDIT_FINDING_CAPPA_EXT ext = new AUDIT_FINDING_CAPPA_EXT();
                ext.CAUSE_ID = c.ROOT_CAUSE_ID.Value;
                ext.CAPPALIST = c;
                ext.CAPPALIST.ROOT_CAUSE = rootcause.ROOT_CAUSE;
                ext.CAPPALIST.CAUSE = CSPdb.AUDIT_MANAGEMENT_CAUSES.GetById(rootcause.CAUSE_ID).CAUSES;
                capaList.Add(ext);
            }

            resultData.CAPA_SUBMISSION.CAPA = capaList;

            //stage2 - Audit Review
            resultData.CAPA_REVIEW.STATUS = map.FirstOrDefault(t => t.STAGE_ID == 2);

            foreach (AUDIT_FINDINGS_CAPA c in capa)
            {
                AUDIT_FINDING_CAPA_REVIEW review = CSPdb.AUDIT_FINDING_CAPA_REVIEW.GetAll().FirstOrDefault(t => t.FINDING_ID == c.FINDING_ID && t.ROOT_CAUSE_ID == c.ROOT_CAUSE_ID && t.UNIQUE_ID == c.UNIQUE_ID && t.ISACTIVE == true);
                if (review == null)
                    review = new AUDIT_FINDING_CAPA_REVIEW();

                AUDIT_FINDINGS_CAPA_REVIEW_EXTENDED ext = new AUDIT_FINDINGS_CAPA_REVIEW_EXTENDED();
                ext.CAP_TARGET_DATE = c.CAP_TARGET_DATE;
                ext.CAUSE = c.CAUSE;
                ext.CORRECTION = c.CORRECTION;
                ext.CORRECTIVE_ACTION_PLAN = c.CORRECTIVE_ACTION_PLAN;
                ext.CREATED_BY = c.CREATED_BY;
                ext.CREATED_DATE = c.CREATED_DATE;
                ext.FINDING_ID = c.FINDING_ID;
                ext.ID = c.ID;
                ext.ISACTIVE = c.ISACTIVE;
                ext.RESPONSIBLE = c.RESPONSIBLE;
                ext.ISCAPAPPROVED = review.ISAPPROVED;
                ext.ISCAPREJECTED = review.ISREJECTED;
                ext.ISROOTCAUSE = c.ISROOTCAUSE;
                ext.ISSUBMITTED = review.ISSUBMITTED;
                ext.NOTES = c.NOTES;
                ext.REMARKS = review.REMARKS;
                ext.PLAN_FOR_EFFECTIVE_CAP = c.PLAN_FOR_EFFECTIVE_CAP;
                ext.PLAN_TARGET_DATE = c.PLAN_TARGET_DATE;
                ext.REVIEW_UPDATED_BY = review.UPDATED_BY;
                ext.ROOT_CAUSE = c.ROOT_CAUSE;
                ext.ROOT_CAUSE_ID = c.ROOT_CAUSE_ID;
                ext.ISCHECKED = review.ISREJECTED.HasValue ? !(review.ISREJECTED.Value) : false;
                ext.STATUS = review.STATUS;
                ext.UNIQUE_ID = c.UNIQUE_ID;
                ext.UPDATED_BY = c.UPDATED_BY;
                ext.UPDATED_DATE = c.UPDATED_DATE;
                ext.ROOTCAUSE_OTHER = c.ROOTCAUSE_OTHER;
                extList.Add(ext);
            }

            resultData.CAPA_REVIEW.CAPA = extList;

            //stage 3 -Audit Implementation
            resultData.CAP_IMPLEMENTATION.STATUS = map.Where(t => t.STAGE_ID == 3).FirstOrDefault();
            List<AUDIT_FINDING_CAPA_IMPLEMENTATION> implist = new List<AUDIT_FINDING_CAPA_IMPLEMENTATION>();
            foreach (AUDIT_FINDINGS_CAPA c in capa)
            {
                AUDIT_FINDING_CAPA_IMPLEMENTATION imp = CSPdb.AUDIT_FINDING_CAPA_IMPLEMENTATION.GetAll()
                            .Where(t => t.FINDING_ID == c.FINDING_ID && t.ROOT_CAUSE_ID == c.ROOT_CAUSE_ID && t.UNIQUE_ID == c.UNIQUE_ID && t.ISACTIVE == true)
                            .OrderByDescending(x => x.ID)
                            .FirstOrDefault();
                if (imp == null)
                {
                    imp = new AUDIT_FINDING_CAPA_IMPLEMENTATION();
                    imp.FINDING_ID = c.FINDING_ID;
                    imp.UNIQUE_ID = c.UNIQUE_ID;
                    imp.ROOT_CAUSE_ID = c.ROOT_CAUSE_ID.HasValue ? c.ROOT_CAUSE_ID.Value : (int?)null;
                    imp.CAPADATA = c;
                    implist.Add(imp);
                }
                else
                {
                    imp.CAPADATA = c;
                    implist.Add(imp);
                }
            }
            resultData.CAP_IMPLEMENTATION.CAPA = implist;

            //stage 4 -Audit Verification

            resultData.CAP_VERIFICATION.STATUS = map.Where(t => t.STAGE_ID == 4).FirstOrDefault();
            List<AUDIT_FINDING_CAPA_VERIFICATION> veriList = new List<AUDIT_FINDING_CAPA_VERIFICATION>();
            foreach (AUDIT_FINDINGS_CAPA c in capa)
            {
                AUDIT_FINDING_CAPA_VERIFICATION imp = CSPdb.AUDIT_FINDING_CAPA_VERIFICATION.GetAll()
                    .Where(t => t.FINDING_ID == c.FINDING_ID && t.ROOT_CAUSE_ID == c.ROOT_CAUSE_ID && t.UNIQUE_ID == c.UNIQUE_ID && t.ISACTIVE == true)
                    .OrderByDescending(x => x.ID)
                    .FirstOrDefault();
                if (imp == null)
                {
                    imp = new AUDIT_FINDING_CAPA_VERIFICATION();
                    imp.FINDING_ID = c.FINDING_ID;
                    imp.UNIQUE_ID = c.UNIQUE_ID;
                    imp.ROOT_CAUSE_ID = c.ROOT_CAUSE_ID.HasValue ? c.ROOT_CAUSE_ID.Value : (int?)null;
                    imp.CAPADATA = c;
                    veriList.Add(imp);
                }
                else
                {
                    imp.CAPADATA = c;
                    veriList.Add(imp);
                }
            }
            resultData.CAP_VERIFICATION.CAPA = veriList;

            return Ok(resultData);
        }
