        [POST("GetAuditFindingCappas")]
        [ActionName("GetAuditFindingCappas")]
        [HttpPost]
        public IHttpActionResult GetAuditFindingCappas(HttpRequestMessage request)
        {
            var content = request.Content;
            var header = request.Headers;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            var results = JsonConvert.DeserializeObject<FINDING_STAGE_DATA>(json);
            var causeIdorRootCauseIdstring = new List<string>();
            var isFromFinding = Convert.ToBoolean(GetHeaderDetails_Int("isFromFinding"));
            if (Request.Headers.Contains("causeIds"))
                causeIdorRootCauseIdstring = Request.Headers.GetValues("causeIds").ToList<string>()[0].ToString().Split(',').ToList<string>();

            var causeList = new List<AUDIT_FINDING_CAPPA_EXT>();
            var cause = new AUDIT_FINDING_CAPPA_EXT();

            var rootcauseList = CSPdb.AUDIT_MANAGEMENT_ROOTCAUSES.GetAll().Where(x => x.ISACTIVE && causeIdorRootCauseIdstring.Contains(x.ID.ToString()) || causeIdorRootCauseIdstring.Contains(x.CAUSE_ID.ToString())).ToList();

            var causeDetailsList = CSPdb.AUDIT_MANAGEMENT_CAUSES.GetAll().Where(x => x.ISACTIVE).ToList();

            var capaSubmission = (List<AUDIT_FINDING_CAPPA_EXT>)results.CAPA_SUBMISSION.CAPA;

            foreach (string i in causeIdorRootCauseIdstring)
            {
                int causeIdOrRootCauseId = Convert.ToInt32(i);

                var res = isFromFinding ? capaSubmission.FirstOrDefault(x => x.CAPPALIST.ROOT_CAUSE_ID == causeIdOrRootCauseId) : capaSubmission.FirstOrDefault(x => x.CAUSE_ID == causeIdOrRootCauseId);

                var rootcause = isFromFinding ? rootcauseList.FirstOrDefault(x => x.ID == causeIdOrRootCauseId) : rootcauseList.FirstOrDefault(x => x.CAUSE_ID == causeIdOrRootCauseId);

                if (res == null)
                {
                    cause = new AUDIT_FINDING_CAPPA_EXT();
                    cause.CAUSE_ID = isFromFinding ? rootcause.CAUSE_ID : causeIdOrRootCauseId;
                    cause.CAPPALIST = new AUDIT_FINDINGS_CAPA();
                    cause.CAPPALIST.FINDING_ID = results.AUDIT_REPORTING_FINDING.FINDINGS.ID;
                    cause.CAPPALIST.ROOT_CAUSE_ID = isFromFinding ? rootcause.ID : (int?)null;
                    cause.CAPPALIST.ROOT_CAUSE = isFromFinding ? rootcause.ROOT_CAUSE : string.Empty;
                    cause.CAPPALIST.CAUSE = isFromFinding ? causeDetailsList.FirstOrDefault(x => x.ID == rootcause.CAUSE_ID).CAUSES : causeDetailsList.FirstOrDefault(x => x.ID == causeIdOrRootCauseId).CAUSES;
                    causeList.Add(cause);
                }
                else
                {
                    cause = res;
                    cause.CAPPALIST.FINDING_ID = results.AUDIT_REPORTING_FINDING.FINDINGS.ID;
                    causeList.Add(cause);
                }

            }
            return Ok(causeList);
        }

