        [POST("UpdateProcessMapping")]
        [ActionName("UpdateProcessMapping")]
        [HttpPost]
        public IHttpActionResult UpdateProcessMapping(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            ProcessModelProcessMapping results = JsonConvert.DeserializeObject<ProcessModelProcessMapping>(json);

            string empid = Request.Headers.GetValues("empId").FirstOrDefault();

            //DELETE existing records
            List<PROCESS_MODEL_PROCESS_MAPPING> delrec = CSPdb.PROCESS_MODEL_PROCESS_MAPPING.GetAll().Where(t => t.PROCESS_MODEL_ID == results.PROCESS_MODEL.ID).ToList();
            delrec.ToList().ForEach(c => c.ISACTIVE = false);
            CSPdb.PROCESS_MODEL_PROCESS_MAPPING.Update(delrec);
            CSPdb.Commit(CanCommit);
            //----------------
            if (results != null && results.PROCESS_MODEL != null)
            {
                foreach (PROCESS p in results.PROCESS)
                {
                    PROCESS_MODEL_PROCESS_MAPPING pm = new PROCESS_MODEL_PROCESS_MAPPING();
                    pm.PROCESS_MODEL_ID = results.PROCESS_MODEL.ID;
                    pm.PROCESS_ID = p.ID;
                    pm.CREATED_BY = empid;
                    pm.CREATED_DATE = DateTime.Now;
                    pm.UPDATED_BY = empid;
                    pm.UPDATED_DATE = DateTime.Now;
                    pm.ISACTIVE = true;

                    CSPdb.PROCESS_MODEL_PROCESS_MAPPING.Add(pm);
                    CSPdb.Commit(CanCommit);
                }
            }

            return Ok(results.PROCESS);
        }



