        [GET("GetObjectivesbyRiskId"), ActionName("GetObjectivesbyRiskId"), HttpGet]
        public IHttpActionResult GetObjectivesbyRiskId(int RiskId)
        {
            List<PROCESS_MODEL_OBJECTIVES_NEW> list = new List<PROCESS_MODEL_OBJECTIVES_NEW>();
            List<RISKS_OBJECTIVES_MAPPING> list2 = (
                from x in base.CSPdb.RISKS_OBJECTIVES_MAPPING.GetAll()
                where x.RISK_ID == RiskId && x.ISACTIVE
                select x).ToList<RISKS_OBJECTIVES_MAPPING>();
            using (List<RISKS_OBJECTIVES_MAPPING>.Enumerator enumerator = list2.GetEnumerator())
            {
                while (enumerator.MoveNext())
                {
                    RISKS_OBJECTIVES_MAPPING m = enumerator.Current;
                    list.Add((
                        from x in base.CSPdb.PROCESS_MODEL_OBJECTIVES_NEW.GetAll()
                        where x.ID == m.OBJECTIVE_ID && x.ISACTIVE
                        select x).FirstOrDefault<PROCESS_MODEL_OBJECTIVES_NEW>());
                }
            }
            return this.Ok<List<PROCESS_MODEL_OBJECTIVES_NEW>>(list);
        }

