        [POST("AddTestControls")]
        [ActionName("AddTestControls")]
        [HttpPost]
        public IHttpActionResult AddTestControls(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            TestControlsMapping results = JsonConvert.DeserializeObject<TestControlsMapping>(json);
            string empid = Request.Headers.GetValues("empId").FirstOrDefault();

            if (results != null)
            {
                PROCESS_MODEL_TESTS_NEW test = results.PROCESS_MODEL_TESTS_NEW;
                List<PROCESS_MODEL_CONTROL_NEW> controls = results.PROCESS_MODEL_CONTROL_NEW;
                if (test != null)
                {
                    PROCESS_MODEL_TESTS_NEW newtest = new PROCESS_MODEL_TESTS_NEW();
                    newtest = test;
                    newtest.UPDATED_BY = empid;
                    newtest.UPDATED_DATE = DateTime.Now;
                    newtest.CREATED_BY = empid;
                    newtest.CREATED_DATE = DateTime.Now;
                    newtest.ISACTIVE = true;
                    CSPdb.PROCESS_MODEL_TESTS_NEW.Add(newtest);
                    CSPdb.Commit(CanCommit);
                }

                if (test != null && controls != null)
                {
                    foreach (var control in controls)
                    {
                        TEST_CONTROL_MAPPING map = new TEST_CONTROL_MAPPING();
                        map.CONTROL_ID = control.ID;
                        map.TEST_ID = test.ID;
                        map.ISACTIVE = true;
                        CSPdb.TEST_CONTROL_MAPPING.Add(map);
                        CSPdb.Commit(CanCommit);
                    }
                }
            }
            return Ok(results);
        }

        [POST("UpdateTestControls")]
        [ActionName("UpdateTestControls")]
        [HttpPost]
        public IHttpActionResult UpdateTestControls([FromBody] TestControlsMapping results)
        {
            PROCESS_MODEL_TESTS_NEW rec = new PROCESS_MODEL_TESTS_NEW();
            string empid = Request.Headers.GetValues("empId").FirstOrDefault();

            if (results != null && results.PROCESS_MODEL_TESTS_NEW != null)
            {
                rec = CSPdb.PROCESS_MODEL_TESTS_NEW.GetById(results.PROCESS_MODEL_TESTS_NEW.ID);
                rec.TITLE = results.PROCESS_MODEL_TESTS_NEW.TITLE;
                rec.DESCRIPTION = results.PROCESS_MODEL_TESTS_NEW.DESCRIPTION;
                rec.UPDATED_BY = empid;
                rec.UPDATED_DATE = DateTime.Now;
                CSPdb.PROCESS_MODEL_TESTS_NEW.Update(rec);
                CSPdb.Commit(CanCommit);

                List<PROCESS_MODEL_CONTROL_NEW> controls = results.PROCESS_MODEL_CONTROL_NEW;
                // delete the existing mapping for this test
                List<TEST_CONTROL_MAPPING> mapping = CSPdb.TEST_CONTROL_MAPPING.GetAll().Where(x => x.TEST_ID == rec.ID).ToList();
                mapping.ForEach(x => x.ISACTIVE = false);
                CSPdb.TEST_CONTROL_MAPPING.DeleteList(mapping);
                CSPdb.Commit(CanCommit);

                // map controls to the test
                if (controls != null)
                {
                    foreach (var control in controls)
                    {
                        TEST_CONTROL_MAPPING map = new TEST_CONTROL_MAPPING();
                        map.CONTROL_ID = control.ID;
                        map.TEST_ID = rec.ID;
                        map.ISACTIVE = true;
                        CSPdb.TEST_CONTROL_MAPPING.Add(map);
                        CSPdb.Commit(CanCommit);
                    }
                }
            }
            return Ok(results);
        }



