        [POST("GetSavedQuestions")]
        [ActionName("GetSavedQuestions")]
        [HttpPost]
        public IHttpActionResult GetSavedQuestions(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            PROCESS_MODEL_QUESTIONS results = JsonConvert.DeserializeObject<PROCESS_MODEL_QUESTIONS>(json);
            CSPdb.PROCESS_MODEL_QUESTIONS.GetAll().Where(t => t.CUSTOMER_ID == results.CUSTOMER_ID && t.PROJECT_ID == results.PROJECT_ID && t.VERSIONID == results.VERSIONID);
            results.QUESTIONS_MODEL = GetQuestionwithClause(results);
            results.PROCESS_MODEL_ID = GetProcessModelId(results);
            results.SERVICE_AREA_ID = GetServiceAreaId(results);

            return Ok(results);
        }
        private int GetProcessModelId(PROCESS_MODEL_QUESTIONS ques)
        {
            int areaId = CSPdb.PROCESS_MODEL_PROCESS.GetAll().Where(t => t.ID == ques.PROCESS_ID).Select(t => t.PROCESS_AREA_ID).FirstOrDefault();
            int ModelId = CSPdb.PROCESS_SERVICE_AREA.GetAll().Where(t => t.ID == areaId).Select(t => t.PROCESS_MODEL_ID).FirstOrDefault();
            return ModelId;
        }
        private int GetServiceAreaId(PROCESS_MODEL_QUESTIONS ques)
        {
            int areaId = CSPdb.PROCESS_MODEL_PROCESS.GetAll().Where(t => t.ID == ques.PROCESS_ID).Select(t => t.PROCESS_AREA_ID).FirstOrDefault();
            int serviceAreaID = CSPdb.PROCESS_SERVICE_AREA.GetAll().Where(t => t.ID == areaId).Select(t => t.GAVS_SERVICE_AREA).FirstOrDefault();
            return serviceAreaID;
        }
        private List<AUDIT_CHECKLIST_QUESTIONS> GetQuestionwithClause(PROCESS_MODEL_QUESTIONS qt)
        {
            List<AUDIT_CHECKLIST_QUESTIONS> q = CSPdb.AUDIT_CHECKLIST_QUESTIONS.GetAll().Where(t => t.CHECKLIST_ID == qt.ID && t.VERSIONID == qt.VERSIONID && t.PROCESS_ID == qt.PROCESS_ID).ToList();
            foreach (AUDIT_CHECKLIST_QUESTIONS acq in q)
            {
                acq.CLAUSES = CSPdb.AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING.GetAll().Where(t => t.QUESTION_ID == acq.ID).Select(t => t.CLAUSE_ID).ToList();
            }
            return q;
        }

