        [GET("GetProcessAreaandProcessforSA")]
        [ActionName("GetProcessAreaandProcessforSA")]
        [HttpGet]
        public IHttpActionResult GetProcessAreaandProcessforSA(string CustomerId, string ProjectId, int ModelId, int ServiceAreaId)
        {
            List<PROCESS_AREA_PROCESS> result = new List<PROCESS_AREA_PROCESS>();
            List<int> serviceAreaIds = CSPdb.PROCESS_SERVICE_AREA.GetAll().Where(t => t.GAVS_SERVICE_AREA == ServiceAreaId).Select(t => t.ID).Distinct().ToList();
            List<int> areaIds = CSPdb.PROCESS_MODEL_PROJECT_CONFIG.GetAll().Where(t => t.CUSTOMER_ID == CustomerId && t.PROJECT_ID == ProjectId && t.PROCESS_MODEL_ID == ModelId && serviceAreaIds.Contains(t.SERVICE_AREA_ID)).Select(t => t.SERVICE_AREA_ID).Distinct().ToList();

            foreach (int ar in areaIds)
            {
                PROCESS_AREA_PROCESS res = new PROCESS_AREA_PROCESS();
                res.PROCESS_AREA = CSPdb.PROCESS_SERVICE_AREA.GetById(ar).PROCESS_AREA_DESCRIPTION;
                res.PROCESS = CSPdb.PROCESS_MODEL_PROCESS.GetAll().Where(t => t.PROCESS_AREA_ID == ar).ToList();
                result.Add(res);
            }
            return Ok(result);
        }

