        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            List<PM_PROCESS_CHECKLIST_MAPPING> mapping = JsonConvert.DeserializeObject<List<PM_PROCESS_CHECKLIST_MAPPING>>(json);

            if (mapping.Count > 0)
            {
                int SAId = mapping[0].PROCESS_ID;
                List<PM_PROCESS_CHECKLIST_MAPPING> deletes = CSPdb.PM_PROCESS_CHECKLIST_MAPPING.GetAll()
                        .Where(t => t.PROCESS_ID == SAId && t.ISACTIVE).ToList();

                if (deletes.Count > 0)
                {
                    deletes.ForEach(t => t.ISACTIVE = false);
                    this.CSPdb.PM_PROCESS_CHECKLIST_MAPPING.Update(deletes);
                }

            }
            this.CSPdb.PM_PROCESS_CHECKLIST_MAPPING.AddList(mapping);
            this.CSPdb.Commit(CanCommit);
            return Ok(mapping);
        }

