        [POST("UpdateChecklistQuestion")]
        [ActionName("UpdateChecklistQuestion")]
        [HttpPost]
        public IHttpActionResult UpdateChecklistQuestion([FromBody] ChecklistQuestionMapping input)
        {
            PM_CHECKLIST_QUESTIONS question = new PM_CHECKLIST_QUESTIONS();
            if (input != null)
            {
                question = input.QUESTION;

                if (question != null)
                {
                    question.UPDATED_DATE = DateTime.Now;
                    CSPdb.PM_CHECKLIST_QUESTIONS.Update(question);
                    CSPdb.Commit(CanCommit);
                }

                var mappingrec = CSPdb.PM_PROCESS_QUESTIONS_MAPPING.GetAll().FirstOrDefault(x => x.QUESTION_ID == question.ID
                        && x.CHECKLIST_ID == question.CHECKLIST_ID
                        && x.SERVICE_AREA_ID == input.SERVICE_AREA_ID
                        && x.PROCESS_AREA_ID == input.PROCESS_AREA_ID
                        && x.PROCESS_ID == input.PROCESS_ID
                        && x.ISACTIVE);

                if (mappingrec != null)
                {
                    mappingrec.DISPLAY_ORDER = input.QUESTION.DISPLAY_ORDER;
                    CSPdb.PM_PROCESS_QUESTIONS_MAPPING.Update(mappingrec);
                    CSPdb.Commit(CanCommit);
                }
            }

            return Ok(question);
        }

        [POST("Feedback")]
        [ActionName("Feedback")]
        [HttpPost]
        public IHttpActionResult UpdateFeedback(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            CUSTOMER_FEEDBACK results = JsonConvert.DeserializeObject<CUSTOMER_FEEDBACK>(json);
            CUSTOMER_FEEDBACK overview = CSPdb.CUSTOMER_FEEDBACK.GetById(results.ID);

            var oldStatus = overview.STATUS;
            if (results != null && overview != null)
            {
                overview.CUSTOMER_ID = results.CUSTOMER_ID;
                overview.CUSTOMER_EMAILID = results.CUSTOMER_EMAILID;
                overview.FEEDBACK = results.FEEDBACK;
                overview.STATUS = results.STATUS;
                overview.COMMENTS = results.COMMENTS;
                overview.UPDATED_BY = results.UPDATED_BY;
                overview.UPDATED_DATE = DateTime.Now;
                if (results.TARGET_DATE.HasValue)
                    overview.TARGET_DATE = results.TARGET_DATE.Value.ToLocalTime();
                overview.ISACTIVE = true;
                CSPdb.CUSTOMER_FEEDBACK.Update(overview);
                CSPdb.Commit(CanCommit);
            }
            //if (overview.STATUS.ToUpper() == "CLOSED")
            if (overview.STATUS.ToUpper() != oldStatus.ToUpper())
            {
                //send mail
                var projects = Cldb.PROJECT.GetAll().Where(t => t.CUST_ID == results.CUSTOMER_ID && t.PROJ_STATUS != "Close" && t.END_DATE > DateTime.Today).ToList();

                var csmMails = new List<string>();// ;
                var pmMails = new List<string>();
                csmMails = helper.GetCSMMailsFromAccount(results.CUSTOMER_ID);
                var pms = projects.Select(x => x.PROJ_PM_EMP_ID).Distinct().ToList();
                pmMails.AddRange(Cldb.EMP_INFO.GetAll().Where(x => pmMails.Contains(x.EMAIL_ID) && x.DOR == null).Select(x => x.EMAIL_ID).ToList());
                //foreach (var item in projects)
                //{
                //    csmMails.Add(helper.GetCSMMailsFromProject(item));
                //    pmMails.AddRange(helper.GetPMFromProject(item));
                //}
                var spoc = new List<string>();// Cldb.EMP_INFO.GetAll().Where(t => t.CSM_TITLE_ID == 7).Select(x => x.EMAIL_ID).ToList();
                string tomail = overview.CUSTOMER_EMAILID;
                string ccmail = string.Join(",", csmMails.Union(pmMails).Where(x => !string.IsNullOrWhiteSpace(x)).Distinct().ToArray());


                string customerName = Cldb.CUSTOMER.GetAll().FirstOrDefault(x => x.CUST_ID == overview.CUSTOMER_ID)?.CUST_NM;

                string customerContact = CSPdb.CUSTOMER_USERS.GetAll().FirstOrDefault(x => x.EMAILID == overview.CUSTOMER_EMAILID)?.DISPLAY_NAME;

                string subject = $"Feedback Update from GAVS";

                Dictionary<string, string> EmailContentValues = new Dictionary<string, string>();
                //FIRSTNAME

                EmailContentValues.Add("FIRSTNAME", customerContact);
                EmailContentValues.Add("TICKET ID", overview.TICKET_ID);
                EmailContentValues.Add("DATE", overview.CREATED_DATE.HasNoValue() ? "-" : overview.CREATED_DATE.ToLocalTime().ToString("dd-MMM-yyyy"));
                EmailContentValues.Add("FEEDBACK", !string.IsNullOrWhiteSpace(overview.FEEDBACK) ? overview.FEEDBACK : "-");
                EmailContentValues.Add("STATUS", !string.IsNullOrWhiteSpace(overview.STATUS) ? overview.STATUS.Replace('-', ' ') : "-");
                EmailContentValues.Add("COMMENTS", !string.IsNullOrWhiteSpace(overview.COMMENTS) ? overview.COMMENTS : "-");
                EmailContentValues.Add("TARGET DATE", overview.TARGET_DATE.HasValue ? overview.TARGET_DATE.GetValueOrDefault().ToLocalTime().ToString("dd-MMM-yyyy") : "-");

                string mailContent = helper.GetEmailContent("CustomerFeedbackResponse.htm", EmailContentValues);
                var ep = new EmailProvider(Cldb, CSPdb);
                if (string.IsNullOrWhiteSpace(tomail)) tomail = _email;
                ep.SendEmail
                    (
                    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                    new EmailContent { from = _email, to = tomail, cc = ccmail, content = mailContent, subject = subject, hasAttachments = false, attachmentFilePath = "" },
                    Request
                    );
            }
            return Ok(overview);
        }

        [POST("UpdateInnovation")]
        [ActionName("UpdateInnovation")]
        [HttpPost]
        public IHttpActionResult UpdateInnovation(HttpRequestMessage request)
        {
            return Content(HttpStatusCode.Conflict, "Ideas have been migrated to new BVD feature. Please use the new feature to Manage Ideas");
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            PROJECT_INNOVATION results = JsonConvert.DeserializeObject<PROJECT_INNOVATION>(json);
            PROJECT_INNOVATION overview = CSPdb.PROJECT_INNOVATION.GetById(results.ID);
            List<GAVSSERVICE> service = results.GAVS_SERVICE;
            if (results != null && overview != null)
            {
                UpdateLastUpdatedDetails(results.PROJECT_ID, results.UPDATED_BY);
                overview.PROJECT_ID = results.PROJECT_ID;
                overview.RAG = results.RAG;
                overview.IDENTIFIED_DATE = results.IDENTIFIED_DATE.ToLocalTime();
                overview.DESCRIPTION = results.DESCRIPTION;
                overview.STATUS = results.STATUS;
                overview.TARGET_DATE = results.TARGET_DATE.GetValueOrDefault(DateTime.Today).ToLocalTime();
                overview.ACTUAL_DATE = results.ACTUAL_DATE.HasValue ? results.ACTUAL_DATE.Value.ToLocalTime() : (DateTime?)null;
                overview.RESPONSIBLE = results.RESPONSIBLE;
                overview.AREA = results.AREA;
                overview.BEFORE_ERROR = results.BEFORE_ERROR;
                overview.BEFORE_CYCLE_TIME = results.BEFORE_CYCLE_TIME;
                overview.BEFORE_EFFORT = results.BEFORE_EFFORT;
                overview.AFTER_ERROR = results.AFTER_ERROR;
                overview.AFTER_CYCLE_TIME = results.AFTER_CYCLE_TIME;
                overview.AFTER_EFFORT = results.AFTER_EFFORT;
                overview.CUSTOMER_SAVINGS = results.CUSTOMER_SAVINGS;
                overview.FINANCIAL_REVENUE = results.FINANCIAL_REVENUE;
                overview.FINANCIAL_OPERATING_COST = results.FINANCIAL_OPERATING_COST;
                overview.FINANCIAL_PROFITABILITY = results.FINANCIAL_PROFITABILITY;
                overview.REFERENCE_IDEA_ID = results.REFERENCE_IDEA_ID;
                overview.AUTOMATE = results.AUTOMATE;
                overview.TOOL_USED = results.TOOL_USED;
                overview.ISINNOVATION = results.ISINNOVATION;
                overview.INNOVATION_DESCRIPTION = results.INNOVATION_DESCRIPTION;
                overview.ISPROCESSIMPROVEMENT = results.ISPROCESSIMPROVEMENT;
                overview.PROCESS_IMPROVEMENT_DESCRIPTION = results.PROCESS_IMPROVEMENT_DESCRIPTION;
                overview.COMMENTS = results.COMMENTS;
                overview.APPROACH = results.APPROACH;
                overview.BEFORE_CASES_COUNT = results.BEFORE_CASES_COUNT;
                overview.AFTER_CASES_COUNT = results.AFTER_CASES_COUNT;
                overview.BEFORE_FTECOST_HOUR = results.BEFORE_FTECOST_HOUR;
                overview.AFTER_FTECOST_HOUR = results.AFTER_FTECOST_HOUR;
                overview.BEFORE_FTECOST_MONTH = results.BEFORE_FTECOST_MONTH;
                overview.AFTER_FTECOST_MONTH = results.AFTER_FTECOST_MONTH;
                overview.CUSTOMER_PERSONHOUR_SAVINGS = results.CUSTOMER_PERSONHOUR_SAVINGS;
                overview.BEFORE_FTESPENT_MONTH = results.BEFORE_FTESPENT_MONTH;
                overview.AFTER_FTESPENT_MONTH = results.AFTER_FTESPENT_MONTH;
                overview.BEFORE_LEAD_TIME = results.BEFORE_LEAD_TIME;
                overview.AFTER_LEAD_TIME = results.AFTER_LEAD_TIME;
                overview.BEFORE_COST = results.BEFORE_COST;
                overview.AFTER_COST = results.AFTER_COST;
                overview.CUSTOMER_BUSINESS_VALUE = results.CUSTOMER_BUSINESS_VALUE;
                overview.BEFORE_OCCOURANCE_COUNT = results.BEFORE_OCCOURANCE_COUNT;
                overview.AFTER_OCCOURANCE_COUNT = results.AFTER_OCCOURANCE_COUNT;
                overview.INTERNAL_SAVINGS = results.INTERNAL_SAVINGS;

                overview.IS_ONETIME = results.IS_ONETIME;
                overview.BEFORE_CYCLE_TIME_UOM = results.BEFORE_CYCLE_TIME_UOM;
                overview.AFTER_CYCLE_TIME_UOM = results.AFTER_CYCLE_TIME_UOM;
                overview.BEFORE_LEAD_TIME_UOM = results.BEFORE_LEAD_TIME_UOM;
                overview.AFTER_LEAD_TIME_UOM = results.AFTER_LEAD_TIME_UOM;
                overview.BEFORE_TIME_TAKEN = results.BEFORE_TIME_TAKEN;
                overview.AFTER_TIME_TAKEN = results.AFTER_TIME_TAKEN;
                overview.BEFORE_TIME_TAKEN_UOM = results.BEFORE_TIME_TAKEN_UOM;
                overview.AFTER_TIME_TAKEN_UOM = results.AFTER_TIME_TAKEN_UOM;

                overview.UPDATED_BY = results.UPDATED_BY;
                overview.UPDATED_DATE = DateTime.Now;
                overview.ISACTIVE = true;
                CSPdb.PROJECT_INNOVATION.Update(overview);
                CSPdb.Commit(CanCommit);
                overview.GAVS_SERVICE = service;
                DeleteInnovationMapping(overview);
                AddGavsService(overview, service);

            }

            if (overview.STATUS.ToLower() == "completed")
                SendMailOnInnovationCompleted(overview);

            return Ok(overview);
        }

        private void SendMailOnInnovationCompleted(PROJECT_INNOVATION overview)
        {

            var project = Cldb.PROJECT.GetAll().FirstOrDefault(x => x.PROJ_ID == overview.PROJECT_ID);

            if (project == null)
                return;

            //splitting to email address

            string csmMails = helper.GetCSMMailsFromProject(project);
            string pmMails = helper.GetPMMailsFromProject(project);
            string subject = string.Empty;
            string statusMsg = string.Empty;
            string mailContent;

            //string tomail = pmMails;
            string ccmail = helper.GetDBConfig("CSS_LINK_CC", "-1");
            var qualitySpoc = helper.GetQualitySpocMailForProject(project);


            string customerName = string.Empty;
            string projectName = string.Empty;

            var customer = Cldb.CUSTOMER.GetAll().FirstOrDefault(t => t.CUST_ID == project.CUST_ID);
            customerName = customer?.CUST_NM;
            projectName = project.PROJ_NM;

            subject = $"Idea / Improvement / Innovation Completed - Project: {projectName}; Customer: {customerName}";
            string ideasUrl = $"{helper.GetAbsoulteUri()}/layout/ideas/" + customer.CUST_ID + "/" + overview.ID;
            //string ideasUrl = "http://localhost:4201/layout/ideas/" + customer.CUST_ID + "/" + overview.ID; 

            string tomail = helper.GetCustomerContactMailsFromProject(project);
            ccmail = helper.ConcatEmails(new List<string>() { pmMails, csmMails, qualitySpoc, Constants.QUALITY_HEAD });
            Dictionary<string, string> EmailContentValues = new Dictionary<string, string>();
            EmailContentValues.Add("Project Name", projectName);
            EmailContentValues.Add("Ideas URL", ideasUrl);

            EmailContentValues.Add("Identified Date", overview.IDENTIFIED_DATE.ToLocalTime().ToString(_dateformat));
            EmailContentValues.Add("Process Area", overview.AREA);
            EmailContentValues.Add("Description", overview.DESCRIPTION);
            EmailContentValues.Add("Status", overview.STATUS);
            EmailContentValues.Add("Target Date", !overview.TARGET_DATE.HasValue ? "NA" : overview.TARGET_DATE.GetValueOrDefault().ToLocalTime().ToString(_dateformat));
            EmailContentValues.Add("Actual Date", !overview.ACTUAL_DATE.HasValue ? "NA" : overview.ACTUAL_DATE.GetValueOrDefault().ToLocalTime().ToString(_dateformat));
            EmailContentValues.Add("Responsible", string.IsNullOrWhiteSpace(overview.RESPONSIBLE) ? "NA" : overview.RESPONSIBLE);
            EmailContentValues.Add("Current State-Error", !overview.BEFORE_ERROR.HasValue ? "NA" : overview.BEFORE_ERROR.ToString());
            EmailContentValues.Add("Current State-Cycle Time in Minutes", !overview.BEFORE_CYCLE_TIME.HasValue ? "NA" : overview.BEFORE_CYCLE_TIME.ToString());
            EmailContentValues.Add("Current State-Effort Per Month in Minutes", !overview.BEFORE_EFFORT.HasValue ? "NA" : overview.BEFORE_EFFORT.ToString());
            EmailContentValues.Add("Future State-Error", !overview.AFTER_ERROR.HasValue ? "NA" : overview.AFTER_ERROR.ToString());
            EmailContentValues.Add("Future State-Cycle Time in Minutes", !overview.AFTER_CYCLE_TIME.HasValue ? "NA" : overview.AFTER_CYCLE_TIME.ToString());
            EmailContentValues.Add("Future State-Effort Per Month in Minutes", !overview.AFTER_ERROR.HasValue ? "NA" : overview.AFTER_ERROR.ToString());
            EmailContentValues.Add("Savings in USD Per Year", !overview.CUSTOMER_SAVINGS.HasValue ? "-" : overview.CUSTOMER_SAVINGS.ToString());
            EmailContentValues.Add("Revenue", !overview.FINANCIAL_REVENUE.HasValue ? "NA" : overview.FINANCIAL_REVENUE.ToString());
            EmailContentValues.Add("Operating Cost", !overview.FINANCIAL_OPERATING_COST.HasValue ? "NA" : overview.FINANCIAL_OPERATING_COST.ToString());
            EmailContentValues.Add("Profitability", !overview.FINANCIAL_PROFITABILITY.HasValue ? "NA" : overview.FINANCIAL_PROFITABILITY.ToString());
            EmailContentValues.Add("Can this be Automated?", overview.AUTOMATE ? YES : NO);
            EmailContentValues.Add("Automation Description/Tool Proposed/Used", string.IsNullOrWhiteSpace(overview.TOOL_USED) ? "NA" : overview.TOOL_USED);
            EmailContentValues.Add("Is this an innovation?", overview.ISINNOVATION ? YES : NO);
            EmailContentValues.Add("Innovation Description", string.IsNullOrWhiteSpace(overview.INNOVATION_DESCRIPTION) ? "NA" : overview.INNOVATION_DESCRIPTION);
            EmailContentValues.Add("Is this a Process Improvement", overview.ISPROCESSIMPROVEMENT ? YES : NO);
            EmailContentValues.Add("Process Improvement Description", string.IsNullOrWhiteSpace(overview.PROCESS_IMPROVEMENT_DESCRIPTION) ? "NA" : overview.PROCESS_IMPROVEMENT_DESCRIPTION);


            foreach (GAVSSERVICE sr in overview.GAVS_SERVICE)
            {

                switch (sr.SERVICE_ID)
                {
                    case 1:
                        EmailContentValues.Add("Gavel", sr.IS_CHECKED ? YES : NO);
                        break;
                    case 2:
                        EmailContentValues.Add("GCare", sr.IS_CHECKED ? YES : NO);
                        break;
                    case 3:
                        EmailContentValues.Add("ZDesk", sr.IS_CHECKED ? YES : NO);
                        break;
                    case 4:
                        EmailContentValues.Add("Zlrrus", sr.IS_CHECKED ? YES : NO);
                        break;
                    case 5:
                        EmailContentValues.Add("ZMan", sr.IS_CHECKED ? YES : NO);
                        break;
                }
            }

            EmailContentValues.Add("Comments", string.IsNullOrWhiteSpace(overview.COMMENTS) ? "NA" : overview.COMMENTS);


            mailContent = helper.GetEmailContent("InnovationCompleted.htm", EmailContentValues);
            var ep = new EmailProvider(Cldb, CSPdb);
            if (string.IsNullOrWhiteSpace(tomail)) tomail = _email;
            ep.SendEmail
                (
                new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                new EmailContent { from = _email, to = tomail, cc = ccmail, content = mailContent, subject = subject, hasAttachments = false, attachmentFilePath = "", ProjId = overview.PROJECT_ID },
                Request
                );

        }
        private void DeleteInnovationMapping(PROJECT_INNOVATION overview)
        {
            List<INNOVATION_SERVICE_MAPPING> innovationmapList = new List<INNOVATION_SERVICE_MAPPING>();
            innovationmapList = CSPdb.INNOVATION_SERVICE_MAPPING.GetAll().Where(t => t.INNOVATION_ID == overview.ID).ToList<INNOVATION_SERVICE_MAPPING>();
            foreach (INNOVATION_SERVICE_MAPPING list in innovationmapList)
            {
                list.ISACTIVE = false;
                CSPdb.INNOVATION_SERVICE_MAPPING.Update(list);
                CSPdb.Commit(CanCommit);
            }
        }


        private bool IsContactAlreadyExisting(string emailId, string custId, int id)
        {
            var existing = CSPdb.CONTACTS.GetAll().Count(x => x.CONTACT_EMAILID == emailId.Trim() && x.CUSTOMER_ID == custId && x.ID != id && x.ISACTIVE);
            return existing > 0;
        }

