        [POST("UpdateScope")]
        [ActionName("UpdateScope")]
        [HttpPost]
        public IHttpActionResult UpdateScope(HttpRequestMessage request)
        {
            var content = request.Content.ReadAsStringAsync().Result;
            var results = JsonConvert.DeserializeObject<PROJECT_SCOPES>(content);
            var projectId = results.PROJECT_SCOPE.PROJECT_ID;
            //Update In-Scope    

            var inscopeList = Cldb.PROJECT_INSCOPE_DETAILS.GetAll().Where(t => t.PROJECT_ID == projectId && t.ISACTIVE).ToList();
            foreach (var res in inscopeList)
            {
                res.ISACTIVE = false;
            }
            foreach (var result in results.PROJECT_INSCOPE_DETAILS)
            {
                var item = inscopeList.FirstOrDefault(t => t.ID == result.ID);
                if (item != null)
                {
                    item.SERVICE_AREA_ID = result.SERVICE_AREA_ID;
                    item.TOOLS = result.TOOLS;
                    item.TECHNOLOGY = result.TECHNOLOGY;
                    //item.CUST_ID = result.CUST_ID;
                    UpdateAuditFields(item);
                    Cldb.PROJECT_INSCOPE_DETAILS.Update(item);
                }
                else
                {
                    var newEntity = new PROJECT_INSCOPE_DETAILS()
                    {

                        SERVICE_AREA_ID = result.SERVICE_AREA_ID,
                        TOOLS = result.TOOLS,
                        TECHNOLOGY = result.TECHNOLOGY,
                        PROJECT_ID = result.PROJECT_ID,
                        // CUST_ID = result.CUST_ID
                    };
                    UpdateAuditFields(newEntity);
                    Cldb.PROJECT_INSCOPE_DETAILS.Add(newEntity);
                }
            }

            Cldb.Commit(CanCommit);
            //Update Project Scope
            var overview = CSPdb.PROJECT_SCOPE.GetAll().FirstOrDefault(t => t.PROJECT_ID == projectId && t.ISACTIVE);
            if (overview != null && results.PROJECT_SCOPE != null)
            {
                overview.RAG = results.PROJECT_SCOPE.RAG;
                overview.DESCRIPTION = results.PROJECT_SCOPE.DESCRIPTION;
                overview.TECHNOLOGY_USED = results.PROJECT_SCOPE.TECHNOLOGY_USED;
                overview.SCOPE = results.PROJECT_SCOPE.SCOPE;
                overview.OBJECTIVES = results.PROJECT_SCOPE.OBJECTIVES;
                overview.DELIVERABLES = results.PROJECT_SCOPE.DELIVERABLES;
                overview.CONSTRAINTS = results.PROJECT_SCOPE.CONSTRAINTS;
                overview.ASSUMPTIONS = results.PROJECT_SCOPE.ASSUMPTIONS;
                overview.OUT_SCOPE = results.PROJECT_SCOPE.OUT_SCOPE;
                UpdateAuditFields(overview);
                CSPdb.PROJECT_SCOPE.Update(overview);

            }
            else
            {
                var newRec = new PROJECT_SCOPE();
                newRec.PROJECT_ID = results.PROJECT_SCOPE.PROJECT_ID;
                newRec.RAG = results.PROJECT_SCOPE.RAG;
                newRec.DESCRIPTION = results.PROJECT_SCOPE.DESCRIPTION;
                newRec.TECHNOLOGY_USED = results.PROJECT_SCOPE.TECHNOLOGY_USED;
                newRec.SCOPE = results.PROJECT_SCOPE.SCOPE;
                newRec.OBJECTIVES = results.PROJECT_SCOPE.OBJECTIVES;
                newRec.DELIVERABLES = results.PROJECT_SCOPE.DELIVERABLES;
                newRec.CONSTRAINTS = results.PROJECT_SCOPE.CONSTRAINTS;
                newRec.ASSUMPTIONS = results.PROJECT_SCOPE.ASSUMPTIONS;
                newRec.OUT_SCOPE = results.PROJECT_SCOPE.OUT_SCOPE;
                UpdateAuditFields(newRec);
                CSPdb.PROJECT_SCOPE.Add(newRec);

            }

            CSPdb.Commit(CanCommit);
            return Ok();
        }


        [POST("DeleteInScope")]
        [ActionName("DeleteInScope")]
        [HttpPost]
        public IHttpActionResult DeleteInScope(HttpRequestMessage request)
        {
            var content = request.Content.ReadAsStringAsync().Result;
            var results = JsonConvert.DeserializeObject<PROJECT_INSCOPE_DETAILS>(content);
            string empId = GetHeaderDetails_String("empid");

            if (results != null)
            {
                ValidateServiceAreaDeletion(results.PROJECT_ID, results.SERVICE_AREA_ID);
                var row = Cldb.PROJECT_INSCOPE_DETAILS.GetAll().FirstOrDefault(t => t.ID == results.ID && t.ISACTIVE);
                if (row != null)
                {
                    var inscopeDetail = row;
                    inscopeDetail.ISACTIVE = false;
                    Cldb.PROJECT_INSCOPE_DETAILS.Update(inscopeDetail);
                    Cldb.Commit(CanCommit);
                }
            }
            return Ok();
        }
        private void ValidateServiceAreaDeletion(string projId, int serviceId)
        {
            var checkpoints = CSPdb.AppRepo.GetSubmitedAssessmentsForCustomerandProject("", projId, serviceId);
            var serviceAreaTitle = CSPdb.PROCESS_SERVICE_AREA_NEW.GetAll().Where(x => x.ID == serviceId && x.ISACTIVE).Select(x => x.TITLE).FirstOrDefault().ToString();
            var opMsg = CheckIfServiceTowerMappedToKpi(serviceId, projId);
            if (!string.IsNullOrEmpty(opMsg))
                throw new HttpResponseException(this.Request.CreateResponse(System.Net.HttpStatusCode.BadRequest, opMsg));

            if (checkpoints.Any())
            {
                throw new HttpResponseException(this.Request.CreateResponse(System.Net.HttpStatusCode.BadRequest, $"This Service Tower ({serviceAreaTitle}) is used in Assessment that has been submitted to appraisee, so it cannot be deleted."));
            }

            var assessmentIds = CSPdb.AUDIT_CHECKLIST_EXECUTION_SUMMARY.GetAll().Where(x => x.PROJECT_ID == projId && x.ISACTIVE).Select(x => x.ASSESSMENT_ID).ToList();
            var serviceAreaHaveFindings = CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.GetAll().Where(x => assessmentIds.Contains(x.AUDIT_ID) && x.SERVICE_AREA_ID == serviceId && x.ISACTIVE).Select(x => x.FINDING_TYPE).ToList();
            if (serviceAreaHaveFindings.Any())
            {
                string findingsType = string.Join(",", serviceAreaHaveFindings);
                throw new HttpResponseException(this.Request.CreateResponse(System.Net.HttpStatusCode.BadRequest, $"This Service Tower ({serviceAreaTitle}) has finding in like {findingsType} . Please take appropriate action for the finding before proceeding further."));
            }
        }

        [POST("UpdateDelivery")]
