            dynamic json = jsonContent;

            PROJECT_DELIVERY results = JsonConvert.DeserializeObject<PROJECT_DELIVERY>(json);

            DateRange wdays = new DateRange(results.PUBLISH_DATE, enDateRange.Weekly);
            PROJECT_DELIVERY overview = CSPdb.PROJECT_DELIVERY.GetAll().Where(t => t.PROJECT_ID == results.PROJECT_ID && t.PUBLISH_DATE >= wdays.StartDate && t.PUBLISH_DATE <= wdays.EndDate).FirstOrDefault<PROJECT_DELIVERY>();

            if (overview != null && results != null)
            {
                overview.RAG = results.RAG;
                overview.LASTWEEK_ACHIEVED = results.LASTWEEK_ACHIEVED;
