                overview.UPDATED_DATE = DateTime.Now;
                CSPdb.PROJECT_DELIVERY.Update(overview);
                CSPdb.Commit(CanCommit);
                UpdateRag(results.PROJECT_ID, ragCategory.delivery, results.RAG, results.UPDATED_BY);
                UpdateLastUpdatedDetails(results.PROJECT_ID, results.UPDATED_BY);
            }
            else
            {
                PROJECT_DELIVERY newRec = new PROJECT_DELIVERY();
                newRec.PROJECT_ID = results.PROJECT_ID;
                newRec.RAG = results.RAG;
                newRec.LASTWEEK_ACHIEVED = results.LASTWEEK_ACHIEVED;
                newRec.NEXTWEEK_MILESTONE = results.NEXTWEEK_MILESTONE;
