                newRec.RAG = results.RAG;
                newRec.RESOURCE_CHALLENGES = results.RESOURCE_CHALLENGES;
                if (results.CREATED_BY != null)
                {
                    newRec.CREATED_BY = results.CREATED_BY;
                    newRec.CREATED_DATE = DateTime.Now;
                }
                else
                {
                    newRec.CREATED_BY = results.UPDATED_BY;
                    newRec.CREATED_DATE = DateTime.Now;
                }
                newRec.UPDATED_BY = results.UPDATED_BY;
                newRec.UPDATED_DATE = DateTime.Now;
                newRec.ISACTIVE = true;
                CSPdb.PROJECT_PEOPLE.Add(newRec);
                CSPdb.Commit(CanCommit);
                UpdateRag(projid, ragCategory.people, results.RAG, results.UPDATED_BY);
                UpdateLastUpdatedDetails(projid, results.UPDATED_BY);
            }
            return Ok();
        }

