        [POST("UpdateRisk")]
        [ActionName("UpdateRisk")]
        [HttpPost]
        public IHttpActionResult UpdateRisk(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            PROJECT_RISK results = JsonConvert.DeserializeObject<PROJECT_RISK>(json);

            var overview = new PROJECT_RISK();
            var newRiskItem = new PROJECT_RISK();

            overview = CSPdb.PROJECT_RISK.GetAll().FirstOrDefault(t => t.PROJECT_ID == results.PROJECT_ID && t.ID == results.ID);

            if (overview != null && results != null)
            {
                newRiskItem.DESCRIPTION = overview.DESCRIPTION;
                newRiskItem.IMPACT = overview.IMPACT;
                newRiskItem.PROBABILITY_SCALE = overview.PROBABILITY_SCALE;
                newRiskItem.IMPACT_SCALE = overview.IMPACT_SCALE;
                newRiskItem.OWNER = overview.OWNER;
                newRiskItem.AREA = overview.AREA;
                newRiskItem.IDENTIFIED_BY = overview.IDENTIFIED_BY;
                newRiskItem.IDENTIFIED_DATE = overview.IDENTIFIED_DATE;
                newRiskItem.RISK_TREATMENT_STRATEGY = overview.RISK_TREATMENT_STRATEGY;
                newRiskItem.ACTUAL_DATE = overview.ACTUAL_DATE;
                newRiskItem.STATUS = overview.STATUS;
                newRiskItem.ACTION_TAKEN = overview.ACTION_TAKEN;
                newRiskItem.UPDATED_BY = overview.UPDATED_BY;
                newRiskItem.UPDATED_DATE = DateTime.Now;
                newRiskItem.ACCEPT_TILL = overview.ACCEPT_TILL.HasValue ? overview.ACCEPT_TILL.Value.ToLocalTime() : (DateTime?)null;
                newRiskItem.IS_DRAFT = overview.IS_DRAFT;
                newRiskItem.RISK_RATING = overview.PROBABILITY_SCALE * overview.IMPACT_SCALE;
                newRiskItem.RISK_CATEGORY = overview.RISK_CATEGORY;
                newRiskItem.LOCATION = overview.LOCATION;
                newRiskItem.RISK_LEVEL = overview.RISK_LEVEL;
                newRiskItem.NEW_CONSEQUENCES_SCALE = overview.NEW_CONSEQUENCES_SCALE;
                newRiskItem.NEW_LIKELIHOOD_SCALE = overview.NEW_LIKELIHOOD_SCALE;
                newRiskItem.NEW_RISK_RATING = overview.NEW_LIKELIHOOD_SCALE * overview.NEW_CONSEQUENCES_SCALE;
                newRiskItem.NEW_RISK_LEVEL = overview.NEW_RISK_LEVEL;
                newRiskItem.NEW_RISK_ASSESSMENT_DATE = overview.NEW_RISK_ASSESSMENT_DATE;
                newRiskItem.RISK_TREATMENT_EFFECTIVENESS_STATUS = overview.RISK_TREATMENT_EFFECTIVENESS_STATUS;
                newRiskItem.RISK_TREATMENT_EFFECTIVENESS_VERIFIED_BY = overview.RISK_TREATMENT_EFFECTIVENESS_VERIFIED_BY;
                newRiskItem.RISK_TREATMENT_EFFECTIVENESS_VERIFIED_DATE = overview.RISK_TREATMENT_EFFECTIVENESS_VERIFIED_DATE;

                overview.DESCRIPTION = results.DESCRIPTION;
                overview.IMPACT = results.IMPACT;
                overview.PROBABILITY_SCALE = results.PROBABILITY_SCALE;
                overview.IMPACT_SCALE = results.IMPACT_SCALE;
                overview.OWNER = results.OWNER;
                overview.AREA = results.AREA;
                overview.IDENTIFIED_BY = results.IDENTIFIED_BY;
                overview.IDENTIFIED_DATE = results.IDENTIFIED_DATE;
                overview.RISK_TREATMENT_STRATEGY = results.RISK_TREATMENT_STRATEGY;
                overview.ACTUAL_DATE = results.ACTUAL_DATE;
                overview.STATUS = results.STATUS;
                overview.ACTION_TAKEN = results.ACTION_TAKEN;
                overview.UPDATED_BY = results.UPDATED_BY;
                overview.UPDATED_DATE = DateTime.Now;
                overview.ACCEPT_TILL = results.ACCEPT_TILL.HasValue ? results.ACCEPT_TILL.Value.ToLocalTime() : (DateTime?)null;
                overview.IS_DRAFT = results.IS_DRAFT;
                overview.RISK_RATING = results.PROBABILITY_SCALE * results.IMPACT_SCALE;
                overview.RISK_CATEGORY = results.RISK_CATEGORY;
                overview.LOCATION = results.LOCATION;
                overview.RISK_LEVEL = results.RISK_LEVEL;
                overview.NEW_CONSEQUENCES_SCALE = results.NEW_CONSEQUENCES_SCALE;
                overview.NEW_LIKELIHOOD_SCALE = results.NEW_LIKELIHOOD_SCALE;
                overview.NEW_RISK_RATING = results.NEW_LIKELIHOOD_SCALE * results.NEW_CONSEQUENCES_SCALE;
                overview.NEW_RISK_LEVEL = results.NEW_RISK_LEVEL;
                overview.NEW_RISK_ASSESSMENT_DATE = results.NEW_RISK_ASSESSMENT_DATE;
                overview.RISK_TREATMENT_EFFECTIVENESS_STATUS = results.RISK_TREATMENT_EFFECTIVENESS_STATUS;
                overview.RISK_TREATMENT_EFFECTIVENESS_VERIFIED_BY = results.RISK_TREATMENT_EFFECTIVENESS_VERIFIED_BY;
                overview.RISK_TREATMENT_EFFECTIVENESS_VERIFIED_DATE = results.RISK_TREATMENT_EFFECTIVENESS_VERIFIED_DATE;
                CSPdb.PROJECT_RISK.Update(overview);


                if (results.ID > 0)
                {
                    var existingRisk = Cldb.RISK_ISO_STANDARD_MAPPING.GetAll().Where(x => x.RISK_ID == results.ID && x.ISACTIVE).ToList();
                    foreach (var item in existingRisk)
                    {
                        item.ISACTIVE = false;
                    }
                    foreach (var item in results.ISO_STD_ID)
                    {
                        var existing = existingRisk.FirstOrDefault(x => x.ISO_STANDARD_ID == item);
                        if (existing != null)
                        {
                            UpdateAuditFields(existing);
                        }
                        else
                        {
                            AddIsoStdRisk(item, results.ID);

                        }
                    }
                    foreach (var item in existingRisk)
                    {
                        Cldb.RISK_ISO_STANDARD_MAPPING.Update(item);
                    }
                }


                var actionItem = CSPdb.PROJECT_ACTIONITEM.GetAll().FirstOrDefault(t => t.RISK_ID == results.ID && t.ISACTIVE);
                if (actionItem != null)
                {
                    actionItem.DESCRIPTION = results.ACTION_ITEM_DESCRIPTION;
                    actionItem.OWNER = results.ACTION_ITEM_OWNER;
                    actionItem.IDENTIFIED_DATE = (DateTime)results.ACTION_ITEM_IDENTIFIED_DATE;
                    actionItem.TARGET_DATE = results.ACTION_ITEM_TARGET_DATE;
                    actionItem.STATUS = results.ACTION_ITEM_STATUS;
                    actionItem.COMMENTS = results.ACTION_ITEM_COMMENTS;
                    actionItem.UPDATED_BY = results.CREATED_BY;
                    actionItem.UPDATED_DATE = DateTime.Now;
                    actionItem.ISACTIVE = true;
                    actionItem.RISK_ID = overview.ID;
                    CSPdb.PROJECT_ACTIONITEM.Update(actionItem);

                    if (actionItem.RISK_ID != null)
                    {
                        var risk = CSPdb.PROJECT_RISK.GetAll().FirstOrDefault(x => x.ID == actionItem.RISK_ID);
                        if (risk != null)
                        {
                            var actionItems = CSPdb.PROJECT_ACTIONITEM.GetAll().Where(x => x.RISK_ID == risk.ID && x.ISACTIVE).ToList();
                            if (actionItems.Any())
                                risk.TARGET_DATE = actionItems.Max(x => x.TARGET_DATE);
                        }
                    }
                    UpdateLastUpdatedDetails(results.PROJECT_ID, results.UPDATED_BY);
                }
                Cldb.Commit(CanCommit);
                CSPdb.Commit(CanCommit);
                UpdateLastUpdatedDetails(results.PROJECT_ID, results.UPDATED_BY);

                var project = Cldb.PROJECT.GetAll().FirstOrDefault(x => x.PROJ_ID == results.PROJECT_ID);
                Tuple<string, string>[] FieldNameWithCaptionList = new Tuple<string, string>[]{

                    Tuple.Create("RISK DESCRIPTION", "DESCRIPTION"),
                    Tuple.Create("BUSINESS IMPACT", "IMPACT"),
                    Tuple.Create("RISK OWNER", "OWNER"),
                    Tuple.Create("STATUS", "STATUS"),
                    Tuple.Create("IDENTIFIED ON", "IDENTIFIED_DATE"),
                    Tuple.Create("IDENTIFIED BY", "IDENTIFIED_BY"),
                    Tuple.Create("RISK TREATMENT PLAN", "ACTION_TAKEN"),
                    Tuple.Create("ACTUAL DATE", "ACTUAL_DATE"),
                    //Tuple.Create("NEW RISK ASSESSMENT DATE", "NEW_RISK_ASSESSMENT_DATE"),
                    //Tuple.Create("RISK TREATMENT EFFECTIVENESS STATUS", "RISK_TREATMENT_EFFECTIVENESS_STATUS"),
                    //Tuple.Create("RISK TREATMENT EFFECTIVENESS VERIFIED BY", "RISK_TREATMENT_EFFECTIVENESS_VERIFIED_BY"),
                    //Tuple.Create("RISK TREATMENT EFFECTIVENESS VERIFIED DATE", "RISK_TREATMENT_EFFECTIVENESS_VERIFIED_DATE"),
                    Tuple.Create("UPDATED DATE", "UPDATED_DATE"),
                    Tuple.Create("UPDATED BY", "UPDATED_BY")
                    };
                SendUpdateMail<PROJECT_RISK>(newRiskItem, overview, project, FieldNameWithCaptionList, "Risk Updated for " + project.PROJ_NM);

            }
            return Ok();

        }



