        [POST("UpdateKPIGoal")]
        [ActionName("UpdateKPIGoal")]
        [HttpPost]
        public IHttpActionResult UpdateKPIGoal(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            KPI_GOALS results = JsonConvert.DeserializeObject<KPI_GOALS>(json);
            KPI_GOALS overview = CSPdb.KPI_GOALS.GetById(results.ID);
            //check if goal already exists
            var isGoalExist = CSPdb.KPI_GOALS.GetAll().Any(t => t.CUSTOMER_ID == results.CUSTOMER_ID && t.PROJECT_ID == results.PROJECT_ID && t.ISACTIVE && t.DESCRIPTION.ToLower() == results.DESCRIPTION.ToLower() && t.ID != results.ID);
            if (isGoalExist)
            {
                return Content(HttpStatusCode.Conflict, "KPI Goal already exists");
            }
            if (overview != null && results != null)
            {
                overview.DESCRIPTION = results.DESCRIPTION;
                overview.START_DATE = results.START_DATE;
                overview.END_DATE = results.END_DATE;
                overview.DISPLAY_ORDER = results.DISPLAY_ORDER;
                overview.UPDATED_BY = results.UPDATED_BY;
                overview.UPDATED_DATE = DateTime.Now;
                CSPdb.KPI_GOALS.Update(overview);
                CSPdb.Commit(CanCommit);
            }

            return Ok();
        }

        [POST("UpdateKPI")]
        [ActionName("UpdateKPI")]
        [HttpPost]
        public IHttpActionResult UpdateKPI(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            KPIWithTargets results = JsonConvert.DeserializeObject<KPIWithTargets>(json);
            var opMsg = CheckIfKpiIdentifierExists(results.KPI_UNIQUEID, results.ID, results.CUSTOMER_ID);
            if (!string.IsNullOrEmpty(opMsg))
                return Content(HttpStatusCode.Conflict, opMsg);
            KPI overview = CSPdb.KPI.GetById(results.ID);
            if (overview != null && results != null)
            {
                overview.SERVICE_AREA = results.SERVICE_AREA;
                overview.ABBREVIATION = results.ABBREVIATION;
                overview.KPI_NAME = results.KPI_NAME;
                overview.KPI_UNIQUEID = results.KPI_UNIQUEID;
                overview.SUPPORT_WINDOW = results.SUPPORT_WINDOW;
                overview.FREQUENCY = results.FREQUENCY;
                overview.PRIORITY = results.PRIORITY;
                overview.SLA_TARGET_UNIT_OF_MEASUREMENT = results.SLA_TARGET_UNIT_OF_MEASUREMENT;
                overview.DISPLAY_ORDER = results.DISPLAY_ORDER;
                overview.CHART_TYPE = results.CHART_TYPE;
                overview.SHOW_IN_CHART = results.SHOW_IN_CHART;
                overview.GLOBAL_KPI_CATEGORY_ID = results.GLOBAL_KPI_CATEGORY_ID;
                overview.IS_SOW_COMMITMENT = results.IS_SOW_COMMITMENT;
                overview.KPI_MASTER_ID = results.KPI_MASTER_ID;
                overview.UPDATED_BY = results.UPDATED_BY;
                overview.UPDATED_DATE = DateTime.Now;
                CSPdb.KPI.Update(overview);
                CSPdb.Commit(CanCommit);

                var kpiBaseMeasure = new SERVICE_LEVEL_MEASUREMENT_2_BASE_MEASURE_CONFIG();
                var exist = CSPdb.SERVICE_LEVEL_MEASUREMENT_2_BASE_MEASURE_CONFIG.GetAll().FirstOrDefault(x => x.KPI_ID == overview.ID && x.ISACTIVE);
                var baseMeasure = Cldb.KPI_MASTER2BASE_MEASURE_CONFIG.GetAll().FirstOrDefault(x => x.KPI_MASTER_ID == overview.KPI_MASTER_ID && x.ISACTIVE);
                if (exist != null)
                {
                    exist.BASE_MEASURE_ID = baseMeasure.BASE_MEASURE_ID;
                    exist.MASTER_ID = overview.KPI_MASTER_ID;
                    UpdateAuditFields(exist);
                    CSPdb.SERVICE_LEVEL_MEASUREMENT_2_BASE_MEASURE_CONFIG.Update(exist);
                }
                else
                {
                    kpiBaseMeasure.KPI_ID = overview.ID;
                    kpiBaseMeasure.BASE_MEASURE_ID = baseMeasure.BASE_MEASURE_ID;
                    kpiBaseMeasure.MASTER_ID = overview.KPI_MASTER_ID;
                    UpdateAuditFields(kpiBaseMeasure);
                    CSPdb.SERVICE_LEVEL_MEASUREMENT_2_BASE_MEASURE_CONFIG.Add(kpiBaseMeasure);
                }

                foreach (KPI_TARGETS t in results.KPI_TARGETS)
                {
                    if (t.ID == 0)
                    {
                        KPI_TARGETS target = new KPI_TARGETS();
                        target.KPI_ID = t.KPI_ID;
                        target.START_DATE = t.START_DATE.ToLocalTime();
                        target.END_DATE = t.END_DATE.ToLocalTime();
                        target.SLA_TARGET_HIGH_DESCRIPTION = t.SLA_TARGET_HIGH_DESCRIPTION;
                        target.SLA_TARGET_HIGH_OPERATOR = t.SLA_TARGET_HIGH_OPERATOR;
                        target.SLA_TARGET_HIGH_VALUE = t.SLA_TARGET_HIGH_VALUE;
                        target.SLA_TARGET_LOW_DESCRIPTION = t.SLA_TARGET_LOW_DESCRIPTION;
                        target.SLA_TARGET_LOW_OPERATOR = t.SLA_TARGET_LOW_OPERATOR;
                        target.SLA_TARGET_LOW_VALUE = t.SLA_TARGET_LOW_VALUE;
                        target.SLA_TARGET_MEDIUM_DESCRIPTION = t.SLA_TARGET_MEDIUM_DESCRIPTION;
                        target.SLA_TARGET_MEDIUM_OPERATOR = t.SLA_TARGET_MEDIUM_OPERATOR;
                        target.SLA_TARGET_MEDIUM_VALUE = t.SLA_TARGET_MEDIUM_VALUE;
                        target.SLA_TARGET_VERYHIGH_DESCRIPTION = t.SLA_TARGET_VERYHIGH_DESCRIPTION;
                        target.SLA_TARGET_VERYHIGH_OPERATOR = t.SLA_TARGET_VERYHIGH_OPERATOR;
                        target.SLA_TARGET_VERYHIGH_VALUE = t.SLA_TARGET_VERYHIGH_VALUE;
                        target.CREATED_BY = overview.CREATED_BY;
                        target.CREATED_DATE = DateTime.Now;
                        target.UPDATED_BY = overview.UPDATED_BY;
                        target.UPDATED_DATE = DateTime.Now;
                        target.ISACTIVE = true;
                        CSPdb.KPI_TARGETS.Add(target);
                    }
                    else
                    {
                        KPI_TARGETS target = CSPdb.KPI_TARGETS.GetById(t.ID);
                        if (target != null)
                        {
                            target.START_DATE = t.START_DATE.ToLocalTime();
                            target.END_DATE = t.END_DATE.ToLocalTime();
                            target.SLA_TARGET_HIGH_DESCRIPTION = t.SLA_TARGET_HIGH_DESCRIPTION;
                            target.SLA_TARGET_HIGH_OPERATOR = t.SLA_TARGET_HIGH_OPERATOR;
                            target.SLA_TARGET_HIGH_VALUE = t.SLA_TARGET_HIGH_VALUE;
                            target.SLA_TARGET_LOW_DESCRIPTION = t.SLA_TARGET_LOW_DESCRIPTION;
                            target.SLA_TARGET_LOW_OPERATOR = t.SLA_TARGET_LOW_OPERATOR;
                            target.SLA_TARGET_LOW_VALUE = t.SLA_TARGET_LOW_VALUE;
                            target.SLA_TARGET_MEDIUM_DESCRIPTION = t.SLA_TARGET_MEDIUM_DESCRIPTION;
                            target.SLA_TARGET_MEDIUM_OPERATOR = t.SLA_TARGET_MEDIUM_OPERATOR;
                            target.SLA_TARGET_MEDIUM_VALUE = t.SLA_TARGET_MEDIUM_VALUE;
                            target.SLA_TARGET_VERYHIGH_DESCRIPTION = t.SLA_TARGET_VERYHIGH_DESCRIPTION;
                            target.SLA_TARGET_VERYHIGH_OPERATOR = t.SLA_TARGET_VERYHIGH_OPERATOR;
                            target.SLA_TARGET_VERYHIGH_VALUE = t.SLA_TARGET_VERYHIGH_VALUE;
                            target.UPDATED_BY = t.UPDATED_BY;
                            target.UPDATED_DATE = DateTime.Now;
                            CSPdb.KPI_TARGETS.Update(target);
                        }
                    }
                }
                CSPdb.Commit(CanCommit);
                UpdateKpiServiceTowerMapping(results.SERVICE_TOWER_ID, results.ID);
            }
            return Ok();
        }

        private void UpdateKpiServiceTowerMapping(List<int> serviceTowerIds, int kpiId)
        {
            foreach (int t in serviceTowerIds)
            {
                KPI_SERVICETOWER_MAPPING kpiServiceTower = Cldb.KPI_SERVICETOWER_MAPPING.GetAll().FirstOrDefault(x => x.KPI_ID == kpiId && x.SERVICE_TOWER_ID == t);
                if (kpiServiceTower == null)
                {
                    kpiServiceTower = new KPI_SERVICETOWER_MAPPING()
                    {
                        KPI_ID = kpiId,
                        SERVICE_TOWER_ID = t
                    };
                    UpdateAuditFields(kpiServiceTower);
                    Cldb.KPI_SERVICETOWER_MAPPING.Add(kpiServiceTower);
                    Cldb.Commit(CanCommit);
                }
                else
                {
                    kpiServiceTower.ISACTIVE = true;
                    UpdateAuditFields(kpiServiceTower);
                    Cldb.KPI_SERVICETOWER_MAPPING.Update(kpiServiceTower);
                    Cldb.Commit(CanCommit);
                }
            }

            var kpiServiceTowers = Cldb.KPI_SERVICETOWER_MAPPING.GetAll().Where(x => x.KPI_ID == kpiId && x.ISACTIVE && !serviceTowerIds.Contains(x.SERVICE_TOWER_ID)).ToList();
            foreach (KPI_SERVICETOWER_MAPPING kpiServiceTower in kpiServiceTowers)
            {
                UpdateAuditFields(kpiServiceTower);
                kpiServiceTower.ISACTIVE = false;
                Cldb.KPI_SERVICETOWER_MAPPING.Update(kpiServiceTower);
                Cldb.Commit(CanCommit);
            }
        }


