        [HttpPost]
        public IHttpActionResult UpdateHighLight(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            HIGHLIGHTS results = JsonConvert.DeserializeObject<HIGHLIGHTS>(json);
            HIGHLIGHTS overview = CSPdb.HIGHLIGHTS.GetAll().Where(t => t.PROJECT_ID == results.PROJECT_ID && t.ID == results.ID).FirstOrDefault<HIGHLIGHTS>();
            if (overview != null && results != null)
            {
                overview.CUSTOMER_ID = results.CUSTOMER_ID;
                overview.PROJECT_ID = results.PROJECT_ID;
                overview.PUBLISH_DATE = results.PUBLISH_DATE;
                overview.CATEGORY = results.CATEGORY;
                overview.DESCRIPTION = results.DESCRIPTION;
                overview.UPDATED_BY = results.CREATED_BY;
                overview.UPDATED_DATE = DateTime.Now;
                overview.ISACTIVE = true;
                CSPdb.HIGHLIGHTS.Update(overview);
                CSPdb.Commit(CanCommit);
                UpdateLastUpdatedDetails(results.PROJECT_ID, results.UPDATED_BY);
            }
            return Ok();
        }

