        private void UpdateSQAChartFilters(ref SQA_PROJECT_CHART_PARAMS_WITH_FILTER ChartParams)
        {
            if (ChartParams.FILTERS != null && ChartParams.FILTERS.Count > 0)
            {
                foreach (SQA_CHART_FILTER f in ChartParams.FILTERS)
                {
                    if (f.FIELD != null && f.FIELD != "")
                    {
                        if (f.ID == 0)
                        {
                            f.CHART_ID = ChartParams.ID;
                            f.CUSTOMER_ID = ChartParams.CUSTOMER_ID;
                            f.PROJECT_ID = ChartParams.PROJECT_ID;
                            CSPdb.SQA_CHART_FILTER.Add(f);
                            CSPdb.Commit(CanCommit);
                        }
                        else
                        {
                            SQA_CHART_FILTER dbFilter = CSPdb.SQA_CHART_FILTER.GetById(f.ID);
                            dbFilter.FIELD = f.FIELD;
                            dbFilter.FILTER = f.FILTER;
                            dbFilter.FILTER_STRING = f.FILTER_STRING;
                            dbFilter.ISACTIVE = f.ISACTIVE;
                            dbFilter.OPERATOR = f.OPERATOR;
                            dbFilter.SORT_ORDER = f.SORT_ORDER;
                            dbFilter.UPDATED_BY = f.UPDATED_BY;
                            dbFilter.UPDATED_DATE = f.UPDATED_DATE;
                            CSPdb.Commit(CanCommit);
                        }
                    }
                }
            }
        }

        [POST("UpdateCrispProjects")]
        [ActionName("UpdateCrispProjects")]
        [HttpPost]
        public IHttpActionResult UpdateCrispProjects(List<CRISP_PROJECT> Projects)
        {
            string empId = "";
            if (Request.Headers.Contains("empId"))
                empId = Request.Headers.GetValues("empId").ToList()[0];
            foreach (CRISP_PROJECT p in Projects)
            {
                if (p.CRISP_SCORES_PROJECT.SELECTED)
                {
                    CRISP_SCORES_PROJECT proj = CSPdb.CRISP_SCORES_PROJECT.GetById(p.CRISP_SCORES_PROJECT.ID);
                    if (proj != null)
                    {
                        proj.NEED_FOCUS = p.CRISP_SCORES_PROJECT.NEED_FOCUS;
                        proj.COMMENTS = p.CRISP_SCORES_PROJECT.COMMENTS;
                        proj.HR_NEED_FOCUS = p.CRISP_SCORES_PROJECT.HR_NEED_FOCUS;
                        proj.HR_NEED_FOCUS_COMMENTS = p.CRISP_SCORES_PROJECT.HR_NEED_FOCUS_COMMENTS;
                        proj.STATUS = p.CRISP_SCORES_PROJECT.STATUS;
                        proj.UPDATED_BY = empId;
                        proj.UPDATED_DATE = DateTime.Now;
                        CSPdb.CRISP_SCORES_PROJECT.Update(proj);
                        CSPdb.Commit(CanCommit);
                    }

                    foreach (CRISP_SCORES_CRITERIA c in p.CRISP_SCORES_CRITERIA)
                    {
                        CRISP_SCORES_CRITERIA overview = CSPdb.CRISP_SCORES_CRITERIA.GetById(c.ID);
                        if (overview != null)
                        {
                            overview.SCORE = c.SCORE;
                            overview.SCORE_PERCENTAGE = c.SCORE_PERCENTAGE;
                            overview.UPDATED_BY = empId;
                            overview.UPDATED_DATE = DateTime.Now;
                            CSPdb.CRISP_SCORES_CRITERIA.Update(overview);
                            CSPdb.Commit(CanCommit);
                        }
                    }
                    //CSPdb.Commit(CanCommit);
                    foreach (CRISP_SCORES_VALIDATIONS v in p.CRISP_SCORES_VALIDATIONS)
                    {
                        CRISP_SCORES_VALIDATIONS overview = CSPdb.CRISP_SCORES_VALIDATIONS.GetById(v.ID);
                        if (overview != null)
                        {
                            overview.ACHIEVED = v.ACHIEVED;
                            overview.COMMENTS = v.COMMENTS;
                            overview.UPDATED_BY = empId;
                            overview.UPDATED_DATE = DateTime.Now;
                            CSPdb.CRISP_SCORES_VALIDATIONS.Update(overview);
                            CSPdb.Commit(CanCommit);

                        }
                    }
                    //CSPdb.Commit(CanCommit);

                }

            }
            UpdateCrispScores(Projects);
            int role = -1;
            if (empId != string.Empty)
            {
                EMP_INFO emp = Cldb.EMP_INFO.GetById(empId);
                role = emp.CSM_TITLE_ID;
            }

            if (role != 10)
                SendEmail_ToCSM(Projects, empId);
            return Ok();
        }

        public class CrispProjectData
        {
            public List<CRISP_PROJECT> Projects { get; set; }
            public string Month { get; set; }
            public int Year { get; set; }
