        [POST("PublishCrispProjects")]
        [ActionName("PublishCrispProjects")]
        [HttpPost]
        public IHttpActionResult PublishCrispProjects(List<CRISP_PROJECT> Projects)
        {
            UpdateCrispProjects(Projects);
            UpdateCrispScores(Projects);
            return Ok();
        }
        public void UpdateCrispScores(List<CRISP_PROJECT> Projects)
        {
            string empId = GetHeaderDetails_String("empId");
            List<CRISP_CRITERIA> crispCriteria = CSPdb.CRISP_CRITERIA.GetAll().ToList<CRISP_CRITERIA>();
            List<CRISP_CATEGORY> crispCategory = CSPdb.CRISP_CATEGORY.GetAll().ToList<CRISP_CATEGORY>();
            foreach (CRISP_PROJECT p in Projects)
            {
                if (p.CRISP_SCORES_PROJECT.SELECTED)
                {
                    foreach (CRISP_SCORES_CATEGORY c in p.CRISP_SCORES_CATEGORY)
                    {
                        CRISP_SCORES_CATEGORY overview = CSPdb.CRISP_SCORES_CATEGORY.GetById(c.ID);
                        if (overview != null)
                        {
                            List<int> criteriaIds = crispCriteria.Where(t => t.CATEGORY_ID == c.CATEGORY_ID).Select(u => u.ID).ToList<int>();
                            overview.SCORE = p.CRISP_SCORES_CRITERIA.Where(t => criteriaIds.Contains(t.CRITERIA_ID) && t.CRISP_SCORES_PROJECT_ID == p.CRISP_SCORES_PROJECT.ID).Sum(x => x.SCORE);
                            overview.UPDATED_BY = empId;
                            overview.UPDATED_DATE = DateTime.Now;
                            CSPdb.CRISP_SCORES_CATEGORY.Update(overview);
                            CSPdb.Commit(CanCommit);
                        }
                    }

                    CRISP_SCORES_PROJECT proj = CSPdb.CRISP_SCORES_PROJECT.GetById(p.CRISP_SCORES_PROJECT.ID);
                    if (proj != null)
                    {
                        proj.SCORE = CSPdb.CRISP_SCORES_CRITERIA.GetAll().Where(t => t.CRISP_SCORES_PROJECT_ID == p.CRISP_SCORES_PROJECT.ID).Sum(x => x.SCORE);
                        proj.UPDATED_BY = empId;
                        proj.UPDATED_DATE = DateTime.Now;
                        CSPdb.CRISP_SCORES_PROJECT.Update(proj);
                        CSPdb.Commit(CanCommit);
                    }
                }
            }
        }


        [POST("UpdateAccessControl")]
        [ActionName("UpdateAccessControl")]
        [HttpPost]
        public IHttpActionResult UpdateAccessControl(HttpRequestMessage request)
        {
            CheckAccessForFeature(36);
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            APP_ACCESS_CONTROLS results = JsonConvert.DeserializeObject<APP_ACCESS_CONTROLS>(json);
            APP_ACCESS_CONTROLS overview = CSPdb.APP_ACCESS_CONTROLS.GetById(results.ID);
            if (overview != null && results != null)
            {
                overview.ACCESS_LEVEL = results.ACCESS_LEVEL;
                overview.ROLE_ID = results.ROLE_ID;
                overview.EMP_ID = results.EMP_ID;

                overview.VIEW_ACCESS = results.VIEW_ACCESS;
                overview.CREATE_ACCESS = results.CREATE_ACCESS;
                overview.EDIT_ACCESS = results.EDIT_ACCESS;
                overview.DELETE_ACCESS = results.DELETE_ACCESS;

                overview.COMMENTS = results.COMMENTS;
                overview.UPDATED_BY = results.UPDATED_BY;
                overview.UPDATED_DATE = DateTime.Now;
                CSPdb.APP_ACCESS_CONTROLS.Update(overview);
                CSPdb.Commit(CanCommit);
            }
            return Ok();
        }


