        [POST("UpdateAccessControls")]
        [ActionName("UpdateAccessControls")]
        [HttpPost]
        public IHttpActionResult UpdateAccessControls(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            List<APP_ACCESS_CONTROLS> results = JsonConvert.DeserializeObject<List<APP_ACCESS_CONTROLS>>(json);
            foreach (APP_ACCESS_CONTROLS a in results)
            {
                APP_ACCESS_CONTROLS overview = CSPdb.APP_ACCESS_CONTROLS.GetById(a.ID);
                if (overview != null && results != null)
                {
                    overview.ROLE_ID = a.ROLE_ID;
                    overview.EMP_ID = a.EMP_ID;
                    overview.CUST_ID = a.CUST_ID;
                    overview.PROJ_ID = a.PROJ_ID;

                    overview.VIEW_ACCESS = a.VIEW_ACCESS;
                    overview.CREATE_ACCESS = a.CREATE_ACCESS;
                    overview.EDIT_ACCESS = a.EDIT_ACCESS;
                    overview.DELETE_ACCESS = a.DELETE_ACCESS;

                    overview.COMMENTS = a.COMMENTS;
                    overview.UPDATED_BY = a.UPDATED_BY;
                    overview.UPDATED_DATE = DateTime.Now;
                    CSPdb.APP_ACCESS_CONTROLS.Update(overview);
                    CSPdb.Commit(CanCommit);
                }
                else
                {
                    APP_ACCESS_CONTROLS acc = new APP_ACCESS_CONTROLS();
                    acc.RESOURCE_ID = a.RESOURCE_ID;
                    acc.ACCESS_LEVEL = a.ACCESS_LEVEL;
                    acc.ROLE_ID = a.ROLE_ID;
                    acc.EMP_ID = a.EMP_ID;
                    acc.CUST_ID = a.CUST_ID;
                    acc.PROJ_ID = a.PROJ_ID;

                    acc.VIEW_ACCESS = a.VIEW_ACCESS;
                    acc.CREATE_ACCESS = a.CREATE_ACCESS;
                    acc.EDIT_ACCESS = a.EDIT_ACCESS;
                    acc.DELETE_ACCESS = a.DELETE_ACCESS;

                    acc.COMMENTS = a.COMMENTS;
                    acc.CREATED_BY = a.UPDATED_BY;
                    acc.CREATED_DATE = DateTime.Now;
                    acc.UPDATED_BY = a.UPDATED_BY;
                    acc.UPDATED_DATE = DateTime.Now;
                    acc.ISACTIVE = true;
                    CSPdb.APP_ACCESS_CONTROLS.Add(acc);
                    CSPdb.Commit(CanCommit);
                }
            }
            return Ok();
        }

        [POST("UpdateMOMDetails")]
        [ActionName("UpdateMOMDetails")]
        [HttpPost]
        public IHttpActionResult UpdateMOMDetails(HttpRequestMessage request)
        {
            string momId = Request.Headers.GetValues("momId").ToList()[0];
            string loopcontent = "";
            string mailcontent = "";
            var content = request.Content;
            string empId = Request.Headers.GetValues("empId").ToList()[0];
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            MOM u = JsonConvert.DeserializeObject<MOM>(json);
            List<PROJECT_ACTIONITEM> ai = new List<PROJECT_ACTIONITEM>();
            List<string> actIds = new List<string>();
            List<string> actId = new List<string>();
            string act;
            List<CUSTOMER_MOM_DETAILS> momi = new List<CUSTOMER_MOM_DETAILS>();
            PROJECT_ACTIONITEM pam = new PROJECT_ACTIONITEM();
            momi = CSPdb.CUSTOMER_MOM_DETAILS.GetAll().Where(t => t.MOM_ID == momId && t.ISACTIVE == true).ToList<CUSTOMER_MOM_DETAILS>();
            //foreach (CUSTOMER_MOM_DETAILS mmm in momi)
            //{
            //    mmm.ISACTIVE = false;
            //    CSPdb.CUSTOMER_MOM_DETAILS.Update(mmm);
            //    CSPdb.Commit(CanCommit);
            //    actIds.Add(mmm.ACTION_ITEM_ID);
            //}
            CUSTOMER_MOM_DETAILS cmd = new CUSTOMER_MOM_DETAILS();
            foreach (MOM.MOM_DETAIL p in u.MOM_ITEMS)
            {
                if ((p.ACTION_ITEM != null || p.ACTION_ITEM != "") && (p.DISCUSSION_POINTS != null || p.DISCUSSION_POINTS != "") && (p.PRIORITY != null || p.PRIORITY != "") && p.RESPONSIBILITY != "0")
                {
                    actId = new List<string>();
                    //CUSTOMER_MOM_DETAILS cmd = new CUSTOMER_MOM_DETAILS();
                    if (p.ID == 0)
                    {
                        cmd.CUSTOMER_ID = string.Join(",", p.CUSTOMER_ID);
                        cmd.PROJECT_ID = string.Join(",", p.PROJECT_ID);
                        cmd.DISCUSSION_POINTS = p.DISCUSSION_POINTS;
                        cmd.DESCRIPTION = u.MEETING_DESCRIPTION;
                        cmd.MOM_DATE = u.MEETING_DATE.ToLocalTime();
                        cmd.MOM_TIME = u.MEETING_TIME;
                        cmd.MOM_VENUE = u.MEETING_VENUE;
                        cmd.MOM_CHAIRPERSON = u.CHAIRPERSON;
                        cmd.MOM_AGENDA = u.MEETING_AGENDA;
                        cmd.MOM_PARTICIPANTS = u.MEETING_PARTICIPANTS;
                        cmd.MOM_STATUS = u.STATUS;
                        cmd.MOM_ID = momId;
                        if (u.STATUS == "submit")
                        {
                            ai = AddNewActionitem(p, u, empId);
                            loopcontent += GetLoopContent(ai);
                            foreach (PROJECT_ACTIONITEM op in ai)
                                actId.Add(op.ID.ToString());
                            act = string.Join(",", actId);
                            cmd.ACTION_ITEM_ID = act;
                        }
                        cmd.ACTION_ITEM_DESCRIPTION = p.ACTION_ITEM;
                        cmd.ACTION_ITEM_PRIORITY = p.PRIORITY;
                        cmd.ACTION_ITEM_RESPONSIBILITY = p.RESPONSIBILITY.ToString();
                        if (p.TARGET_DATE != null)
                            cmd.ACTION_ITEM_TARGET_DATE = Convert.ToDateTime(p.TARGET_DATE).ToLocalTime();
                        else
                            cmd.ACTION_ITEM_TARGET_DATE = null;
                        cmd.CREATED_BY = empId;
                        cmd.CREATED_DATE = DateTime.Now;
                        cmd.UPDATED_BY = empId;
                        cmd.UPDATED_DATE = DateTime.Now;
                        cmd.ISACTIVE = true;
                        CSPdb.CUSTOMER_MOM_DETAILS.Add(cmd);
                        CSPdb.Commit(CanCommit);
                    }
                    else
                    {
                        cmd = CSPdb.CUSTOMER_MOM_DETAILS.GetAll().Where(t => t.ID == p.ID).FirstOrDefault();
                        cmd.CUSTOMER_ID = string.Join(",", p.CUSTOMER_ID);
                        cmd.PROJECT_ID = string.Join(",", p.PROJECT_ID);
                        cmd.DISCUSSION_POINTS = p.DISCUSSION_POINTS;
                        cmd.DESCRIPTION = u.MEETING_DESCRIPTION;
                        cmd.MOM_DATE = u.MEETING_DATE.ToLocalTime();
                        cmd.MOM_TIME = u.MEETING_TIME;
                        cmd.MOM_VENUE = u.MEETING_VENUE;
                        cmd.MOM_CHAIRPERSON = u.CHAIRPERSON;
                        cmd.MOM_AGENDA = u.MEETING_AGENDA;
                        cmd.MOM_PARTICIPANTS = u.MEETING_PARTICIPANTS;
                        cmd.MOM_STATUS = u.STATUS;
                        cmd.MOM_ID = momId;
                        if (u.STATUS == "submit")
                        {
                            ai = AddNewActionitem(p, u, empId);
                            loopcontent += GetLoopContent(ai);
                            foreach (PROJECT_ACTIONITEM op in ai)
                                actId.Add(op.ID.ToString());
                            act = string.Join(",", actId);
                            cmd.ACTION_ITEM_ID = act;
                        }
                        cmd.ACTION_ITEM_DESCRIPTION = p.ACTION_ITEM;
                        cmd.ACTION_ITEM_PRIORITY = p.PRIORITY;
                        cmd.ACTION_ITEM_RESPONSIBILITY = p.RESPONSIBILITY.ToString();
                        if (p.TARGET_DATE != null)
                            cmd.ACTION_ITEM_TARGET_DATE = Convert.ToDateTime(p.TARGET_DATE).ToLocalTime();
                        cmd.CREATED_BY = empId;
                        cmd.CREATED_DATE = DateTime.Now;
                        cmd.UPDATED_BY = empId;
                        cmd.UPDATED_DATE = DateTime.Now;
                        cmd.ISACTIVE = true;
                        CSPdb.CUSTOMER_MOM_DETAILS.Update(cmd);
                        CSPdb.Commit(CanCommit);
                    }

                }
            }
            if (cmd.MOM_STATUS == "submit")
            {
                mailcontent = UpdateMailContent(cmd, loopcontent);
                SendMailToEmp(u, mailcontent, empId);
            }
            return Ok();
        }


