        [GET("GetDBConfig")]
        [ActionName("GetDBConfig")]
        [HttpGet]
        public IHttpActionResult GetDBConfig(string key, string custId, string projId)
        {
            return Ok(GetDBConfigValue(key, custId, projId));
        }

        [GET("GetDBConfigArrayValues")]
        [ActionName("GetDBConfigArrayValues")]
        [HttpGet]
        public IHttpActionResult GetDBConfigArrayValues(string key, string custId, string projId)
        {
            var result = new List<string>();
            var configValues = GetDBConfigValue(key, custId, projId);

            if (!string.IsNullOrWhiteSpace(configValues))
            {
                result = configValues.Split(',').ToList();
            }
            return Ok(result);
        }

        private string GetDBConfigValue(string key, string custId, string projId)
        {
            return helper.GetDBConfig(key, custId, projId);
        }

        private string GetCustomerId(string ProjId)
        {
            string CustId = "0";
            PROJECT proj = Cldb.PROJECT.GetAll().Where(t => t.PROJ_ID == ProjId).FirstOrDefault();
            if (proj != null)
                CustId = proj.CUST_ID;

            return CustId;
        }
        private void SendTimeSheetMail(ProjectTimesheetDetailsEmp emp, string SenderEmail, string SenderName, enDateRange period, DateTime StartDate, DateTime EndDate, string comments, string status)
        {
            string subject = string.Empty;
            string statusMsg = string.Empty;
            string mailContent;
            string headercontent;
            string bodycontent;

            string ccmail = "";

            var project = Cldb.PROJECT.GetAll().FirstOrDefault(x => x.PROJ_ID == emp.PROJ_ID);

            string CustId = project.CUST_ID;// GetCustomerId(emp.PROJ_ID);

            List<string> pmlist = new List<string>();
            headercontent = GetListOfDate(StartDate, EndDate);
            bodycontent = GetListOfEmployees(emp, status, StartDate, EndDate);
            string tomail = helper.GetCSMMailsFromProject(project);

            if (string.IsNullOrWhiteSpace(tomail))
                tomail = _email;

            ccmail = helper.GetPMMailsFromProject(project);
            //foreach (string pm in pmlist)
            //    ccmail = ccmail + pm + ",";
            //ccmail = ccmail + SenderEmail + ",";
            //ccmail = ccmail + ConfigurationManager.AppSettings["premierpmo"];
            ccmail = ccmail + "," + helper.GetDBConfig("PMO", CustId);

            string ParaTag = "<p style = 'padding:25px 0 15px;font-family:Arial;font-size:12px'>";

            if (comments != string.Empty && status != "APPROVED" && status != "CUSTOMER REJECT")
                comments = ParaTag + "<b>Comments</b> : " + comments + "</p>";

            //Selected Period
            string sPeriod = string.Empty;
            if (period == enDateRange.Monthly)
            {
                sPeriod = StartDate.ToString("MMM-yyyy");
            }
            else if (period == enDateRange.Weekly)
            {
                sPeriod = "Week " + StartDate.ToString("dd-MMM-yyy") + " to " + EndDate.ToString("dd-MMM-yyy");
            }

            if (status == "APPROVED")
                subject = GetProjectAliasName(emp) + " (" + sPeriod + ") timesheet Approved";
            else if (status == "CUSTOMER REJECT")
                subject = GetProjectAliasName(emp) + " (" + sPeriod + ") timesheet Rejected";
            else if (status == "FOR APPROVAL")
                subject = GetProjectAliasName(emp) + " (" + sPeriod + ") timesheet awaiting for your approval";


            if (status == "APPROVED")
                statusMsg = "<h3>" + "Timesheet approved by " + SenderName + "</h3>";
            else if (status == "CUSTOMER REJECT")
                statusMsg = "<h3>" + "Timesheet rejected by " + SenderName + "</h3>";

            if (status == "FOR APPROVAL")
            {
                string senderEmails = ccmail + "," + helper.GetDBConfig("FORAPPROVAL", CustId);
                var additional = helper.GetEmployeeMailId(SenderEmail);
                if (!string.IsNullOrWhiteSpace(additional))
                    senderEmails = additional + "," + senderEmails;
                //string senderEmails = ConfigurationManager.AppSettings["premierforapproval"];
                List<string> CustomerEmailIds = new List<string>();
                List<string> CustomerNames = new List<string>();
                var employees = emp.employees.Where(x => x.DUMMY == false && x.STATUS.ToUpper() == "FOR APPROVAL").Select(x => x.FRST_NM).Distinct().ToList();
                StringBuilder sb = new StringBuilder();
                sb.AppendLine("<table>");
                int i = 1;
                foreach (var item in employees)
                {
                    sb.AppendLine($"<tr><td>{i++}.</td><td>{item}</td></tr>");
                }
                sb.AppendLine("</table>");

                GetCustomersByProjectId(emp.PROJ_ID, out CustomerEmailIds, out CustomerNames);
                SendMail_ApprovalRemainder(string.Join(", ", CustomerEmailIds), string.Join(", ", CustomerNames), senderEmails, subject, CustId, sb.ToString());
            }
            else
            {
                mailContent = "<style>p{margin: 0;padding: 0;font - size:60px;line - height:30px;}table,td,th{border: 1px solid #A49D9C;border-collapse:collapse;text-align:center;font-family:calibri}td { min-width: 30px; } th{ background:#A9A9A9}</style>" +
                    statusMsg + comments +
                    ParaTag + "<b>Project Name</b> : " + GetProjectAliasName(emp) + " </p>" +
                    ParaTag + "<b>Timesheet Period</b> : " + sPeriod + " </p>" +
                    "<table style = 'width:100%;'> ";
                if (status == "APPROVED" || status == "CUSTOMER REJECT")
                    mailContent += ParaTag += "<tr><th>Employee Name</th><th>Task</th>" + headercontent + "<th>Total</th><th>Status</th><th>Comments</th><th>Customer Comments</th></tr>" + bodycontent + "</table>";
                else
                    mailContent += ParaTag += "<tr><th>Employee Name</th><th>Task</th>" + headercontent + "<th>Total</th><th>Status</th><th>Comments</th></tr>" + bodycontent + "</table>";

                mailContent += GetFooterContent();

                if (status == "APPROVED" || status == "CUSTOMER REJECT")
                {
                    List<string> CustomerEmailIds = new List<string>();
                    List<string> CustomerNames = new List<string>();
                    GetCustomersByProjectId(emp.PROJ_ID, out CustomerEmailIds, out CustomerNames);
                    if (CustomerEmailIds.Count > 0)
                        ccmail = ccmail + "," + String.Join(",", CustomerEmailIds) + ",";
                }

                var ep = new EmailProvider(Cldb, CSPdb);
                if (string.IsNullOrWhiteSpace(subject))
                    ep.SendEmail
                       (
                       new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                       new EmailContent { from = _email, to = ConfigurationManager.AppSettings["DefaultMail"], content = mailContent, subject = subject, hasAttachments = false, attachmentFilePath = "", ProjId = emp.PROJ_ID },
                       Request
                       );
                else
                    ep.SendEmail
                        (
                        new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                        new EmailContent { from = _email, to = tomail, cc = ccmail, content = mailContent, subject = subject, hasAttachments = false, attachmentFilePath = "", ProjId = emp.PROJ_ID },
                        Request
                        );
            }
        }
        private string GetProjectAliasName(ProjectTimesheetDetailsEmp emp)
        {
            if (emp.PROJ_ALIAS_NM != null && emp.PROJ_ALIAS_NM != string.Empty)
                return emp.PROJ_ALIAS_NM;
            else
                return emp.PROJ_NM;
        }

        private void SendMail_ApprovalRemainder(string ToEmailId, string ToName, string SenderEmaiId, string Subject, string custId, string employees)
        {
            string filePath = HttpContext.Current.Server.MapPath("~/UploadFile/Mails/") + "PremierForApprovalReminder.htm";
            using (System.IO.StreamReader sr = new StreamReader(filePath))
            {
                string emailContent = sr.ReadToEnd();
                emailContent = emailContent.Replace("{{CUSTOMER_NM}}", ToName);
                emailContent = emailContent.Replace("{{URL}}", IsPremier(custId) ? $"layout/timesheetnewhome/{custId}" : $"layout/timesheet/{custId}");
                emailContent = emailContent.Replace("{{EMPLOYEES}}", employees);
                var ep = new EmailProvider(Cldb, CSPdb);
                ep.SendEmail
                    (
                    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                    new EmailContent { from = _email, to = ToEmailId, cc = SenderEmaiId, content = emailContent, subject = Subject, hasAttachments = false, attachmentFilePath = "" },
                    Request
                    );
            }
        }


        private string GetListOfDate(DateTime startDate, DateTime endDate)
        {
            string loopcontent = string.Empty;
