        private string GetListOfEmployees(ProjectTimesheetDetailsEmp emp, string status, DateTime startDate, DateTime endDate)
        {
            string loopcontent = "";
            string dateloop;
            foreach (var empG in emp.employees.Where(x => x.DUMMY == false).OrderBy(x => x.FRST_NM))
            {
                foreach (var empdet in empG.TIMESHEET.Where(x => x.PROJ_RESRC_TIME_ENTRY_ID != null && !string.IsNullOrWhiteSpace(x.PROJ_TASK)).GroupBy(x => x.PROJ_TASK))
                {
                    dateloop = GetDateLoop(empdet.ToList(), status, startDate, endDate);
                    if (status == "APPROVED" || status == "CUSTOMER REJECT")
                        loopcontent = loopcontent + "<tr><td style ='text-align:left'> " + empG.FRST_NM + "</td><td>" + empdet.Key + "</td>" + dateloop + "<td>" + empdet.Sum(x => x.CLOCKED_MINS) + "</td><td>" + empG.STATUS + "</td><td>" + GetTimesheetComments(empdet.ToList()) + "</td><td>" + empG.REJECT_DESC + "</td></tr>";
                    else
                        loopcontent = loopcontent + "<tr><td style ='text-align:left'> " + empG.FRST_NM + "</td><td>" + empG.TASK_NAME + "</td>" + dateloop + "<td>" + empdet.Sum(x => x.CLOCKED_MINS) + "</td><td>" + empG.STATUS + "</td><td>" + GetTimesheetComments(empdet.ToList()) + "</td></tr>";
                }

            }
            return loopcontent;
        }
        private string GetDateLoop(List<TimesheetDetailsMonthly> monthdata, string status, DateTime startDate, DateTime endDate)
        {
            string loopdata = "";
            for (DateTime i = startDate; i <= endDate; i = i.AddDays(1))
            {
                var tsd = monthdata.FirstOrDefault(x => x.DATE_ID == GetDateDim(i));
                if (tsd == null)
                {
                    loopdata = loopdata + "<td style = 'width : 30px'> - </td>";
                    continue;
                }

                if (tsd.CLNDR_DAY_NAME == "Sun" || tsd.CLNDR_DAY_NAME == "Sat")
                    loopdata = loopdata + "<td style = 'background:#f3f37e;width:30px'>" + tsd.CLOCKED_MINS + "</td>";
                else if (tsd.PROJ_TASK_ID == 3)
                    loopdata = loopdata + "<td style = 'background:#c5fbc5;width:30px'>" + tsd.CLOCKED_MINS + "</td>";
                else if (tsd.PROJ_TASK_ID == 5)
                    loopdata = loopdata + "<td style = 'background:#a3ffff;width:30px'>" + tsd.CLOCKED_MINS + "</td>";
                else
                    loopdata = loopdata + "<td style = 'width : 30px'>" + tsd.CLOCKED_MINS + "</td>";
            }
            //foreach (var ts in monthdata.GroupBy(x=>x.CLNDR_DATE))
            //{
            //    var tsd = ts.First();
            //    if (tsd.CLNDR_DAY_NAME == "Sun" || tsd.CLNDR_DAY_NAME == "Sat")
            //        loopdata = loopdata + "<td style = 'background:#f3f37e;width:30px'>" + ts.Where(x => x.TIME_ENTRY_STATUS == status).Sum(x=>x.CLOCKED_MINS )+ "</td>";
            //    else if (tsd.PROJ_TASK_ID == 3)
            //        loopdata = loopdata + "<td style = 'background:#c5fbc5;width:30px'>" + ts.Where(x => x.TIME_ENTRY_STATUS == status).Sum(x => x.CLOCKED_MINS) + "</td>";
            //    else if (tsd.PROJ_TASK_ID == 5)
            //        loopdata = loopdata + "<td style = 'background:#a3ffff;width:30px'>" + ts.Where(x => x.TIME_ENTRY_STATUS == status).Sum(x => x.CLOCKED_MINS) + "</td>";
            //    else
            //        loopdata = loopdata + "<td style = 'width : 30px'>" + ts.Sum(x => x.CLOCKED_MINS) + "</td>";
            //}
            return loopdata;
        }

