        private void SendErrorNotificationMail(string error, string errorTrace)
        {
            string subject = string.Empty;
            string statusMsg = string.Empty;
            string tomail = Constants.QUALITY_MAIL;
            //string ccmail = helper.GetDBConfig("CSS_LINK_CC", -1);
            //string csmMails = helper.GetCSMMailsFromProject(cust.PROJ_ID);
            //string pmMails = helper.GetPMMailsFromProject(cust.PROJ_ID);
            //string ccmail = QUALITY_MAIL;
            //string csmMails = QUALITY_MAIL;
            //string pmMails = QUALITY_MAIL;


            subject = "Timesheet Failure";
            //ccmail = helper.ConcatEmails(new List<string>() { ccmail, csmMails, pmMails });

            StringBuilder sbMessage = new StringBuilder();
            sbMessage.Append("<p>Hi,</p>");
            sbMessage.Append("<p>An unexpected error has occurred, Please find below the error details</p>");
            sbMessage.Append("<p><b>Error  :</b>" + error + "</p>");
            sbMessage.Append("<p><b>Trace  :</b>" + errorTrace + "</p>");
            //sbMessage.Append("<p>Thank You,<br>" + sFromname + "</p>");
            sbMessage.Append("<p>Thank You,<br>Team CSM</p>");

            var ep = new EmailProvider(Cldb, CSPdb);
            ep.SendEmail
                (
                new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                new EmailContent { from = _email, to = Constants._csmSupportMail, content = sbMessage.ToString(), subject = subject, hasAttachments = false, attachmentFilePath = "" },
                Request
                );

        }


        private void SendTimeSheetMailMultipleProjects(List<ProjectTimesheetDetailsEmp> ProjectTimesheets, string empId, enDateRange period, DateTime StartDate, DateTime EndDate, string status = null, string comments = null)
        {
            var custName = GetCustomerName(empId);
            foreach (ProjectTimesheetDetailsEmp projectTimesheet in ProjectTimesheets)
            {
                List<EmployeeTimesheetDetails> lstEmployees = projectTimesheet.employees.Where(t => t.SELECTED == true).ToList();
                if (lstEmployees.Any())
                {
                    projectTimesheet.employees = lstEmployees;
                    //string comments = string.Empty;
                    //string status = string.Empty;
                    if (projectTimesheet != null && projectTimesheet.employees.Any() && projectTimesheet.employees[0].TIMESHEET.Any())
                    {
                        comments = comments ?? projectTimesheet.employees[0].TIMESHEET[0]?.REJECT_DESC;
                        status = status ?? projectTimesheet.employees[0].TIMESHEET[0]?.TIME_ENTRY_STATUS.Trim();
                    }
                    SendTimeSheetMail(projectTimesheet, empId, custName, period, StartDate, EndDate, comments, status);
                }
            }
        }

        [POST("UpdateTimesheetDetailsMonthlyEmp")]
        [ActionName("UpdateTimesheetDetailsMonthlyEmp")]
        [HttpPost]
        public IHttpActionResult UpdateTimesheetDetailsMonthlyEmp(HttpRequestMessage request)
        {
            var watch = Stopwatch.StartNew();
            string empId = Request.Headers.GetValues("empId").ToList()[0];
            string period = this.GetHeaderDetails_String("period");
            string role = this.GetHeaderDetails_String("role");
            enDateRange enPeriod = (enDateRange)Enum.Parse(typeof(enDateRange), period, true);
            DateTime StartDate = this.GetHeaderDetails_Date("startDate");
            DateTime EndDate = this.GetHeaderDetails_Date("endDate");
            string comments = string.Empty;
            string status = string.Empty;
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            bool sendmailflag = false;
            string SenderName = string.Empty;
            ProjectTimesheetDetailsEmp projectTimesheet = JsonConvert.DeserializeObject<ProjectTimesheetDetailsEmp>(json);
            List<PROJ_RESRC_TIME_ENTRY> addRecords = new List<PROJ_RESRC_TIME_ENTRY>();
            List<PROJ_RESRC_TIME_ENTRY> updateRecords = new List<PROJ_RESRC_TIME_ENTRY>();

            foreach (EmployeeTimesheetDetails employeeTimesheet in projectTimesheet.employees)
            {
                if ((employeeTimesheet.STATUS == "APPROVED" && role == "5") || (employeeTimesheet.STATUS == "CUSTOMER REJECT" && role == "5")
                    || (employeeTimesheet.STATUS == "FOR APPROVAL"))
                {
                    SenderName = this.GetCustomerName(empId);
                    status = employeeTimesheet.STATUS;
                    sendmailflag = true;
                }
                foreach (TimesheetDetailsMonthly timesheet in employeeTimesheet.TIMESHEET)
                {
                    if (timesheet.PROJ_RESRC_TIME_ENTRY_ID == null)
                    {
                        if (timesheet.CLOCKED_MINS != null)
                        {
                            PROJ_RESRC_TIME_ENTRY newTS = new PROJ_RESRC_TIME_ENTRY()
                            {
                                PROJ_ID = projectTimesheet.PROJ_ID,
                                BILLING_PROJ_ID = employeeTimesheet.BILLING_PROJ_ID,
                                EMP_ID = employeeTimesheet.EMP_ID,
                                DATE_ID = timesheet.DATE_ID,
                                PROJ_TASK_ID = timesheet.PROJ_TASK_ID.HasValue ? timesheet.PROJ_TASK_ID : 1,
                                //TASK_DESC = employeeTimesheet.COMMENTS,
                                CLOCKED_MINS = timesheet.CLOCKED_MINS,
                                TIME_ENTRY_STATUS = timesheet.TIME_ENTRY_STATUS,
                                OTHER_DETAILS = timesheet.OTHER_DETAILS,
                                APPRL_DATE = timesheet.APPRL_DATE,
                                REJECT_DATE = timesheet.REJECT_DATE,
                                REJECT_DESC = timesheet.REJECT_DESC,
                                CREATED_DATE = DateTime.Now,
                                CREATED_BY = empId,
                                UPDATED_BY = empId,
                                UPDATED_DATE = DateTime.Now

                            };
                            //Cldb.PROJ_RESRC_TIME_ENTRY.Add(newTS);
                            addRecords.Add(newTS);

                        }
                    }
                    else if (timesheet.TIME_ENTRY_STATUS != "APPROVED")
                    {
                        PROJ_RESRC_TIME_ENTRY newTS = Cldb.PROJ_RESRC_TIME_ENTRY.GetAll().Where(t => t.PROJ_RESRC_TIME_ENTRY_ID == timesheet.PROJ_RESRC_TIME_ENTRY_ID).FirstOrDefault();
                        newTS.PROJ_ID = timesheet.PROJ_ID;
                        newTS.BILLING_PROJ_ID = employeeTimesheet.BILLING_PROJ_ID;
                        newTS.EMP_ID = timesheet.EMP_ID;
                        newTS.DATE_ID = timesheet.DATE_ID;
                        newTS.PROJ_TASK_ID = timesheet.PROJ_TASK_ID;
                        //newTS.TASK_DESC = employeeTimesheet.COMMENTS;
                        if (timesheet.CLOCKED_MINS == null)
                            newTS.CLOCKED_MINS = 0;
                        //else
                        //    newTS.CLOCKED_MINS = timesheet.CLOCKED_MINS;
                        newTS.TIME_ENTRY_STATUS = timesheet.TIME_ENTRY_STATUS;
                        newTS.OTHER_DETAILS = timesheet.OTHER_DETAILS;
                        newTS.APPRL_DATE = timesheet.APPRL_DATE;
                        newTS.REJECT_DATE = timesheet.REJECT_DATE;
                        newTS.REJECT_DESC = timesheet.REJECT_DESC;
                        newTS.UPDATED_BY = empId;
                        newTS.UPDATED_DATE = DateTime.Now;
                        //Cldb.PROJ_RESRC_TIME_ENTRY.Update(newTS);
                        updateRecords.Add(newTS);

                    }
                }
                //Cldb.Commit(CanCommit);
            }
            //if (addRecords.Count > 0)
            //    Cldb.AppRepo.Insert_PROJ_RESRC_TIME_ENTRY_PSA(ToDataTable(addRecords));
            if (updateRecords.Count > 0)
                Cldb.AppRepo.Update_PROJ_RESRC_TIME_ENTRY_PSA(ToDataTable(updateRecords));

            UpdatePSA(updateRecords, empId);

            if (sendmailflag)
            {
                if (projectTimesheet != null && projectTimesheet.employees.Count > 0 && projectTimesheet.employees[0].TIMESHEET.Count > 0)
                {
                    comments = projectTimesheet.employees[0].TIMESHEET[0].REJECT_DESC;
                }
                SendTimeSheetMail(projectTimesheet, empId, SenderName, enPeriod, StartDate, EndDate, comments, status);
            }
            FillResponseTime(watch);
            return Ok();
        }

