        [POST("UpdateProcessModel")]
        [ActionName("UpdateProcessModel")]
        [HttpPost]
        public IHttpActionResult UpdateProcessModel(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            string empId = Request.Headers.GetValues("empId").ToList()[0];
            //int empIds = Convert.ToInt32(empId);
            dynamic json = jsonContent;
            PROCESS_MODEL results = JsonConvert.DeserializeObject<PROCESS_MODEL>(json);
            PROCESS_MODEL overview = CSPdb.PROCESS_MODEL.GetById(results.ID);
            if (results != null)
            {
                overview.TITLE = results.TITLE;
                overview.DESCRIPTION = results.DESCRIPTION;
                overview.RELEASE_VERSION_REFERENCE = results.RELEASE_VERSION_REFERENCE;
                overview.RELEASE_DATE = results.RELEASE_DATE;
                overview.UPDATED_BY = empId;
                overview.UPDATED_DATE = DateTime.Now;
                overview.ISACTIVE = true;

                var existing = CSPdb.PROCESS_MODEL.GetAll().Any(x => x.ID != results.ID && x.TITLE == results.TITLE
                               && x.RELEASE_VERSION_REFERENCE == results.RELEASE_VERSION_REFERENCE);
                if (existing)
                {
                    return Content(HttpStatusCode.Conflict, "Process model with same Title, Release Version exists already.");
                }

                CSPdb.PROCESS_MODEL.Update(overview);
                CSPdb.Commit(CanCommit);
            }
            return Ok(overview);
        }


