        [POST("CheckProjectAllocationExpiry")]
        [ActionName("CheckProjectAllocationExpiry")]
        [HttpPost]
        public IHttpActionResult CheckProjectAllocationExpiry()
        {

            //string empid = "0";
            List<string> result = new List<string>();
            List<string> Projects = new List<string>();
            var empIdString = GetHeaderDetails_String("empId");
            var dateToCheck = DateTime.Today.AddDays(10);
            //if (int.TryParse(empIdString, out empid))
            //{
            var allocation = Cldb.PROJECT_RESOURCE.GetAll().Where(x => x.ID != null && x.EMP_ID == empIdString).ToList();
            var projectIds = allocation.Select(x => x.PROJ_ID).Distinct().ToList();
            var projects = Cldb.PROJECT.GetAll().Where(x => projectIds.Contains(x.PROJ_ID)).ToList();

            if (allocation.Any(x => x.END_DATE > DateTime.Today && x.END_DATE <= dateToCheck))
            {
                var temp = allocation.Where(x => x.END_DATE > DateTime.Today && x.END_DATE <= dateToCheck).ToList();
                result.AddRange(projects.Where(x => temp.Any(c => c.PROJ_ID == x.PROJ_ID)).Select(x => x.PROJ_NM));
            }

            if (projects.Any(x => x.END_DATE > DateTime.Today && x.END_DATE <= dateToCheck))
                result.AddRange(projects.Where(x => x.END_DATE > DateTime.Today && x.END_DATE <= dateToCheck).Select(x => x.PROJ_NM));

            //}

            return Ok(string.Join(",", result));
        }

