        [POST("AddTaskandAudit")]
        [ActionName("AddTaskandAudit")]
        [HttpPost]
        public IHttpActionResult AddTaskandAudit(HttpRequestMessage request)
        {
            var stopwatch = Stopwatch.StartNew();
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            string empId = this.GetHeaderDetails_String("empid");
            //TASK task = JsonConvert.DeserializeObject<TASK>(json);
            var taskAudit = JsonConvert.DeserializeObject<TASK_AUDIT_VM>(json);
            string strMessage = string.Empty;
            var projectRecords = Cldb.PROJECT.GetAll().Where(x => x.PROJ_STATUS != "Close").ToList();
            if (taskAudit.PROJ_IDS != null && taskAudit.PROJ_IDS.Count > 0)
            {
                foreach (var item in taskAudit.PROJ_IDS)
                {
                    var projId = item;
                    var custId = projectRecords.FirstOrDefault(x => x.PROJ_ID == projId)?.CUST_ID;
                    var task = helper.AddTaskandAudit(taskAudit, request, CanCommit, empId, out strMessage, custId, projId);
                }
            }
            else
            {
                var task = helper.AddTaskandAudit(taskAudit, request, CanCommit, empId, out strMessage);
            }

            if (!string.IsNullOrEmpty(strMessage))
                return Content(HttpStatusCode.Conflict, strMessage);
            FillResponseTime(stopwatch);
            return Ok();
        }


        [POST("AddTask")]
        [ActionName("AddTask")]
        [HttpPost]
        public IHttpActionResult AddTask(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            TASK task = JsonConvert.DeserializeObject<TASK>(json);
            string empId = this.GetHeaderDetails_String("empid");
            bool isnew = false;
            if (task != null)
            {
                if (task.SCHEDULED_START_DATE.HasValue) task.SCHEDULED_START_DATE = task.SCHEDULED_START_DATE.Value.ToLocalTime();
                if (task.DUE_DATE.HasValue) task.DUE_DATE = task.DUE_DATE.Value.ToLocalTime();
                if (task.ACTUAL_START_DATE.HasValue) task.ACTUAL_START_DATE = task.ACTUAL_START_DATE.Value.ToLocalTime();
                if (task.ACTUAL_END_DATE.HasValue) task.ACTUAL_END_DATE = task.ACTUAL_END_DATE.Value.ToLocalTime();
                if (task.RECURRENCE != null)
                {
                    task.RECURRENCE.START_DATE = task.RECURRENCE.START_DATE.ToLocalTime();
                    task.RECURRENCE.END_DATE = task.RECURRENCE.END_DATE.ToLocalTime();
                }
                if (task.ID == 0)
                {
                    isnew = true;
                    CSPdb.TASK.Add(task);
                }
                else
                {
                    helper.InsertTaskStatusHistory(task, empId);
                    CSPdb.TASK.Update(task);
                }
                CSPdb.Commit(CanCommit);
                if (task.SET_RECURRENCE)
                {
                    helper.CleanupRecurrence(task.RECURRENCE);
                    task.RECURRENCE.TASK_ID = task.ID;
                    if (task.RECURRENCE.ID == 0)
                        CSPdb.TASK_RECURRENCE.Add(task.RECURRENCE);
                    else
                    {
                        CSPdb.TASK_RECURRENCE.Update(task.RECURRENCE);
                        helper.DeleteScheduledTask(task, CanCommit);
                    }
                    var resultText = helper.CreateScheduledTask(task, CanCommit);
                    if (!string.IsNullOrEmpty(resultText))
                        return Content(HttpStatusCode.Conflict, resultText);
                }
                else
                {
                    helper.DeleteScheduledTask(task, CanCommit);
                    task.PARENT_TASK_ID = task.ID;
                    CSPdb.TASK.Update(task);
                }
                CSPdb.Commit(CanCommit);
            }
            var taskAudit = new TASK_AUDIT_VM();
            taskAudit.Task = task;
            helper.SendMailToTaskPersons(taskAudit, Request, isnew);
            return Ok(task);
        }

        private string CheckIfKpiIdentifierExists(string kpiUniqueId, int id, string custId)
        {
            int count = 0;
            if (id > 0)
                count = CSPdb.KPI.GetAll().Count(x => x.KPI_UNIQUEID == kpiUniqueId && x.ID != id && x.CUSTOMER_ID == custId);
            else
                count = CSPdb.KPI.GetAll().Count(x => x.KPI_UNIQUEID == kpiUniqueId && x.CUSTOMER_ID == custId);
            if (count > 0)
                return string.Format(kpiIdentifierConflictMsg, kpiUniqueId);
            else
                return string.Empty;
        }

        private List<int> getServiceTowersMappedToKpi(int kpiId)
        {
            var kpiServiceTowerMapping = Cldb.KPI_SERVICETOWER_MAPPING.GetAll().Where(x => x.KPI_ID == kpiId && x.ISACTIVE).Select(x => x.SERVICE_TOWER_ID);
            var serviceTowers = new List<int>();
            if (kpiServiceTowerMapping != null && kpiServiceTowerMapping.Count() > 0)
            {
                foreach (int st in kpiServiceTowerMapping)
                    serviceTowers.Add(st);
            }
            return serviceTowers;
        }

        private string getServiceTowerNamesCSVMappedToKpi(int kpiId)
        {
            var kpiServiceTowerMapping = Cldb.KPI_SERVICETOWER_MAPPING.GetAll().Where(x => x.KPI_ID == kpiId && x.ISACTIVE).Select(x => x.SERVICE_TOWER_ID);
            var serviceTowerIds = new List<int>();
            if (kpiServiceTowerMapping != null && kpiServiceTowerMapping.Count() > 0)
            {
                foreach (int st in kpiServiceTowerMapping)
                    serviceTowerIds.Add(st);
            }
            else
                return string.Empty;
            var serviceTowers = CSPdb.PROCESS_SERVICE_AREA_NEW.GetAll().Where(x => serviceTowerIds.Contains(x.ID)).OrderBy(x => x.TITLE);
            var opCsv = string.Join(", ", serviceTowers.Select(x => x.TITLE));
            return opCsv;
        }
        private string CheckIfServiceTowerMappedToKpi(int? serviceTowerId, string projId = null)
        {
            int count = 0;
            var kpiServiceTowerMapping = Cldb.KPI_SERVICETOWER_MAPPING.GetAll().Where(x => x.SERVICE_TOWER_ID == serviceTowerId && x.ISACTIVE).Select(x => x.KPI_ID);

            var kpis = new List<int>();
            if (kpiServiceTowerMapping != null && kpiServiceTowerMapping.Count() > 0)
            {
                foreach (int kt in kpiServiceTowerMapping)
                    kpis.Add(kt);

                if (string.IsNullOrEmpty(projId))
                    count = CSPdb.KPI.GetAll().Count(x => x.ISACTIVE && kpis.Contains(x.ID));
                else
                    count = CSPdb.KPI.GetAll().Count(x => x.PROJECT_ID == projId && x.ISACTIVE && kpis.Contains(x.ID));

                if (count > 0)
                {
                    dynamic listKpis = new List<string>();
                    if (string.IsNullOrEmpty(projId))
                        listKpis = CSPdb.KPI.GetAll().Where(x => x.ISACTIVE && kpis.Contains(x.ID)).Select(x => x.KPI_NAME);
                    else
                        listKpis = CSPdb.KPI.GetAll().Where(x => x.PROJECT_ID == projId && x.ISACTIVE && kpis.Contains(x.ID)).Select(x => x.KPI_NAME);
                    var kpiCSV = string.Join(", ", listKpis);
                    var serviceTower = CSPdb.PROCESS_SERVICE_AREA_NEW.GetById(serviceTowerId).TITLE;
                    return string.Format(serviceTowerKpiConflictMsg, serviceTower, kpiCSV);
                }
            }
            return string.Empty;
        }








