        [POST("GetSpData")]
        [ActionName("GetSpData")]
        [HttpPost]

        public IHttpActionResult GetSpData(HttpRequestMessage request)
        {
            var stopwatch = Stopwatch.StartNew();
            string spName = this.GetHeaderDetails_String("spname");
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            List<REPORTS_PARAMS> lstParams = JsonConvert.DeserializeObject<List<REPORTS_PARAMS>>(json);
            bool hasStartDate = lstParams.Any(p => p.PARAM_TYPE == "DATE");
            if (hasStartDate)
            {
                var startDateParam = lstParams.FirstOrDefault(p => p.PARAM_NAME == "StartDate");
                var endDateParam = lstParams.FirstOrDefault(p => p.PARAM_NAME == "EndDate");

                if (startDateParam != null && endDateParam != null && DateTime.TryParse(startDateParam.PARAM_VALUE, out DateTime sdate) &&
                    DateTime.TryParse(endDateParam.PARAM_VALUE, out DateTime edate) &&
                    sdate > edate)
                {
                    return Content(HttpStatusCode.Conflict, "Please select end date greater than the start date");
                }
            }

            if (lstParams.Any())
            {
                Cldb.REPORTS_PARAMS.Update(lstParams);
                Cldb.Commit(CanCommit);
            }
            DataTable td = Cldb.AppRepo.GetTable(spName, lstParams);
            var reportId = lstParams.Select(x => x.REPORT_SP_ID);
            var reportName = Cldb.REPORTS_SP_DETAILS.GetAll().FirstOrDefault(x => x.SP_NAME == spName)?.SP_DISPLAY_NAME;
            var reportNameInDB = helper.GetDBConfig("PORTFOLIO_WISE_REPORTS", "-1");
            if (reportNameInDB == reportName)
            {
                td.Columns.Add("KPI_ACTUAL");
                td.Columns.Add("SLA_STATUS");
                foreach (DataRow row in td.Rows)
                {
                    var result = GetSLAStatus(row.Field<int>("FORMULA_ID"), 0, row.Field<decimal?>("KPI_NUMERATOR"),
                        row.Field<decimal?>("KPI_DENOMINATOR"), row.Field<string>("FORMULA"), row.Field<decimal>("EXPECTED_SERVICE_LEVEL"), row.Field<decimal>("MINIMUM_SERVICE_LEVEL"));
                    row["KPI_ACTUAL"] = result.Item1;
                    row["SLA_STATUS"] = result.Item2;

                }
                td.Columns.Remove("FORMULA_ID");
                td.Columns.Remove("FORMULA");
            }
            FillResponseTime(stopwatch);
            return Ok(td);
        }


