        [POST("AddAuditSchedule")]
        [ActionName("AddAuditSchedule")]
        [HttpPost]
        public IHttpActionResult AddAuditSchedule(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            AUDIT_SCHEDULE audit = JsonConvert.DeserializeObject<AUDIT_SCHEDULE>(json);

            if (audit != null)
            {
                audit.SCHEDULED_DATE = audit.SCHEDULED_DATE.HasValue ? audit.SCHEDULED_DATE.Value.ToLocalTime() : audit.SCHEDULED_DATE.GetValueOrDefault();
                if (audit.ID > 0)
                    CSPdb.AUDIT_SCHEDULE.Update(audit);
                else
                    CSPdb.AUDIT_SCHEDULE.Add(audit);
                CSPdb.Commit(CanCommit);
                ////
                helper.DeleteAuditScheduleRef(audit.ID);

                List<AUDIT_SCHEDULE_REF> AuditRef = new List<AUDIT_SCHEDULE_REF>();
                if (audit.AUDITEE_EMP_ID != null)
                {
                    foreach (string i in audit.AUDITEE_EMP_ID)
                    {
                        AuditRef.Add(helper.getNewAuditRef(audit, "AUDITEE_EMP_ID", i.ToString()));
                    }
                }
                if (audit.SERVICE_AREA_ID != null)
                {
                    foreach (int i in audit.SERVICE_AREA_ID)
                    {
                        AuditRef.Add(helper.getNewAuditRef(audit, "SERVICE_AREA_ID", i.ToString()));
                    }
                }
                CSPdb.AUDIT_SCHEDULE_REF.AddList(AuditRef);
                CSPdb.Commit(CanCommit);
            }
            return Ok(audit);
        }



