        [POST("AddRisk")]
        [ActionName("AddRisk")]
        [HttpPost]
        public IHttpActionResult AddRisk(HttpRequestMessage request)
        {
            var stopwatch = Stopwatch.StartNew();
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            PROJECT_RISK results = JsonConvert.DeserializeObject<PROJECT_RISK>(json);


            AddRiskInternal(results);
            FillResponseTime(stopwatch);
            return Ok();
        }



        [POST("AddValueadds")]
        [ActionName("AddValueadds")]
        [HttpPost]
        public IHttpActionResult AddValueadds(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;

            dynamic json = jsonContent;

            var results = JsonConvert.DeserializeObject<PROJECT_VALUEADDS>(json);

            string projid = ((PROJECT_VALUEADDS)results).PROJECT_ID;

            PROJECT_VALUEADDS overview = new PROJECT_VALUEADDS();

            if (results != null)
            {
                overview.PROJECT_ID = results.PROJECT_ID;
                overview.RAG = results.RAG;
                overview.DESCRIPTION = results.DESCRIPTION;
                overview.BENEFITS = results.BENEFITS;
                overview.VALUEADD_BY = results.VALUEADD_BY;
                overview.STATUS = results.STATUS;
                overview.ACTION_PLAN = results.ACTION_PLAN;
                overview.TARGET_DATE = results.TARGET_DATE;
                overview.CREATED_BY = results.CREATED_BY;
                overview.CREATED_DATE = DateTime.Now;
                overview.UPDATED_BY = results.CREATED_BY;
                overview.UPDATED_DATE = DateTime.Now;
                overview.ISACTIVE = true;
                CSPdb.PROJECT_VALUEADDS.Add(overview);
                CSPdb.Commit(CanCommit);
                UpdateRag(projid, ragCategory.valueadds, results.RAG, results.CREATED_BY);
                UpdateLastUpdatedDetails(results.PROJECT_ID, results.CREATED_BY);
            }
            return Ok(overview);
        }
        [POST("AddActionitem")]
        [ActionName("AddActionitem")]
        [HttpPost]
        public IHttpActionResult AddActionitem(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;

            dynamic json = jsonContent;

            var results = JsonConvert.DeserializeObject<PROJECT_ACTIONITEM>(json);

            string projid = ((PROJECT_ACTIONITEM)results).PROJECT_ID;

            PROJECT_ACTIONITEM overview = new PROJECT_ACTIONITEM();

            if (results != null)
            {
                overview.PROJECT_ID = results.PROJECT_ID;
                overview.RAG = results.RAG;
                overview.DESCRIPTION = results.DESCRIPTION;
                overview.SOURCE = results.SOURCE;
                overview.OWNER = results.OWNER;
                overview.PRIORITY = results.PRIORITY;
                overview.IDENTIFIED_DATE = results.IDENTIFIED_DATE;
                overview.TARGET_DATE = results.TARGET_DATE;
                overview.STATUS = results.STATUS;
                overview.COMPLETION_DATE = results.COMPLETION_DATE;
                overview.COMMENTS = results.COMMENTS;
                overview.CREATED_BY = results.CREATED_BY;
                overview.CREATED_DATE = DateTime.Now;
                overview.UPDATED_BY = results.CREATED_BY;
                overview.UPDATED_DATE = DateTime.Now;
                overview.ISACTIVE = true;
                CSPdb.PROJECT_ACTIONITEM.Add(overview);
                CSPdb.Commit(CanCommit);
                UpdateRag(projid, ragCategory.actionitem, results.RAG, results.CREATED_BY);
                UpdateLastUpdatedDetails(results.PROJECT_ID, results.CREATED_BY);
            }

            //AddActionItem Mail_Start

            var project = Cldb.PROJECT.GetAll().FirstOrDefault(x => x.PROJ_ID == overview.PROJECT_ID);

            if (project == null)
                return Ok(results);


            //spliting to email address

            string csmMails = helper.GetCSMMailsFromProject(project);
            string pmMails = helper.GetPMMailsFromProject(project);
            string subject = string.Empty;
            string statusMsg = string.Empty;
            string mailContent;

            string tomail = pmMails;
            string ccmail = helper.GetDBConfig("CSS_LINK_CC", "-1");
            var qualitySpoc = helper.GetQualitySpocMailForProject(project);


            string customerName = string.Empty;
            string projectName = string.Empty;

            var customer = Cldb.CUSTOMER.GetAll().FirstOrDefault(t => t.CUST_ID == project.CUST_ID);
            customerName = customer?.CUST_NM;
            projectName = project.PROJ_NM;


            subject = $"New Action Item Identified - Project: {projectName}; Customer: {customerName}";
            ccmail = helper.ConcatEmails(new List<string>() { ccmail, csmMails, qualitySpoc });

            Dictionary<string, string> EmailContentValues = new Dictionary<string, string>();
            EmailContentValues.Add("Project Name", projectName);
            EmailContentValues.Add("Description", overview.DESCRIPTION);
            EmailContentValues.Add("Source", overview.SOURCE);
            EmailContentValues.Add("Owner", overview.OWNER);
            EmailContentValues.Add("Priority", overview.PRIORITY);
            EmailContentValues.Add("Identified Date", overview.IDENTIFIED_DATE.ToLocalTime().ToString(_dateformat));
            EmailContentValues.Add("Target Date", overview.TARGET_DATE.GetValueOrDefault().ToLocalTime().ToString(_dateformat));
            EmailContentValues.Add("Status", overview.STATUS);
            EmailContentValues.Add("Completion Date", !overview.COMPLETION_DATE.HasValue ? "-" : overview.COMPLETION_DATE.GetValueOrDefault().ToLocalTime().ToString(_dateformat));

            EmailContentValues.Add("Comments", string.IsNullOrWhiteSpace(overview.COMMENTS) ? "-" : overview.COMMENTS);

            mailContent = helper.GetEmailContent("AddActionItem.htm", EmailContentValues);

            var ep = new EmailProvider(Cldb, CSPdb);
            if (string.IsNullOrWhiteSpace(tomail)) tomail = _email;
            ep.SendEmail
                (
                new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                new EmailContent { from = _email, to = tomail, cc = ccmail, content = mailContent, subject = subject, hasAttachments = false, attachmentFilePath = "", ProjId = overview.PROJECT_ID },
                Request
                );

            //AddActionItem Mail_End

            LoadActionItemsDetails();
            return Ok(overview);
        }

