        [GET("GetAllPortfolioProjectList")]
        [ActionName("GetAllPortfolioProjectList")]
        [HttpGet]
        public IHttpActionResult GetAllPortfolioProjectList(string custid, bool AllProjects = false)
        {
            var empId = GetHeaderDetails_String("empId");

            var allowedProjs = GetProjectListForUser(empId, custid);

            var query = (from x in Cldb.PROJECT.GetAll().ToList()
                         join y in CSPdb.PORTFOLIO_PROJECT.GetAll().ToList()
                         on x.PROJ_ID equals y.PROJ_ID
                         where x.CUST_ID == custid && x.PROJ_ID == x.PARENT_PROJ_ID && allowedProjs.Any(a => a.PROJ_ID == x.PROJ_ID)
                         select new
                         {
                             portfolio_id = y.PORTFOLIO_ID,
                             proj_id = x.PROJ_ID,
                             proj_nm = !string.IsNullOrWhiteSpace(x.PROJ_ALIAS_NM) ? x.PROJ_ALIAS_NM : x.PROJ_NM
                         }).OrderBy(x => x.proj_nm).ToList();

            return Ok(query);
        }

