        [POST("AddProcessFile")]
        [ActionName("AddProcessFile")]
        [HttpPost]
        public HttpResponseMessage AddProcessFile()
        {
            HttpResponseMessage response = new HttpResponseMessage();
            var httpRequest = HttpContext.Current.Request;
            if (httpRequest.Files.Count > 0)
            {
                foreach (string file in httpRequest.Files)
                {
                    var postedFile = httpRequest.Files[file];
                    string ServerFileName = Guid.NewGuid().ToString() + System.IO.Path.GetExtension(postedFile.FileName);
                    string contentType = postedFile.ContentType;
                    var filePath = HttpContext.Current.Server.MapPath("~/UploadFile/" + ServerFileName);
                    string jsonProcess = AddProcessFile(postedFile.FileName, ServerFileName, contentType);
                    postedFile.SaveAs(filePath);


                    //Mail Part

                    string category = null;
                    if (Request.Headers.Contains("REPORT_CATEGORY"))
                        category = Request.Headers.GetValues("REPORT_CATEGORY").ToList()[0];
                    string PROJECT_ID = Request.Headers.GetValues("PROJECT_ID").ToList()[0];

                    string filename = postedFile.FileName;


                    var project = Cldb.PROJECT.GetAll().FirstOrDefault(x => x.PROJ_ID == PROJECT_ID);

                    if (project != null)

                    {
                        //spliting to email address

                        string csmMails = helper.GetCSMMailsFromProject(project);
                        string pmMails = helper.GetPMMailsFromProject(project);
                        string subject = string.Empty;
                        string statusMsg = string.Empty;
                        string mailContent;

                        string tomail = pmMails;
                        string ccmail = helper.GetDBConfig("CSS_LINK_CC", "-1");
                        var qualitySpoc = helper.GetQualitySpocMailForProject(project);


                        string customerName = string.Empty;
                        string projectName = string.Empty;

                        var customer = Cldb.CUSTOMER.GetAll().FirstOrDefault(t => t.CUST_ID == project.CUST_ID);
                        customerName = customer?.CUST_NM;
                        projectName = project.PROJ_NM;


                        subject = $"New Process Identified - Project: {projectName}; Customer: {customerName}";
                        ccmail = helper.ConcatEmails(new List<string>() { ccmail, csmMails, qualitySpoc });

                        Dictionary<string, string> EmailContentValues = new Dictionary<string, string>();
                        EmailContentValues.Add("Project Name", projectName);
                        EmailContentValues.Add("File Name", Path.GetFileNameWithoutExtension(filename));
                        EmailContentValues.Add("File Name Server", ServerFileName);
                        EmailContentValues.Add("File Extension", Path.GetExtension(filename));
                        EmailContentValues.Add("Report Type", Request.Headers.GetValues("REPORT_TYPE").ToList()[0]);
                        EmailContentValues.Add("Category", string.IsNullOrWhiteSpace(category) ? "-" : category);
                        EmailContentValues.Add("Publish Date", Request.Headers.GetValues("PUBLISH_DATE").ToList()[0]);

                        mailContent = helper.GetEmailContent("AddProcess.htm", EmailContentValues);
                        var ep = new EmailProvider(Cldb, CSPdb);
                        if (string.IsNullOrWhiteSpace(tomail)) tomail = _email;
                        //ep.SendEmail
                        //    (
                        //    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                        //    new EmailContent { from = _email, to = tomail, cc = ccmail, content = mailContent, subject = subject, hasAttachments = true, attachmentFilePath = filePath },
                        //    Request
                        //    );

                    }

                    //


                    response = new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent(jsonProcess, System.Text.Encoding.UTF8, "application/json") };
                }
            }
            return response;
        }



