        private void DeleteSQAReportData(int reportId, DataTable dtInput)
        {
            SQA_PROJECT_REPORTS_STRUCT DateFieldRow = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().Where(t => t.REPORT_ID == reportId && t.CHART_FIELD_NAME == "Created Date").FirstOrDefault();
            if (DateFieldRow != null)
            {
                try
                {
                    DataView dv = dtInput.DefaultView;
                    dv.RowFilter = "[" + DateFieldRow.FIELD_DISPLAY_NAME + "] <> ''";
                    dv.Sort = DateFieldRow.FIELD_DISPLAY_NAME;
                    DataTable sortedDT = dv.ToTable();
                    DateTime StartDate = Convert.ToDateTime(sortedDT.Rows[0][DateFieldRow.FIELD_DISPLAY_NAME].ToString());
                    DateTime EndDate = Convert.ToDateTime(sortedDT.Rows[sortedDT.Rows.Count - 1][DateFieldRow.FIELD_DISPLAY_NAME].ToString());
                    if (sortedDT.Rows.Count > 0)
                        CSPdb.AppRepo.Delete_SQA_DATA_REPOSITORY(reportId, DateFieldRow.FIELD_DISPLAY_NAME, StartDate, EndDate);
                }
                catch (Exception)
                {
                }
            }
        }
        private void AddSQAReportData(int reportId, DataTable dtInput)
        {

            DeleteSQAReportData(reportId, dtInput);

            List<SQA_DATA_REPOSITORY> records = new List<SQA_DATA_REPOSITORY>();
            foreach (DataRow row in dtInput.Rows)
            {
                string guid = Guid.NewGuid().ToString();

                foreach (DataColumn column in dtInput.Columns)
                {
                    if (column.ColumnName.ToLower() == "created on")
                    {
                        var val = row[column.ColumnName].ToString();
                    }
                    SQA_DATA_REPOSITORY data = new SQA_DATA_REPOSITORY()
                    {
                        REPORT_ID = reportId,
                        ROW_ID = guid,
                        FIELD_NAME = column.ColumnName,
                        FIELD_VALUE = row[column.ColumnName].ToString().Replace(@"""", "")
                    };
                    records.Add(data);
                }
            }
            if (records.Count > 0)
            {
                CSPdb.AppRepo.Insert_SQA_DATA_REPOSITORY(this.ToDataTable(records));
            }
        }


