        [POST("AddProjectComplainceDetails")]
        [ActionName("AddProjectComplainceDetails")]
        [HttpPost]
        public HttpResponseMessage AddProjectComplainceDetails()
        {
            HttpResponseMessage response = new HttpResponseMessage();
            var httpRequest = HttpContext.Current.Request;
            if (httpRequest.Files.Count > 0)
            {

                foreach (string file in httpRequest.Files)
                {
                    var postedFile = httpRequest.Files[file];
                    string contentType = postedFile.ContentType;
                    var createPath = HttpContext.Current.Server.MapPath("~/ProcessComplainceFile");
                    if (!Directory.Exists(createPath))
                    {
                        Directory.CreateDirectory(createPath);
                    }
                    var filePath = HttpContext.Current.Server.MapPath("~/ProcessComplainceFile/" + postedFile.FileName);
                    postedFile.SaveAs(filePath);
                    string excelConnectionString = string.Format("Provider=Microsoft.ACE.OLEDB.12.0;Data Source={0};Extended Properties=Excel 12.0", filePath);
                    string id = Request.Headers.GetValues("ID").ToList()[0];
                    string jsonProcess;
                    COMPLIANCE_TRAINING_ASSESSMENT_RESULT ctar = new COMPLIANCE_TRAINING_ASSESSMENT_RESULT();
                    List<COMPLIANCE_TRAINING_ASSESSMENT_RESULT> ctarlist = new List<COMPLIANCE_TRAINING_ASSESSMENT_RESULT>();
                    using (OleDbConnection connection = new OleDbConnection())
                    {
                        connection.ConnectionString = excelConnectionString;
                        OleDbCommand command = new OleDbCommand("select * from [Worksheet$]", connection);
                        connection.Open();
                        // Create DbDataReader to Data Worksheet
                        DbDataReader dr = command.ExecuteReader();

                        // SQL Server Connection String
                        string sqlConnectionString = ConfigurationManager.ConnectionStrings["DefaultConnection"].ConnectionString;
                        // Bulk Copy to SQL Server 
                        //SqlConnection conn = new SqlConnection();
                        using (SqlConnection conn = new SqlConnection())
                        {
                            conn.ConnectionString = sqlConnectionString;
                            SqlCommand cmd = new SqlCommand("CREATE TABLE #Test1([Employee Code][int] NULL,[Name][varchar](100) NULL,[Date of Completion][datetime] NULL,[Attempted][int] NULL, [Correct Answers][int] NULL,[Marks Scored][int] NULL,[Percentage][decimal](18, 0) NULL,[Result][varchar](10) NULL)", conn);
                            conn.Open();
                            cmd.ExecuteNonQuery();

                            SqlBulkCopy bulkInsert = new SqlBulkCopy(conn);
                            bulkInsert.DestinationTableName = "#Test1";
                            bulkInsert.WriteToServer(dr);
                            var directoryPath = HttpContext.Current.Server.MapPath("~/ProcessComplainceFile");
                            string selectString = "SELECT " + id + ",[Employee Code],[Name],[Date of Completion],[Attempted],[Correct Answers],[Marks Scored],[Percentage],[Result],getdate(),[Employee Code] FROM #Test1";
                            SqlCommand comm = new SqlCommand(selectString, conn);
                            SqlDataAdapter sda = new SqlDataAdapter(comm);
                            DataSet ds = new DataSet();
                            sda.Fill(ds);

                            if (ds != null && ds.Tables.Count > 0)
                            {
                                foreach (DataRow r in ds.Tables[0].Rows)
                                {
                                    var insertQuery = "INSERT INTO COMPLIANCE_TRAINING_ASSESSMENT_RESULT([TITLE_ID], [EMP_ID], [EMP_NAME],[DATE_OF_COMPLETION],[ATTEMPTED],[CORRECT_ANSWERS],[TOTAL_MARKS],[TOTAL_PERCENTAGE],[RESULT],[IMPORT_DATE],[IMPORTED_BY]) " +
                                                       "VALUES('" + id + "'," + r["Employee Code"] + ",'" + r["Name"] + "','" + r["Date of Completion"] + "'," + r["Attempted"] + "," + r["Correct Answers"] + "," + r["Marks Scored"] + "," + r["Percentage"] + ",'" + r["Result"] + "','" + DateTime.Now.ToString() + "'," + r["Employee Code"] + ")";
                                    using (var mergeCommand = new SqlCommand(insertQuery, conn))
                                    {
                                        try
                                        {
                                            mergeCommand.ExecuteNonQuery();
                                            ctar = Cldb.COMPLIANCE_TRAINING_ASSESSMENT_RESULT.GetAll().OrderByDescending(t => t.ID).FirstOrDefault();
                                            ctarlist.Add(ctar);
                                            jsonProcess = Newtonsoft.Json.JsonConvert.SerializeObject(ctarlist);
                                            response = new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent(jsonProcess, System.Text.Encoding.UTF8, "application/json") };
                                        }

                                        catch (Exception)
                                        {
                                            //return this.Request.CreateResponse(HttpStatusCode.NotImplemented, ex);
                                            //string result = "Duplicate values not copied to the table.";
                                            response = new HttpResponseMessage(HttpStatusCode.NotImplemented)
                                            {
                                                Content = new StringContent("Duplicate values not copied to the table", System.Text.Encoding.UTF8, "application/text")
                                            };
                                        }

                                    }

                                }
                                conn.Close();
                                connection.Close();
                            }
                        }
                        //conn = null;
                        if ((System.IO.File.Exists(filePath)))
                        {
                            System.IO.File.Delete(filePath);
                        }
                        //if ((System.IO.Directory.Exists(directoryPath)))
                        //{
                        //    System.IO.Directory.Delete(directoryPath, true);
                        //}
                    }

                }

            }
            return response;
        }

        [POST("GetSQAProjectChart")]
        [ActionName("GetSQAProjectChart")]
        [HttpPost]
        public IHttpActionResult GetSQAProjectChart(HttpRequestMessage request)
        {
            Object chart;
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            SQA_PROJECT_CHART_PARAMS_WITH_FILTER ChartParams = JsonConvert.DeserializeObject<SQA_PROJECT_CHART_PARAMS_WITH_FILTER>(json);

            if (ChartParams.CHART_TYPE == "Pareto")
                chart = GetParetoChart(ChartParams);
            else if ((ChartParams.GROUP_BY_LEVEL1 == null || ChartParams.GROUP_BY_LEVEL1 == "") && (ChartParams.GROUP_BY_LEVEL2 == null || ChartParams.GROUP_BY_LEVEL2 == ""))
                chart = GetLineChart(ChartParams);
            else
                chart = GetProjectChart(ChartParams);
            return Ok(chart);
        }
        private HighChartsPareto GetParetoChart(SQA_PROJECT_CHART_PARAMS_WITH_FILTER ChartParams)
        {

            HighChartsPareto chart = new HighChartsPareto();
            string yAxis = string.Empty;
            //xAxis
            //xAxis = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().Where(t => t.REPORT_ID == ChartParams.REPORT_TYPE_ID && t.CHART_FIELD_NAME == ChartParams.XAXIS_TYPE).FirstOrDefault().FIELD_DISPLAY_NAME;
            string xAxis = string.Empty;
            var xField = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().Where(t => t.REPORT_ID == ChartParams.DATA_DUMP_ID && t.CHART_FIELD_NAME == ChartParams.XAXIS_TYPE).FirstOrDefault();
            if (xField == null)
            {
                chart.title.text = ChartParams.TITLE + "Field '" + ChartParams.XAXIS_TYPE + "' is not mapped for this project's data dump";
                return chart;
            }
            else
                xAxis = xField.FIELD_DISPLAY_NAME;


            if (ChartParams.YAXIS_TYPE.ToLower() != "count")
            {
                //yAxis = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().Where(t => t.REPORT_ID == ChartParams.DATA_DUMP_ID && t.CHART_FIELD_NAME == ChartParams.YAXIS_TYPE).FirstOrDefault().FIELD_DISPLAY_NAME;
                var yField = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().Where(t => t.REPORT_ID == ChartParams.DATA_DUMP_ID && t.CHART_FIELD_NAME == ChartParams.YAXIS_TYPE).FirstOrDefault();
                if (yField == null)
                {
                    chart.title.text = ChartParams.TITLE + "Field '" + ChartParams.XAXIS_TYPE + "' is not mapped for this project's data dump";
                    return chart;
                }
                else
                    yAxis = yField.FIELD_DISPLAY_NAME;
            }
            else
                yAxis = ChartParams.YAXIS_TYPE.ToLower();

            var result = this.CSPdb.AppRepo.GetChartDetails(GetChartDateField(ChartParams), xAxis, yAxis, "", "", "", "", ChartParams.DATA_DUMP_ID, ChartParams.START_DATE.ToLocalTime(), ChartParams.END_DATE.ToLocalTime(), ChartParams.FilterXmlString());

            result = result.OrderByDescending(t => int.Parse(t.yAxis));


            //Chart
            chart.chart.renderTo = "container";
            //Title
            chart.title.text = ChartParams.TITLE;
            //xAxis
            chart.xAxis.categories = result.Select(t => t.xAxis).ToList<string>();
            chart.xAxis.crosshair = true;
            //yAxis
            HighChartsParetoyAxis1 y1 = new HighChartsParetoyAxis1();
            y1.title.text = "";
            HighChartsParetoyAxis2 y2 = new HighChartsParetoyAxis2();
            y2.title.text = "";
            y2.labels.format = "{value}%";
            chart.yAxis.Add(y1);
            chart.yAxis.Add(y2);
            //series
            chart.series.Add(new HighChartsParetoySeries1() { type = "pareto", name = "Cumulative%", yAxis = 1, zIndex = 10, baseSeries = 1 });
            chart.series.Add(new HighChartsParetoySeries2() { type = "column", name = xAxis, zIndex = 2, data = result.Select(t => decimal.Parse(t.yAxis)).ToList<decimal>() });
            return chart;
        }

        private string GetChartDateField(SQA_PROJECT_CHART_PARAMS ChartParams)
        {
            string dateField = string.Empty;

            SQA_PROJECT_REPORTS_STRUCT xAxis = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().Where(t => t.REPORT_ID == ChartParams.DATA_DUMP_ID && t.CHART_FIELD_NAME == ChartParams.XAXIS_TYPE).FirstOrDefault();
            SQA_PROJECT_REPORTS_STRUCT yAxis = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().Where(t => t.REPORT_ID == ChartParams.DATA_DUMP_ID && t.CHART_FIELD_NAME == ChartParams.YAXIS_TYPE).FirstOrDefault();
            SQA_PROJECT_REPORTS_STRUCT defaultDateField = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().Where(t => t.REPORT_ID == ChartParams.DATA_DUMP_ID && t.CHART_FIELD_NAME == "Created Date").FirstOrDefault();
            if (xAxis != null && xAxis.DATA_TYPE == "datetime")
                dateField = xAxis.FIELD_NAME;
            else if (yAxis != null && yAxis.DATA_TYPE == "datetime")
                dateField = yAxis.FIELD_NAME;
            else
                dateField = defaultDateField.FIELD_NAME;

            return dateField;
        }
        private HighChartsLine GetLineChart(SQA_PROJECT_CHART_PARAMS_WITH_FILTER ChartParams)
        {
            List<ChartDataMonthly> result = this.GetChartDetailsFromDB(ChartParams);

            HighChartsLine chart = new HighChartsLine();
            if (result != null && result.Count > 0 && result[0].xAxis == "Error")
            {
                chart.title = new title() { text = ChartParams.TITLE, style = new style() { color = "#333333", fontSize = "20px" } };
                chart.subtitle.text = result[0].yAxis;
                return chart;
            }
            //Chart
            string charttype = "line";
            if (ChartParams.CHART_TYPE == "Bar")
                charttype = "column";
            else if (ChartParams.CHART_TYPE == "Line")
                charttype = "line";
            //chart.chart.polar = false;

            //Title
            chart.title.text = ChartParams.TITLE;
            chart.title.style = new style() { color = "#333333", fontSize = "20px" };
            chart.xAxis.gridLineWidth = 1;
            //Plot Options
            chart.plotOptions.series.dataLabels.enabled = true;


            //Series Actual
            seriesItem item = new seriesItem();
            item.type = charttype;
            item.name = ChartParams.XAXIS_TYPE;
            item.width = 1;
            string yAxisTitle = ChartParams.YAXIS_LABLE;
            foreach (ChartDataMonthly d in result)
            {
                item.data.Add(Convert.ToDecimal(d.yAxis));
                chart.xAxis.categories.Add(d.xAxis);
            }

            if (ChartParams.TARGET != null)
            {
                seriesItem target = new seriesItem();
                target.name = "Target";
                target.color = "#63be7b";
                target.width = 1;
                foreach (ChartDataMonthly d in result)
                    target.data.Add(Convert.ToDecimal(ChartParams.TARGET));
                chart.series.Add(target);
            }

            chart.series.Add(item);
            chart.yAxis = new yAxis();
            chart.yAxis.tickInterval = 20;
            chart.yAxis.title.text = yAxisTitle;
            chart.yAxis.gridLineWidth = 1;

            return chart;
        }
        private List<ChartDataMonthly> GetChartDetailsFromDB(SQA_PROJECT_CHART_PARAMS_WITH_FILTER ChartParams)
        {
            List<ChartDataMonthly> result = new List<ChartDataMonthly>();
            string xAxis = string.Empty;
            string yAxis = string.Empty;
            string level1 = string.Empty;
            string level2 = string.Empty;
            //Data Dump
            if (ChartParams.DATA_DUMP_ID == -1)
                return GetChartDataDumpNotFound(ChartParams.DATA_DUMP_TYPE);
            //xAaxis
            var xField = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().FirstOrDefault(t => t.REPORT_ID == ChartParams.DATA_DUMP_ID && t.CHART_FIELD_NAME == ChartParams.XAXIS_TYPE);
            if (xField == null)
                return GetChartFieldNotFound(ChartParams.XAXIS_TYPE);
            else
                xAxis = xField.FIELD_DISPLAY_NAME;

            //yAxis
            if (ChartParams.YAXIS_TYPE.ToLower() != "count")
            {
                var yField = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().FirstOrDefault(t => t.REPORT_ID == ChartParams.DATA_DUMP_ID && t.CHART_FIELD_NAME == ChartParams.YAXIS_TYPE);
                if (yField == null)
                    return GetChartFieldNotFound(ChartParams.YAXIS_TYPE);
                else
                    yAxis = yField.FIELD_DISPLAY_NAME;
            }
            else
                yAxis = ChartParams.YAXIS_TYPE.ToLower();
            //Level 1
            if (ChartParams.GROUP_BY_LEVEL1 != null && ChartParams.GROUP_BY_LEVEL1 != string.Empty)
            {
                var Level1Field = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().FirstOrDefault(t => t.REPORT_ID == ChartParams.DATA_DUMP_ID && t.CHART_FIELD_NAME == ChartParams.GROUP_BY_LEVEL1);
                if (Level1Field == null)
                    return GetChartFieldNotFound(ChartParams.GROUP_BY_LEVEL1);
                else
                    level1 = Level1Field.FIELD_DISPLAY_NAME;
            }
            //Level 2
            if (ChartParams.GROUP_BY_LEVEL2 != null && ChartParams.GROUP_BY_LEVEL2 != string.Empty)
            {
                //level2 = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().Where(t => t.REPORT_ID == ChartParams.REPORT_TYPE_ID && t.CHART_FIELD_NAME == ChartParams.GROUP_BY_LEVEL2).FirstOrDefault().FIELD_DISPLAY_NAME;
                var Level2Field = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().FirstOrDefault(t => t.REPORT_ID == ChartParams.DATA_DUMP_ID && t.CHART_FIELD_NAME == ChartParams.GROUP_BY_LEVEL2);
                if (Level2Field == null)
                    return GetChartFieldNotFound(ChartParams.GROUP_BY_LEVEL2);
                else
                    level2 = Level2Field.FIELD_DISPLAY_NAME;
            }


            SQA_PROJECT_REPORTS_STRUCT reportStruct = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().Where(t => t.REPORT_ID == ChartParams.DATA_DUMP_ID && t.FIELD_NAME == xAxis).FirstOrDefault();
            string xAxisDataType = "datetime";
            if (reportStruct != null)
                xAxisDataType = reportStruct.DATA_TYPE;

            result = this.CSPdb.AppRepo.GetChartDetails(GetChartDateField(ChartParams), xAxis, yAxis, level1, level2, xAxisDataType, ChartParams.FREQUENCY, ChartParams.DATA_DUMP_ID, ChartParams.START_DATE.ToLocalTime(), ChartParams.END_DATE.ToLocalTime(), ChartParams.FilterXmlString()).ToList<ChartDataMonthly>();


            return result;
        }

        private List<ChartDataMonthly> GetChartFieldNotFound(string FieldName)
        {
            return new List<ChartDataMonthly>() { new ChartDataMonthly() { xAxis = "Error", yAxis = "Field '" + FieldName + "' is not mapped for this project's data dump", GroupBy = "" } };
        }
        private List<ChartDataMonthly> GetChartDataDumpNotFound(string DataDumpType)
        {
            return new List<ChartDataMonthly>() { new ChartDataMonthly() { xAxis = "Error", yAxis = "Data Dump type '" + DataDumpType + "' is not added for this project", GroupBy = "" } };
        }

        private HighChartsColumn GetProjectChart(SQA_PROJECT_CHART_PARAMS_WITH_FILTER ChartParams)
        {
            List<ChartDataMonthly> result = this.GetChartDetailsFromDB(ChartParams);

            HighChartsColumn chart = new HighChartsColumn();

            if (result != null && result.Count > 0 && result[0].xAxis == "Error")
            {
                chart.title = new title() { text = ChartParams.TITLE, style = new style() { color = "#333333", fontSize = "20px" } };
                chart.subtitle.text = result[0].yAxis;
                return chart;
            }
            var xAxisDistinct = result.Select(t => t.xAxis).Distinct().ToList();
            List<DateTime> DateDistinct = new List<DateTime>();
            if (ChartParams.XAXIS_TYPE == "Created Date")
                DateDistinct = xAxisDistinct.Select(t => DateTime.Parse(t)).OrderBy(t => t).ToList();


            var monthDetails = this.CSPdb.AppRepo.GetMonthDetails(ChartParams.START_DATE.ToLocalTime(), ChartParams.END_DATE.ToLocalTime());

            var Level1 = result.Select(t => t.GroupBy).Distinct();



            //Chart
            if (ChartParams.CHART_TYPE == "Bar")
                chart.chart.type = "column";
            else
                chart.chart.type = ChartParams.CHART_TYPE.ToLower();

            //chart.chart.polar = false;
            chart.plotOptions.series.dataLabels.enabled = true;
            chart.title = new title() { text = ChartParams.TITLE, style = new style() { color = "#333333", fontSize = "20px" } };
            if (ChartParams.XAXIS_TYPE == "Created Date")
                chart.xAxis.categories = DateDistinct.Select(t => t.ToString("dd-MMM-yyy")).ToList();
            else
                chart.xAxis.categories = result.OrderBy(t => t.xAxis).Select(u => u.xAxis).Distinct().ToList();

            chart.yAxis = new yAxisOnlyWithTitle();
            chart.yAxis.title.text = ChartParams.YAXIS_LABLE;
            chart.series = new List<seriesItem>();
            foreach (string c in Level1)
            {
                List<int> idata = new List<int>();
                foreach (string d in xAxisDistinct)
                {
                    ChartDataMonthly entry = result.Where(t => t.GroupBy == c && t.xAxis == d).FirstOrDefault();
                    if (entry == null)
                        idata.Add(0);
                    else
                        idata.Add(Convert.ToInt32(entry.yAxis));
                }

                List<decimal> sdata = new List<decimal>();
                foreach (int i in idata)
                    sdata.Add(i);
                seriesItem s = new seriesItem() { name = c, data = sdata };
                chart.series.Add(s);
            }

            if (ChartParams.TARGET != null)
            {
                seriesItem target = new seriesItem();
                target.type = "line";
                target.name = "Target";
                target.color = "#63be7b";
                target.width = 3;
                foreach (MonthDetails d in monthDetails)
                    target.data.Add(Convert.ToDecimal(ChartParams.TARGET));
                chart.series.Add(target);
            }
            return chart;


        }





