        List<GroupCharts> _groupCharts = new List<GroupCharts>();
        [POST("GetSQAGroupCharts")]
        [ActionName("GetSQAGroupCharts")]
        [HttpPost]
        public IHttpActionResult GetSQAGroupCharts(HttpRequestMessage request)
        {
            string projectId = Request.Headers.GetValues("ProjectId").ToList()[0];
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            SQA_CHART_GROUPS parameters = JsonConvert.DeserializeObject<SQA_CHART_GROUPS>(json);

            List<SQA_PROJECT_CHART_PARAMS> chartParams = CSPdb.SQA_PROJECT_CHART_PARAMS.GetAll().Where(t => t.CATEGORY == parameters.GROUP_ID && t.ISACTIVE == true).OrderBy(t => t.CATEGORY).ThenBy(t => t.SUBCATEGORY).ThenBy(t => t.TITLE).ToList();
            if (chartParams.Count == 0)
                return BadRequest("No Charts built for this Analysis");

            foreach (SQA_PROJECT_CHART_PARAMS c in chartParams)
            {
                c.START_DATE = parameters.START_DATE.ToLocalTime();
                c.END_DATE = parameters.END_DATE.ToLocalTime();
                if (c.PROJECT_ID != projectId)
                {

                    SQA_PROJECT_REPORTS reports = CSPdb.SQA_PROJECT_REPORTS.GetAll().Where(t => t.DATA_DUMP_TYPE.Contains(c.DATA_DUMP_TYPE) && t.PROJECT_ID == projectId).OrderByDescending(x => x.ID).FirstOrDefault();
                    if (reports != null)
                        c.DATA_DUMP_ID = reports.ID;
                    else
                        c.DATA_DUMP_ID = -1;
                }
            }

            //Group by Perspective
            List<GroupCharts> groupCharts = new List<GroupCharts>();
            var results = chartParams.GroupBy(t => t.SUBCATEGORY);

            //foreach (var group in results)
            //{
            //    groupCharts.Add(new GroupCharts() { GroupName = group.Key, Charts = GetChartFromParams(GetSQAChartParamsWithFilter(group.ToList())) });
            //}
            //return Ok(groupCharts);

            foreach (var group in results)
            {
                groupCharts.Add(new GroupCharts() { GroupName = group.Key, Params = group.ToList(), Charts = new List<object>() });
            }
            return Ok(groupCharts);
        }

        private void AddChartToGroup(string groupName, List<SQA_PROJECT_CHART_PARAMS> chartParams)
        {
            _groupCharts.Add(new GroupCharts() { GroupName = groupName, Charts = GetChartFromParams(GetSQAChartParamsWithFilter(chartParams)) });
        }

