        {
            public string GroupName { get; set; }
            public List<object> Charts { get; set; }
            public List<SQA_PROJECT_CHART_PARAMS> Params { get; set; }
        }

        [POST("GetSQAGroupChartsForProject")]
        [ActionName("GetSQAGroupChartsForProject")]
        [HttpPost]
        public IHttpActionResult GetSQAGroupChartsForProject(HttpRequestMessage request)
        {
            string projectId = Request.Headers.GetValues("ProjectId").ToList()[0];
            string startDate = Request.Headers.GetValues("startDate").ToList()[0];
            string endDate = Request.Headers.GetValues("endDate").ToList()[0];
            string chartUser = Request.Headers.GetValues("chartUser").ToList()[0];
            string category = Request.Headers.GetValues("category").ToList()[0];
            string subcategory = Request.Headers.GetValues("subcategory").ToList()[0];

            List<SQA_PROJECT_CHART_PARAMS> chartParams = new List<SQA_PROJECT_CHART_PARAMS>();
            if (chartUser == "SYSTEM")
                chartParams = CSPdb.SQA_PROJECT_CHART_PARAMS.GetAll().Where(t => t.CHART_USER == chartUser && t.CATEGORY == category && t.ISACTIVE == true).OrderBy(t => t.CATEGORY).ThenBy(t => t.SUBCATEGORY).ThenBy(t => t.TITLE).ToList();
            else
                chartParams = CSPdb.SQA_PROJECT_CHART_PARAMS.GetAll().Where(t => t.PROJECT_ID == projectId && t.CATEGORY == category && t.ISACTIVE == true).OrderBy(t => t.CATEGORY).ThenBy(t => t.SUBCATEGORY).ThenBy(t => t.TITLE).ToList();

            if (chartParams.Count == 0)
                return BadRequest("No Charts built for this Analysis");

            //Report Type
            if (chartUser == "SYSTEM")
            {
                string ErrorMessages = string.Empty;
                foreach (SQA_PROJECT_CHART_PARAMS c in chartParams)
                {
                    c.START_DATE = Convert.ToDateTime(startDate).ToLocalTime();
                    c.END_DATE = Convert.ToDateTime(endDate).ToLocalTime();

                    SQA_PROJECT_REPORTS reports = CSPdb.SQA_PROJECT_REPORTS.GetAll().Where(t => t.DATA_DUMP_TYPE.Contains(c.DATA_DUMP_TYPE) && t.PROJECT_ID == projectId).OrderByDescending(x => x.ID).FirstOrDefault();

                    if (reports != null)
                        c.DATA_DUMP_ID = reports.ID;
                    else
                        c.DATA_DUMP_ID = -1;
                    //ErrorMessages += "Data (" + c.DATA_DUMP_TYPE + ") not available for chart " + c.TITLE + "\n";
                }
            }
            List<object> charts = GetChartFromParams(GetSQAChartParamsWithFilter(chartParams));
            return Ok(charts);
        }

