        private List<SQA_PROJECT_CHART_PARAMS_WITH_FILTER> GetSQAChartParamsWithFilter(List<SQA_PROJECT_CHART_PARAMS> chartParams)
        {
            List<SQA_PROJECT_CHART_PARAMS_WITH_FILTER> chartsWithFilter = new List<SQA_PROJECT_CHART_PARAMS_WITH_FILTER>();
            foreach (SQA_PROJECT_CHART_PARAMS c in chartParams)
            {
                string s = JsonConvert.SerializeObject(c);
                SQA_PROJECT_CHART_PARAMS_WITH_FILTER cf = JsonConvert.DeserializeObject<SQA_PROJECT_CHART_PARAMS_WITH_FILTER>(s);
                cf.FILTERS = CSPdb.SQA_CHART_FILTER.GetAll().Where(t => t.CHART_ID == c.ID && t.ISACTIVE == true).ToList();
                chartsWithFilter.Add(cf);
            }
            return chartsWithFilter;
        }
        private SQA_PROJECT_CHART_PARAMS_WITH_FILTER GetSQAChartParamsWithFilter(SQA_PROJECT_CHART_PARAMS chartParam)
        {
            string s = JsonConvert.SerializeObject(chartParam);
            SQA_PROJECT_CHART_PARAMS_WITH_FILTER chartsWithFilter = JsonConvert.DeserializeObject<SQA_PROJECT_CHART_PARAMS_WITH_FILTER>(s);
            chartsWithFilter.FILTERS = CSPdb.SQA_CHART_FILTER.GetAll().Where(t => t.CHART_ID == chartParam.ID && t.ISACTIVE == true).ToList();
            return chartsWithFilter;
        }

        [POST("GetSQAChartFromParams")]
        [ActionName("GetSQAChartFromParams")]
        [HttpPost]
        public IHttpActionResult GetSQAChartFromParams(HttpRequestMessage request)
        {
            var stopwatch = Stopwatch.StartNew();
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            SQA_PROJECT_CHART_PARAMS chartParams = JsonConvert.DeserializeObject<SQA_PROJECT_CHART_PARAMS>(json);
            object chart = GetChartFromParams(GetSQAChartParamsWithFilter(chartParams));
            FillResponseTime(stopwatch);
            return Ok(chart);
        }
        private List<object> GetChartFromParams(List<SQA_PROJECT_CHART_PARAMS_WITH_FILTER> chartParams)
        {
            List<object> charts = new List<object>();
            foreach (SQA_PROJECT_CHART_PARAMS_WITH_FILTER param in chartParams)
            {
                if (param.CHART_TYPE == "Pareto")
                    charts.Add(GetParetoChart(param));
                else if ((param.GROUP_BY_LEVEL1 == null || param.GROUP_BY_LEVEL1 == "") && (param.GROUP_BY_LEVEL2 == null || param.GROUP_BY_LEVEL2 == ""))
                    charts.Add(GetLineChart(param));
                else
                    charts.Add(GetProjectChart(param));
            }
            return charts;
        }
        private object GetChartFromParams(SQA_PROJECT_CHART_PARAMS_WITH_FILTER chartParams)
        {
            if (chartParams.CHART_TYPE == "Pareto")
                return GetParetoChart(chartParams);
            else if ((chartParams.GROUP_BY_LEVEL1 == null || chartParams.GROUP_BY_LEVEL1 == "") && (chartParams.GROUP_BY_LEVEL2 == null || chartParams.GROUP_BY_LEVEL2 == ""))
                return GetLineChart(chartParams);
            else
                return GetProjectChart(chartParams);
        }

        private DataTable GetDataTableFromReportType(int ReportTypeId)
        {
            DataTable tb = new DataTable();

            List<SQA_PROJECT_REPORTS_STRUCT> ReportStrut = CSPdb.SQA_PROJECT_REPORTS_STRUCT.GetAll().Where(t => t.REPORT_ID == ReportTypeId).ToList<SQA_PROJECT_REPORTS_STRUCT>();
            foreach (SQA_PROJECT_REPORTS_STRUCT col in ReportStrut)
            {
                if (col.CHART_FIELD_NAME != string.Empty && col.CHART_FIELD_NAME != null)
                    tb.Columns.Add(new DataColumn(col.CHART_FIELD_NAME, GetDataType(col.DATA_TYPE)));
            }
            return tb;
        }
        private Type GetDataType(string DataType)
        {
            if (DataType == "int")
                return typeof(int);
            else if (DataType == "datetime")
                return typeof(DateTime);
            else if (DataType == "bit")
                return typeof(Boolean);
            else
                return typeof(string);
        }
