        [POST("AddEngagementReportFile")]
        [ActionName("AddEngagementReportFile")]
        [HttpPost]
        public HttpResponseMessage AddEngagementReportFile()
        {
            HttpResponseMessage response = new HttpResponseMessage();
            var httpRequest = HttpContext.Current.Request;
            if (httpRequest.Files.Count > 0)
            {
                foreach (string file in httpRequest.Files)
                {
                    var postedFile = httpRequest.Files[file];
                    string ServerFileName = Guid.NewGuid().ToString() + System.IO.Path.GetExtension(postedFile.FileName);
                    string contentType = postedFile.ContentType;
                    var filePath = HttpContext.Current.Server.MapPath("~/UploadFile/" + ServerFileName);
                    string jsonProcess = AddEngagementReportFile(postedFile.FileName, ServerFileName, contentType);
                    postedFile.SaveAs(filePath);
                    response = new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent(jsonProcess, System.Text.Encoding.UTF8, "application/json") };
                }
            }
            return response;
        }

        [POST("AddSuccessFile")]
        [ActionName("AddSuccessFile")]
        [HttpPost]
        public HttpResponseMessage AddSuccessFile()
        {
            HttpResponseMessage response = new HttpResponseMessage();
            var httpRequest = HttpContext.Current.Request;
            if (httpRequest.Files.Count > 0)
            {
                foreach (string file in httpRequest.Files)
                {
                    var postedFile = httpRequest.Files[file];
                    string ServerFileName = Guid.NewGuid().ToString() + System.IO.Path.GetExtension(postedFile.FileName);
                    string contentType = postedFile.ContentType;
                    var filePath = HttpContext.Current.Server.MapPath("~/UploadFile/" + ServerFileName);
                    string jsonSuccess = AddSuccessFile(postedFile.FileName, ServerFileName, contentType);
                    postedFile.SaveAs(filePath);


                    //
                    string filename = postedFile.FileName;
                    string PROJECT_ID = Request.Headers.GetValues("PROJECT_ID").ToList()[0];

                    var project = Cldb.PROJECT.GetAll().FirstOrDefault(x => x.PROJ_ID == PROJECT_ID);
                    if (project != null)
                    {

                        //spliting to email address
                        string csmMails = helper.GetCSMMailsFromProject(project);
                        string pmMails = helper.GetPMMailsFromProject(project);
                        string subject = string.Empty;
                        string statusMsg = string.Empty;
                        string mailContent;

                        string tomail = pmMails;
                        string ccmail = helper.GetDBConfig("CSS_LINK_CC", "-1");
                        var qualitySpoc = helper.GetQualitySpocMailForProject(project);


                        string customerName = string.Empty;
                        string projectName = string.Empty;

                        var customer = Cldb.CUSTOMER.GetAll().FirstOrDefault(t => t.CUST_ID == project.CUST_ID);
                        customerName = customer?.CUST_NM;
                        projectName = project.PROJ_NM;

                        subject = $"New Success Identified - Project: {projectName}; Customer: {customerName}";
                        ccmail = helper.ConcatEmails(new List<string>() { ccmail, csmMails, qualitySpoc });

                        Dictionary<string, string> EmailContentValues = new Dictionary<string, string>();
                        EmailContentValues.Add("Project Name", projectName);
                        EmailContentValues.Add("File Name", Path.GetFileNameWithoutExtension(filename));
                        EmailContentValues.Add("File Extension", Path.GetExtension(filename));
                        EmailContentValues.Add("Report Type", Request.Headers.GetValues("REPORT_TYPE").ToList()[0]);
                        EmailContentValues.Add("Publish Date", Request.Headers.GetValues("PUBLISH_DATE").ToList()[0]);


                        mailContent = helper.GetEmailContent("AddSuccess.htm", EmailContentValues);
                        var ep = new EmailProvider(Cldb, CSPdb);
                        //if (string.IsNullOrWhiteSpace(tomail)) tomail = _email;
                        //ep.SendEmail
                        //    (
                        //    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                        //    new EmailContent { from = _email, to = tomail, cc = ccmail, content = mailContent, subject = subject, hasAttachments = true, attachmentFilePath = filePath },
                        //    Request
                        //    );

                    }
                    //

                    response = new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent(jsonSuccess, System.Text.Encoding.UTF8, "application/json") };


                }
            }
            return response;
        }

        [GET("GetCustomerContacts")]
        [ActionName("GetCustomerContacts")]
        [HttpGet]
        public IHttpActionResult GetCustomerContacts(string customerId)
        {
            var result = Cldb.AppRepo.GetCustomerContactsForAccount(customerId);
            var grouping = result.GroupBy(x => x.EMAIL_ID);
            var result1 = new List<CUSTOMER_CONTACTS>();
            foreach (var item in grouping)
            {
                result1.Add(new CUSTOMER_CONTACTS { EMAIL_ID = item.Key, DISPLAY_NAME = item.First().DISPLAY_NAME, IS_ACTIVE = true });
            }
            return Ok(result1);
        }

        [POST("CustomerProjects")]
        [ActionName("CustomerProjects")]
        [HttpPost]
        public IHttpActionResult AddCustomerProjects(HttpRequestMessage request)
        {
            LogRequest(null, "AddCustomerProjects");
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            string empId = Request.Headers.GetValues("empId").ToList()[0];

            CustomerProjects results = JsonConvert.DeserializeObject<CustomerProjects>(json);

            CUSTOMER_USERS cust = CSPdb.CUSTOMER_USERS.GetAll().FirstOrDefault(t => t.EMAILID.ToLower() == results.EMAILID);
            if (cust == null)
            {
                cust = new CUSTOMER_USERS()
                {
                    EMAILID = results.EMAILID,
                    DISPLAY_NAME = results.DISPLAY_NAME,
                    CREATED_BY = empId,
                    CREATED_DATE = DateTime.Now,
                    UPDATED_BY = empId,
                    UPDATED_DATE = DateTime.Now,
                    SPECIFIC_SURVEY_OPTED = results.SPECIFIC_SURVEY_OPTED,

                };
                CSPdb.CUSTOMER_USERS.Add(cust);
                CSPdb.Commit(CanCommit);
            }
            else
            {
                //Delete unwanted

                //DeleteCustomerProjects(results.EMAILID, results.CUST_ID, Convert.ToInt32(empId));//Delete Existing projects
                cust.EMAILID = results.EMAILID;
                cust.DISPLAY_NAME = results.DISPLAY_NAME;
                cust.UPDATED_BY = empId;
                cust.UPDATED_DATE = DateTime.Now;
                cust.SPECIFIC_SURVEY_OPTED = results.SPECIFIC_SURVEY_OPTED;
                CSPdb.CUSTOMER_USERS.Update(cust);
                CSPdb.Commit(CanCommit);
            }
            var newProjects = new List<CUSTOMER_PROJECTS>();
            var updatedProjects = new List<CUSTOMER_PROJECTS>();
            var originalProjects = new List<CUSTOMER_PROJECTS>();

            foreach (CUSTOMER_PROJECTS p in results.CUSTOMER_PROJECTS)
            {
                CUSTOMER_PROJECTS proj = CSPdb.CUSTOMER_PROJECTS.GetAll().FirstOrDefault(t => t.CUSTOMER_USER_ID == cust.ID && t.PROJ_ID == p.PROJ_ID);

                if (proj == null)
                {
                    var newProj = new CUSTOMER_PROJECTS()
                    {
                        ID = 0,
                        CUSTOMER_USER_ID = cust.ID,
                        CUST_ID = results.CUST_ID,
                        CUST_NM = results.CUST_NM,
                        PROJ_ID = p.PROJ_ID,
                        PROJ_NM = p.PROJ_NM,
                        CSAT_SURVEY = p.CSAT_SURVEY,
                        CSAT_FREQUENCY = p.CSAT_FREQUENCY,
                        REPORTING = p.REPORTING,
                        SPOC = p.SPOC
                    };
                    UpdateAuditFields(newProj);
                    CSPdb.CUSTOMER_PROJECTS.Add(newProj);
                    newProjects.Add(newProj);
                }
                else
                {
                    var originalProj = new CUSTOMER_PROJECTS
                    {
                        CUST_NM = proj.CUST_NM,
                        PROJ_NM = proj.PROJ_NM,
                        REPORTING = proj.REPORTING,
                        CSAT_SURVEY = proj.CSAT_SURVEY,
                        CSAT_FREQUENCY = proj.CSAT_FREQUENCY
                    };
                    originalProjects.Add(originalProj);
                    proj.SPOC = p.SPOC;
                    proj.REPORTING = p.REPORTING;
                    proj.CSAT_SURVEY = p.CSAT_SURVEY;
                    proj.CSAT_FREQUENCY = p.CSAT_FREQUENCY;
                    UpdateAuditFields(proj);
                    CSPdb.CUSTOMER_PROJECTS.Update(proj);
                    updatedProjects.Add(proj);
                }


            }
            if (results.ACSAT)
            {
                var existing = CSPdb.CUSTOMER_PROJECTS.GetAll().FirstOrDefault(x => x.CUST_ID == results.CUST_ID && x.CUSTOMER_USER_ID == cust.ID && x.PROJ_ID == null && x.ISACTIVE);
                if (existing != null)
                {

                    if (!results.ACSAT)
                    {
                        CSPdb.CUSTOMER_PROJECTS.Delete(existing);
                    }
                    else
                    {

                    }
                }
                else
                {
                    var newproj = new CUSTOMER_PROJECTS
                    {
                        CUSTOMER_USER_ID = cust.ID,
                        CUST_NM = results.CUST_NM,
                        PROJ_NM = results.CUST_NM,
                        CUST_ID = results.CUST_ID,
                        CSAT_SURVEY = true,
                        CSAT_FREQUENCY = "Half-Yearly",
                    };
                    UpdateAuditFields(newproj);
                    CSPdb.CUSTOMER_PROJECTS.Add(newproj);



                }
            }
            CSPdb.Commit(CanCommit);
            if (newProjects.Count > 0)
                SendNotificationToStakeholders(newProjects, results.EMAILID, results.DISPLAY_NAME, CRUD.Create, null);

            if (updatedProjects.Count > 0)
                SendNotificationToStakeholders(updatedProjects, cust.EMAILID, results.DISPLAY_NAME, CRUD.Update, originalProjects);

            //genereate css batch customers
            if (results.CUST_ID == PREMIER_CUSTOMER_ID)
            {
                var batch = CSPdb.CSS_BATCH_MONTHLY.GetAll().OrderByDescending(x => x.ID).Take(1);
                if (batch.Any())

                    GenerateMissingCustomerContactsPremier(batch.First().ID);
            }
            else
            {
                var batch = CSPdb.CSS_BATCHES.GetAll().Where(x => x.FREQUENCY.ToLower() == "quarterly").OrderByDescending(x => x.ID).Take(1);
                if (batch.Any())

                    GenerateMissingCustomerContacts(batch.First().ID);
            }
            return Ok();
        }

        [POST("Highlights")]
