        [POST("AddKPIGoal")]
        [ActionName("AddKPIGoal")]
        [HttpPost]
        public IHttpActionResult AddKPIGoal(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;

            KPI_GOALS u = JsonConvert.DeserializeObject<KPI_GOALS>(json);
            //check if goal already exists
            var isGoalExist = CSPdb.KPI_GOALS.GetAll().Any(t => t.CUSTOMER_ID == u.CUSTOMER_ID && t.PROJECT_ID == u.PROJECT_ID && t.ISACTIVE && t.DESCRIPTION.ToLower() == u.DESCRIPTION.ToLower());
            if (isGoalExist)
            {
                return Content(HttpStatusCode.Conflict, "KPI Goal already exists");
            }
            CSPdb.KPI_GOALS.Add(u);
            CSPdb.Commit(CanCommit);
            return Ok(u);
        }

        [POST("AddKPI")]
        [ActionName("AddKPI")]
        [HttpPost]
        public IHttpActionResult AddKPI(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            KPIWithTargets u = JsonConvert.DeserializeObject<KPIWithTargets>(json);
            var opMsg = CheckIfKpiIdentifierExists(u.KPI_UNIQUEID, -1, u.CUSTOMER_ID);
            if (!string.IsNullOrEmpty(opMsg))
                return Content(HttpStatusCode.Conflict, opMsg);
            KPI kpi = new KPI();
            kpi.CUSTOMER_ID = u.CUSTOMER_ID;
            kpi.PROJECT_ID = u.PROJECT_ID;
            kpi.GOAL_ID = u.GOAL_ID;
            kpi.SERVICE_AREA = u.SERVICE_AREA;
            kpi.ABBREVIATION = u.ABBREVIATION;
            kpi.KPI_NAME = u.KPI_NAME;
            kpi.SUPPORT_WINDOW = u.SUPPORT_WINDOW;
            kpi.FREQUENCY = u.FREQUENCY;
            kpi.PRIORITY = u.PRIORITY;
            kpi.SLA_TARGET_UNIT_OF_MEASUREMENT = u.SLA_TARGET_UNIT_OF_MEASUREMENT;
            kpi.DISPLAY_ORDER = u.DISPLAY_ORDER;
            kpi.CHART_TYPE = u.CHART_TYPE;
            kpi.SHOW_IN_CHART = u.SHOW_IN_CHART;
            kpi.GLOBAL_KPI_CATEGORY_ID = u.GLOBAL_KPI_CATEGORY_ID;
            kpi.IS_SOW_COMMITMENT = u.IS_SOW_COMMITMENT;
            kpi.CREATED_BY = u.CREATED_BY;
            kpi.CREATED_DATE = u.CREATED_DATE;
            kpi.UPDATED_BY = u.UPDATED_BY;
            kpi.UPDATED_DATE = u.UPDATED_DATE;
            kpi.ISACTIVE = u.ISACTIVE;
            kpi.KPI_UNIQUEID = u.KPI_UNIQUEID;
            kpi.KPI_MASTER_ID = u.KPI_MASTER_ID;
            CSPdb.KPI.Add(kpi);
            CSPdb.Commit(CanCommit);

            var kpiBaseMeasure = new SERVICE_LEVEL_MEASUREMENT_2_BASE_MEASURE_CONFIG();
            var exist = CSPdb.SERVICE_LEVEL_MEASUREMENT_2_BASE_MEASURE_CONFIG.GetAll().FirstOrDefault(x => x.KPI_ID == kpi.ID && x.ISACTIVE);
            var baseMeasure = Cldb.KPI_MASTER2BASE_MEASURE_CONFIG.GetAll().FirstOrDefault(x => x.KPI_MASTER_ID == kpi.KPI_MASTER_ID && x.ISACTIVE);
            if (exist != null)
            {
                kpiBaseMeasure.KPI_ID = kpi.ID;
                kpiBaseMeasure.BASE_MEASURE_ID = baseMeasure.BASE_MEASURE_ID;
                kpiBaseMeasure.MASTER_ID = kpi.KPI_MASTER_ID;
                UpdateAuditFields(kpiBaseMeasure);
                CSPdb.SERVICE_LEVEL_MEASUREMENT_2_BASE_MEASURE_CONFIG.Update(kpiBaseMeasure);
            }
            else
            {
                kpiBaseMeasure.KPI_ID = kpi.ID;
                kpiBaseMeasure.BASE_MEASURE_ID = baseMeasure.BASE_MEASURE_ID;
                kpiBaseMeasure.MASTER_ID = kpi.KPI_MASTER_ID;
                UpdateAuditFields(kpiBaseMeasure);
                CSPdb.SERVICE_LEVEL_MEASUREMENT_2_BASE_MEASURE_CONFIG.Add(kpiBaseMeasure);
            }
            CSPdb.Commit(CanCommit);

            foreach (KPI_TARGETS t in u.KPI_TARGETS)
            {
                KPI_TARGETS target = new KPI_TARGETS();
                target.KPI_ID = kpi.ID;
                target.START_DATE = t.START_DATE;
                target.END_DATE = t.END_DATE;
                target.SLA_TARGET_VERYHIGH_DESCRIPTION = t.SLA_TARGET_VERYHIGH_DESCRIPTION;
                target.SLA_TARGET_VERYHIGH_OPERATOR = t.SLA_TARGET_VERYHIGH_OPERATOR;
                target.SLA_TARGET_VERYHIGH_VALUE = t.SLA_TARGET_VERYHIGH_VALUE;
                target.SLA_TARGET_HIGH_DESCRIPTION = t.SLA_TARGET_HIGH_DESCRIPTION;
                target.SLA_TARGET_HIGH_OPERATOR = t.SLA_TARGET_HIGH_OPERATOR;
                target.SLA_TARGET_HIGH_VALUE = t.SLA_TARGET_HIGH_VALUE;
                target.SLA_TARGET_MEDIUM_DESCRIPTION = t.SLA_TARGET_MEDIUM_DESCRIPTION;
                target.SLA_TARGET_MEDIUM_OPERATOR = t.SLA_TARGET_MEDIUM_OPERATOR;
                target.SLA_TARGET_MEDIUM_VALUE = t.SLA_TARGET_MEDIUM_VALUE;
                target.SLA_TARGET_LOW_DESCRIPTION = t.SLA_TARGET_LOW_DESCRIPTION;
                target.SLA_TARGET_LOW_OPERATOR = t.SLA_TARGET_LOW_OPERATOR;
                target.SLA_TARGET_LOW_VALUE = t.SLA_TARGET_LOW_VALUE;
                target.CREATED_BY = u.CREATED_BY;
                target.CREATED_DATE = u.CREATED_DATE;
                target.UPDATED_BY = u.UPDATED_BY;
                target.UPDATED_DATE = u.UPDATED_DATE;
                target.ISACTIVE = u.ISACTIVE;
                CSPdb.KPI_TARGETS.Add(target);
            }
            CSPdb.Commit(CanCommit);

            UpdateKpiServiceTowerMapping(u.SERVICE_TOWER_ID, kpi.ID);
            return Ok();
        }

