        [POST("AddKPIDetails")]
        [ActionName("AddKPIDetails")]
        [HttpPost]
        public IHttpActionResult AddKPIDetails([FromBody] List<KPI_DetailMonthandWeekly> k)
        {
            var watch = Stopwatch.StartNew();
            LogRequest(prefix: "AddKPIDetails", content: JsonConvert.SerializeObject(k));
            string empId = Request.Headers.GetValues("empId").ToList()[0];
            KPI_DETAILS data = new KPI_DETAILS();

            foreach (KPI_DetailMonthandWeekly u in k)
            {
                if (u.KPI_Month.Count > 0)
                {
                    foreach (KPI_Month_List ml in u.KPI_Month)
                    {
                        foreach (KPI_DETAILS kd in ml.Monthly)
                        {
                            if (kd.ID == 0)
                            {
                                var existing = CSPdb.KPI_DETAILS.GetAll().Where(x => x.KPI_ID == kd.KPI_ID && x.PERIOD_TYPE == "Monthly" && x.PERIOD.Year == kd.PERIOD.Year && x.PERIOD.Month == kd.PERIOD.Month && x.ISACTIVE).ToList();
                                if (existing.Any())
                                    existing.ForEach(x => x.ISACTIVE = false);

                                data.PERIOD_TYPE = "Monthly";
                                data.PERIOD = kd.PERIOD;
                                data.KPI_ID = kd.KPI_ID;
                                data.KPI_ACTUAL = kd.KPI_ACTUAL;
                                data.HIGHLIGHTS = kd.HIGHLIGHTS;
                                data.ISFLAG = kd.ISFLAG;
                                data.KPI_METRIC = kd.KPI_METRIC;
                                data.SLA_STATUS = kd.SLA_STATUS;
                                data.BaseMeasureDataList = kd.BaseMeasureDataList;
                                data.CapaStage = kd.CapaStage;
                                UpdateAuditFields(data);
                                CSPdb.KPI_DETAILS.Add(data);
                                CSPdb.Commit(CanCommit);
                                AddBaseMeasure(data);
                                if (checkIfCAPARequired(data, false))
                                    AddCapaForKPIInternal(data.CapaStage, data, "", data.PERIOD, empId);
                            }
                            else
                            {
                                KPI_DETAILS overview = CSPdb.KPI_DETAILS.GetById(kd.ID);
                                if (overview != null && u != null)
                                {
                                    overview.PERIOD_TYPE = "Monthly";
                                    overview.KPI_ACTUAL = kd.KPI_ACTUAL;
                                    overview.KPI_METRIC = kd.KPI_METRIC;
                                    overview.HIGHLIGHTS = kd.HIGHLIGHTS;
                                    overview.ISFLAG = kd.ISFLAG;
                                    overview.PERIOD = kd.PERIOD;
                                    overview.SLA_STATUS = kd.SLA_STATUS;
                                    overview.BaseMeasureDataList = kd.BaseMeasureDataList;
                                    overview.CapaStage = kd.CapaStage;
                                    UpdateAuditFields(overview);
                                    CSPdb.KPI_DETAILS.Update(overview);
                                    CSPdb.Commit(CanCommit);
                                }
                                AddBaseMeasure(overview);
                                if (overview.SLA_STATUS == "Met" && overview.CapaStage.CAPA_SUBMISSION.CAPA.Count > 0)
                                    UpdateCAPAForKPI(overview.ID);
                                if (checkIfCAPARequired(overview, false))
                                    AddCapaForKPIInternal(overview.CapaStage, overview, "", overview.PERIOD, empId);
                            }
                        }
                    }
                }
            }

            foreach (KPI_DetailMonthandWeekly u in k)
            {
                if (u.KPI_Quaterly.Count > 0)
                {
                    foreach (KPI_Quarterly_List ql in u.KPI_Quaterly)
                    {
                        foreach (KPI_DETAILS kd in ql.Quarterly)
                        {
                            if (kd.ID == 0)
                            {
                                var existing = CSPdb.KPI_DETAILS.GetAll().Where(x => x.KPI_ID == kd.KPI_ID && x.PERIOD_TYPE == "Quarterly" && x.PERIOD.Year == kd.PERIOD.Year && x.PERIOD.Month == kd.PERIOD.Month && x.ISACTIVE).ToList();
                                if (existing.Any())
                                    existing.ForEach(x => x.ISACTIVE = false);

                                data = new KPI_DETAILS();
                                data.PERIOD_TYPE = "Quarterly";
                                data.PERIOD = kd.PERIOD;
                                data.KPI_ID = kd.KPI_ID;
                                data.KPI_ACTUAL = kd.KPI_ACTUAL;
                                data.HIGHLIGHTS = kd.HIGHLIGHTS;
                                data.ISFLAG = kd.ISFLAG;
                                data.KPI_METRIC = kd.KPI_METRIC;
                                data.SLA_STATUS = kd.SLA_STATUS;
                                data.BaseMeasureDataList = kd.BaseMeasureDataList;
                                data.CapaStage = kd.CapaStage;
                                UpdateAuditFields(data);
                                CSPdb.KPI_DETAILS.Add(data);
                                CSPdb.Commit(CanCommit);
                                AddBaseMeasure(data);
                                if (checkIfCAPARequired(data, false))
                                    AddCapaForKPIInternal(data.CapaStage, data, "", data.PERIOD, empId);
                            }
                            else
                            {
                                KPI_DETAILS overview = CSPdb.KPI_DETAILS.GetById(kd.ID);
                                if (overview != null && u != null)
                                {
                                    overview.PERIOD_TYPE = "Quarterly";
                                    overview.KPI_ACTUAL = kd.KPI_ACTUAL;
                                    overview.KPI_METRIC = kd.KPI_METRIC;
                                    overview.HIGHLIGHTS = kd.HIGHLIGHTS;
                                    overview.PERIOD = kd.PERIOD;
                                    overview.SLA_STATUS = kd.SLA_STATUS;
                                    overview.ISFLAG = kd.ISFLAG;
                                    overview.BaseMeasureDataList = kd.BaseMeasureDataList;
                                    overview.CapaStage = kd.CapaStage;
                                    UpdateAuditFields(overview);
                                    CSPdb.KPI_DETAILS.Update(overview);
                                    CSPdb.Commit(CanCommit);
                                }
                                AddBaseMeasure(overview);
                                if (overview.SLA_STATUS == "Met" && overview.CapaStage.CAPA_SUBMISSION.CAPA.Count > 0)
                                    UpdateCAPAForKPI(overview.ID);
                                if (checkIfCAPARequired(overview, false))
                                    AddCapaForKPIInternal(overview.CapaStage, overview, "", overview.PERIOD, empId);
                            }
                        }
                    }
                }
            }

            foreach (KPI_DetailMonthandWeekly u in k)
            {
                if (u.KPI_week.Count > 0)
                {
                    foreach (KPI_Week_List wl in u.KPI_week)
                    {
                        foreach (KPI_DETAILS kd in wl.Week1)
                        {
                            if (kd.ID == 0)
                            {
                                var existing = CSPdb.KPI_DETAILS.GetAll()
                                    .Where(x => x.KPI_ID == kd.KPI_ID && x.PERIOD_TYPE == "Week1" && x.PERIOD.Year == kd.PERIOD.Year && x.PERIOD.Month == kd.PERIOD.Month && x.ISACTIVE).ToList();
                                if (existing.Any())
