        private string GetLoopContent(List<PROJECT_ACTIONITEM> ai)
        {
            string loopcontent = "";
            string customername;
            string projectname;
            //string empName;
            foreach (PROJECT_ACTIONITEM a in ai)
            {
                //int empId = Convert.ToInt32(a.OWNER);
                customername = Cldb.CUSTOMER.GetAll().Where(t => t.CUST_ID == a.CUSTOMER_ID).Select(t => t.CUST_NM).FirstOrDefault();
                projectname = Cldb.PROJECT.GetAll().Where(t => t.PROJ_ID == a.PROJECT_ID).Select(t => t.PROJ_NM).FirstOrDefault();
                //empName = Cldb.EMP_INFO.GetAll().Where(t => t.EMP_ID == empId).Select(t => t.FRST_NM).FirstOrDefault();
                if (a.TARGET_DATE != null)
                {
                    loopcontent += "<tr><td> " + customername + "</td><td> " + projectname + "</td><td> " + a.COMMENTS + "</td>" +
                    "<td> " + a.DESCRIPTION + " </td><td> " + a.PRIORITY + " </td><td> " + a.OWNER + " </td><td> " + Convert.ToDateTime(a.TARGET_DATE).ToString("MM/dd/yyyy") + " </td></tr>";
                }
                else
                    loopcontent += "<tr><td> " + customername + "</td><td> " + projectname + "</td><td> " + a.COMMENTS + "</td>" +
                        "<td> " + a.DESCRIPTION + " </td><td> " + a.PRIORITY + " </td><td> " + a.OWNER + " </td><td>  </td></tr>";
            }
            return loopcontent;
        }
