        private List<PROJECT_ACTIONITEM> AddNewActionitem(MOM.MOM_DETAIL md, MOM u, string empId)
        {
            List<PROJECT_ACTIONITEM> ai = new List<PROJECT_ACTIONITEM>();
            List<string> projId = new List<string>();
            foreach (string p in md.CUSTOMER_ID)
            {
                string pid = p;// Convert.ToInt32(p);
                if (md.PROJECT_ID.Count == 0)
                {
                    PROJECT_ACTIONITEM pai = new PROJECT_ACTIONITEM();
                    pai.CUSTOMER_ID = pid;//Convert.ToInt32(p);
                    pai.DESCRIPTION = md.ACTION_ITEM;
                    pai.SOURCE = u.MEETING_DESCRIPTION;
                    pai.OWNER = GetEmployeeNamebyId(md.RESPONSIBILITY.ToString());
                    pai.PRIORITY = md.PRIORITY;
                    pai.IDENTIFIED_DATE = u.MEETING_DATE.ToLocalTime();
                    if (md.TARGET_DATE != null)
                        pai.TARGET_DATE = Convert.ToDateTime(md.TARGET_DATE).ToLocalTime();
                    pai.STATUS = "Open";
                    pai.COMMENTS = md.DISCUSSION_POINTS;
                    pai.CREATED_BY = empId;
                    pai.CREATED_DATE = DateTime.Now;
                    pai.UPDATED_BY = empId;
                    pai.UPDATED_DATE = DateTime.Now;
                    if (u.STATUS == "submit")
                        pai.ISACTIVE = true;
                    else
                        pai.ISACTIVE = false;
                    CSPdb.PROJECT_ACTIONITEM.Add(pai);
                    CSPdb.Commit(CanCommit);
                    ai.Add(pai);
                }
                else
                {
                    projId = Cldb.PROJECT.GetAll().Where(t => t.CUST_ID == pid).Select(t => t.PROJ_ID).ToList<string>();
                    foreach (string pp in md.PROJECT_ID)
                    {
                        if (projId.Contains(pp))
                        {
                            PROJECT_ACTIONITEM pai = new PROJECT_ACTIONITEM();
                            pai.CUSTOMER_ID = pid;// Convert.ToInt32(p);
                            pai.PROJECT_ID = pp;
                            pai.DESCRIPTION = md.ACTION_ITEM;
                            pai.SOURCE = u.MEETING_DESCRIPTION;
                            pai.OWNER = GetEmployeeNamebyId(md.RESPONSIBILITY.ToString());
                            pai.PRIORITY = md.PRIORITY;
                            pai.IDENTIFIED_DATE = u.MEETING_DATE.ToLocalTime();
                            if (md.TARGET_DATE != null)
                                pai.TARGET_DATE = Convert.ToDateTime(md.TARGET_DATE).ToLocalTime();
                            pai.STATUS = "Open";
                            pai.COMMENTS = md.DISCUSSION_POINTS;
                            pai.CREATED_BY = empId;
                            pai.CREATED_DATE = DateTime.Now;
                            pai.UPDATED_BY = empId;
                            pai.UPDATED_DATE = DateTime.Now;
                            if (u.STATUS == "submit")
                                pai.ISACTIVE = true;
                            else
                                pai.ISACTIVE = false;
                            CSPdb.PROJECT_ACTIONITEM.Add(pai);
                            CSPdb.Commit(CanCommit);
                            ai.Add(pai);
                        }
                    }
                }
            }
            return ai;
        }

