        [POST("AddBestPractices")]
        [ActionName("AddBestPractices")]
        [HttpPost]
        public IHttpActionResult AddBestPractices(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            string empId = Request.Headers.GetValues("empId").ToList()[0];
            dynamic json = jsonContent;
            PROJECT_BEST_PRACTICES_EXT results = JsonConvert.DeserializeObject<PROJECT_BEST_PRACTICES_EXT>(json);
            PROJECT_BEST_PRACTICES overview = new PROJECT_BEST_PRACTICES();
            if (results != null)
            {
                overview.REFERENCE_BEST_PRACTICE_ID = results.REFERENCE_BEST_PRACTICE_ID;
                overview.PROJECT_ID = results.PROJECT_ID;
                overview.DESCRIPTION = results.DESCRIPTION;
                overview.REPORTED_BY = results.REPORTED_BY;
                overview.REPORTED_DATE = results.REPORTED_DATE.ToLocalTime();
                overview.REVIEWED_BY = results.REVIEWED_BY;
                if (results.REVIEWED_DATE == null)
                    overview.REVIEWED_DATE = results.REVIEWED_DATE;
                else
                    overview.REVIEWED_DATE = results.REVIEWED_DATE.Value.ToLocalTime();

                overview.APPROVED_BY = results.APPROVED_BY;
                if (results.APPROVED_DATE == null)
                    overview.APPROVED_DATE = results.APPROVED_DATE;
                else
                    overview.APPROVED_DATE = results.APPROVED_DATE.Value.ToLocalTime();
                overview.SERVICE_AREA = results.SERVICE_AREA;
                overview.PROCESS_AREA = results.PROCESS_AREA;
                overview.PROCESS = results.PROCESS;
                if (results.TARGET_DATE == null)
                    overview.TARGET_DATE = results.TARGET_DATE;
                else
                    overview.TARGET_DATE = results.TARGET_DATE.Value.ToLocalTime();
                if (results.ACTUAL_DATE == null)
                    overview.ACTUAL_DATE = results.ACTUAL_DATE;
                else
                    overview.ACTUAL_DATE = results.ACTUAL_DATE.Value.ToLocalTime();
                overview.STATUS = results.STATUS;
                overview.REMARKS = results.REMARKS;
                overview.APPLICABLE_FOR = results.APPLICABLE_FOR;
                overview.NOT_APPLICABLE_FOR = results.NOT_APPLICABLE_FOR;
                overview.CREATED_BY = empId;
                overview.CREATED_DATE = DateTime.Now;
                overview.UPDATED_BY = empId;
                overview.UPDATED_DATE = DateTime.Now;
                overview.ISACTIVE = true;
                CSPdb.PROJECT_BEST_PRACTICES.Add(overview);
                CSPdb.Commit(CanCommit);
                results.ID = overview.ID;
            }
            return Ok(results);
        }
