        [POST("AddSubProject")]
        [ActionName("AddSubProject")]
        [HttpPost]
        public IHttpActionResult AddSubProject(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;

            dynamic json = jsonContent;

            SUBPROJECT results = JsonConvert.DeserializeObject<SUBPROJECT>(json);

            if (results != null)
            {
                if (results.ID == 0)
                {
                    SUBPROJECT overview = new SUBPROJECT();
                    overview.CUSTOMER_ID = results.CUSTOMER_ID;
                    overview.PROJECT_ID = results.PROJECT_ID;
                    overview.SUBPROJECT_NM = results.SUBPROJECT_NM;
                    overview.OBJECTIVES = results.OBJECTIVES;
                    overview.OWNER_ID = results.OWNER_ID;
                    overview.CREATED_BY = results.CREATED_BY;
                    overview.CREATED_DATE = DateTime.Now;
                    overview.UPDATED_BY = results.CREATED_BY;
                    overview.UPDATED_DATE = DateTime.Now;
                    overview.ISACTIVE = true;
                    CSPdb.SUBPROJECT.Add(overview);
                    try
                    {
                        CSPdb.Commit(CanCommit);
                    }
                    catch (Exception ex)
                    {
                        if (ex.InnerException != null && ex.InnerException.InnerException != null && ex.InnerException.InnerException.Message != null
                                                && ex.InnerException.InnerException.Message.ToLower().Contains("cannot insert duplicate key"))
                            return BadRequest("SubProject name already exists");
                    }
                }
                else
                {

                    SUBPROJECT overview = CSPdb.SUBPROJECT.GetById(results.ID);
                    overview.SUBPROJECT_NM = results.SUBPROJECT_NM;
                    overview.OBJECTIVES = results.OBJECTIVES;
                    overview.OWNER_ID = results.OWNER_ID;
                    overview.UPDATED_BY = results.UPDATED_BY;
                    overview.UPDATED_DATE = DateTime.Now;
                    overview.ISACTIVE = true;
                    CSPdb.SUBPROJECT.Update(overview);
                    CSPdb.Commit(CanCommit);
                }
            }
            return Ok();
        }
        [POST("AddProjectProcessConfig")]
        [ActionName("AddProjectProcessConfig")]
        [HttpPost]
        public IHttpActionResult AddProjectProcessConfig(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            string empId = Request.Headers.GetValues("empId").ToList()[0];
            //string empIds = empId;
            dynamic json = jsonContent;
            List<PROCESS_MODEL_DESCRIPTION> results = JsonConvert.DeserializeObject<List<PROCESS_MODEL_DESCRIPTION>>(json);
            string projId = results[0].SERVICE_AREA[0].PROCESS_NAME[0].PROJECT_ID;
            PROCESS_MODEL_PROJECT_CONFIG checkList = CSPdb.PROCESS_MODEL_PROJECT_CONFIG.GetAll().Where(t => t.PROJECT_ID == projId).FirstOrDefault();
            if (checkList != null)
            {
                CSPdb.AppRepo.DeleteProcessProjectConfig(projId);
            }
            foreach (PROCESS_MODEL_DESCRIPTION model in results)
            {
                foreach (SERVICE_AREA area in model.SERVICE_AREA)
                {
                    foreach (PROCESS_DESCRIPTION desc in area.PROCESS_NAME)
                    {
                        PROCESS_MODEL_PROJECT_CONFIG config = new PROCESS_MODEL_PROJECT_CONFIG();
                        config.CUSTOMER_ID = desc.CUSTOMER_ID;
                        config.PROJECT_ID = desc.PROJECT_ID;
                        config.PROCESS_MODEL_ID = desc.MODEL_ID;
                        config.SERVICE_AREA_ID = desc.AREA_ID;
                        config.DESCRIPITION_ID = desc.DESCRIPTION_ID;
                        config.APPLICABLE = desc.APPLICABLE;
                        config.CREATED_BY = empId;
                        config.CREATED_DATE = DateTime.Now;
                        config.UPDATED_BY = empId;
                        config.UPDATED_DATE = DateTime.Now;
                        config.ISACTIVE = true;
                        CSPdb.PROCESS_MODEL_PROJECT_CONFIG.Add(config);
                        CSPdb.Commit(CanCommit);
                    }
                }
            }
            return Ok();
        }
        [POST("SaveAuditExecDetails")]
        [ActionName("SaveAuditExecDetails")]
        [HttpPost]
        public IHttpActionResult SaveAuditExecDetails([FromBody] List<AUDIT_EXECUTION_MODEL> AuditData)
        {
            string empId = Request.Headers.GetValues("empId").FirstOrDefault();
            //string empIds = empId;
            List<AUDIT_EXECUTION_MODEL> resultList = new List<AUDIT_EXECUTION_MODEL>();

            foreach (var overview in AuditData)
            {
                if (overview.ISEVALUATED)
                {
                    AUDIT_EXECUTION_MODEL result = new AUDIT_EXECUTION_MODEL();
                    if (overview.AUDIT_EXECUTION_ID == 0)
                    {
                        int? exec = CSPdb.AUDIT_EXECUTION_MODEL.GetAll().OrderByDescending(t => t.ID).Select(t => t.AUDIT_EXECUTION_ID).FirstOrDefault();
                        if (exec == null)
                            exec = 0;
                        result.CUSTOMER_ID = overview.CUSTOMER_ID;
                        result.PROJECT_ID = overview.PROJECT_ID;
                        result.AUDIT_EXECUTION_ID = Convert.ToInt32((exec + 1));
                        result.AUDIT_START_DATE = overview.AUDIT_START_DATE;
                        result.AUDIT_TITLE = overview.AUDIT_TITLE;
                        result.AUDITOR_NAME = overview.AUDITOR_NAME;
                        result.AUDIT_END_DATE = overview.AUDIT_END_DATE;
                        result.AUDIT_PLAN_REFERENCE = overview.AUDIT_PLAN_REFERENCE;
                        result.TEST_ID = overview.TEST_ID;
                        result.TEST_RESULT = overview.TEST_RESULT;
                        result.STATUS_OF_CONTROL = overview.STATUS_OF_CONTROL;
                        result.RESULT_DESCRIPTION = overview.RESULT_DESCRIPTION;
                        result.FINDING_DESCRIPTION = overview.FINDING_DESCRIPTION;
                        result.FINDING_TYPE = overview.FINDING_TYPE;
                        result.SEVERITY = overview.SEVERITY;
                        result.STATUS_OF_AUDIT = overview.STATUS_OF_AUDIT;
                        result.CREATED_DATE = DateTime.Now;
                        result.CREATED_BY = empId;
                        result.UPDATED_DATE = DateTime.Now;
                        result.UPDATED_BY = empId;
                        result.ISACTIVE = true;
                        CSPdb.AUDIT_EXECUTION_MODEL.Add(result);
                        CSPdb.Commit(CanCommit);
                        result.AUDITEE_NAME = overview.AUDITEE_NAME;
                        result.IMPACTING_ATTRIBUTES = overview.IMPACTING_ATTRIBUTES;
                        SaveImpactingAttribues(result, result.IMPACTING_ATTRIBUTES);
                        SaveAuditeeDetails(result, result.AUDITEE_NAME);
                        result.ISEVALUATED = true;
                        resultList.Add(result);
                        AuditData.ForEach(x => x.AUDIT_EXECUTION_ID = result.AUDIT_EXECUTION_ID);
                    }
                    else
                    {
                        if (overview.ID == 0)
                        {
                            result.CUSTOMER_ID = overview.CUSTOMER_ID;
                            result.PROJECT_ID = overview.PROJECT_ID;
                            result.AUDIT_EXECUTION_ID = overview.AUDIT_EXECUTION_ID;
                            result.AUDIT_START_DATE = overview.AUDIT_START_DATE;
                            result.AUDIT_TITLE = overview.AUDIT_TITLE;
                            result.AUDITOR_NAME = overview.AUDITOR_NAME;
                            result.AUDIT_END_DATE = overview.AUDIT_END_DATE;
                            result.AUDIT_PLAN_REFERENCE = overview.AUDIT_PLAN_REFERENCE;
                            result.TEST_ID = overview.TEST_ID;
                            result.TEST_RESULT = overview.TEST_RESULT;
                            result.STATUS_OF_CONTROL = overview.STATUS_OF_CONTROL;
                            result.RESULT_DESCRIPTION = overview.RESULT_DESCRIPTION;
                            result.FINDING_DESCRIPTION = overview.FINDING_DESCRIPTION;
                            result.FINDING_TYPE = overview.FINDING_TYPE;
                            result.SEVERITY = overview.SEVERITY;
                            result.STATUS_OF_AUDIT = overview.STATUS_OF_AUDIT;
                            result.CREATED_DATE = DateTime.Now;
                            result.CREATED_BY = empId;
                            result.UPDATED_DATE = DateTime.Now;
                            result.UPDATED_BY = empId;
                            result.ISACTIVE = true;
                            CSPdb.AUDIT_EXECUTION_MODEL.Add(result);
                            CSPdb.Commit(CanCommit);
                            result.AUDITEE_NAME = overview.AUDITEE_NAME;
                            result.IMPACTING_ATTRIBUTES = overview.IMPACTING_ATTRIBUTES;
                            SaveImpactingAttribues(result, result.IMPACTING_ATTRIBUTES);
                            SaveAuditeeDetails(result, result.AUDITEE_NAME);
                            result.ISEVALUATED = true;
                            resultList.Add(result);
                        }
                        else
                        {
                            result = CSPdb.AUDIT_EXECUTION_MODEL.GetAll().Where(t => t.ID == overview.ID).FirstOrDefault();
                            result.CUSTOMER_ID = overview.CUSTOMER_ID;
                            result.PROJECT_ID = overview.PROJECT_ID;
                            result.AUDIT_START_DATE = overview.AUDIT_START_DATE;
                            result.AUDIT_EXECUTION_ID = overview.AUDIT_EXECUTION_ID;
                            result.AUDIT_TITLE = overview.AUDIT_TITLE;
                            result.AUDITOR_NAME = overview.AUDITOR_NAME;
                            result.AUDIT_END_DATE = overview.AUDIT_END_DATE;
                            result.AUDIT_PLAN_REFERENCE = overview.AUDIT_PLAN_REFERENCE;
                            result.TEST_ID = overview.TEST_ID;
                            result.TEST_RESULT = overview.TEST_RESULT;
                            result.STATUS_OF_CONTROL = overview.STATUS_OF_CONTROL;
                            result.RESULT_DESCRIPTION = overview.RESULT_DESCRIPTION;
                            result.FINDING_DESCRIPTION = overview.FINDING_DESCRIPTION;
                            result.FINDING_TYPE = overview.FINDING_TYPE;
                            result.SEVERITY = overview.SEVERITY;
                            result.STATUS_OF_AUDIT = overview.STATUS_OF_AUDIT;
                            result.CREATED_DATE = DateTime.Now;
                            result.CREATED_BY = empId;
                            result.UPDATED_DATE = DateTime.Now;
                            result.UPDATED_BY = empId;
                            result.ISACTIVE = true;
                            CSPdb.AUDIT_EXECUTION_MODEL.Update(result);
                            CSPdb.Commit(CanCommit);
                            result.AUDITEE_NAME = overview.AUDITEE_NAME;
                            result.IMPACTING_ATTRIBUTES = overview.IMPACTING_ATTRIBUTES;
                            SaveImpactingAttribues(result, result.IMPACTING_ATTRIBUTES);
                            SaveAuditeeDetails(result, result.AUDITEE_NAME);
                            result.ISEVALUATED = true;
                            resultList.Add(result);
                        }

                    }
                }
                else
                    resultList.Add(overview);
            }
            return Ok(resultList);

        }

        private void SaveImpactingAttribues(AUDIT_EXECUTION_MODEL mod, List<string> impacts)
        {
            List<EXECUTION_IMPACT_MAPPING> mappinglist = CSPdb.EXECUTION_IMPACT_MAPPING.GetAll().Where(t => t.AUDIT_ID == mod.AUDIT_EXECUTION_ID && t.TEST_ID == mod.TEST_ID).ToList<EXECUTION_IMPACT_MAPPING>();
            foreach (EXECUTION_IMPACT_MAPPING list in mappinglist)
            {
                CSPdb.EXECUTION_IMPACT_MAPPING.Delete(list);
            }
            foreach (string s in impacts)
            {

                EXECUTION_IMPACT_MAPPING mapping = new EXECUTION_IMPACT_MAPPING();
                mapping.AUDIT_ID = mod.AUDIT_EXECUTION_ID;
                mapping.TEST_ID = mod.TEST_ID;
                mapping.IMPACTING_ATTRIBUTES = s;
                mapping.CREATED_DATE = DateTime.Now;
                mapping.CREATED_BY = mod.CREATED_BY;
                mapping.UPDATED_DATE = DateTime.Now;
                mapping.UPDATED_BY = mod.UPDATED_BY;
                mapping.ISACTIVE = true;
                CSPdb.EXECUTION_IMPACT_MAPPING.Add(mapping);
                CSPdb.Commit(CanCommit);
            }
        }
        private void SaveAuditeeDetails(AUDIT_EXECUTION_MODEL mod, List<string> impacts)
        {
            List<AUDIT_EXECUTION_AUDITEE_DETAILS> mappinglist = CSPdb.AUDIT_EXECUTION_AUDITEE_DETAILS.GetAll().Where(t => t.AUDIT_EXECUTION_ID == mod.AUDIT_EXECUTION_ID).ToList<AUDIT_EXECUTION_AUDITEE_DETAILS>();
            foreach (AUDIT_EXECUTION_AUDITEE_DETAILS list in mappinglist)
            {
                CSPdb.AUDIT_EXECUTION_AUDITEE_DETAILS.Delete(list);
            }
            foreach (string s in impacts)
            {

                AUDIT_EXECUTION_AUDITEE_DETAILS mapping = new AUDIT_EXECUTION_AUDITEE_DETAILS();
                mapping.AUDIT_EXECUTION_ID = mod.AUDIT_EXECUTION_ID;
                mapping.AUDITEE_EMP_ID = s;
                mapping.CREATED_DATE = DateTime.Now;
                mapping.CREATED_BY = mod.CREATED_BY;
                mapping.UPDATED_DATE = DateTime.Now;
                mapping.UPDATED_BY = mod.UPDATED_BY;
                mapping.ISACTIVE = true;
                CSPdb.AUDIT_EXECUTION_AUDITEE_DETAILS.Add(mapping);
                CSPdb.Commit(CanCommit);
            }
        }

        [POST("AddCheckListExecution")]
        [ActionName("AddCheckListExecution")]
        [HttpPost]
        public IHttpActionResult AddCheckListExecution(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            string empId = Request.Headers.GetValues("empId").ToList()[0];
            //string empIds = empId;
            dynamic json = jsonContent;
            AUDIT_CHECKLIST_PROJECT_EXECUTION dummy = new AUDIT_CHECKLIST_PROJECT_EXECUTION();
            List<AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED> resultList = new List<AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED>();
            List<AUDIT_CHECKLIST_EXECUTION> results = JsonConvert.DeserializeObject<List<AUDIT_CHECKLIST_EXECUTION>>(json);
            int auditId = CSPdb.AUDIT_CHECKLIST_PROJECT_EXECUTION.GetAll().OrderByDescending(t => t.AUDIT_ID).Select(t => t.AUDIT_ID).FirstOrDefault();
            resultList = GetExecutionList(results);
            foreach (AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED res in resultList)
            {
                if (res.AUDIT_ID != 0)
                {
                    AUDIT_CHECKLIST_PROJECT_EXECUTION checkList = CSPdb.AUDIT_CHECKLIST_PROJECT_EXECUTION.GetAll().Where(t => t.AUDIT_ID == res.AUDIT_ID && t.APPLICABLE_QUESTIONS == res.APPLICABLE_QUESTIONS).FirstOrDefault();
                    checkList.AUDIT_TITLE = res.AUDIT_TITLE;
                    checkList.ACTUAL_AUDIT_START_DATE = res.ACTUAL_AUDIT_START_DATE;
                    checkList.ACTUAL_AUDIT_END_DATE = res.ACTUAL_AUDIT_END_DATE;
                    checkList.APPLICABLE_QUESTIONS = res.APPLICABLE_QUESTIONS;
                    checkList.AUDITOR_NAME = res.AUDITOR_NAME;
                    checkList.AUDIT_SCOPE = res.AUDIT_SCOPE;
                    checkList.AUDIT_PLANNED_HOURS = res.AUDIT_PLANNED_HOURS;
                    checkList.AUDIT_ACTUAL_HOURS = res.AUDIT_ACTUAL_HOURS;
                    checkList.STATUS = res.STATUS;
                    checkList.ISSUBMITTED = res.ISSUBMITTED;
                    checkList.NOTES = res.NOTES;
                    checkList.CREATED_BY = empId;
                    checkList.CREATED_DATE = DateTime.Now;
                    checkList.UPDATED_BY = empId;
                    checkList.UPDATED_DATE = DateTime.Now;
                    checkList.ISACTIVE = true;
                    CSPdb.AUDIT_CHECKLIST_PROJECT_EXECUTION.Update(checkList);
                    CSPdb.Commit(CanCommit);
                    SaveCheckListfindings(checkList, res);
                    SaveSampleAudits(checkList, res);
                    if (checkList.ISSUBMITTED == true)
                    {
                        //SaveLastUpdatedDetails(checkList, res);
                        SaveChecklistQuestionIsSubmitted(checkList.APPLICABLE_QUESTIONS);
                    }

                    dummy = checkList;
                }
                else
                {
                    AUDIT_CHECKLIST_PROJECT_EXECUTION checkList = new AUDIT_CHECKLIST_PROJECT_EXECUTION();
                    checkList.AUDIT_ID = (auditId + 1);
                    checkList.CUSTOMER_ID = res.CUSTOMER_ID;
                    checkList.PROJECT_ID = res.PROJECT_ID;
                    checkList.AUDIT_TITLE = res.AUDIT_TITLE;
                    checkList.ACTUAL_AUDIT_START_DATE = res.ACTUAL_AUDIT_START_DATE;
                    checkList.ACTUAL_AUDIT_END_DATE = res.ACTUAL_AUDIT_END_DATE;
                    checkList.APPLICABLE_QUESTIONS = res.APPLICABLE_QUESTIONS;
                    checkList.AUDITOR_NAME = res.AUDITOR_NAME;
                    checkList.AUDIT_SCOPE = res.AUDIT_SCOPE;
                    checkList.AUDIT_PLANNED_HOURS = res.AUDIT_PLANNED_HOURS;
                    checkList.AUDIT_ACTUAL_HOURS = res.AUDIT_ACTUAL_HOURS;
                    checkList.STATUS = res.STATUS;
                    checkList.NOTES = res.NOTES;
                    checkList.ISSUBMITTED = res.ISSUBMITTED;
                    checkList.CREATED_BY = empId;
                    checkList.CREATED_DATE = DateTime.Now;
                    checkList.UPDATED_BY = empId;
                    checkList.UPDATED_DATE = DateTime.Now;
                    checkList.ISACTIVE = true;
                    CSPdb.AUDIT_CHECKLIST_PROJECT_EXECUTION.Add(checkList);
                    CSPdb.Commit(CanCommit);
                    SaveCheckListfindings(checkList, res);
                    SaveSampleAudits(checkList, res);
                    if (checkList.ISSUBMITTED == true)
                    {
                        //SaveLastUpdatedDetails(checkList, res);
                        SaveChecklistQuestionIsSubmitted(checkList.APPLICABLE_QUESTIONS);
                    }

                    dummy = checkList;
                }

            }

            //if(resultList[0].ISSUBMITTED)
            //SendFindingMailDetails(dummy, resultList[0]);

            SaveCheckListAuditeeDetails(dummy, resultList[0]);
            return Ok();
        }

