        private List<AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED> GetExecutionList(List<AUDIT_CHECKLIST_EXECUTION> results)
        {
            List<AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED> resultList = new List<AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED>();
            foreach (AUDIT_CHECKLIST_EXECUTION res in results)
            {
                foreach (AUDIT_CHECKLIST_SERVICE_AREA area in res.PROCESS_AREA_DATA)
                {
                    foreach (PROCESS_DESC pro in area.PROCESS)
                    {
                        foreach (AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED detail in pro.CHECKPOINTS)
                        {
                            resultList.Add(detail);
                        }
                    }
                }
            }
            return resultList;
        }
        private List<AUDIT_CHECKLIST_PROJECT_FINDINGS> SaveCheckListfindings(AUDIT_CHECKLIST_PROJECT_EXECUTION exe, AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED result)
        {
            var output = new List<AUDIT_CHECKLIST_PROJECT_FINDINGS>();

            foreach (var rec in result.FINDINGS)
            {

                AUDIT_CHECKLIST_PROJECT_FINDINGS find = CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.GetAll().FirstOrDefault(t => t.AUDIT_ID == exe.AUDIT_ID && t.APPLICABLE_QUESTIONS == exe.APPLICABLE_QUESTIONS
                                                && t.PROCESS_ID == exe.PROCESS_ID && t.SERVICE_AREA_ID == exe.SERVICE_AREA_ID && t.PROCESS_MODEL_ID == exe.PROCESS_MODEL_ID
                                                && t.PROCESS_AREA_ID == exe.PROCESS_AREA_ID
                                                && t.FINDING_TYPE == rec.FINDING_TYPE && t.ISACTIVE);
                if (find != null)
                {
                    if (!string.IsNullOrEmpty(rec.FINDING_DESCRIPTION.Trim()))
                    {
                        find.FINDING_DESCRIPTION = rec.FINDING_DESCRIPTION;
                        find.FINDING_TYPE = rec.FINDING_TYPE;
                        find.UPDATED_DATE = DateTime.Now;
                        find.UPDATED_BY = exe.UPDATED_BY;
                        find.ISACTIVE = true;
                        find.SERVICE_AREA_ID = result.SERVICE_AREA_ID;
                        find.PROCESS_ID = result.PROCESS_ID;
                        find.PROCESS_MODEL_ID = result.PROCESS_MODEL_ID;
                        find.PROCESS_AREA_ID = result.PROCESS_AREA_ID;
                        if (result.ISSUBMITTED)
                            find.ISSUBMITTED = true;
                        else
                            find.ISSUBMITTED = false;
                        CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.Update(find);
                        CSPdb.Commit(CanCommit);
                        find.FINDING_CATEGORY = rec.FINDING_CATEGORY;
                        find.GO_CATEGORY = rec.GO_CATEGORY;
                        output.Add(find);
                    }
                    else
                    {
                        find.ISACTIVE = false;
                        find.ISSUBMITTED = false;
                        CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.Update(find);
                        CSPdb.Commit(CanCommit);
                        find.GO_CATEGORY = rec.GO_CATEGORY;
                    }

                }
                else
                {
                    if (!string.IsNullOrEmpty(rec.FINDING_DESCRIPTION.Trim()))
                    {
                        find = new AUDIT_CHECKLIST_PROJECT_FINDINGS();
                        find.AUDIT_ID = exe.AUDIT_ID;
                        find.APPLICABLE_QUESTIONS = exe.APPLICABLE_QUESTIONS;
                        find.FINDING_DESCRIPTION = rec.FINDING_DESCRIPTION;
                        find.FINDING_TYPE = rec.FINDING_TYPE;
                        find.CREATED_DATE = DateTime.Now;
                        find.CREATED_BY = exe.CREATED_BY;
                        find.UPDATED_DATE = DateTime.Now;
                        find.UPDATED_BY = exe.UPDATED_BY;
                        find.ISACTIVE = true;
                        find.SERVICE_AREA_ID = result.SERVICE_AREA_ID;
                        find.PROCESS_ID = result.PROCESS_ID;
                        find.PROCESS_MODEL_ID = result.PROCESS_MODEL_ID;
                        find.PROCESS_AREA_ID = result.PROCESS_AREA_ID;
                        if (result.ISSUBMITTED)
                            find.ISSUBMITTED = true;
                        else
                            find.ISSUBMITTED = false;
                        CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.Add(find);
                        CSPdb.Commit(CanCommit);
                        find.FINDING_CATEGORY = rec.FINDING_CATEGORY;
                        find.GO_CATEGORY = rec.GO_CATEGORY;
                        output.Add(find);
                    }
                }
            }

            return output;



            //AUDIT_CHECKLIST_PROJECT_FINDINGS find = CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.GetAll().Where(t => t.AUDIT_ID == exe.AUDIT_ID && t.APPLICABLE_QUESTIONS == exe.APPLICABLE_QUESTIONS
            //                        && t.PROCESS_ID == exe.PROCESS_ID && t.SERVICE_AREA_ID == exe.SERVICE_AREA_ID).FirstOrDefault();
            //if (find != null)
            //{
            //    find.FINDING_DESCRIPTION = result.FINDINGS.FINDING_DESCRIPTION;
