        private void SaveSampleAudits(AUDIT_CHECKLIST_PROJECT_EXECUTION exe, AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED result)
        {
            List<AUDIT_CHECKLIST_PROJECT_SAMPLES_AUDITED> deleteDetails = CSPdb.AUDIT_CHECKLIST_PROJECT_SAMPLES_AUDITED.GetAll().Where(t => t.AUDIT_ID == exe.AUDIT_ID && t.APPLICABLE_QUESTIONS == exe.APPLICABLE_QUESTIONS
                                    && t.PROCESS_ID == exe.PROCESS_ID && t.SERVICE_AREA_ID == exe.SERVICE_AREA_ID && t.PROCESS_MODEL_ID == exe.PROCESS_MODEL_ID
                                    && t.PROCESS_AREA_ID == exe.PROCESS_AREA_ID).ToList();

            if (deleteDetails != null && deleteDetails.Count > 0)
                CSPdb.AUDIT_CHECKLIST_PROJECT_SAMPLES_AUDITED.DeleteList(deleteDetails);

            foreach (CHECKLIST_SAMPLE_AUDITED f in result.CHECKLIST_SAMPLE_AUDITED)
            {
                if (f.EMP_ID != "0")
                {
                    AUDIT_CHECKLIST_PROJECT_SAMPLES_AUDITED find = new AUDIT_CHECKLIST_PROJECT_SAMPLES_AUDITED();
                    find.AUDIT_ID = exe.AUDIT_ID;
                    find.APPLICABLE_QUESTIONS = exe.APPLICABLE_QUESTIONS;
                    find.TOTAL_SAMPLES_AUDITED = f.TOTAL_SAMPLES_AUDITED;
                    find.EMP_ID = f.EMP_ID;
                    find.SAMPLES_COMPLIED = f.SAMPLES_COMPLIED;
                    find.SAMPLES_NOTCOMPLIED = f.SAMPLES_NOTCOMPLIED;
                    find.TOTAL_SAMPLES_AUDITED = f.TOTAL_SAMPLES_AUDITED;
                    find.COMMENTS = f.COMMENTS;
                    find.PERCENTAGE = f.PERCENTAGE;
                    find.CREATED_DATE = DateTime.Now;
                    find.CREATED_BY = exe.CREATED_BY;
                    find.UPDATED_DATE = DateTime.Now;
                    find.UPDATED_BY = exe.UPDATED_BY;
                    find.SERVICE_AREA_ID = result.SERVICE_AREA_ID;
                    find.PROCESS_ID = result.PROCESS_ID;
                    find.PROCESS_MODEL_ID = result.PROCESS_MODEL_ID;
                    find.PROCESS_AREA_ID = result.PROCESS_AREA_ID;
                    find.ISACTIVE = true;
                    CSPdb.AUDIT_CHECKLIST_PROJECT_SAMPLES_AUDITED.Add(find);
                    CSPdb.Commit(CanCommit);
                }
            }
        }
        private void SaveLastUpdatedDetails(AUDIT_CHECKLIST_PROJECT_EXECUTION exe, List<AUDIT_CHECKLIST_PROJECT_FINDINGS> result)
        {
            List<int> stages = CSPdb.AUDIT_FINDING_STAGES.GetAll().Select(t => t.ID).ToList();

            if (result == null || !result.Any())
                return;

            foreach (var find in result)
            {
                foreach (var s in stages)
                {
                    var rec = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(x => x.FINDING_ID == find.ID && x.STAGE_ID == s && x.ISACTIVE);
                    if (rec != null)
                    {
                        if (rec.STAGE_STATUS == "Auditee Rejected")
                        {
                            rec.STAGE_STATUS = "New";
                            rec.ISCOMPLETE = false;
                            rec.UPDATED_DATE = DateTime.Now;
                            CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(rec);
                            CSPdb.Commit(CanCommit);
                            DeleteAuditeeAcceptance(find.ID);
                        }
                    }
                    else
                    {
                        var mapp = new AUDIT_FINDING_STAGES_MAPPING();
                        mapp.STAGE_ID = s;
                        mapp.FINDING_ID = find.ID;
                        mapp.STAGE_STATUS = "New";
                        mapp.ISCOMPLETE = false;
                        mapp.CREATED_DATE = DateTime.Now;
                        mapp.CREATED_BY = exe.CREATED_BY;
                        mapp.UPDATED_BY = exe.UPDATED_BY;
                        mapp.UPDATED_DATE = DateTime.Now;
                        mapp.ISACTIVE = true;
                        CSPdb.AUDIT_FINDING_STAGES_MAPPING.Add(mapp);
                        CSPdb.Commit(CanCommit);
                    }
                }
            }
        }

        private void DeleteAuditeeAcceptance(int findingId)
        {
            var rec = CSPdb.AUDITEE_ACCEPTANCE.GetAll().FirstOrDefault(x => x.FINDING_ID == findingId && x.ISACTIVE);
            if (rec != null)
            {
                rec.ISACTIVE = false;
                rec.ISSUBMITTED = false;
                CSPdb.AUDITEE_ACCEPTANCE.Update(rec);
                CSPdb.Commit(CanCommit);
            }
        }
        private void SaveCheckListAuditeeDetails(AUDIT_CHECKLIST_PROJECT_EXECUTION exe, AUDIT_CHECKLIST_PROJECT_EXECUTION_EXTENDED result)
        {
            foreach (string emp in result.AUDITEE_NAME)
            {
                CHECKLIST_EXECUTION_AUDITEE_DETAILS deleteDetails = CSPdb.CHECKLIST_EXECUTION_AUDITEE_DETAILS.GetAll().Where(t => t.AUDIT_ID == exe.AUDIT_ID && t.AUDITEE_EMP_ID == emp).FirstOrDefault();
                if (deleteDetails != null)
                    CSPdb.CHECKLIST_EXECUTION_AUDITEE_DETAILS.Delete(deleteDetails);

                CHECKLIST_EXECUTION_AUDITEE_DETAILS auditeedetails = new CHECKLIST_EXECUTION_AUDITEE_DETAILS();
                auditeedetails.AUDIT_ID = exe.AUDIT_ID;
                auditeedetails.AUDITEE_EMP_ID = emp;
                auditeedetails.CREATED_DATE = DateTime.Now;
                auditeedetails.CREATED_BY = exe.CREATED_BY;
                auditeedetails.UPDATED_DATE = DateTime.Now;
                auditeedetails.UPDATED_BY = exe.UPDATED_BY;
                auditeedetails.ISACTIVE = true;
                CSPdb.CHECKLIST_EXECUTION_AUDITEE_DETAILS.Add(auditeedetails);
                CSPdb.Commit(CanCommit);
            }
        }


