        private void SendCAPSubmissionMail(int fid)
        {
            AUDIT_CHECKLIST_PROJECT_FINDINGS finding = CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.GetAll().Where(t => t.ID == fid).FirstOrDefault();
            var auditeeId = CSPdb.AUDIT_FINDINGS_CAPA.GetAll().Where(t => t.FINDING_ID == fid).Select(t => t.UPDATED_BY).FirstOrDefault();
            string auditeeName = GetEmployeeNamebyId(auditeeId.ToString());
            AUDIT_CHECKLIST_PROJECT_EXECUTION exe = CSPdb.AUDIT_CHECKLIST_PROJECT_EXECUTION.GetAll().Where(t => t.AUDIT_ID == finding.AUDIT_ID).FirstOrDefault();

            string filePath = HttpContext.Current.Server.MapPath("~/UploadFile/Mails/") + "ChecklistFindingCAPSubmission.htm";
            using (System.IO.StreamReader sr = new StreamReader(filePath))
            {
                string emailContent = sr.ReadToEnd();
                emailContent = emailContent.Replace("{{AUDITOR_NAME}}", GetEmployeeNamebyId(exe.AUDITOR_NAME.ToString()));
                emailContent = emailContent.Replace("{{AUDITEE_NAME}}", auditeeName);
                emailContent = emailContent.Replace("{{FINDING}}", finding.FINDING_DESCRIPTION);
                var ep = new EmailProvider(Cldb, CSPdb);
                ep.SendEmail
                    (
                    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                    new EmailContent { from = _email, to = GetEmailIdByEmpId(exe.AUDITOR_NAME), cc = GetEmailIdByEmpId(auditeeId), content = emailContent, subject = "CAP submission response changes.Please login to view changes", hasAttachments = false, attachmentFilePath = "", ProjId = exe.PROJECT_ID },
                    Request

                    );
            }
        }
        private void UpdateIsActive(AUDIT_FINDING_CAPPA_EXT fcap)
        {
            AUDIT_FINDINGS_CAPA capa = CSPdb.AUDIT_FINDINGS_CAPA.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.CAPPALIST.FINDING_ID && t.UNIQUE_ID == fcap.CAPPALIST.UNIQUE_ID && t.ROOT_CAUSE_ID == fcap.CAPPALIST.ROOT_CAUSE_ID && t.ISACTIVE);
            if (capa != null)
            {
                capa.ISACTIVE = false;
                CSPdb.AUDIT_FINDINGS_CAPA.Update(capa);
                CSPdb.Commit(CanCommit);
            }
        }
        private void UpdateFindingStatus(AUDIT_FINDINGS_CAPA fcap)
        {
            AUDIT_FINDING_STAGES_MAPPING mapping = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 1 && t.ISACTIVE);
            if (mapping != null)
            {
                mapping.STAGE_STATUS = fcap.STATUS;
                mapping.ISCOMPLETE = true;
                //mapping.UPDATED_BY = fcap.UPDATED_BY;
                //mapping.UPDATED_DATE = DateTime.Now; 
                UpdateAuditFields(mapping, fcap.UPDATED_BY);
                CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(mapping);
            }

            AUDIT_FINDING_STAGES_MAPPING mappingNew = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 2);
            if (mappingNew != null)
            {
                mappingNew.STAGE_STATUS = "New";
                mappingNew.ISCOMPLETE = false;
                //mappingNew.UPDATED_BY = fcap.UPDATED_BY;
                //mappingNew.UPDATED_DATE = DateTime.Now; 
                UpdateAuditFields(mappingNew, fcap.UPDATED_BY);
                CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(mappingNew);
            }

            AUDIT_FINDING_STAGES_MAPPING mappingNew1 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 3);
            if (mappingNew1 != null)
            {
                mappingNew1.STAGE_STATUS = "New";
                mappingNew1.ISCOMPLETE = false;
                //mappingNew1.UPDATED_BY = fcap.UPDATED_BY;
                //mappingNew1.UPDATED_DATE = DateTime.Now;
                UpdateAuditFields(mappingNew1, fcap.UPDATED_BY);
                CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(mappingNew1);
            }
            AUDIT_FINDING_STAGES_MAPPING mappingNew2 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 4);
            if (mappingNew2 != null)
            {
                mappingNew2.STAGE_STATUS = "New";
                mappingNew2.ISCOMPLETE = false;
                //mappingNew2.UPDATED_BY = fcap.UPDATED_BY;
                //mappingNew2.UPDATED_DATE = DateTime.Now;
                UpdateAuditFields(mappingNew2, fcap.UPDATED_BY);
                CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(mappingNew2);
            }
            AUDIT_FINDING_CAPA_STATUS_HISTORY his = new AUDIT_FINDING_CAPA_STATUS_HISTORY();
            his.FINDING_ID = fcap.FINDING_ID;
            his.ROOT_CAUSE_ID = fcap.ROOT_CAUSE_ID.HasValue ? fcap.ROOT_CAUSE_ID.Value : (int?)null;
            his.UNIQUE_ID = fcap.UNIQUE_ID;
            his.STATUS = fcap.STATUS;
            //his.UPDATED_BY = fcap.UPDATED_BY;
            //his.UPDATED_DATE = DateTime.Now;
            his.ISACTIVE = true;
            UpdateAuditFields(his, fcap.UPDATED_BY);
            CSPdb.AUDIT_FINDING_CAPA_STATUS_HISTORY.Add(his);
            CSPdb.Commit(CanCommit);
        }

        private void UpdateFindingStatusForAuditorRejection(AUDITEE_ACCEPTANCE fcap, int auditId, string empId)
        {
            AUDIT_CHECKLIST_EXECUTION_DETAILS details = CSPdb.AUDIT_CHECKLIST_EXECUTION_DETAILS.GetAll().FirstOrDefault(t => t.ASSESSMENT_ID == auditId && t.STATUS_CATEGORY == "NMET" && !t.ISSUBMITTED);
            if (details != null)
            {
                details.ISSUBMITTED = true;
                details.UPDATED_BY = empId;
                details.UPDATED_DATE = DateTime.Now;
                CSPdb.AUDIT_CHECKLIST_EXECUTION_DETAILS.Update(details);
                CSPdb.Commit(CanCommit);
            }

            AUDIT_CHECKLIST_PROJECT_FINDINGS findings = CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.GetAll().FirstOrDefault(t => t.ID == fcap.FINDING_ID && t.ISACTIVE);
            if (findings != null)
            {
                findings.ISSUBMITTED = true;
                findings.UPDATED_BY = empId;
                findings.UPDATED_DATE = DateTime.Now;
                CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.Update(findings);
                CSPdb.Commit(CanCommit);
            }

            AUDIT_FINDING_STAGES_MAPPING stage1 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 1 && t.ISCOMPLETE);
            if (stage1 != null)
            {
                stage1.STAGE_STATUS = "New";
                stage1.ISCOMPLETE = false;
                CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(stage1);
                CSPdb.Commit(CanCommit);
            }
        }
        private void UpdateFindingStatusForAuditorAcceptance(AUDITEE_ACCEPTANCE fcap, int auditId, string empId)
        {

            AUDIT_CHECKLIST_PROJECT_FINDINGS findings = CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.GetAll().FirstOrDefault(t => t.ID == fcap.FINDING_ID && t.ISACTIVE && fcap.ISSUBMITTED == false);
            if (findings != null)
            {
                findings.ISSUBMITTED = true;
                UpdateAuditFields(findings);
                CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.Update(findings);
                CSPdb.Commit(CanCommit);
            }

            AUDIT_CHECKLIST_EXECUTION_DETAILS details = CSPdb.AUDIT_CHECKLIST_EXECUTION_DETAILS.GetAll().FirstOrDefault(t => t.ASSESSMENT_ID == auditId && t.STATUS_CATEGORY == "NMET" && !t.ISSUBMITTED);
            if (details != null)
            {
                details.ISSUBMITTED = true;
                UpdateAuditFields(details);
                CSPdb.AUDIT_CHECKLIST_EXECUTION_DETAILS.Update(details);
                CSPdb.Commit(CanCommit);
            }
            string rejectionValue = "Auditee Rejected";
            AUDIT_FINDING_STAGES_MAPPING stage1 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 1);
            if (stage1 != null)
            {
                stage1.STAGE_STATUS = rejectionValue;
                stage1.ISCOMPLETE = true;
                UpdateAuditFields(stage1);
                CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(stage1);
                CSPdb.Commit(CanCommit);
            }

            AUDIT_FINDING_STAGES_MAPPING stage2 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 2);
            if (stage2 != null)
            {
                stage2.STAGE_STATUS = rejectionValue;
                stage2.ISCOMPLETE = true;
                CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(stage2);
                CSPdb.Commit(CanCommit);
            }

            AUDIT_FINDING_STAGES_MAPPING stage3 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 3);
            if (stage3 != null)
            {
                stage3.STAGE_STATUS = rejectionValue;
                stage3.ISCOMPLETE = true;
                UpdateAuditFields(stage3);
                CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(stage3);
                CSPdb.Commit(CanCommit);
            }

            AUDIT_FINDING_STAGES_MAPPING stage4 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 4);
            if (stage4 != null)
            {
                stage4.STAGE_STATUS = rejectionValue;
                stage4.ISCOMPLETE = true;
                UpdateAuditFields(stage4);
                CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(stage4);
                CSPdb.Commit(CanCommit);
            }
            AUDIT_FINDING_STAGES_MAPPING stage5 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 5);
            if (stage5 != null)
            {
                stage5.STAGE_STATUS = rejectionValue;
                stage5.ISCOMPLETE = true;
                UpdateAuditFields(stage5);
                CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(stage5);
                CSPdb.Commit(CanCommit);
            }
        }
        private string UpdateFindingStatusForAuditeeRejection(AUDITEE_ACCEPTANCE fcap)
        {
            AUDIT_FINDING_STAGES_MAPPING mapping = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 1);
            if (mapping != null && !mapping.ISCOMPLETE)
            {
                mapping.STAGE_STATUS = "Auditee Rejected";
                mapping.ISCOMPLETE = true;
                mapping.STATUS_DATE = DateTime.Now;
                UpdateAuditFields(mapping);
                CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(mapping);
                AUDIT_FINDING_CAPA_STATUS_HISTORY his = new AUDIT_FINDING_CAPA_STATUS_HISTORY();
                his.FINDING_ID = fcap.FINDING_ID;
                // his.ROOT_CAUSE_ID = fcap.ROOT_CAUSE_ID;
                his.UNIQUE_ID = fcap.UNIQUE_ID;
                his.STATUS = fcap.STATUS;
                UpdateAuditFields(his);
                CSPdb.AUDIT_FINDING_CAPA_STATUS_HISTORY.Add(his);
                CSPdb.Commit(CanCommit);
                return string.Empty;
            }
            else
            {
                return "Unable to reject the finding, It must have been already Rejected or Accepted and CAP in Progress";
            }


        }

