        private void SendCAPReviewImplementationMail(int fid)
        {
            AUDIT_CHECKLIST_PROJECT_FINDINGS finding = CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.GetAll().Where(t => t.ID == fid).FirstOrDefault();
            List<AUDIT_FINDING_CAPA_IMPLEMENTATION> capa = CSPdb.AUDIT_FINDING_CAPA_IMPLEMENTATION.GetAll().Where(t => t.FINDING_ID == fid && t.ISACTIVE).ToList<AUDIT_FINDING_CAPA_IMPLEMENTATION>();
            string capStatus = "";
            foreach (AUDIT_FINDING_CAPA_IMPLEMENTATION c in capa)
            {
                if (!c.ISIMPLEMENTED)
                {
                    capStatus = "NOT IMPLEMENTED";
                    break;
                }
                else
                    capStatus = "IMPLEMENTED";

            }
            var auditeeId = CSPdb.AUDIT_FINDINGS_CAPA.GetAll().Where(t => t.FINDING_ID == fid).Select(t => t.UPDATED_BY).FirstOrDefault();
            string auditeeName = GetEmployeeNamebyId(auditeeId.ToString());
            AUDIT_CHECKLIST_PROJECT_EXECUTION exe = CSPdb.AUDIT_CHECKLIST_PROJECT_EXECUTION.GetAll().Where(t => t.AUDIT_ID == finding.AUDIT_ID).FirstOrDefault();

            string filePath = HttpContext.Current.Server.MapPath("~/UploadFile/Mails/") + "ChecklistFindingCAPReviewImplementation.htm";
            using (System.IO.StreamReader sr = new StreamReader(filePath))
            {
                string emailContent = sr.ReadToEnd();
                emailContent = emailContent.Replace("{{AUDITOR_NAME}}", GetEmployeeNamebyId(exe.AUDITOR_NAME.ToString()));
                emailContent = emailContent.Replace("{{AUDITEE_NAME}}", auditeeName);
                emailContent = emailContent.Replace("{{FINDING}}", finding.FINDING_DESCRIPTION);
                emailContent = emailContent.Replace("{{CAP_ACCEPTANCE_STATUS}}", capStatus);
                var ep = new EmailProvider(Cldb, CSPdb);
                ep.SendEmail
                    (
                    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                    new EmailContent { from = _email, to = GetEmailIdByEmpId(exe.AUDITOR_NAME), cc = GetEmailIdByEmpId(capa[0].UPDATED_BY), content = emailContent, subject = "CAP submission response changes.Please login to view changes", hasAttachments = false, attachmentFilePath = "", ProjId = exe.PROJECT_ID },
                    Request
                    );
            }
        }
        private void UpdateFindingImplementationStatus(AUDIT_FINDING_CAPA_IMPLEMENTATION fcap, string CapStatus)
        {
            AUDIT_FINDING_STAGES_MAPPING mapping = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().Where(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 3).FirstOrDefault();
            //List<AUDIT_FINDING_CAPA_IMPLEMENTATION> capalist = CSPdb.AUDIT_FINDING_CAPA_IMPLEMENTATION.GetAll().Where(t => t.FINDING_ID == fcap.FINDING_ID && t.UNIQUE_ID == fcap.UNIQUE_ID && t.ISACTIVE == true).ToList();
            //foreach (AUDIT_FINDING_CAPA_IMPLEMENTATION c in capalist)
            //{
            //    if (!c.ISIMPLEMENTED)
            //    {
            //        mapping.STAGE_STATUS = "CAP Not Implemented";
            //        mapping.ISCOMPLETE = false;

            //        break;
            //    }
            //    else
            //    {
            //        mapping.STAGE_STATUS = "CAP Implemented";
            //        mapping.ISCOMPLETE = true;
            //    }

            //}
            if (mapping != null)
            {
                mapping.STAGE_STATUS = CapStatus;

                if (mapping.STAGE_STATUS == "Corrective Action Plan Implemented")
                    mapping.ISCOMPLETE = true;
                else
                    mapping.ISCOMPLETE = false;
                CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(mapping);
            }


            AUDIT_FINDING_CAPA_STATUS_HISTORY his = new AUDIT_FINDING_CAPA_STATUS_HISTORY();
            his.FINDING_ID = fcap.FINDING_ID;
            his.ROOT_CAUSE_ID = fcap.ROOT_CAUSE_ID.HasValue ? fcap.ROOT_CAUSE_ID.Value : (int?)null;
            his.UNIQUE_ID = fcap.UNIQUE_ID;
            his.STATUS = fcap.STATUS;
            UpdateAuditFields(his);
            his.ISACTIVE = true;
            CSPdb.AUDIT_FINDING_CAPA_STATUS_HISTORY.Add(his);
            CSPdb.Commit(CanCommit);
        }

