        private void SendCAPReviewVerificationMail(int fid)
        {
            AUDIT_CHECKLIST_PROJECT_FINDINGS finding = CSPdb.AUDIT_CHECKLIST_PROJECT_FINDINGS.GetAll().Where(t => t.ID == fid).FirstOrDefault();
            List<AUDIT_FINDING_CAPA_VERIFICATION> capa = CSPdb.AUDIT_FINDING_CAPA_VERIFICATION.GetAll().Where(t => t.FINDING_ID == fid && t.ISACTIVE).ToList<AUDIT_FINDING_CAPA_VERIFICATION>();
            string capStatus = "";
            foreach (AUDIT_FINDING_CAPA_VERIFICATION c in capa)
            {
                if (!c.ISVERIFIED)
                {
                    capStatus = "Verified";
                    break;
                }
                else
                {
                    if (c.RECOMMENDED_ACTION == "Resubmit Corrective Action Plan")
                        capStatus = "Resubmit Corrective Action Plan";
                    else if (c.RECOMMENDED_ACTION == "Reimplement Corrective Action Plan")
                        capStatus = "Reimplement Corrective Action Plan";
                }
                capStatus = "";

            }
            var auditeeId = CSPdb.AUDIT_FINDINGS_CAPA.GetAll().Where(t => t.FINDING_ID == fid).Select(t => t.UPDATED_BY).FirstOrDefault();
            string auditeeName = GetEmployeeNamebyId(auditeeId.ToString());
            AUDIT_CHECKLIST_PROJECT_EXECUTION exe = CSPdb.AUDIT_CHECKLIST_PROJECT_EXECUTION.GetAll().Where(t => t.AUDIT_ID == finding.AUDIT_ID).FirstOrDefault();

            string filePath = HttpContext.Current.Server.MapPath("~/UploadFile/Mails/") + "ChecklistFindingCAPReviewVerification.htm";
            using (System.IO.StreamReader sr = new StreamReader(filePath))
            {
                string emailContent = sr.ReadToEnd();
                emailContent = emailContent.Replace("{{AUDITOR_NAME}}", GetEmployeeNamebyId(exe.AUDITOR_NAME.ToString()));
                emailContent = emailContent.Replace("{{AUDITEE_NAME}}", auditeeName);
                emailContent = emailContent.Replace("{{FINDING}}", finding.FINDING_DESCRIPTION);
                emailContent = emailContent.Replace("{{CAP_ACCEPTANCE_STATUS}}", capStatus);
                var ep = new EmailProvider(Cldb, CSPdb);
                ep.SendEmail
                    (
                    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                    new EmailContent { from = _email, to = GetEmailIdByEmpId(exe.AUDITOR_NAME), cc = GetEmailIdByEmpId(capa[0].UPDATED_BY), content = emailContent, subject = "CAP submission response changes.Please login to view changes", hasAttachments = false, attachmentFilePath = "", ProjId = exe.PROJECT_ID },
                    Request

                    );
            }
        }

        private void UpdateIsActiveVerifcation(AUDIT_FINDING_CAPA_VERIFICATION fcap)
        {
            AUDIT_FINDING_CAPA_VERIFICATION capa = CSPdb.AUDIT_FINDING_CAPA_VERIFICATION.GetAll().Where(t => t.FINDING_ID == fcap.FINDING_ID && t.UNIQUE_ID == fcap.UNIQUE_ID && t.ROOT_CAUSE_ID == fcap.ROOT_CAUSE_ID).FirstOrDefault();
            if (capa != null)
            {
                capa.ISACTIVE = false;
                CSPdb.AUDIT_FINDING_CAPA_VERIFICATION.Update(capa);
                CSPdb.Commit(CanCommit);
            }
        }
        private void UpdateCAPSubmissionDetails(AUDIT_FINDING_CAPA_VERIFICATION verification)
        {
            AUDIT_FINDINGS_CAPA capa = CSPdb.AUDIT_FINDINGS_CAPA.GetAll().FirstOrDefault(t => t.FINDING_ID == verification.FINDING_ID && t.ROOT_CAUSE_ID == verification.ROOT_CAUSE_ID && t.UNIQUE_ID == verification.UNIQUE_ID && t.ISACTIVE == true);
            if (capa != null)
            {
                capa.ISSUBMITTED = false;
                capa.STATUS = "Corrective Action Plan Submission Failed";
                CSPdb.AUDIT_FINDINGS_CAPA.Update(capa);
                CSPdb.Commit(CanCommit);
            }

            AUDIT_FINDING_CAPA_REVIEW capRev = CSPdb.AUDIT_FINDING_CAPA_REVIEW.GetAll().FirstOrDefault(t => t.FINDING_ID == verification.FINDING_ID && t.ROOT_CAUSE_ID == verification.ROOT_CAUSE_ID && t.UNIQUE_ID == verification.UNIQUE_ID && t.ISACTIVE == true);
            if (capRev != null)
            {
                capRev.ISACTIVE = false;
                capRev.ISSUBMITTED = false;
                CSPdb.AUDIT_FINDING_CAPA_REVIEW.Update(capRev);
                CSPdb.Commit(CanCommit);
            }
            AUDIT_FINDING_CAPA_IMPLEMENTATION capImp = CSPdb.AUDIT_FINDING_CAPA_IMPLEMENTATION.GetAll().FirstOrDefault(t => t.FINDING_ID == verification.FINDING_ID && t.ROOT_CAUSE_ID == verification.ROOT_CAUSE_ID && t.UNIQUE_ID == verification.UNIQUE_ID && t.ISACTIVE == true);
            if (capImp != null)
            {
                capImp.ISACTIVE = false;
                CSPdb.AUDIT_FINDING_CAPA_IMPLEMENTATION.Update(capImp);
                CSPdb.Commit(CanCommit);
            }
        }

