        private void UpdateFindingVerificationStatus(AUDIT_FINDING_CAPA_VERIFICATION fcap, string CapStatus)
        {
            AUDIT_FINDING_STAGES_MAPPING mapping = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().FirstOrDefault(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 4 && t.ISACTIVE);
            if (mapping == null)
                return;

            switch (CapStatus)
            {
                case "Corrective Action Implementation Verified":
                    mapping.STAGE_STATUS = "Corrective Action Implementation Verified";
                    mapping.ISCOMPLETE = true;
                    CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(mapping);
                    break;

                case "Resubmit Corrective  Action Plan":
                    mapping.STAGE_STATUS = "Corrective Action Implementation Failed";
                    mapping.ISCOMPLETE = false;
                    CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(mapping);

                    AUDIT_FINDING_STAGES_MAPPING stage1 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().Where(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 1).FirstOrDefault();
                    if (stage1 != null)
                    {
                        stage1.ISCOMPLETE = false;
                        stage1.STAGE_STATUS = "Corrective Action Plan Resubmit";
                        CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(stage1);
                    }

                    AUDIT_FINDING_STAGES_MAPPING stage2 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().Where(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 2).FirstOrDefault();
                    if (stage2 != null)
                    {
                        stage2.ISCOMPLETE = false;
                        stage2.STAGE_STATUS = "New";
                        CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(stage2);
                    }

                    AUDIT_FINDING_STAGES_MAPPING stage3 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().Where(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 3).FirstOrDefault();
                    if (stage3 != null)
                    {
                        stage3.ISCOMPLETE = false;
                        stage3.STAGE_STATUS = "New";
                        CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(stage3);
                    }
                    break;

                case "Reimplement Corrective Action Plan":
                    AUDIT_FINDING_STAGES_MAPPING stage4 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().Where(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 4).FirstOrDefault();
                    if (stage4 != null)
                    {
                        stage4.ISCOMPLETE = false;
                        stage4.STAGE_STATUS = "New";
                        CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(stage4);
                    }
                    AUDIT_FINDING_STAGES_MAPPING stage33 = CSPdb.AUDIT_FINDING_STAGES_MAPPING.GetAll().Where(t => t.FINDING_ID == fcap.FINDING_ID && t.STAGE_ID == 3).FirstOrDefault();
                    if (stage33 != null)
                    {
                        stage33.ISCOMPLETE = false;
                        stage33.STAGE_STATUS = "New";
                        CSPdb.AUDIT_FINDING_STAGES_MAPPING.Update(stage33);
                    }
                    break;

            }

            AUDIT_FINDING_CAPA_STATUS_HISTORY his = new AUDIT_FINDING_CAPA_STATUS_HISTORY();
            his.FINDING_ID = fcap.FINDING_ID;
            his.ROOT_CAUSE_ID = fcap.ROOT_CAUSE_ID.HasValue ? fcap.ROOT_CAUSE_ID.Value : (int?)null;
            his.UNIQUE_ID = fcap.UNIQUE_ID;
            his.STATUS = fcap.STATUS;
            UpdateAuditFields(his);
            his.ISACTIVE = true;
            CSPdb.AUDIT_FINDING_CAPA_STATUS_HISTORY.Add(his);
            CSPdb.Commit(CanCommit);
        }

        //AddProcessModel
        [POST("AddProcessModel")]
        [ActionName("AddProcessModel")]
        [HttpPost]
        public IHttpActionResult AddProcessModel(HttpRequestMessage request)
        {
            string empId = Request.Headers.GetValues("empId").ToList()[0];
            //int empIds = Convert.ToInt32(empId);
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            PROCESS_MODEL results = JsonConvert.DeserializeObject<PROCESS_MODEL>(json);
            PROCESS_MODEL query = new PROCESS_MODEL();
            query.TITLE = results.TITLE;
            query.DESCRIPTION = results.DESCRIPTION;
            query.RELEASE_VERSION_REFERENCE = results.RELEASE_VERSION_REFERENCE;
            query.RELEASE_DATE = results.RELEASE_DATE.ToLocalTime();
            query.CREATED_BY = empId;
            query.CREATED_DATE = DateTime.Now;
            query.UPDATED_BY = empId;
            query.UPDATED_DATE = DateTime.Now;
            query.ISACTIVE = true;


            var existing = CSPdb.PROCESS_MODEL.GetAll().Any(x => x.TITLE == results.TITLE
                                && x.RELEASE_VERSION_REFERENCE == results.RELEASE_VERSION_REFERENCE);
            if (existing)
            {
                return Content(HttpStatusCode.Conflict, "Process model with same Title, Release Version exists already.");
            }
            CSPdb.PROCESS_MODEL.Add(query);
            CSPdb.Commit(CanCommit);
            return Ok();
        }

