        [POST("SaveCheckListQuestions")]
        [ActionName("SaveCheckListQuestions")]
        [HttpPost]
        public IHttpActionResult SaveCheckListQuestions(HttpRequestMessage request)
        {
            string empId = Request.Headers.GetValues("empId").ToList()[0];
            //int empIds = Convert.ToInt32(empId);
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            PROCESS_MODEL_QUESTIONS results = JsonConvert.DeserializeObject<PROCESS_MODEL_QUESTIONS>(json);
            PROCESS_MODEL_QUESTIONS res = CSPdb.PROCESS_MODEL_QUESTIONS.GetAll().Where(t => t.CUSTOMER_ID == results.CUSTOMER_ID && t.PROJECT_ID == results.PROJECT_ID && t.VERSIONID == results.VERSIONID && t.ISACTIVE == true).FirstOrDefault();
            if (res == null)
            {
                res = new PROCESS_MODEL_QUESTIONS();
                res.CUSTOMER_ID = results.CUSTOMER_ID;
                res.PROJECT_ID = results.PROJECT_ID;
                res.DESCRIPTION = results.DESCRIPTION;
                res.VERSIONID = results.VERSIONID;
                res.EFFECTIVE_FROM = results.EFFECTIVE_FROM;
                res.CREATED_BY = empId;
                res.CREATED_DATE = DateTime.Now;
                res.UPDATED_BY = empId;
                res.UPDATED_DATE = DateTime.Now;
                res.ISACTIVE = true;
                res.ISSUBMITTED = results.ISSUBMITTED;
                CSPdb.PROCESS_MODEL_QUESTIONS.Add(res);
                CSPdb.Commit(CanCommit);
                res.QUESTIONS_MODEL = results.QUESTIONS_MODEL;
                res.PROCESS_ID = results.PROCESS_ID;
                AddProcessQuestions(res, empId);
            }
            else
            {
                res.PROCESS_ID = results.PROCESS_ID;
                res.DESCRIPTION = results.DESCRIPTION;
                res.VERSIONID = results.VERSIONID;
                res.EFFECTIVE_FROM = results.EFFECTIVE_FROM;
                res.CREATED_BY = empId;
                res.CREATED_DATE = DateTime.Now;
                res.UPDATED_BY = empId;
                res.UPDATED_DATE = DateTime.Now;
                res.ISACTIVE = true;

                CSPdb.PROCESS_MODEL_QUESTIONS.Update(res);
                CSPdb.Commit(CanCommit);
                AddProcessQuestions(results, empId);
            }

            return Ok(res);
        }

        private void AddProcessQuestions(PROCESS_MODEL_QUESTIONS questions, string empId)
        {
            foreach (AUDIT_CHECKLIST_QUESTIONS ques in questions.QUESTIONS_MODEL)
            {
                if (ques.ID == 0)
                {
                    AUDIT_CHECKLIST_QUESTIONS qt = new AUDIT_CHECKLIST_QUESTIONS();
                    qt.CHECKLIST_ID = questions.ID;
                    qt.PROCESS_ID = questions.PROCESS_ID;
                    qt.VERSIONID = questions.VERSIONID;
                    qt.WEIGHTAGE_ID = ques.WEIGHTAGE_ID;
                    qt.CATEGORY = ques.CATEGORY;
                    qt.LOOK_FOR = ques.LOOK_FOR;
                    qt.ISAPPLICABLE = true;
                    qt.CREATED_BY = empId;
                    qt.CREATED_DATE = DateTime.Now;
                    qt.ISACTIVE = true;
                    qt.UPDATED_BY = empId;
                    qt.UPDATED_DATE = DateTime.Now;

                    CSPdb.AUDIT_CHECKLIST_QUESTIONS.Add(qt);
                    CSPdb.Commit(CanCommit);
                    qt.CLAUSES = ques.CLAUSES;
                    AddProcessClauses(qt);
                }
                else
                {
                    AUDIT_CHECKLIST_QUESTIONS qt = CSPdb.AUDIT_CHECKLIST_QUESTIONS.GetAll().Where(t => t.ID == ques.ID && t.CHECKLIST_ID == questions.ID && t.ISACTIVE == true).FirstOrDefault();
                    if (qt == null)
                    {
                        AUDIT_CHECKLIST_QUESTIONS qut = new AUDIT_CHECKLIST_QUESTIONS();
                        qut.CHECKLIST_ID = questions.ID;
                        qut.PROCESS_ID = questions.PROCESS_ID;
                        qut.VERSIONID = questions.VERSIONID;
                        qut.WEIGHTAGE_ID = ques.WEIGHTAGE_ID;
                        qut.CATEGORY = ques.CATEGORY;
                        qut.LOOK_FOR = ques.LOOK_FOR;
                        qut.ISAPPLICABLE = true;
                        qut.CREATED_BY = empId;
                        qut.CREATED_DATE = DateTime.Now;
                        qut.ISACTIVE = true;
                        qut.UPDATED_BY = empId;
                        qut.UPDATED_DATE = DateTime.Now;

                        CSPdb.AUDIT_CHECKLIST_QUESTIONS.Add(qut);
                        CSPdb.Commit(CanCommit);
                        qut.CLAUSES = ques.CLAUSES;
                        AddProcessClauses(qut);
                    }
                    else
                    {
                        qt.PROCESS_ID = questions.PROCESS_ID;
                        qt.VERSIONID = questions.VERSIONID;
                        qt.WEIGHTAGE_ID = ques.WEIGHTAGE_ID;
                        qt.CATEGORY = ques.CATEGORY;
                        qt.LOOK_FOR = ques.LOOK_FOR;
                        qt.ISAPPLICABLE = true;
                        qt.ISACTIVE = true;
                        qt.UPDATED_BY = empId;
                        qt.UPDATED_DATE = DateTime.Now;

                        CSPdb.AUDIT_CHECKLIST_QUESTIONS.Update(qt);
                        CSPdb.Commit(CanCommit);
                        qt.CLAUSES = ques.CLAUSES;
                        UpdateProcessClauses(qt);
                    }

                }



            }
        }
        private void AddProcessClauses(AUDIT_CHECKLIST_QUESTIONS qt)
        {
            foreach (int i in qt.CLAUSES)
            {
                AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING ques = new AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING();
                ques.CLAUSE_ID = i;
                ques.QUESTION_ID = qt.ID;
                ques.CREATED_DATE = DateTime.Now;
                ques.CREATED_BY = qt.CREATED_BY;
                ques.UPDATED_DATE = DateTime.Now;
                ques.UPDATED_BY = qt.CREATED_BY;
                ques.ISACTIVE = true;

                CSPdb.AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING.Add(ques);
                CSPdb.Commit(CanCommit);
            }


        }

        private void UpdateProcessClauses(AUDIT_CHECKLIST_QUESTIONS qt)
        {
            foreach (int i in qt.CLAUSES)
            {
                AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING ques = CSPdb.AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING.GetAll().Where(t => t.CLAUSE_ID == i && t.QUESTION_ID == qt.ID && t.ISACTIVE == true).FirstOrDefault();
                if (ques == null)
                {
                    ques = new AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING();
                    ques.CLAUSE_ID = i;
                    ques.QUESTION_ID = qt.ID;
                    ques.CREATED_DATE = DateTime.Now;
                    ques.CREATED_BY = qt.CREATED_BY;
                    ques.UPDATED_DATE = DateTime.Now;
                    ques.UPDATED_BY = qt.CREATED_BY;
                    ques.ISACTIVE = true;

                    CSPdb.AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING.Add(ques);
                    CSPdb.Commit(CanCommit);
                }
                else
                {
                    ques.CLAUSE_ID = i;
                    ques.QUESTION_ID = qt.ID;
                    ques.UPDATED_DATE = DateTime.Now;
                    ques.UPDATED_BY = qt.CREATED_BY;
                    ques.ISACTIVE = true;

                    CSPdb.AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING.Update(ques);
                    CSPdb.Commit(CanCommit);
                }
            }
        }

        [POST("SaveNewChecklistVersion")]
        [ActionName("SaveNewChecklistVersion")]
        [HttpPost]
        public IHttpActionResult SaveNewChecklistVersion(HttpRequestMessage request)
        {
            string empId = Request.Headers.GetValues("empid").ToList()[0];
            //int empIds = Convert.ToInt32(empId);
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            PROCESS_MODEL_QUESTIONS results = JsonConvert.DeserializeObject<PROCESS_MODEL_QUESTIONS>(json);
            PROCESS_MODEL_QUESTIONS res = CSPdb.PROCESS_MODEL_QUESTIONS.GetAll().Where(t => t.CUSTOMER_ID == results.CUSTOMER_ID && t.PROJECT_ID == results.PROJECT_ID).OrderByDescending(t => t.VERSIONID).FirstOrDefault();

            res.ISACTIVE = false;
            res.UPDATED_BY = empId;
            res.UPDATED_DATE = DateTime.Now;

            CSPdb.PROCESS_MODEL_QUESTIONS.Update(res);
            CSPdb.Commit(CanCommit);
            res.QUESTIONS_MODEL = CSPdb.AUDIT_CHECKLIST_QUESTIONS.GetAll().Where(t => t.CHECKLIST_ID == res.ID).ToList();
            foreach (AUDIT_CHECKLIST_QUESTIONS q in res.QUESTIONS_MODEL)
            {
                q.CLAUSES = CSPdb.AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING.GetAll().Where(t => t.QUESTION_ID == q.ID).Select(t => t.CLAUSE_ID).ToList();
            }
            res.PROCESS_ID = results.PROCESS_ID;
            UpdateProcessQuestions(res, empId);

            PROCESS_MODEL_QUESTIONS ques = new PROCESS_MODEL_QUESTIONS();
            ques.CUSTOMER_ID = results.CUSTOMER_ID;
            ques.PROJECT_ID = results.PROJECT_ID;
            ques.DESCRIPTION = results.DESCRIPTION;
            ques.VERSIONID = results.VERSIONID;
            ques.EFFECTIVE_FROM = results.EFFECTIVE_FROM;
            ques.CREATED_BY = empId;
            ques.CREATED_DATE = DateTime.Now;
            ques.UPDATED_BY = empId;
            ques.UPDATED_DATE = DateTime.Now;
            ques.ISACTIVE = true;
            ques.ISSUBMITTED = false;

            CSPdb.PROCESS_MODEL_QUESTIONS.Add(ques);
            CSPdb.Commit(CanCommit);
            ques.QUESTIONS_MODEL = res.QUESTIONS_MODEL;
            ques.PROCESS_ID = results.PROCESS_ID;
            AddProcessQuestions(ques, empId);

            return Ok(res);
        }

        private void UpdateProcessQuestions(PROCESS_MODEL_QUESTIONS questions, string empId)
        {
            foreach (AUDIT_CHECKLIST_QUESTIONS ques in questions.QUESTIONS_MODEL)
            {
                AUDIT_CHECKLIST_QUESTIONS qt = CSPdb.AUDIT_CHECKLIST_QUESTIONS.GetAll().Where(t => t.ID == ques.ID && t.CHECKLIST_ID == questions.ID).FirstOrDefault();
                if (qt != null)
                {
                    qt.ISACTIVE = false;
                    qt.UPDATED_BY = empId;
                    qt.UPDATED_DATE = DateTime.Now;

                    CSPdb.AUDIT_CHECKLIST_QUESTIONS.Update(qt);
                    CSPdb.Commit(CanCommit);

                    qt.CLAUSES = ques.CLAUSES;
                    UpdateIsactiveProcessClauses(qt);
                }
            }
        }

        private void UpdateIsactiveProcessClauses(AUDIT_CHECKLIST_QUESTIONS qt)
        {
            foreach (int i in qt.CLAUSES)
            {
                AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING ques = CSPdb.AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING.GetAll().Where(t => t.CLAUSE_ID == i && t.QUESTION_ID == qt.ID).FirstOrDefault();
                ques.UPDATED_DATE = DateTime.Now;
                ques.UPDATED_BY = qt.CREATED_BY;
                ques.ISACTIVE = false;

                CSPdb.AUDIT_CHECKLIST_QUESTION_CLAUSES_MAPPING.Update(ques);
                CSPdb.Commit(CanCommit);
            }


        }
