        [POST("DeleteChecklist")]
        [ActionName("DeleteChecklist")]
        [HttpPost]
        public IHttpActionResult DeleteChecklist([FromBody] PM_CHECKLIST pM_CHECKLIST)
        {

            if (pM_CHECKLIST != null)
            {
                var ischecklistusedForAssessment = CSPdb.AUDIT_CHECKLIST_EXECUTION_SUMMARY.GetAll().Where(t => t.CHECKLIST_ID == pM_CHECKLIST.ID && t.ISACTIVE).FirstOrDefault();

                if (ischecklistusedForAssessment != null)
                {
                    return Content(HttpStatusCode.Conflict, $"This check list cannot be deleted as it is used in the {ischecklistusedForAssessment.AUDIT_TITLE} assessment planned on {ischecklistusedForAssessment.PLANNED_AUDIT_START_DATE}.");
                }

                var rec = CSPdb.PM_CHECKLIST.GetAll().Where(x => x.ID == pM_CHECKLIST.ID).FirstOrDefault();
                if (rec != null)
                {
                    rec.ISACTIVE = false;
                    CSPdb.PM_CHECKLIST.Update(rec);
                    CSPdb.Commit(CanCommit);
                }
            }

            return Ok(pM_CHECKLIST);
        }

