        [POST("AddChecklistStatusList")]
        [ActionName("AddChecklistStatusList")]
        [HttpPost]
        public IHttpActionResult AddChecklistStatusList([FromBody] AuditStatusModel auditStatusModel)
        {
            var empId = Request.Headers.GetValues("empid").FirstOrDefault();
            var newRec = new AUDIT_CHECKLIST_STATUS_LIST();
            if (auditStatusModel != null)
            {
                var statusHeader = auditStatusModel.Statusheader;
                if (!string.IsNullOrEmpty(statusHeader))
                {
                    newRec = new AUDIT_CHECKLIST_STATUS_LIST();
                    newRec.STATUS_TITLE = statusHeader;
                    newRec.CREATED_BY = empId;
                    newRec.CREATED_DATE = DateTime.Now;
                    newRec.UPDATED_BY = empId;
                    newRec.UPDATED_DATE = DateTime.Now;
                    newRec.ISACTIVE = true;
                    CSPdb.AUDIT_CHECKLIST_STATUS_LIST.Add(newRec);
                    CSPdb.Commit(CanCommit);


                    if (auditStatusModel.MetStatusValues != null && auditStatusModel.MetStatusValues.Count > 0)
                    {
                        foreach (var value in auditStatusModel.MetStatusValues)
                        {
                            var statusRec = new AUDIT_CHECKLIST_STATUS_LIST_VALUES();
                            statusRec.STATUS_LIST_ID = newRec.ID;
                            statusRec.STATUS_LIST_VALUE = value.STATUS;
                            statusRec.MULTIPLIER = value.MULTIPLIER;
                            statusRec.CREATED_BY = empId;
                            statusRec.CREATED_DATE = DateTime.Now;
                            statusRec.UPDATED_BY = empId;
                            statusRec.UPDATED_DATE = DateTime.Now;
                            statusRec.ISACTIVE = true;
                            statusRec.STATUS_CATEGORY = "MET";
                            CSPdb.AUDIT_CHECKLIST_STATUS_LIST_VALUES.Add(statusRec);
                            CSPdb.Commit(CanCommit);
                        }
                    }
                    if (auditStatusModel.NotMetStatusValues != null && auditStatusModel.NotMetStatusValues.Count > 0)
                    {
                        foreach (var value in auditStatusModel.NotMetStatusValues)
                        {
                            var statusRec = new AUDIT_CHECKLIST_STATUS_LIST_VALUES();
                            statusRec.STATUS_LIST_ID = newRec.ID;
                            statusRec.STATUS_LIST_VALUE = value.STATUS;
                            statusRec.MULTIPLIER = value.MULTIPLIER;
                            statusRec.CREATED_BY = empId;
                            statusRec.CREATED_DATE = DateTime.Now;
                            statusRec.UPDATED_BY = empId;
                            statusRec.UPDATED_DATE = DateTime.Now;
                            statusRec.ISACTIVE = true;
                            statusRec.STATUS_CATEGORY = "NMET";
                            CSPdb.AUDIT_CHECKLIST_STATUS_LIST_VALUES.Add(statusRec);
                            CSPdb.Commit(CanCommit);
                        }
                    }
                    if (auditStatusModel.NAStatusValues != null && auditStatusModel.NAStatusValues.Count > 0)
                    {
                        foreach (var value in auditStatusModel.NAStatusValues)
                        {
                            var statusRec = new AUDIT_CHECKLIST_STATUS_LIST_VALUES();
                            statusRec.STATUS_LIST_ID = newRec.ID;
                            statusRec.STATUS_LIST_VALUE = value.STATUS;
                            statusRec.MULTIPLIER = value.MULTIPLIER;
                            statusRec.CREATED_BY = empId;
                            statusRec.CREATED_DATE = DateTime.Now;
                            statusRec.UPDATED_BY = empId;
                            statusRec.UPDATED_DATE = DateTime.Now;
                            statusRec.ISACTIVE = true;
                            statusRec.STATUS_CATEGORY = "N/A";
                            CSPdb.AUDIT_CHECKLIST_STATUS_LIST_VALUES.Add(statusRec);
                            CSPdb.Commit(CanCommit);
                        }
                    }
                }
            }

            return Ok(newRec);

        }

