            ActionItemsViewDetails results = JsonConvert.DeserializeObject<ActionItemsViewDetails>(json);

            PROJECT_ACTIONITEM query = CSPdb.PROJECT_ACTIONITEM.GetById(results.ACTION_ITEM_ID);
