        [POST("UpdateActionitemforRisk")]
        [ActionName("UpdateActionitemforRisk")]
        [HttpPost]
        public IHttpActionResult UpdateActionitemforRisk(HttpRequestMessage request)
        {
            var empId = this.GetHeaderDetails_String("empId");
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            PROJECT_ACTIONITEM results = JsonConvert.DeserializeObject<PROJECT_ACTIONITEM>(json);

            PROJECT_ACTIONITEM query = CSPdb.PROJECT_ACTIONITEM.GetAll().FirstOrDefault(t => t.ID == results.ID && t.ISACTIVE);
            if (query != null)
            {
                query.DESCRIPTION = results.DESCRIPTION;
                query.SOURCE = results.SOURCE;
                query.OWNER = results.OWNER;
                query.PRIORITY = results.PRIORITY;
                query.IDENTIFIED_DATE = results.IDENTIFIED_DATE.ToLocalTime();
                query.TARGET_DATE = results.TARGET_DATE.HasValue ? results.TARGET_DATE.Value.ToLocalTime() : (DateTime?)null;
                query.STATUS = results.STATUS;
                query.COMPLETION_DATE = results.COMPLETION_DATE.HasValue ? results.COMPLETION_DATE.Value.ToLocalTime() : (DateTime?)null;
                query.COMMENTS = results.COMMENTS;
                CSPdb.PROJECT_ACTIONITEM.Update(query);


                CSPdb.Commit(CanCommit);
                if (query.RISK_ID != null)
                {
                    var risk = CSPdb.PROJECT_RISK.GetAll().FirstOrDefault(x => x.ID == query.RISK_ID);
                    if (risk != null)
                    {
                        var actionItems = CSPdb.PROJECT_ACTIONITEM.GetAll().Where(x => x.RISK_ID == risk.ID && x.ISACTIVE).ToList();
                        if (actionItems.Any())
                            risk.TARGET_DATE = actionItems.Max(x => x.TARGET_DATE);
                    }
                }
                UpdateLastUpdatedDetails(results.PROJECT_ID, results.UPDATED_BY);
            }
            return Ok();
        }


