        [POST("DeleteCustomerProjects")]
        [ActionName("DeleteCustomerProjects")]
        [HttpPost]
        public IHttpActionResult DeleteCustomerProjects(string CustomerEmailid, string CustomerId, string Empid)
        {
            LogRequest(null, "DeleteCustomerProjects");
            CUSTOMER_USERS cust = CSPdb.CUSTOMER_USERS.GetAll().Where(t => t.EMAILID.ToLower() == CustomerEmailid).FirstOrDefault();
            if (cust != null)
            {
                var query1 = GetProjectListForUser(Empid).ToList();
                List<string> empProjects = query1.Select(t => t.PROJ_ID).ToList<string>();
                List<CUSTOMER_PROJECTS> custProjects = CSPdb.CUSTOMER_PROJECTS.GetAll().Where(t => empProjects.Contains(t.PROJ_ID) && t.CUST_ID == CustomerId && t.CUSTOMER_USER_ID == cust.ID).ToList<CUSTOMER_PROJECTS>();
                foreach (CUSTOMER_PROJECTS cp in custProjects)
                {
                    CSPdb.CUSTOMER_PROJECTS.Delete(cp);
                    CSPdb.Commit(CanCommit);
                }
                SendNotificationToStakeholders(custProjects, cust.EMAILID, cust.DISPLAY_NAME, CRUD.Delete, null);
            }
            return Ok();
        }

        [POST("DeleteKPIGoal")]
        [ActionName("DeleteKPIGoal")]
        [HttpPost]
        public IHttpActionResult DeleteKPIGoal(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            KPI_GOALS results = JsonConvert.DeserializeObject<KPI_GOALS>(json);

            int resultCount = CSPdb.KPI.GetAll().Count(t => t.GOAL_ID == results.ID && t.ISACTIVE);
            if (resultCount >= 1)
            {
                return Content(HttpStatusCode.Conflict, "Since this Goal is mapped to active KPI, It can't be deleted");
            }
            KPI_GOALS query = CSPdb.KPI_GOALS.GetById(results.ID);
            if (query != null)
            {
                query.ISACTIVE = false;
                CSPdb.KPI_GOALS.Update(query);
                CSPdb.Commit(CanCommit);
                UpdateLastUpdatedDetails(results.PROJECT_ID, results.UPDATED_BY);
            }
            return Ok();
        }

