        [POST("DeleteProjectResource")]
        [ActionName("DeleteProjectResource")]
        [HttpPost]
        public IHttpActionResult DeleteProjectResource(HttpRequestMessage request)
        {
            var content = request.Content;
            string jsonContent = content.ReadAsStringAsync().Result;
            dynamic json = jsonContent;
            ProjectResourceByEmpId results = JsonConvert.DeserializeObject<ProjectResourceByEmpId>(json);
            int projRsrcId = 0;
            if (results != null)
            {
                // List<PROJECT_RESOURCE> resources = Cldb.PROJECT_RESOURCE.GetAll().Where(t => t.EMP_ID == results.EMP_ID && t.PROJ_ID == results.PROJ_ID).ToList<PROJECT_RESOURCE>(); //bak
                List<PROJECT_RESOURCE> resources;
                if (results.PROJ_RESRC_ID == 0)
                {
                    //resources = Cldb.PROJECT_RESOURCE.GetAll().Where(t => t.EMP_ID == results.EMP_ID && t.PROJ_ID == results.PROJ_ID).ToList<PROJECT_RESOURCE>();
                    List<PROJECT_RESOURCE> objProjRid = Cldb.PROJECT_RESOURCE.GetAll().Where(t => t.EMP_ID == results.EMP_ID && t.PROJ_ID == results.PROJ_ID && t.START_DATE == results.START_DATE && t.END_DATE == results.END_DATE).ToList<PROJECT_RESOURCE>();
                    foreach (PROJECT_RESOURCE probj in objProjRid)
                    {
                        projRsrcId = probj.PROJ_RESRC_ID;
                    }
                    resources = Cldb.PROJECT_RESOURCE.GetAll().Where(t => t.PROJ_RESRC_ID == projRsrcId && t.EMP_ID == results.EMP_ID && t.PROJ_ID == results.PROJ_ID).ToList<PROJECT_RESOURCE>();
                }
                else
                {
                    resources = Cldb.PROJECT_RESOURCE.GetAll().Where(t => t.PROJ_RESRC_ID == results.PROJ_RESRC_ID && t.EMP_ID == results.EMP_ID && t.PROJ_ID == results.PROJ_ID).ToList<PROJECT_RESOURCE>();
                }
                foreach (PROJECT_RESOURCE pr in resources)
                {
                    Cldb.PROJECT_RESOURCE.Delete(pr);
                    Cldb.Commit(CanCommit);
                }
            }
            return Ok();
        }

