        private string AddProcessFile(string filename, string ServerFileName, string contentType)
        {
            string category = null;
            if (Request.Headers.Contains("REPORT_CATEGORY"))
                category = Request.Headers.GetValues("REPORT_CATEGORY").ToList()[0];

            PROJECT_PROCESS p = new PROJECT_PROCESS()
            {
                PROJECT_ID = Request.Headers.GetValues("PROJECT_ID").ToList()[0],
                RAG = "",
                //FILE_CONTENT = '';
                FILE_NAME = Path.GetFileNameWithoutExtension(filename),
                FILE_NAME_SERVER = ServerFileName,
                FILE_EXTENSION = Path.GetExtension(filename),
                FILE_TYPE = contentType,
                REPORT_TYPE = Request.Headers.GetValues("REPORT_TYPE").ToList()[0],
                CATEGORY = category,
                PUBLISH_DATE = Convert.ToDateTime(Request.Headers.GetValues("PUBLISH_DATE").ToList()[0]),
                CREATED_BY = Request.Headers.GetValues("CREATED_BY").ToList()[0],
                CREATED_DATE = DateTime.Now,
                UPDATED_BY = Request.Headers.GetValues("CREATED_BY").ToList()[0],
                UPDATED_DATE = DateTime.Now,
                ISACTIVE = true
            };
            CSPdb.PROJECT_PROCESS.Add(p);
            CSPdb.Commit(CanCommit);
            string jsonProcess = Newtonsoft.Json.JsonConvert.SerializeObject(p);
            return jsonProcess;
        }
