        private CSPMODEL.Client GetNewClient(ProjectBase p, List<ENGAGEMENT_OVERVIEW> overviewList, List<CUSTOMER_REPORTS> customerReportList)
        {
            CSPMODEL.Client newClient = new CSPMODEL.Client() { Client_ID = p.CUST_ID, Client_NM = p.CUST_NM };
            var RESULT = overviewList.FirstOrDefault(t => t.CUSTOMER_ID == p.CUST_ID);
            if (RESULT != null)
            {
                newClient.Client_RAG = RESULT.RAG;
                if (!string.IsNullOrWhiteSpace(RESULT.CUSTOMER_NAME))
                    newClient.Client_NM = RESULT.CUSTOMER_NAME;
                newClient.Client_Description = RESULT.CUSTOMER_DESCRIPTION;
                newClient.Client_Goals = RESULT.CUSTOMER_GOALS;
                newClient.Gavs_Description = RESULT.GAVS_DESCRIPTION;
                //newClient.reports = GetEngageReport(p.CUST_ID, customerReportList);
            }
            return newClient;
        }
        private CSPMODEL.Client GetNewClient(CUSTOMER_PROJECTS p, List<ENGAGEMENT_OVERVIEW> overviewList)
        {
            CSPMODEL.Client newClient = new CSPMODEL.Client() { Client_ID = p.CUST_ID, Client_NM = p.CUST_NM };
            var query = overviewList.Where(t => t.CUSTOMER_ID == p.CUST_ID);
            if (query != null && query.Count<ENGAGEMENT_OVERVIEW>() > 0)
            {
                ENGAGEMENT_OVERVIEW RESULT = query.ToList<ENGAGEMENT_OVERVIEW>()[0];
                newClient.Client_RAG = RESULT.RAG;
                newClient.Client_NM = RESULT.CUSTOMER_NAME;
                newClient.Client_Description = RESULT.CUSTOMER_DESCRIPTION;
                newClient.Client_Goals = RESULT.CUSTOMER_GOALS;
                newClient.Gavs_Description = RESULT.GAVS_DESCRIPTION;
            }
            return newClient;
        }
        private List<CUSTOMER_REPORTS> GetEngageReport(string CustomerId, List<CUSTOMER_REPORTS> customerReports)
        {
            var query = customerReports.Where(t => t.CUSTOMER_ID == CustomerId && t.ISACTIVE).OrderByDescending(t => t.PUBLISH_DATE).ToList<CUSTOMER_REPORTS>();
            return query;
        }
        private string GetProjectRAG(List<PROJECT_RAGS> project_rags, string ProjectId, ragCategory Category)
        {
            string rag = "";
            var query = project_rags.Where(t => t.PROJECT_ID == ProjectId && t.CATEGORY == Category.ToString());
            if (query != null && query.Count<PROJECT_RAGS>() > 0)
                rag = query.ToList<PROJECT_RAGS>()[0].RAG;
            return rag;
        }
        private DateTime GetProjectPublishedOn(List<PROJECT_RAGS> project_rags, string ProjectId)
        {
            DateTime PublishedOn = DateTime.Now;
            var query = project_rags.Where(t => t.PROJECT_ID == ProjectId && t.CATEGORY == "project");
            if (query != null && query.Count<PROJECT_RAGS>() > 0)
                PublishedOn = query.ToList<PROJECT_RAGS>()[0].PUBLISHED_ON;
            return PublishedOn;
        }
