        private PROJECT_DELIVERY_DETAILS GetProjectDeliveryDetails(string ProjectId, DateTime CurrentDate)
        {
            DateRange dtRange = new DateRange(CurrentDate, enDateRange.Weekly);
            PROJECT_DELIVERY delivery = CSPdb.PROJECT_DELIVERY.GetAll().Where(t => t.PROJECT_ID == ProjectId && t.PUBLISH_DATE >= dtRange.StartDate && t.PUBLISH_DATE <= dtRange.EndDate).FirstOrDefault();

            if (delivery == null)
            {
                delivery = new PROJECT_DELIVERY()
                {
                    PROJECT_ID = ProjectId,
                };
            }


            PROJECT_DELIVERY_DETAILS deliverydetails = new PROJECT_DELIVERY_DETAILS() { delivery = delivery, daterange = dtRange };
            return deliverydetails;
        }
        private ProjectPeopleDetails GetProjectPeople(string ProjectId)
        {
            var resource = Cldb.AppRepo.ResourceCount(ProjectId);

            List<Model.CSP.ResourceDetails> lstResource = new List<Model.CSP.ResourceDetails>();

            List<CSM_TITLES> titles = Cldb.CSM_TITLES.GetAll().ToList<CSM_TITLES>();

            var project = Cldb.PROJECT.GetAll().FirstOrDefault(t => t.PROJ_ID == ProjectId);


            foreach (var t in titles)
            {

                List<Resource> res = resource.Where(r => r.TITLE == t.TITLE).ToList<Resource>();
                if (res.Count > 0)
                {
                    Model.CSP.ResourceDetails resourceDetails = new Model.CSP.ResourceDetails();
                    resourceDetails.TITLE = t.TITLE;
                    resourceDetails.RESOURCE = res;
                    lstResource.Add(resourceDetails);
                }
                else if (t.TITLE.ToLower() == "quality" && !string.IsNullOrWhiteSpace(project.QUALITY_SPOC))
                {
                    var qspoc = Cldb.EMP_INFO.GetAll().FirstOrDefault(x => x.EMP_ID == project.QUALITY_SPOC && x.DOR == null);
                    if (qspoc != null)
                    {
                        lstResource.Add(new Model.CSP.ResourceDetails
                        {
                            TITLE = t.TITLE,
                            RESOURCE = new List<Resource> { new Resource
                            { TITLE = t.TITLE, EMP_ID = qspoc.EMP_ID, NAME = qspoc.FRST_NM ,
                            //ActiveFrom = (qspoc.DOJ > project.START_DATE) ? qspoc.DOJ.ToString("MMM dd, yyyy") : project.START_DATE.ToString("MMM dd, yyyy") }
                            ActiveFrom = project.START_DATE.ToString("MMM dd, yyyy") }
                            }
                        });
                    }
                }

            }




            var RESULT = new PROJECT_PEOPLE();
            var query = CSPdb.PROJECT_PEOPLE.GetAll().Where(t => t.PROJECT_ID == ProjectId);
            if (query != null && query.Count<PROJECT_PEOPLE>() > 0)
                RESULT = query.ToList<PROJECT_PEOPLE>()[0];


            return new ProjectPeopleDetails
            {
                PROJECT_PEOPLE = RESULT,
                RESOURCE = lstResource,
            };


        }
        private PROJECT_PROCESS[] GetProjectProcess(string ProjectId)
        {
            var query = CSPdb.PROJECT_PROCESS.GetAll().Where(t => t.PROJECT_ID == ProjectId && t.ISACTIVE).OrderByDescending(u => u.PUBLISH_DATE).ToArray<PROJECT_PROCESS>();
            return query;
        }
        private PROJECT_RISK[] GetProjectRisk(string ProjectId)
        {
            var query = CSPdb.PROJECT_RISK.GetAll().Where(t => t.PROJECT_ID == ProjectId && t.ISACTIVE).OrderByDescending(u => u.IDENTIFIED_DATE).ToArray<PROJECT_RISK>();
            return query;
        }
        private PROJECT_ISSUE[] GetProjectIssue(string ProjectId)
        {
            var query = CSPdb.PROJECT_ISSUE.GetAll().Where(t => t.PROJECT_ID == ProjectId && t.ISACTIVE).OrderByDescending(u => u.IDENTIFIED_DATE).ToArray<PROJECT_ISSUE>();
            return query;
        }
        private PROJECT_INNOVATION[] GetProjectInnovation(string ProjectId)
        {
            var query = CSPdb.PROJECT_INNOVATION.GetAll().Where(t => t.PROJECT_ID == ProjectId && t.ISACTIVE).OrderByDescending(u => u.IDENTIFIED_DATE).ToArray<PROJECT_INNOVATION>();
            List<int> innovationIds = query.Select(t => t.ID).ToList<int>();
            List<GAVSSERVICE> gavsServicelist = new List<GAVSSERVICE>();
            GAVSSERVICE gavsService = new GAVSSERVICE();
            List<GAVS_SERVICE> service = CSPdb.GAVS_SERVICE.GetAll().ToList<GAVS_SERVICE>();
            INNOVATION_SERVICE_MAPPING serviceloop = new INNOVATION_SERVICE_MAPPING();
            List<INNOVATION_SERVICE_MAPPING> servicemapping = CSPdb.INNOVATION_SERVICE_MAPPING.GetAll().Where(t => innovationIds.Contains(t.INNOVATION_ID)).ToList<INNOVATION_SERVICE_MAPPING>();
            PROJECT_INNOVATION innovation = new PROJECT_INNOVATION();
            foreach (PROJECT_INNOVATION inn in query)
            {
                gavsServicelist = new List<GAVSSERVICE>();
                foreach (GAVS_SERVICE ser in service)
                {
                    serviceloop = servicemapping.Where(t => t.SERVICE_ID == ser.ID && t.INNOVATION_ID == inn.ID).FirstOrDefault();
                    if (serviceloop == null)
                    {
                        gavsService = new GAVSSERVICE();
                        gavsService.SERVICE_ID = ser.ID;
                        gavsService.IS_CHECKED = false;
                    }
                    else
                    {
                        gavsService = new GAVSSERVICE();
                        gavsService.SERVICE_ID = ser.ID;
                        gavsService.IS_CHECKED = true;
                    }
                    gavsServicelist.Add(gavsService);
                }
                inn.GAVS_SERVICE = gavsServicelist;
            }
            return query;
        }
