        [GET("InviteUser")]
        [ActionName("InviteUser")]
        [HttpGet]
        public IHttpActionResult InviteUser(string email, string empid)
        {
            string sender = GetEmailIdByEmpId(empid);
            string msg = string.Empty;
            //sender = "roopsundar.venkat@gavstech.com";
            CUSTOMER_USERS dbData = CSPdb.CUSTOMER_USERS.GetAll().Where(t => t.EMAILID.ToUpper() == email.ToUpper()).FirstOrDefault<CUSTOMER_USERS>();
            if (dbData != null)
            {
                if (dbData.ACTIVATION_CODE == null || dbData.ACTIVATION_CODE == string.Empty)
                {
                    dbData.ACTIVATION_CODE = Guid.NewGuid().ToString();
                    dbData.ACTIVATION_VALIDITY = DateTime.Now;
                    CSPdb.CUSTOMER_USERS.Update(dbData);
                    CSPdb.Commit(CanCommit);
                }
                var baseurl = HttpContext.Current.Request.UrlReferrer.AbsoluteUri.Replace("customerinvite", "");
                string siteurl = baseurl + "setpassword/" + dbData.EMAILID + "/" + Security.HashSHA1(dbData.ACTIVATION_CODE);
                SendMail_Invite(dbData.EMAILID, dbData.DISPLAY_NAME, sender, siteurl);
            }
            else
                return Content(HttpStatusCode.Unauthorized, "Email id not found in our database, please contact GAVS team to get access.");

            return Ok(msg);
        }

        private void SendMail_Invite(string emailid, string name, string sender, string baseUrl)
        {

            string filePath = HttpContext.Current.Server.MapPath("~/UploadFile/Mails/") + "ClientInvitation.htm";
            using (System.IO.StreamReader sr = new StreamReader(filePath))
            {
                string emailContent = sr.ReadToEnd();
                emailContent = emailContent.Replace("{{CUSTOMER_NM}}", name);
                emailContent = emailContent.Replace("{{BASEURL}}", baseUrl);
                var ep = new EmailProvider(Cldb, CSPdb);
                ep.SendEmail
                    (
                    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                    new EmailContent { from = _email, to = emailid, cc = sender, content = emailContent, subject = "Neurealm invites you to join the Customer Success Management Platform", hasAttachments = false, attachmentFilePath = "" }, Request
                    );
            }
        }


