        private void SendEmail_ToCSM(List<CRISP_PROJECT> proj, string empId)
        {
            //List<CRISP_PROJECT> selectedProjects = proj.Where(t => t.CRISP_SCORES_PROJECT.STATUS == "Published" && t.CRISP_SCORES_PROJECT.SELECTED == true).ToList<CRISP_PROJECT>();
            //if (selectedProjects.Count == 0)
            //    return;
            //else
            //    proj = selectedProjects;

            List<int> projIds = new List<int>();
            List<CRISP_SCORES_CATEGORY> score = new List<CRISP_SCORES_CATEGORY>();
            List<CRISP_SCORES_PROJECT> projects = new List<CRISP_SCORES_PROJECT>();
            List<CRISP_SCORES_CRITERIA> cpc = new List<CRISP_SCORES_CRITERIA>();
            foreach (CRISP_PROJECT p in proj)
                if (p.CRISP_SCORES_PROJECT.SELECTED)
                {
                    CRISP_SCORES_PROJECT csp = new CRISP_SCORES_PROJECT();
                    csp = CSPdb.CRISP_SCORES_PROJECT.GetAll().Where(t => t.ID == p.CRISP_SCORES_PROJECT.ID).FirstOrDefault();
                    projIds.Add(csp.ID);
                    projects.Add(csp);
                }
            //Data
            var basProjects = GetProjectListForUser(empId).ToList(); // Cldb.PROJECT.GetAll().Where(x => PROJECT_IDs.Contains(x.PROJ_ID)).ToList<PROJECT>();

            List<CRISP_CATEGORY> categories = CSPdb.CRISP_CATEGORY.GetAll().ToList<CRISP_CATEGORY>();
            List<CRISP_CRITERIA> criterias = CSPdb.CRISP_CRITERIA.GetAll().ToList<CRISP_CRITERIA>();
            List<CRISP_VALIDATIONS> validations = CSPdb.CRISP_VALIDATIONS.GetAll().ToList<CRISP_VALIDATIONS>();
            List<CRISP_SCORES_CRITERIA> score_criterias = CSPdb.CRISP_SCORES_CRITERIA.GetAll().Where(t => projIds.Contains(t.CRISP_SCORES_PROJECT_ID)).ToList<CRISP_SCORES_CRITERIA>();
            //List<CRISP_SCORES_VALIDATIONS> score_validations = CSPdb.CRISP_SCORES_VALIDATIONS.GetAll().Where(t => projIds.Contains(t.CRISP_SCORES_PROJECT_ID)).ToList<CRISP_SCORES_VALIDATIONS>();
            List<CRISP_SCORES_CATEGORY> score_categories = CSPdb.CRISP_SCORES_CATEGORY.GetAll().Where(t => projIds.Contains(t.CRISP_SCORES_PROJECT_ID)).ToList<CRISP_SCORES_CATEGORY>();
            List<CRISP_SCORES_VALIDATIONS> score_validations = new List<CRISP_SCORES_VALIDATIONS>();
            List<CrispProjectSummary> summary = new List<CrispProjectSummary>();
            int finalscore = 0;
            foreach (CRISP_SCORES_PROJECT proja in projects)
            {
                score_validations = CSPdb.CRISP_SCORES_VALIDATIONS.GetAll().Where(t => t.CRISP_SCORES_PROJECT_ID == proja.ID).ToList<CRISP_SCORES_VALIDATIONS>();
                CrispProjectSummary projDetails = GetCristProjectDetails(proja, basProjects, categories, score_categories, criterias, score_criterias, validations, score_validations);
                foreach (CRISP_SCORES_CRITERIA pra in score_criterias)
                {
                    if ((pra.CRITERIA_ID <= 2 && pra.CRITERIA_ID > 0) && pra.CRISP_SCORES_PROJECT_ID == proja.ID)
                    {
                        if (pra.CRITERIA_ID == 1)
                            finalscore = 0;
                        finalscore = finalscore + pra.SCORE;
                        projDetails.categories[0].score = finalscore;
                        projDetails.categories[0].rag = GetRagFromScore(projDetails.categories[0].targetScore, finalscore);
                    }
                    else if ((pra.CRITERIA_ID == 3 || pra.CRITERIA_ID == 4) && pra.CRISP_SCORES_PROJECT_ID == proja.ID)
                    {
                        if (pra.CRITERIA_ID == 3)
                            finalscore = 0;
                        finalscore = finalscore + pra.SCORE;
                        projDetails.categories[1].score = finalscore;
                        projDetails.categories[1].rag = GetRagFromScore(projDetails.categories[1].targetScore, finalscore);
                    }
                    else if ((pra.CRITERIA_ID == 5 || pra.CRITERIA_ID == 6) && pra.CRISP_SCORES_PROJECT_ID == proja.ID)
                    {
                        if (pra.CRITERIA_ID == 5)
                            finalscore = 0;
                        finalscore = finalscore + pra.SCORE;
                        projDetails.categories[2].score = finalscore;
                        projDetails.categories[2].rag = GetRagFromScore(projDetails.categories[2].targetScore, finalscore);
                    }
                    else if ((pra.CRITERIA_ID == 7 || pra.CRITERIA_ID == 8) && pra.CRISP_SCORES_PROJECT_ID == proja.ID)
                    {
                        if (pra.CRITERIA_ID == 7)
                            finalscore = 0;
                        finalscore = finalscore + pra.SCORE;
                        projDetails.categories[3].score = finalscore;
                        projDetails.categories[3].rag = GetRagFromScore(projDetails.categories[3].targetScore, finalscore);
                    }
                    else if ((pra.CRITERIA_ID == 9 || pra.CRITERIA_ID == 10 || pra.CRITERIA_ID == 11) && pra.CRISP_SCORES_PROJECT_ID == proja.ID)
                    {
                        if (pra.CRITERIA_ID == 9)
                            finalscore = 0;
                        finalscore = finalscore + pra.SCORE;
                        projDetails.categories[4].score = finalscore;
                        projDetails.categories[4].rag = GetRagFromScore(projDetails.categories[4].targetScore, finalscore);
                    }
                }
                projDetails.score = projDetails.categories[0].score + projDetails.categories[1].score + projDetails.categories[2].score + projDetails.categories[3].score + projDetails.categories[4].score;
                summary.Add(projDetails);

            }
            if (proj.Any())
                SendEmailContent(summary, empId, proj[0].CRISP_SCORES_PROJECT.PUBLISH_DATE);
        }
        private void SendEmailContent(List<CrispProjectSummary> summary, string empId, DateTime publishdate)
        {
            string maildata = "";

            string sendermail = "";

            string period = "";
            string month = "";
            string year;


            month = CultureInfo.CurrentCulture.DateTimeFormat.GetAbbreviatedMonthName(publishdate.Month);
            year = publishdate.Year.ToString().Substring(2, 2);
            period = month + "-" + year;
            CrispCategoryDetails c = new CrispCategoryDetails();
            List<EMP_INFO> csm = new List<EMP_INFO>();
            List<string> pm = new List<string>();
            List<string> csmEmail = new List<string>();
            List<string> qualitySpocList = new List<string>();

            Dictionary<string, List<CrispProjectSummary>> group = new Dictionary<string, List<CrispProjectSummary>>();

            foreach (CrispProjectSummary cps in summary)
            {
                switch (cps.CRISP_SCORES_PROJECT?.STATUS?.ToUpper())
                {
                    case "NEW":
                    case "WIP":
                    case "":
                        continue;
                }
                csm = helper.GetCSMFromProject(cps.projecT_ID);
                csmEmail = csm.Select(t => t.EMAIL_ID).ToList<string>();
                foreach (string e in csmEmail)
                {
                    if (group.ContainsKey(e))
                    {
                        //group[e] = group[e].Add(cps);
                        List<CrispProjectSummary> l = group[e];
                        if (!l.Any(x => x.projecT_ID == cps.projecT_ID))
                        {
                            l.Add(cps);
                            group[e] = l;
                        }
                    }

                    else
                        group.Add(e, new List<CrispProjectSummary>() { cps });
                }
            }
            foreach (KeyValuePair<string, List<CrispProjectSummary>> entry in group)
            {
                maildata = GetHTMLContent(entry.Value, entry.Key);
                sendermail = _email;
                foreach (CrispProjectSummary projectSummary in entry.Value)
                {
                    var project = Cldb.PROJECT.GetAll().FirstOrDefault(x => x.PROJ_ID == projectSummary.projecT_ID);
                    pm.AddRange(helper.GetPMFromProject(project));

                    //sendermail = string.Join(",", pm);

                    //sendermail = sendermail + "," + GetEmailIdByEmpId(Convert.ToInt32(empId));
                    qualitySpocList.Add(helper.GetQualitySpocMailForProject(project));
                }
                pm.Add(entry.Key);
                var ep = new EmailProvider(Cldb, CSPdb);
                ep.SendEmail
                    (
                    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                     new EmailContent { from = _email, to = string.Join(",", pm), cc = string.Join(",", qualitySpocList), content = maildata, subject = $"CRISP Score for your review for {period}", hasAttachments = false, attachmentFilePath = "" }, Request
                    //new EmailContent { from = "mangayarkarasi.j@gavstech.com", to = "mangayarkarasi.j@gavstech.com", cc = "mangayarkarasi.j@gavstech.com", content = maildata, subject = "CRISP Score for your review - (" + period + ")", hasAttachments = false, attachmentFilePath = "" }
                    );

            }
        }


        private string GetHTMLContent(List<CrispProjectSummary> summarylist, string csm)
        {

            string htmlcontent = "";
            string htmlcontent1;
            string projname;
            string total;

            string csmName = Cldb.EMP_INFO.GetAll().Where(t => t.EMAIL_ID == csm).Select(t => t.FRST_NM).FirstOrDefault();
            string mailbody = "";
            string mailsignature = "";
            foreach (CrispProjectSummary cps in summarylist)
            {
                string scoredata = "";
                string validations = "";
                //string csmname = "";
                //List<EMP_INFO> csm = new List<EMP_INFO>();
                //csm = GetCSMFromProject(cps.projecT_ID);
                //foreach (EMP_INFO c in csm)
                //{
                //    csmname = csmname + c.FRST_NM + ",";
                //}
                //  period = "<p><u> Period</u> :" + month + ", " + year.ToString() + " </p><br>";

                mailbody = "<p>Hello " + csmName + "</p><br>";
                mailbody += $"<p>Please find below the CRISP Score for your Projects and submitted for approval by Quality Head.To view the CRISP score of your projects, log into CSM portal(<a href ='{helper.GetAbsoulteUri()}'> {helper.GetAbsoulteUri()} </a>) and click on the settings feature that is available on the top right corner.</p> <p>Choose <b>CRISP Scores Entry</b> and then select Customer, Project and Period to view the CRISP score for your projects. Please review and send your feedback to <a href ='mailto:{Constants.QUALITY_MAIL}'>{Constants.QUALITY_MAIL}</a> within a day to conclude on the same before publishing the final CRISP score online in the CSM portal.<p>";

                int score = 0;
                projname = "<td>" + cps.projecT_NAME + "</td>";
                foreach (CrispCategoryDetails ccd in cps.categories)
                {
                    scoredata += "<td style='background:" + ccd.rag + "'>" + ccd.score + "</td>";
                    score += ccd.score;
                }
                foreach (validations val in cps.validations)
                {
                    validations += "<table style = 'width:100%;'><tr><th style = 'width:50%'>Check Points</th><th>Comments</th></tr>" +
                        "<tr><td>" + val.VALIDATION_NAME + "</td><td>" + val.COMMENTS + "</td></tr></table>";
                }
                cps.rag = GetRagFromScore(100, score);
                total = "<td style='background:" + cps.rag + "'>" + score + "</td>";
                htmlcontent1 = projname + scoredata + total;
                htmlcontent += "<div style = 'margin-top:10px;margin-bottom:10px;'><table style = 'width:100%;'>" +
                                "<tr><th style ='width:65%'>Project</th><th>C</th><th>R</th><th>I</th><th>S</th><th>P</th><th>Total</th></tr>" +
                                 "<tr>" + htmlcontent1 + "</tr>" +
                               "</table><div style='margin-top:10px'>" + validations + "</div></div> ";
            }
            mailsignature = "<p>Note: The portal is best viewed in Chrome browsers</p><br><p>Regards,</p><br><p>Process Quality Assurance Team</p><p>Neurealm (Formerly GS Lab | GAVS Technologies)</p><p>7th Floor, Block B, Futura Tech Park, 334, Rajiv Gandhi Salai (OMR) Sholinganallur Chennai - 600 119</p>" +
                "<p>Phone: +91 44 66694287</p><p>Email: Quality@neurealm.com<mailto:Quality@neurealm.com></p><p>Web: www.neurealm.com<http://www.neurealm.com></p>";
            htmlcontent = " <style>p{margin: 0;padding: 0;font - size:60px;line - height:30px;}table,td,th{border: 1px solid #A49D9C;border-collapse:collapse;text-align:left;font-family:calibri}</style>" + mailbody + "" + htmlcontent + "" + mailsignature;
            return htmlcontent;
        }
