        private void GetCustomersByProjectId(string projId, out List<string> CustomerEmailIds, out List<string> CustomerNames)
        {
            List<int> CustomerIds = CSPdb.CUSTOMER_PROJECTS.GetAll().Where(t => t.PROJ_ID == projId && t.REPORTING).Select(t => t.CUSTOMER_USER_ID).ToList<int>();
            if (!CustomerIds.Any())
                CustomerIds = CSPdb.CUSTOMER_PROJECTS.GetAll().Where(t => t.PROJ_ID == projId).Select(t => t.CUSTOMER_USER_ID).ToList<int>();

            List<CUSTOMER_USERS> customers = new List<CUSTOMER_USERS>();
            customers = CSPdb.CUSTOMER_USERS.GetAll().Where(t => CustomerIds.Contains(t.ID)).ToList();
            CustomerEmailIds = customers.Select(t => t.EMAILID).ToList<string>();
            CustomerNames = customers.Select(t => t.DISPLAY_NAME).ToList<string>();
        }
        private void SendMailToEmp(MOM ai, string content, string empId)
        {

            List<string> ccemail = new List<string>();
            string tomail = GetEmailIdByEmpId(empId);
            string ccmail = "";
            foreach (MOM.MOM_DETAIL action in ai.MOM_ITEMS)
            {
                string emp_Id = "0";
                if (action.RESPONSIBILITY != "0")
                {
                    emp_Id = action.RESPONSIBILITY;
                    string empName = GetEmailIdByEmpId(emp_Id);
                    if (!ccemail.Contains(empName))
                        ccemail.Add(empName);
                }
            }
            ccmail = string.Join(",", ccemail.ToArray());
            var ep = new EmailProvider(Cldb, CSPdb);
            ep.SendEmail
                (
                new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                new EmailContent { from = _email, to = tomail, cc = ccmail, content = content, subject = "Minutes of Meeting detail", hasAttachments = false, attachmentFilePath = "" }, Request
                );

        }

