        public DataTable ToDataTable<T>(List<T> items)
        {
            DataTable dataTable = new DataTable(typeof(T).Name);

            //Get all the properties
            PropertyInfo[] Props = typeof(T).GetProperties(BindingFlags.Public | BindingFlags.Instance);
            foreach (PropertyInfo prop in Props)
            {
                //Defining type of data column gives proper data table 
                var type = (prop.PropertyType.IsGenericType && prop.PropertyType.GetGenericTypeDefinition() == typeof(Nullable<>) ? Nullable.GetUnderlyingType(prop.PropertyType) : prop.PropertyType);
                //Setting column names as Property names
                dataTable.Columns.Add(prop.Name, type);
            }
            foreach (T item in items)
            {
                var values = new object[Props.Length];
                for (int i = 0; i < Props.Length; i++)
                {
                    //inserting property values to datatable rows
                    values[i] = Props[i].GetValue(item, null);
                }
                dataTable.Rows.Add(values);
            }
            //put a breakpoint here and check datatable
            return dataTable;
        }
        public class Security
        {
            public static string HashSHA1(string value)
            {
                var sha1 = System.Security.Cryptography.SHA1.Create();
                var inputBytes = Encoding.ASCII.GetBytes(value);
                var hash = sha1.ComputeHash(inputBytes);

                var sb = new StringBuilder();
                for (var i = 0; i < hash.Length; i++)
                {
                    sb.Append(hash[i].ToString("X2"));
                }
                return sb.ToString();
            }
        }
        public class BasicAuthenticationAttribute : AuthorizationFilterAttribute
        {
            public override void OnAuthorization(System.Web.Http.Controllers.HttpActionContext actionContext)
            {
                if (actionContext.Request.Headers.Authorization == null)
                {
                    actionContext.Response = actionContext.Request.CreateResponse(HttpStatusCode.Unauthorized);
                }
                else
                {
                    // Gets header parameters  
                    string authenticationString = actionContext.Request.Headers.Authorization.Parameter;
                    string originalString = Encoding.UTF8.GetString(Convert.FromBase64String(authenticationString));

                    // Gets username and password  
                    string usrename = originalString.Split(':')[0];
                    string password = originalString.Split(':')[1];

                    // Validate username and password  
                    if (!ApiSecurity.VaidateUser(usrename, password))
                    {
                        // returns unauthorized error  
                        actionContext.Response = actionContext.Request.CreateResponse(HttpStatusCode.Unauthorized);
                    }
                }
                base.OnAuthorization(actionContext);
            }
        }

        [GET("TimeSheetRemainderEmail")]
        [ActionName("TimeSheetRemainderEmail")]
        [HttpGet]
        public IHttpActionResult TimeSheetRemainderEmail()
        {
            DateTime StartDate = this.GetHeaderDetails_Date("startDate");
            DateTime EndDate = this.GetHeaderDetails_Date("endDate").AddDays(-2);
            string CustomerId = this.GetHeaderDetails_String("customerId");
            string projectId = this.GetHeaderDetails_String("projectId");
            var empId = this.GetHeaderDetails_String("empId");
            var projects = GetProjectsForUser(empId);

            List<EMP_INFO_FOR_CUSTOMER> employeeListObj = Cldb.AppRepo.RemainderEmail(StartDate, EndDate, CustomerId, projectId).ToList<EMP_INFO_FOR_CUSTOMER>();

            employeeListObj = employeeListObj.Where(x => projects.Contains(x.PROJ_ID)).ToList();

            bool mailStatus = employeeListObj.Any() ? SendTimesheetBulkMail(employeeListObj, empId) : true;
            if (mailStatus == true)
            {
                return Ok(mailStatus);
            }
            else
            {
                return Ok(mailStatus);
            }

        }
        private bool SendTimesheetBulkMail(List<EMP_INFO_FOR_CUSTOMER> emplist, string empid)
        {
            bool emailStatus = false;
            DateTime startdate = this.GetHeaderDetails_Date("startDate");
            DateTime EndDate = this.GetHeaderDetails_Date("endDate").AddDays(-2);

            //spliting to email address
            var toemailaddress = string.Join(",", emplist.Select(p => p.EMAIL_ID.ToString()));

            string manager = string.Empty;

            string statusMsg = string.Empty;
            string mailContent;
            string tomail = toemailaddress;
            string ccmail = helper.GetDBConfig("CSS_LINK_CC", "-1");
            //string intempid = empid;
            //if (int.TryParse(empid, out intempid))
            //{
            var employee = Cldb.EMP_INFO.GetAll().FirstOrDefault(x => x.EMP_ID == empid);
            if (employee != null)
            {
                manager = employee.FRST_NM;
                ccmail = employee.EMAIL_ID + "," + ccmail;
            }
            //}
            // subject = "GAVS - " + Frequency + " Customer Success Survey for the project " + overview.PROJ_NM + " and period " + PreviousPeriod;
            var subject = $"GAVS - Reminder Email For Timesheet Entry triggered by your manager {manager}";
            // ccmail = helper.ConcatEmails(new List<string>() { ccmail, csmMails, pmMails });

            Dictionary<string, string> EmailContentValues = new Dictionary<string, string>();

            EmailContentValues.Add("STARTDATE", startdate.ToString("dd-MMM-yyyy"));
            EmailContentValues.Add("DUEDATE", EndDate.ToString("dd-MMM-yyyy"));

            mailContent = helper.GetEmailContent("BulkRemainderEmail.htm", EmailContentValues);

            try
            {
                var ep = new EmailProvider(Cldb, CSPdb);
                ep.SendEmail
                    (
                    new EmailConfig { environment = enumEnvironment.Dev, smtpAccount = _email, smtpHost = "smtp.office365.com", smtpPassword = _password, smtpPortValue = "587" },
                    new EmailContent { from = _email, to = tomail, cc = ccmail, content = mailContent, subject = subject, hasAttachments = false, attachmentFilePath = "" }, Request
                    );
                emailStatus = true;
            }
#pragma warning disable CS0168 // The variable 'ex' is declared but never used
            catch (Exception ex)
#pragma warning restore CS0168 // The variable 'ex' is declared but never used
            {

            }
            return emailStatus;
        }

